/* 20 điểm ngữ pháp bổ sung (viết thêm cho từng cấp), gắn vào GRAMMAR, GRAMMAR_BANK, GRAMMAR_THEORY và GRAMMAR_GX. Thứ tự trong mỗi cấp theo trình tự dạy. */
(function () {
  const NEW = [{"id":"adjectives-adverbs","lvl":"A2","title":"Adjectives and adverbs of manner","vi":"Tính từ và trạng từ chỉ cách thức","exams":["CEFR","VSTEP","IELTS"],"form":"Tính từ + danh từ: a careful driver. Trạng từ cách thức: tính từ + -ly (careful → carefully): drives carefully.\nBất quy tắc: good → well; fast, hard, late giữ nguyên.\nSau linking verb (be, feel, look, seem, sound, taste): dùng tính từ.","use":"Dùng tính từ để mô tả người, vật; dùng trạng từ chỉ cách thức để nói hành động diễn ra như thế nào. Sau feel, look, sound, seem dùng tính từ, không dùng trạng từ.","ex":[["She is a careful driver. She drives carefully.","Cô ấy là một tài xế cẩn thận. Cô ấy lái xe một cách cẩn thận."],["He speaks English very well.","Anh ấy nói tiếng Anh rất tốt."],["You look tired today.","Hôm nay trông bạn mệt đấy."],["The train was fast, and it arrived early.","Chuyến tàu nhanh và đến sớm."]],"err":[["She speaks English good.","She speaks English well.","Bổ nghĩa cho động từ “speaks” cần trạng từ “well”, không dùng tính từ “good”."],["You look tiredly today.","You look tired today.","Sau linking verb “look” dùng tính từ “tired” để mô tả vẻ ngoài, không dùng trạng từ."],["The children played happy in the garden.","The children played happily in the garden.","Bổ nghĩa cho động từ “played” cần trạng từ “happily”, không dùng tính từ “happy”."]],"quiz":[["The nurse spoke ___ to the frightened child.",["gently","gentle","gentleness","more gentle"],0,"Bổ nghĩa cho động từ “spoke” cần trạng từ cách thức, và gently là trạng từ của gentle.",{"gentle":"“Gentle” là tính từ, không bổ nghĩa cho động từ “spoke”.","gentleness":"“Gentleness” là danh từ, không dùng làm trạng từ sau động từ.","more gentle":"“More gentle” là so sánh hơn, không có “than” hay ngữ cảnh so sánh nào."}],["My sister is a very ___ cook.",["nicely","well","goodly","good"],3,"Trước danh từ “cook” cần tính từ, và good là tính từ tương ứng với “well”.",{"well":"“Well” là trạng từ, không đứng trước danh từ “cook”.","goodly":"“Goodly” là từ hiếm, không dùng với nghĩa giỏi trong câu này.","nicely":"“Nicely” là trạng từ, không đứng trước danh từ “cook”."}],["This coffee tastes ___. Can I have another cup?",["wonderfully","wonderful","wonder","wonderfulness"],1,"Taste là linking verb nên đi với tính từ wonderful; “another cup” cho thấy cà phê ngon.",{"wonderfully":"“Wonderfully” là trạng từ, không dùng sau linking verb “tastes”.","wonder":"“Wonder” là danh từ hoặc động từ, không mô tả vị của cà phê.","wonderfulness":"“Wonderfulness” là danh từ hiếm, không dùng sau “tastes”."}],["He drove so ___ that we arrived an hour early.",["fastly","faster","fast","fastest"],2,"Fast vừa là tính từ vừa là trạng từ, không có dạng “fastly”; “so ___ that” dùng dạng gốc.",{"fastly":"“Fastly” không tồn tại trong tiếng Anh chuẩn.","faster":"“Faster” là so sánh hơn, không hợp với cấu trúc “so ... that”.","fastest":"“Fastest” là so sánh nhất, không hợp với cấu trúc “so ... that”."}]]},{"id":"as-as","lvl":"A2","title":"As … as, the same as, different from","vi":"So sánh bằng: as … as, the same as, different from","exams":["CEFR","VSTEP"],"form":"S + be + as + tính từ + as + ... Phủ định: not as/so + tính từ + as.\nthe same (noun) as / different from / similar to + ...\nas many + danh từ đếm được số nhiều / as much + danh từ không đếm được + as ...","use":"Dùng để nói hai người hay vật bằng nhau (as … as), không bằng nhau (not as … as), hoặc giống/khác nhau (the same as, different from, similar to).","ex":[["My brother is as tall as my father.","Anh tôi cao bằng bố tôi."],["This bus isn't as fast as the train.","Xe buýt này không nhanh bằng tàu hoả."],["Her phone is the same as mine.","Điện thoại của cô ấy giống hệt điện thoại của tôi."],["I don't have as many books as you.","Tôi không có nhiều sách bằng bạn."]],"err":[["She is as taller as her sister.","She is as tall as her sister.","Giữa as … as ta dùng dạng gốc của tính từ, không dùng dạng so sánh hơn “taller”."],["My bag is same as yours.","My bag is the same as yours.","“Same” luôn đi với “the”: “the same as”. Tiếng Việt nói “giống” nên dễ bỏ mất “the”."],["Her flat is similar with mine.","Her flat is similar to mine.","Tính từ “similar” đi với “to”, không đi với “with”. Đừng dịch “giống với” thành “similar with”."]],"quiz":[["This phone is ___ expensive as that one.",["so","as","than","like"],1,"So sánh bằng khẳng định dùng as + tính từ + as. Chỗ trống đầu tiên cần “as”, vì phía sau đã có “as that one”.",{"so":"“So … as” chỉ dùng trong câu phủ định; câu này khẳng định (is), nên phải dùng as … as.","than":"“Than” đi với dạng so sánh hơn như “more expensive”, còn ở đây có “as” phía sau nên cần as … as.","like":"“Like” không đứng trước tính từ để so sánh bằng; cấu trúc cần là as + tính từ + as."}],["The exam wasn't ___ difficult as I expected.",["as","than","more","too"],0,"Câu phủ định so sánh bằng có dạng not as + tính từ + as. Chữ “as I expected” phía sau cho thấy cần “as” ở chỗ trống.",{"than":"“Than” dùng với dạng so sánh hơn; câu này có “as I expected” nên cần as … as.","more":"“More difficult” phải đi với “than”, không đi với “as I expected”.","too":"“Too difficult” nghĩa là quá khó, không tạo được phép so sánh với “as I expected”."}],["Her handwriting is the same ___ mine.",["with","like","as","than"],2,"Cấu trúc đúng là the same as + danh từ hoặc đại từ. Ở đây “mine” là vế được so sánh nên cần “as”.",{"with":"Sau “the same” dùng “as” để nối với vế so sánh, không dùng “with”.","like":"“The same like” là lỗi hay gặp; cấu trúc đúng là the same as.","than":"“Than” chỉ dùng với dạng so sánh hơn, không đi với “the same”."}],["My opinion is different ___ yours.",["as","with","of","from"],3,"Tính từ different đi với giới từ “from” (hoặc “to” trong tiếng Anh Anh). Vế sau là “yours” nên chọn “from”.",{"as":"“Different as” không tồn tại; “as” dùng trong the same as, không dùng với different.","with":"“Different with” là lỗi hay gặp do tiếng Việt; tính từ different đi với “from”.","of":"“Of” không đi với different khi so sánh hai ý kiến."}]]},{"id":"can-ability","lvl":"A1","title":"Can, can't, could (ability, permission, requests)","vi":"Can, can't, could: khả năng, xin phép, yêu cầu","exams":["CEFR","VSTEP","TOEIC"],"form":"S + can/can't + V (nguyên mẫu, không to). Câu hỏi: Can + S + V?\nQuá khứ: S + could/couldn't + V.\nYêu cầu lịch sự: Could I/you + V ...?","use":"Dùng “can” để nói khả năng hiện tại, xin phép và nhờ vả; dùng “could” cho khả năng trong quá khứ và để xin phép, nhờ vả lịch sự hơn.","ex":[["She can speak three languages.","Cô ấy có thể nói ba thứ tiếng."],["I can't find my keys.","Tôi không tìm thấy chìa khóa của mình."],["Could I use your phone, please?","Cho tôi mượn điện thoại của bạn được không ạ?"],["When I was five, I could swim.","Hồi năm tuổi, tôi đã biết bơi."]],"err":[["She cans swim very well.","She can swim very well.","“can” không thêm -s ở ngôi thứ ba số ít: he/she/it can."],["I can to drive a car.","I can drive a car.","Sau “can” dùng động từ nguyên mẫu không “to”."],["Do you can help me?","Can you help me?","“can” tự đảo lên trước chủ ngữ để lập câu hỏi, không dùng “do”."]],"quiz":[["My little sister is only four, but she ___ read already.",["cans","can","can to","is can"],1,"Chủ ngữ “she” vẫn đi với “can” nguyên dạng, và sau đó là động từ “read” không có “to”.",{"cans":"Động từ khuyết thiếu “can” không thêm -s dù chủ ngữ “she” là ngôi thứ ba số ít.","can to":"Sau “can” phải dùng động từ nguyên mẫu không “to”, nên “can to read” là sai.","is can":"Không dùng “is” cùng “can”; “can” đã đóng vai trò trợ động từ rồi."}],["I'm sorry, I ___ come to the party tomorrow. I have to work.",["can't","don't can","can","no can"],0,"“I'm sorry” và lý do phải đi làm cho thấy cần dạng phủ định “can't” để nói không thể đến.",{"don't can":"Không dùng “do” với “can”; muốn phủ định chỉ cần thêm “not” vào “can”.","can":"Câu có “I'm sorry” và “have to work” cho thấy người nói không thể đến, nên cần dạng phủ định.","no can":"“no can” không phải cấu trúc đúng trong tiếng Anh chuẩn; phủ định của “can” là “can't” hoặc “cannot”."}],["___ you help me with this heavy box, please?",["Do","Are","Can","Does"],2,"Muốn nhờ ai giúp ta dùng “Can you + V ...?”, và “please” xác nhận đây là lời nhờ vả.",{"Do":"“Do you help me” sẽ thiếu “can”; để nhờ vả cần động từ khuyết thiếu, không dùng “do”.","Are":"“Are” cần đi với tính từ hoặc V-ing, không thể đứng trước “help” để nhờ vả.","Does":"“Does” dùng với he/she/it, và cũng không tạo thành câu nhờ vả với động từ nguyên mẫu."}],["When my father was young, he ___ run ten kilometres without stopping.",["can","cans","is could","could"],3,"Mệnh đề “when my father was young” chỉ quá khứ, nên dùng “could” để nói khả năng trong quá khứ.",{"can":"“when ... was young” chỉ quá khứ nên không dùng “can” ở hiện tại.","cans":"“can” không bao giờ thêm -s, và ở đây còn sai thì.","is could":"Không dùng “is” trước “could”; “could” tự đứng trước động từ nguyên mẫu."}]]},{"id":"demonstratives","lvl":"A1","title":"This, that, these, those","vi":"This, that, these, those (đây, đó, những cái này/kia)","exams":["CEFR","VSTEP"],"form":"Gần: this (số ít) / these (số nhiều). Xa: that (số ít) / those (số nhiều).\nThis/That + is; These/Those + are. Hỏi: What's this? Who are those?","use":"Dùng để chỉ người hoặc vật ở gần hay ở xa người nói, số ít hay số nhiều; cũng dùng khi giới thiệu người và khi nói điện thoại.","ex":[["This is my notebook.","Đây là cuốn vở của tôi."],["Those books on the shelf are new.","Những cuốn sách trên kệ kia còn mới."],["These apples are very sweet.","Những quả táo này rất ngọt."],["Hello, this is Anna. Is that Mark?","Xin chào, Anna đây. Đó có phải Mark không?"]],"err":[["This are my keys.","These are my keys.","Chìa khóa là số nhiều nên phải dùng “these … are”, không dùng “this … are”."],["I like that shoes.","I like those shoes.","“Shoes” là số nhiều, nên dùng “those”, không dùng “that”."],["Hello, is this Mark?","Hello, is that Mark?","Khi gọi điện, hỏi người ở đầu dây kia dùng “that”; chỉ khi nói về mình mới dùng “this”."]],"quiz":[["Look at ___ birds in the tree over there.",["those","these","that","this"],0,"Chim là số nhiều và ở xa (over there), nên dùng “those”.",{"this":"“This” là số ít và chỉ vật gần, không hợp với “birds” và “over there”.","these":"“These” là số nhiều nhưng chỉ vật gần, trong khi đàn chim ở xa (over there).","that":"“That” là số ít, không đi với danh từ số nhiều “birds”."}],["Dad, ___ is my friend Tom. He is standing next to me.",["That","This","Those","These"],1,"Giới thiệu người đang đứng ngay cạnh mình dùng “this is”; chủ ngữ số ít và có “next to me”.",{"That":"“That” chỉ người ở xa, trong khi Tom đứng ngay cạnh người nói.","Those":"“Those” là số nhiều và chỉ người ở xa, không đi với “is” và một người.","These":"“These” là số nhiều, không đi với “is” và một người."}],["I can't carry ___ bags. They are too heavy.",["that","this","these","it"],2,"“Bags” là số nhiều và đang ở gần người nói, nên dùng “these”; “They are” cũng xác nhận số nhiều.",{"this":"“This” là số ít, không đi với “bags” (số nhiều).","that":"“That” là số ít, không đi với “bags” (số nhiều).","it":"“It” không đứng trước danh từ để chỉ vật, và là số ít."}],["Who is ___ man over there, near the door?",["these","those","this","that"],3,"“Man” là số ít và ở xa (over there), nên dùng “that”.",{"these":"“These” là số nhiều, không đi với “man” và “is”.","those":"“Those” là số nhiều, không đi với danh từ số ít “man”.","this":"“This” chỉ người ở gần, trong khi người đàn ông ở xa (over there)."}]]},{"id":"dependent-prepositions","lvl":"B1","title":"Verb, adjective and noun + preposition","vi":"Động từ, tính từ, danh từ + giới từ","exams":["CEFR","VSTEP","TOEIC","IELTS"],"form":"Verb / Adj / Noun + giới từ cố định: depend on, good at, afraid of, reason for.\nGiới từ + danh từ hoặc V-ing: interested in learning (không dùng to V).","use":"Nhiều động từ, tính từ và danh từ luôn đi với một giới từ nhất định; phải học cả cụm, vì giới từ không dịch theo từng chữ từ tiếng Việt.","ex":[["It depends on the weather.","Việc đó tùy thuộc vào thời tiết."],["She is good at explaining difficult ideas.","Cô ấy giỏi giải thích những ý khó."],["He is afraid of speaking in public.","Anh ấy sợ nói trước đám đông."],["What is the reason for the delay?","Lý do của sự chậm trễ là gì?"]],"err":[["I'm interested on music.","I'm interested in music.","“Interested” luôn đi với “in”, không dùng “on”."],["She is good in maths.","She is good at maths.","Chỉ kỹ năng giỏi về việc gì dùng “good at”; “good in” là lỗi hay gặp."],["I'm very proud about my son.","I'm very proud of my son.","“Proud” đi với “of”, không dùng “about”."]],"quiz":[["Whether we go on a picnic depends ___ the weather.",["of","at","from","on"],3,"Động từ “depend” luôn đi với giới từ “on”; chủ ngữ là cả mệnh đề Whether we go nên “depends on” đứng trước the weather.",{"of":"“Depend of” là lỗi do dịch “phụ thuộc vào” sang “of”; cụm đúng chỉ có “depend on”.","from":"“Depend from” không tồn tại trong tiếng Anh hiện đại; chỉ có depend on.","at":"“Depend at” không phải cụm cố định; “at” chỉ vị trí hoặc thời điểm, không đi với depend."}],["Lan is very good ___ explaining things to patients.",["at","in","of","with"],0,"Nói về kỹ năng làm tốt một việc dùng “good at” + V-ing; explaining là V-ing nên giới từ cần là “at”.",{"in":"“Good in explaining” là lỗi hay gặp do dịch “giỏi về”; kỹ năng dùng “at”.","of":"“Good of explaining” dùng sai giới từ; “of” không đi với good khi nói về kỹ năng.","with":"“Good with” đi với người hay vật bạn xử lý tốt (good with children), không đi với V-ing."}],["He is afraid ___ flying, so he always travels by train.",["from","at","of","for"],2,"Tính từ “afraid” đi với giới từ “of”, và sau giới từ dùng V-ing: afraid of flying.",{"from":"“Afraid from” là lỗi do dịch “sợ từ”; không có cụm này trong tiếng Anh.","at":"“Afraid at” không phải cụm đúng; at không đi với afraid trong cách nói sợ một việc.","for":"“Afraid for” nghĩa là lo lắng cho an toàn của ai đó, không phải sợ việc bay."}],["We're looking forward ___ you at the conference.",["to see","for seeing","to seeing","of seeing"],2,"“Look forward to” có “to” là giới từ nên theo sau là V-ing; seeing you là dạng đúng.",{"to see":"“To see” dùng to V sau “to”, mà ở đây “to” là giới từ nên không dùng động từ nguyên mẫu.","for seeing":"“For seeing” dùng sai giới từ; cụm cố định chỉ là look forward to.","of seeing":"“Of seeing” cũng dùng sai giới từ; look forward không đi với of."}]]},{"id":"frequency-adverbs","lvl":"A1","title":"Adverbs of frequency","vi":"Trạng từ chỉ tần suất","exams":["CEFR","VSTEP","TOEIC"],"form":"S + always/usually/often/sometimes/rarely/never + V (thường).\nS + be + always/usually/often... Hỏi: How often ...? Trả lời: every day, twice a week.","use":"Dùng để nói một việc xảy ra thường xuyên đến mức nào, từ 100% (always) đến 0% (never); vị trí thường đứng trước động từ thường và sau “be”.","ex":[["I always drink tea in the morning.","Tôi luôn uống trà vào buổi sáng."],["She is never late for work.","Cô ấy không bao giờ đi làm muộn."],["We sometimes eat out on Saturdays.","Thỉnh thoảng chúng tôi ăn ngoài vào thứ Bảy."],["How often do you visit your grandparents? Twice a month.","Bạn thăm ông bà bao lâu một lần? Hai lần một tháng."]],"err":[["I go always to school by bike.","I always go to school by bike.","Trạng từ tần suất đứng trước động từ thường, không đứng sau động từ."],["He usually is tired in the evening.","He is usually tired in the evening.","Với động từ “be”, trạng từ tần suất đứng sau “be”."],["She doesn't never eat meat.","She never eats meat.","“Never” đã mang nghĩa phủ định nên không dùng thêm “don't/doesn't”."]],"quiz":[["My sister ___ gets up before six. She loves the early morning.",["always","never","rarely","hardly"],0,"“Loves the early morning” cho thấy cô ấy thích dậy sớm, nên phải là “always”.",{"never":"“Never” nghĩa là không bao giờ, mâu thuẫn với việc cô ấy thích buổi sáng sớm.","rarely":"“Rarely” là hiếm khi, không hợp với việc thích dậy sớm.","hardly":"“Hardly” cần đi với “ever” để có nghĩa gần như không bao giờ, và cũng mâu thuẫn."}],["Mark is ___ late for class. He is a very punctual student.",["usually","never","always","often"],1,"“Never” đi sau be: “is never late”; “punctual” cho thấy không bao giờ muộn.",{"usually":"“Usually late” nghĩa là thường muộn, mâu thuẫn với “very punctual”.","always":"“Always late” nghĩa là lúc nào cũng muộn, mâu thuẫn với “punctual”.","often":"“Often late” nghĩa là hay muộn, mâu thuẫn với “punctual”."}],["I ___ drink coffee in the evening because it keeps me awake.",["often","always","rarely","usually"],2,"“Keeps me awake” là lý do tránh cà phê buổi tối, nên “rarely” (hiếm khi) hợp lý.",{"often":"“Often” là hay uống, trái với lý do vì nó làm mất ngủ.","always":"“Always” là luôn uống, trái với lý do vì nó làm mất ngủ.","usually":"“Usually” là thường uống, trái với lý do vì nó làm mất ngủ."}],["They ___ play football on Sundays, so the park is full of them.",["never","rarely","hardly ever","often"],3,"Công viên đầy người chơi nghĩa là họ chơi thường xuyên, nên chọn “often”.",{"never":"“Never” là không bao giờ, mâu thuẫn với việc công viên đầy người.","rarely":"“Rarely” là hiếm khi, mâu thuẫn với việc công viên đầy người.","hardly ever":"“Hardly ever” là gần như không bao giờ, mâu thuẫn với việc công viên đầy họ."}]]},{"id":"have-got","lvl":"A1","title":"Have and have got","vi":"Have và have got: sở hữu, gia đình, bệnh","exams":["CEFR","VSTEP"],"form":"S + have/has got + N. Phủ định: haven't/hasn't got. Câu hỏi: Have/Has + S + got ...?\nS + have/has + N (dùng do/does: Do you have ...? I don't have ...).\nHành động: have breakfast, have a shower (không dùng “have got”).","use":"Dùng “have (got)” để nói ai có gì, có người thân nào, hoặc bị đau, bị bệnh gì; dùng “have” (không “got”) cho bữa ăn và hoạt động như “have breakfast”.","ex":[["I've got two brothers and a sister.","Tôi có hai anh em trai và một chị gái."],["She hasn't got a car.","Cô ấy không có xe hơi."],["Have you got a pen?","Bạn có bút không?"],["We have lunch at twelve.","Chúng tôi ăn trưa lúc mười hai giờ."]],"err":[["She have got a new phone.","She has got a new phone.","Ngôi thứ ba số ít (he/she/it) dùng “has got”, không dùng “have got”."],["Do you have got a pen?","Have you got a pen? / Do you have a pen?","Không trộn “do” với “have got”: chọn “Have you got ...?” hoặc “Do you have ...?”."],["I'm having got a headache.","I've got a headache.","“have got” không dùng ở dạng tiếp diễn; muốn nói “bị đau đầu” dùng “I've got a headache”."]],"quiz":[["My sister ___ got two small children.",["has","have","is","does"],0,"Chủ ngữ “my sister” là she nên dùng “has got” để nói sở hữu.",{"have":"Chủ ngữ “my sister” là ngôi thứ ba số ít nên cần “has”, không phải “have”.","is":"“is got” không phải cấu trúc đúng vì “got” đi với “have/has”.","does":"“does got” không tồn tại; “have got” không dùng trợ động từ “do”."}],["We ___ got a big garden behind our house.",["have","has","are","do"],0,"Chủ ngữ “we” đi với “have got”; “has got” chỉ dùng cho he/she/it.",{"has":"Chủ ngữ “we” đi với “have”, không đi với “has”.","are":"“are got” sai; “got” đi sau “have/has”.","do":"“do got” không phải cấu trúc đúng của “have got”."}],["I ___ got any money with me. Can you pay for the coffee?",["hasn't","don't","haven't","not"],2,"Chủ ngữ “I” và nhờ người khác trả tiền cho thấy phủ định “haven't got any”.",{"hasn't":"Chủ ngữ “I” đi với “haven't”, không dùng “hasn't”.","don't":"“don't got” không dùng trong tiếng Anh chuẩn viết ở trình độ này.","not":"Thiếu trợ động từ; phải có “haven't” trước “got”."}],["A: ___ you got a pen? B: Yes, I have.",["Do","Have","Are","Has"],1,"Câu trả lời ngắn “Yes, I have” tương ứng với câu hỏi “Have you got ...?”.",{"Do":"Câu trả lời “Yes, I have” cho thấy câu hỏi dùng “Have you got ...?”, không phải “Do”.","Are":"“Are you got” sai vì “got” đi với “have”.","Has":"“Has” chỉ dùng với he/she/it, không dùng với “you”."}]]},{"id":"imperatives","lvl":"A1","title":"Imperatives and let's","vi":"Câu mệnh lệnh và Let's","exams":["CEFR","VSTEP"],"form":"Khẳng định: V (nguyên mẫu). Phủ định: Don't + V.\nRủ rê: Let's + V. Phủ định: Let's not + V.\nLịch sự: Please + V / V, please.","use":"Dùng để ra lệnh, hướng dẫn, nhờ vả, cảnh báo, hoặc rủ ai cùng làm gì. Thêm “please” để nghe lịch sự hơn.","ex":[["Open your book, please.","Làm ơn mở sách ra."],["Don't touch the door. It's hot.","Đừng chạm vào cửa. Nó nóng đấy."],["Let's have lunch together.","Chúng ta cùng ăn trưa nhé."],["Take two tablets after meals.","Uống hai viên sau bữa ăn."]],"err":[["Not run in the corridor.","Don't run in the corridor.","Phủ định của câu mệnh lệnh dùng “Don't” + động từ nguyên mẫu, không dùng “Not” đứng một mình."],["Let's to go home.","Let's go home.","Sau “Let's” là động từ nguyên mẫu không “to”."],["You sit down, please.","Sit down, please.","Câu mệnh lệnh không cần chủ ngữ “you”; chỉ cần động từ nguyên mẫu."]],"quiz":[["___ the window, please. It's cold.",["Close","Closing","To close","You closing"],0,"Câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu; “please” và lý do “It's cold” cho thấy đây là lời nhờ đóng cửa sổ.",{"Closing":"Câu mệnh lệnh dùng động từ nguyên mẫu, không dùng dạng V-ing như “Closing” ở đầu câu.","To close":"Mệnh lệnh không dùng “to” trước động từ; chỉ cần động từ nguyên mẫu đứng đầu câu.","You closing":"Dạng này không phải câu hoàn chỉnh; mệnh lệnh cần động từ nguyên mẫu, không có chủ ngữ."}],["___ late for the interview tomorrow!",["Not be","Don't be","Aren't","No be"],1,"Mệnh lệnh phủ định là “Don't + V”. Với “be” ta nói “Don't be late”, giống như với mọi động từ khác.",{"Not be":"Phủ định của mệnh lệnh phải là “Don't” + V; “Not” đứng một mình ở đầu câu là sai.","Aren't":"Mệnh lệnh không dùng “aren't”; ta cần “Don't be” với động từ nguyên mẫu “be”.","No be":"“No” không dùng để tạo câu mệnh lệnh phủ định; phải dùng “Don't” trước động từ."}],["It's a lovely day. ___ go to the park!",["Let","Let to","Let's","We"],2,"“Let's + V” dùng để rủ người khác cùng làm; ngữ cảnh “lovely day” và “go to the park” là một lời đề nghị.",{"Let":"“Let” đứng riêng sẽ cần tân ngữ phía sau; lời rủ cùng đi phải là “Let's” (let us).","Let to":"“Let to” không phải cấu trúc rủ rê; lời rủ cùng làm phải là “Let's” (let us) + động từ.","We":"“We go” là câu trần thuật, không phải lời rủ; ở đây cần “Let's” trước “go”."}],["Please ___ your phone in the exam room.",["switching off","to switch off","switches off","switch off"],3,"Sau “Please” ta dùng động từ nguyên mẫu không “to”, và không thêm đuôi -s hay -ing vào động từ.",{"switching off":"Sau “Please” là động từ nguyên mẫu, không dùng V-ing.","to switch off":"Không dùng “to” sau “please”; mệnh lệnh dùng động từ nguyên mẫu trần.","switches off":"Mệnh lệnh không chia động từ theo ngôi; “switches” có đuôi -s là sai."}]]},{"id":"in-case-unless","lvl":"B1","title":"In case, unless, as long as, provided","vi":"Phòng khi, trừ khi, miễn là","exams":["CEFR","VSTEP","TOEIC","IELTS"],"form":"in case + S + V (hiện tại đơn / quá khứ đơn): phòng khi.\nunless + S + V = if … not.\nas long as / provided (that) + S + V (hiện tại đơn): với điều kiện là.","use":"Dùng “in case” để nói về việc ta làm trước như một sự phòng ngừa, còn “unless”, “as long as”, “provided” diễn tả điều kiện: chỉ không xảy ra / chỉ xảy ra khi điều kiện đó đúng.","ex":[["I'll take an umbrella in case it rains.","Tôi sẽ mang ô phòng khi trời mưa."],["You can't enter the ward unless you wear a mask.","Bạn không được vào khu bệnh nếu không đeo khẩu trang."],["You may borrow the book as long as you return it on Friday.","Bạn có thể mượn quyển sách miễn là trả lại vào thứ Sáu."],["We left early in case there was heavy traffic.","Chúng tôi đi sớm phòng khi kẹt xe."]],"err":[["I'll take a coat in case it will be cold.","I'll take a coat in case it is cold.","Sau “in case” dùng hiện tại đơn để nói về tương lai, không dùng “will”."],["Unless you don't hurry, you'll miss the bus.","Unless you hurry, you'll miss the bus.","“Unless” đã mang nghĩa phủ định (= if … not) nên động từ sau nó ở dạng khẳng định."],["You can go out as long you finish your homework.","You can go out as long as you finish your homework.","Cụm đầy đủ là “as long as”, cần đủ hai chữ “as”."]],"quiz":[["Lan wrote down the patient's number ___ she forgot it later.",["if","in case","unless","provided"],1,"“In case” diễn tả việc làm trước để phòng ngừa; câu kể ở quá khứ (wrote down) nên mệnh đề sau dùng past simple.",{"if":"“If she forgot it later” chỉ điều kiện sau đó mới viết, trong khi cô ấy ghi số trước để phòng quên.","unless":"“Unless she forgot” nghĩa là trừ khi cô ấy quên, làm câu vô lý về nghĩa.","provided":"“Provided she forgot” nghĩa là miễn là cô ấy quên, không hợp với hành động ghi lại để phòng ngừa."}],["You can't enter the lab ___ you wear a coat.",["in case","as long as","because","unless"],3,"Cấm vào trừ một ngoại lệ là mặc áo choàng, đó là nghĩa của “unless” (= if you don't wear a coat).",{"in case":"“In case you wear a coat” nghĩa là phòng khi bạn mặc áo, không nêu được điều kiện để được vào.","as long as":"“As long as you wear” nghĩa là miễn là bạn mặc, sẽ đảo ngược ý: mặc áo thì bị cấm.","because":"“Because you wear a coat” nêu lý do bị cấm, trái với ý thông thường của quy định phòng thí nghiệm."}],["You can borrow my laptop ___ you bring it back by Friday.",["unless","in case","although","as long as"],3,"“As long as” = miễn là, nêu điều kiện duy nhất để được mượn; sau nó dùng hiện tại đơn (you bring).",{"unless":"“Unless you bring it back” nghĩa là trừ khi bạn mang trả, làm câu cho mượn nhưng lại ngầm không cho.","in case":"“In case you bring it back” nghĩa là phòng khi bạn trả lại, không nêu điều kiện cho phép mượn.","although":"“Although” nghĩa là mặc dù, tạo ý tương phản không hợp lý với việc trả máy đúng hạn."}],["Unless it ___ tomorrow, we will have the picnic in the park.",["will rain","rains","doesn't rain","rained"],1,"Sau “unless” dùng hiện tại đơn khẳng định để nói về tương lai; “tomorrow” cho thấy đây là điều kiện tương lai.",{"will rain":"“Will rain” không dùng trong mệnh đề điều kiện sau unless; phải dùng hiện tại đơn.","doesn't rain":"“Doesn't rain” thành phủ định kép, vì unless đã mang nghĩa if … not.","rained":"“Rained” là quá khứ, không hợp với “tomorrow” và với câu điều kiện về tương lai."}]]},{"id":"modals-deduction","lvl":"B1","title":"Must, can't, might, may, could: deduction about the present","vi":"Suy đoán ở hiện tại với must, can't, might","exams":["CEFR","VSTEP","IELTS"],"form":"must / can't / might / may / could + be (+ V-ing / adj / noun)\nTự tin: must be (chắc chắn có) · can't be (chắc chắn không) · Không chắc: might / may / could be","use":"Dùng để đoán một điều đang đúng ở hiện tại dựa trên bằng chứng bạn thấy hoặc biết, với mức chắc chắn khác nhau, từ gần 100% (must) đến không chắc (might).","ex":[["She must be tired after the night shift.","Cô ấy chắc hẳn mệt sau ca đêm."],["That can't be Mr Hale; he is in Rome this week.","Đó không thể là ông Hale; tuần này ông ấy ở Rome."],["He might be waiting outside.","Có thể anh ấy đang đợi bên ngoài."],["The nurse isn't answering; she could be with a patient.","Y tá không trả lời; có thể cô ấy đang ở với bệnh nhân."]],"err":[["You must to be hungry after work.","You must be hungry after work.","Sau must dùng động từ nguyên mẫu không “to”."],["He can't to be a doctor.","He can't be a doctor.","Sau can't cũng là động từ nguyên mẫu không “to”."],["The light is on, so they must be sleep.","The light is on, so they must be asleep.","Cần tính từ “asleep” sau be, không dùng động từ “sleep”."]],"quiz":[["Ann has worked since six this morning and hasn't eaten. She ___ be exhausted.",["can't","must","mustn't","must to"],1,"Bằng chứng rất rõ (làm việc từ sáng, chưa ăn) nên dùng must để nói gần như chắc chắn là đúng.",{"can't":"Can't nghĩa là chắc chắn không thể, trái với bằng chứng cho thấy cô ấy rất mệt.","mustn't":"Mustn't diễn tả điều bị cấm, không dùng để suy đoán về trạng thái hiện tại.","must to":"Sau modal must không có “to”, chỉ dùng động từ nguyên mẫu trực tiếp."}],["That ___ be Dr Lee. He is on holiday in Spain this week.",["must","might","can't","mustn't"],2,"Bác sĩ đang đi nghỉ ở Tây Ban Nha nên ta chắc chắn đó không phải ông ấy, vì vậy dùng can't.",{"must":"Must nói chắc chắn là đúng, nhưng câu sau cho biết ông ấy đang ở nơi khác.","might":"Might chỉ là khả năng yếu, không hợp khi bằng chứng cho thấy gần như không thể.","mustn't":"Mustn't là lệnh cấm, người ta không dùng nó để suy đoán phủ định."}],["I don't know where Mai is. She ___ be at the library, or she may be at the gym.",["must","can't","mustn't","might"],3,"Người nói chỉ đoán và đưa hai khả năng, nên dùng might (không chắc) thay vì must hay can't.",{"must":"Must thể hiện sự chắc chắn, mâu thuẫn với “I don't know” và hai khả năng được nêu.","can't":"Can't loại trừ hoàn toàn khả năng, nhưng người nói còn đưa ra nơi cô ấy có thể ở.","mustn't":"Mustn't nghĩa là cấm đoán, không hợp với việc đoán vị trí của Mai."}],["A: Who is calling? B: I'm not sure. It ___ be my sister, or it might be the bank.",["could","can't","must","mustn't"],0,"Người nói đưa ra hai khả năng và nói “not sure”, nên chọn could, một modal chỉ khả năng không chắc.",{"can't":"Can't phủ nhận hoàn toàn, nhưng người nói vẫn nghĩ đó có thể là chị gái mình.","must":"Must chỉ sự chắc chắn, không hợp với “I'm not sure” và khả năng thứ hai.","mustn't":"Mustn't là cấm đoán, không dùng để đoán ai đang gọi."}]]},{"id":"passive-reporting","lvl":"B2","title":"Passive: get-passive and reporting passives","vi":"Bị động với get và bị động tường thuật","exams":["CEFR","VSTEP","IELTS"],"form":"get + V3: She got promoted. Phủ định: didn't get + V3.\nIt is said/believed that + mệnh đề. S + is said/believed + to V (hiện tại) / to have + V3 (trước đó).\nS + be supposed to + V: bị mong đợi/được yêu cầu phải làm.","use":"Dùng get + V3 để nói về một sự việc bất ngờ, ngoài ý muốn trong văn nói; dùng bị động tường thuật (It is said that…) để nêu tin đồn, niềm tin chung trong văn viết trang trọng.","ex":[["He got fired last week.","Anh ấy bị sa thải tuần trước."],["It is believed that the virus spreads through the air.","Người ta tin rằng virus lây qua không khí."],["The nurse is said to have worked abroad.","Nghe nói cô y tá từng làm việc ở nước ngoài."],["You are supposed to wash your hands first.","Bạn phải rửa tay trước (theo quy định)."]],"err":[["My bike got stole yesterday.","My bike got stolen yesterday.","Sau “get” phải dùng V3 (stolen), không dùng dạng quá khứ đơn stole."],["He is said that he is a doctor.","He is said to be a doctor. / It is said that he is a doctor.","Hoặc dùng “It is said that + mệnh đề”, hoặc dùng “He is said to + V”, không trộn hai cấu trúc."],["The thief is believed to escape last night.","The thief is believed to have escaped last night.","Hành động xảy ra trước thời điểm tin/nói thì dùng “to have + V3”."]],"quiz":[["My bag ___ on the train yesterday.",["got stolen","got steal","got stealing","was stole"],0,"Get-passive có dạng get/got + V3 và dùng cho sự việc không mong muốn; “yesterday” cho thấy ta dùng got + stolen.",{"got steal":"Sau “get” phải dùng V3, nhưng “steal” là nguyên mẫu nên không thể tạo thành câu bị động.","got stealing":"Sau “get” trong bị động không dùng V-ing; “stealing” không mang nghĩa bị lấy mất.","was stole":"Cấu trúc bị động cần V3 là “stolen”, còn “stole” chỉ là dạng quá khứ đơn của động từ."}],["It is believed ___ the old bridge was built in 1850.",["to","that","for","of"],1,"Cấu trúc It is believed that + mệnh đề; chủ ngữ giả “It” đi với “that” và mệnh đề “the old bridge was built”.",{"to":"Sau “It is believed” phải có mệnh đề đầy đủ, nên “to” không phù hợp với chủ ngữ giả “It”.","for":"Giới từ “for” không đi sau “It is believed” để dẫn một mệnh đề.","of":"“of” là giới từ nên không thể mở đầu một mệnh đề có chủ ngữ và động từ."}],["The suspect is said ___ in the city centre.",["living","that lives","to live","live"],2,"Dạng S + is said + to V dùng cho hành động hiện tại; chủ ngữ “The suspect” đứng trước “is said” nên cần “to live”.",{"living":"Sau “is said” cần động từ nguyên mẫu có “to”, không dùng V-ing ở cấu trúc này.","that lives":"Khi chủ ngữ thật “The suspect” đứng đầu câu thì không dùng “that + mệnh đề” sau “is said”.","live":"Thiếu “to”; cấu trúc đúng là S + is said + to + V."}],["The ancient temple is thought ___ over 800 years ago.",["to be built","to have built","being built","to have been built"],3,"Hành động xây dựng xảy ra trước lúc người ta “think”, nên dùng to have been built; “800 years ago” là tín hiệu.",{"to be built":"Đây là hiện tại bị động, không hợp với “over 800 years ago” là mốc đã qua trước hiện tại.","to have built":"Ngôi đền không tự xây nên cần bị động “been built”, không phải chủ động “built”.","being built":"V-ing không đi sau “is thought” và không diễn tả hành động đã xảy ra từ lâu."}]]},{"id":"past-perfect","lvl":"B1","title":"Past perfect","vi":"Quá khứ hoàn thành","exams":["CEFR","VSTEP","IELTS","TOEIC"],"form":"Khẳng định: S + had + V3.\nPhủ định: S + hadn't + V3.\nNghi vấn: Had + S + V3?","use":"Dùng để nói về một hành động xảy ra trước một mốc hoặc một hành động khác trong quá khứ, giúp người nghe biết việc nào xảy ra trước.","ex":[["When we arrived, the film had already started.","Khi chúng tôi đến, bộ phim đã bắt đầu rồi."],["She was upset because she had lost her keys.","Cô ấy buồn vì đã làm mất chìa khóa."],["I had never flown before that trip.","Trước chuyến đi đó tôi chưa từng đi máy bay."],["He said he had finished the report.","Anh ấy nói rằng anh ấy đã hoàn thành báo cáo."]],"err":[["When I arrived, the train has already left.","When I arrived, the train had already left.","Nói về việc xảy ra trước một mốc trong quá khứ thì dùng had + V3, không dùng has/have."],["She had went home before I called.","She had gone home before I called.","Sau had phải dùng quá khứ phân từ (V3): gone, không dùng went."],["I had visited Da Nang last summer.","I visited Da Nang last summer.","Khi chỉ có một hành động trong quá khứ với mốc rõ ràng, dùng quá khứ đơn; không cần quá khứ hoàn thành."]],"quiz":[["When we got to the cinema, the film ___ already.",["had started","has started","was starting","starts"],0,"Phim bắt đầu trước lúc chúng tôi đến rạp, với “already”, nên dùng had started.",{"has started":"Câu kể về quá khứ (“got to”), nên không dùng hiện tại hoàn thành “has started”.","was starting":"Quá khứ tiếp diễn nói việc đang diễn ra, không nói việc đã xong trước khi đến.","starts":"Hiện tại đơn không phù hợp với mốc quá khứ “when we got to the cinema”."}],["She was upset because she ___ her keys.",["has lost","had lost","was losing","loses"],1,"Việc mất chìa khóa xảy ra trước lúc buồn, nên dùng had lost để giải thích nguyên nhân.",{"has lost":"Hiện tại hoàn thành không phù hợp vì cả câu kể về quá khứ với “was upset”.","was losing":"Quá khứ tiếp diễn nói việc đang xảy ra, không nói việc đã mất trước khi buồn.","loses":"Hiện tại đơn lệch thì với “was upset” trong câu quá khứ."}],["The floor was wet because someone ___ it.",["has mopped","is mopping","had mopped","mops"],2,"Việc lau sàn xảy ra trước tình trạng ướt trong quá khứ, nên dùng had mopped.",{"has mopped":"Hiện tại hoàn thành không hợp với mệnh đề chính ở quá khứ “was wet”.","is mopping":"Hiện tại tiếp diễn lệch thì với “was wet” và không chỉ việc đã làm trước đó.","mops":"Hiện tại đơn nói thói quen, không giải thích tình trạng sàn ướt trong quá khứ."}],["I couldn't open the door because I ___ my key at home.",["have left","was leaving","leave","had left"],3,"Việc để quên chìa khóa xảy ra trước việc không mở được cửa, nên dùng had left.",{"have left":"Hiện tại hoàn thành lệch thì với “couldn't open” ở quá khứ.","was leaving":"Quá khứ tiếp diễn không diễn tả việc để quên chìa khóa đã xảy ra trước đó.","leave":"Hiện tại đơn không phù hợp với câu kể về quá khứ “couldn't”."}]]},{"id":"present-perfect-continuous","lvl":"B1","title":"Present perfect continuous","vi":"Hiện tại hoàn thành tiếp diễn","exams":["CEFR","VSTEP","IELTS"],"form":"Khẳng định: S + have/has been + V-ing.\nPhủ định: S + haven't/hasn't been + V-ing.\nNghi vấn: Have/Has + S + been + V-ing?","use":"Dùng để nhấn mạnh một hành động bắt đầu trong quá khứ và kéo dài đến hiện tại (với for/since), hoặc vừa mới diễn ra và để lại kết quả có thể nhìn thấy.","ex":[["I've been waiting for the bus for half an hour.","Tôi đã đợi xe buýt được nửa tiếng rồi."],["She has been learning German since January.","Cô ấy đã học tiếng Đức từ tháng Một."],["Your hands are dirty. Have you been gardening?","Tay bạn bẩn quá. Bạn vừa làm vườn à?"],["It has been raining all day.","Trời đã mưa suốt cả ngày."]],"err":[["I am living here since 2020.","I have been living here since 2020.","Có “since” (từ mốc quá khứ đến nay) thì không dùng hiện tại tiếp diễn; phải dùng have been + V-ing hoặc have + V3."],["She has been work here for two years.","She has been working here for two years.","Sau “been” phải là V-ing, không dùng động từ nguyên mẫu."],["I have been writing five emails today.","I have written five emails today.","Khi nói số lượng đã hoàn tất (five emails) thì dùng hiện tại hoàn thành đơn, không dùng tiếp diễn."]],"quiz":[["I ___ for the bus for twenty minutes, and it still hasn't come.",["have been waiting","wait","am waiting","waited"],0,"Hành động đợi bắt đầu trong quá khứ và vẫn kéo dài, có “for twenty minutes” và “still hasn't come”, nên dùng have been waiting.",{"wait":"Thì hiện tại đơn không đi với “for twenty minutes” để nói việc kéo dài đến hiện tại; câu cần dạng hoàn thành tiếp diễn.","am waiting":"Hiện tại tiếp diễn chỉ nói hành động ngay lúc này, không nối khoảng thời gian “for twenty minutes” từ quá khứ.","waited":"Quá khứ đơn nói hành động đã chấm dứt, nhưng “it still hasn't come” cho thấy việc đợi vẫn tiếp diễn."}],["Nam's hands are covered in soil. He ___ in the garden since six o'clock.",["digs","has been digging","dug","is digging"],1,"Có mốc “since six o'clock” và tay còn dính đất, nên cần has been digging cho việc kéo dài đến hiện tại.",{"digs":"Hiện tại đơn nói thói quen; “since six o'clock” cần thì hoàn thành, không dùng hiện tại đơn.","dug":"Quá khứ đơn không đi với “since six o'clock” để nói việc kéo dài đến bây giờ.","is digging":"Hiện tại tiếp diễn không kết hợp với “since”; mốc thời gian trong quá khứ cần have/has been + V-ing."}],["How long ___ studying English?",["are you","do you","have you been","did you been"],2,"Hỏi thời gian kéo dài đến hiện tại dùng How long + have you been + V-ing; sau blank có “studying” nên cần “been”.",{"are you":"Câu hỏi “How long” về quãng thời gian đến nay cần have you been, không dùng hiện tại tiếp diễn.","do you":"Hiện tại đơn “do you” thiếu dạng V-ing và không diễn tả khoảng thời gian kéo dài đến hiện tại.","did you been":"“Did” đi với động từ nguyên mẫu, không đi với “been”; cấu trúc này sai hoàn toàn."}],["I ___ Mr Hoang since 2015, and he is a very kind man.",["have been knowing","know","am knowing","have known"],3,"“Know” là động từ trạng thái, đi với “since 2015” nên dùng hiện tại hoàn thành đơn: have known.",{"have been knowing":"“Know” là động từ chỉ trạng thái nên không dùng ở dạng tiếp diễn, dù có “since”.","know":"Hiện tại đơn không đi với “since 2015” để nói mối quen biết kéo dài từ quá khứ.","am knowing":"Động từ trạng thái “know” không chia tiếp diễn, và “since” cần thì hoàn thành."}]]},{"id":"pronouns","lvl":"A1","title":"Subject and object pronouns","vi":"Đại từ chủ ngữ và tân ngữ","exams":["CEFR","VSTEP"],"form":"Chủ ngữ: I, you, he, she, it, we, they (đứng trước động từ).\nTân ngữ: me, you, him, her, it, us, them (sau động từ hoặc giới từ).","use":"Đại từ chủ ngữ thay cho người hoặc vật làm chủ ngữ; đại từ tân ngữ thay cho người hoặc vật nhận hành động, hoặc đứng sau giới từ.","ex":[["She works here and I like her.","Cô ấy làm việc ở đây và tôi quý cô ấy."],["Give the keys to him, please.","Làm ơn đưa chìa khóa cho anh ấy."],["We know them from university.","Chúng tôi biết họ từ hồi đại học."],["Who is it? It's me.","Ai đấy? Tôi đây."]],"err":[["Me like coffee.","I like coffee.","“Me” là đại từ tân ngữ; làm chủ ngữ trước động từ phải dùng “I”."],["She gave the book to I.","She gave the book to me.","Sau giới từ “to” dùng đại từ tân ngữ “me”, không dùng “I”."],["My sister she works in a clinic.","My sister works in a clinic.","Không nhắc lại chủ ngữ: danh từ “My sister” đã là chủ ngữ, không thêm “she”."]],"quiz":[["My brother is a doctor. ___ works at a big hospital.",["He","Him","His","They"],0,"Chỗ trống là chủ ngữ của “works” và thay cho “My brother” (nam, một người), nên dùng “He”.",{"Him":"“Him” là đại từ tân ngữ, không thể đứng trước động từ “works” làm chủ ngữ.","His":"“His” là sở hữu, nghĩa là “của anh ấy”, không thể làm chủ ngữ ở đây.","They":"“They” là số nhiều; “My brother” là một người nên cần “He”."}],["I like Sara. I often talk to ___.",["she","her","hers","herself"],1,"Sau giới từ “to” dùng đại từ tân ngữ; “Sara” là nữ nên chọn “her”.",{"she":"“She” là đại từ chủ ngữ; sau giới từ “to” cần đại từ tân ngữ.","hers":"“Hers” nghĩa là “của cô ấy”, không dùng thay cho người sau “to”.","herself":"“Herself” là đại từ phản thân, chỉ dùng khi chủ ngữ và tân ngữ là cùng một người."}],["Tom and I are friends. ___ study together every day.",["Us","Them","We","They"],2,"“Tom and I” gồm cả người nói, nên khi thay thế làm chủ ngữ dùng “We”.",{"Us":"“Us” là tân ngữ, không đứng đầu câu làm chủ ngữ cho “study”.","Them":"“Them” chỉ người khác, không gồm người nói; “Tom and I” là “chúng tôi”.","They":"“They” là ngôi thứ ba; người nói nằm trong “Tom and I” nên phải dùng “We”."}],["Ms Brown is our English teacher. We really like ___.",["she","hers","they","her"],3,"“Ms Brown” là một phụ nữ và đứng sau động từ “like” làm tân ngữ, nên dùng “her”.",{"she":"“She” là chủ ngữ; sau động từ “like” cần đại từ tân ngữ.","hers":"“Hers” nghĩa là “của cô ấy”, không chỉ người được yêu mến.","they":"“They” là số nhiều; “Ms Brown” chỉ một người nên không hợp."}]]},{"id":"quantifiers-2","lvl":"A2","title":"Each, every, all, both, either, neither","vi":"Lượng từ: each, every, all, both, either, neither","exams":["CEFR","VSTEP"],"form":"each / every + danh từ số ít + động từ số ít. all + danh từ số nhiều/không đếm được.\nboth + danh từ số nhiều + động từ số nhiều. either / neither + danh từ số ít (hai đối tượng).\neach / both / either / neither + of + the/my/them ...","use":"Dùng để nói về cả nhóm (all, every, each) hoặc về hai người, hai vật (both, either, neither). Cần chú ý danh từ và động từ đi kèm là số ít hay số nhiều.","ex":[["Every student has a locker.","Mỗi học sinh đều có một tủ khoá."],["Both of my parents work in a hospital.","Cả bố và mẹ tôi đều làm việc ở bệnh viện."],["You can take either bus; both go to the station.","Bạn đi xe buýt nào cũng được; cả hai đều đến nhà ga."],["Neither of the shops is open on Sunday.","Cả hai cửa hàng đều không mở cửa vào Chủ nhật."]],"err":[["Every students must wear a badge.","Every student must wear a badge.","Sau every dùng danh từ số ít, không thêm -s, dù ý nghĩa là cả nhóm."],["Both doors is open.","Both doors are open.","Both nói về hai cửa nên là số nhiều, động từ phải là “are”, không dùng “is”."],["She studied every day yesterday.","She studied all day yesterday.","Nói về suốt một khoảng thời gian thì dùng “all day”; “every day” nghĩa là ngày nào cũng làm."]],"quiz":[["___ student in the class has a locker.",["All","Both","Every","Either"],2,"“Student” là danh từ số ít và động từ “has” cũng số ít, nên dùng every. Câu nói về mọi học sinh trong lớp.",{"All":"“All” đi với danh từ số nhiều (all students), nhưng “student” ở đây là số ít.","Both":"“Both” chỉ dùng cho hai người, mà một lớp học có nhiều học sinh.","Either":"“Either” nghĩa là một trong hai, không hợp khi nói về cả lớp."}],["___ my parents are teachers.",["Every","Both","Each","Either"],1,"Hai người cùng làm một nghề thì dùng both + danh từ số nhiều. Động từ “are” cũng số nhiều.",{"Every":"“Every” cần danh từ số ít, còn “parents” là số nhiều.","Each":"“Each” cần danh từ số ít hoặc đi với “of”, nên không đứng trước “my parents”.","Either":"“Either” nghĩa là một trong hai và cần động từ số ít, không hợp với “are teachers”."}],["___ of the two shirts fits me; they are both too small.",["Neither","Either","Every","Both"],0,"Cả hai áo đều không vừa, nên dùng neither of the two + động từ số ít. Chữ “too small” cho thấy nghĩa phủ định.",{"Either":"“Either” mang nghĩa khẳng định (cái nào cũng được), trong khi câu nói cả hai đều không vừa.","Every":"“Every” không dùng với “of the two”; chỉ dùng cho nhóm từ ba trở lên.","Both":"“Both of the two shirts fits” sai vì “both” đi với động từ số nhiều “fit”."}],["You can take the bus or the train. ___ is fine.",["Either","Neither","Every","Both"],0,"Có hai lựa chọn và cái nào cũng được nên dùng either. Chữ “or” báo hiệu có hai khả năng.",{"Neither":"“Neither” nghĩa là không cái nào ổn, mâu thuẫn với ý “có thể đi bằng cái nào”.","Every":"“Every” cần danh từ đi sau và không dùng cho hai đối tượng.","Both":"“Both” đi với động từ số nhiều “are”, nhưng câu dùng “is”; nghĩa cũng không khớp ý chọn một trong hai."}]]},{"id":"relative-nondefining","lvl":"B2","title":"Non-defining relative clauses","vi":"Mệnh đề quan hệ không xác định","exams":["CEFR","VSTEP","IELTS"],"form":"N, who/which/whose/where/when + ..., (có dấu phẩy hai bên).\nS + V, which + V (which chỉ cả mệnh đề trước).\nGiới từ + whom/which: with whom, in which.","use":"Dùng để thêm thông tin phụ về một người hoặc vật đã rõ, không dùng để nhận dạng. Bỏ mệnh đề đi thì câu chính vẫn đủ nghĩa, và mệnh đề luôn nằm giữa dấu phẩy.","ex":[["My sister, who lives in Osaka, works as a dentist.","Chị tôi, người sống ở Osaka, làm nha sĩ."],["The new clinic, which opened in May, is already busy.","Phòng khám mới, mở cửa hồi tháng Năm, đã rất đông."],["She passed the exam, which surprised everyone.","Cô ấy đã đỗ kỳ thi, điều khiến ai cũng ngạc nhiên."],["Dr Park, with whom I work, is giving a talk.","Bác sĩ Park, người tôi cùng làm việc, sắp có bài nói."]],"err":[["The bridge, that was built in 1990, is closed.","The bridge, which was built in 1990, is closed.","Mệnh đề có dấu phẩy không dùng “that”; chọn “which” cho vật."],["The bus was late again, what made me angry.","The bus was late again, which made me angry.","“What” không làm đại từ quan hệ; dùng “which” cho cả mệnh đề phía trước."],["Mr Ono, whose his shop is on my street, sells fruit.","Mr Ono, whose shop is on my street, sells fruit.","“Whose” đã thay cho “his”, không lặp lại đại từ sở hữu."]],"quiz":[["My grandfather, ___ is 90, still walks every morning.",["who","that","which","whom"],0,"Dùng “who” cho người, làm chủ ngữ trong mệnh đề có dấu phẩy; dấu hiệu là “grandfather” và dấu phẩy.",{"that":"Sau dấu phẩy không dùng “that”; mệnh đề này thêm thông tin phụ.","which":"“Which” dùng cho vật, còn grandfather là người.","whom":"“Whom” là tân ngữ, nhưng ở đây từ cần thay thế đang làm chủ ngữ."}],["The new library, ___ opened last month, has a quiet study room.",["that","which","what","who"],1,"“Which” dùng cho vật trong mệnh đề không xác định; dấu hiệu là dấu phẩy sau “library”.",{"that":"Sau dấu phẩy không được dùng “that”.","what":"“What” không làm đại từ quan hệ, nên không nối được mệnh đề.","who":"“Who” chỉ người, còn library là vật."}],["Mr Tran, ___ daughter is a nurse, works at the clinic.",["who's","which","whose","whom"],2,"“Whose + danh từ” chỉ sở hữu; “whose daughter” nghĩa là con gái của ông Tran.",{"who's":"“Who's” là who is, không phù hợp: “who is daughter” sai nghĩa.","which":"“Which” chỉ vật, không thể chỉ người.","whom":"“Whom” là tân ngữ, không đứng trước danh từ daughter."}],["We stayed in Da Lat, ___ the weather is cool all year.",["which","that","when","where"],3,"“Where” thay cho “in + địa điểm”; dấu hiệu là Da Lat và dấu phẩy.",{"which":"“Which the weather is cool” thiếu giới từ in; không nối được.","that":"Sau dấu phẩy không dùng “that”, và “that” không chỉ nơi chốn ở đây.","when":"“When” chỉ thời gian, còn Da Lat là nơi chốn."}]]},{"id":"some-any","lvl":"A2","title":"Some, any, no and compounds","vi":"Some, any, no và các từ ghép","exams":["CEFR","VSTEP","TOEIC"],"form":"Khẳng định: some + danh từ đếm được số nhiều / không đếm được.\nPhủ định & câu hỏi: any. Nghĩa phủ định: no + danh từ.\nTừ ghép: some/any/no/every + one/body/thing/where.","use":"Dùng some, any, no để nói về một lượng không xác định, và dùng somebody, anything, nowhere... khi không nêu cụ thể người, vật hay nơi chốn. Dùng some trong lời mời và lời nhờ.","ex":[["There are some apples in the bag.","Có vài quả táo trong túi."],["I don't have any money today.","Hôm nay tôi không có đồng nào."],["Would you like some tea?","Bạn dùng chút trà nhé?"],["Is there anybody in the office?","Có ai trong văn phòng không?"]],"err":[["I don't have some time.","I don't have any time.","Câu phủ định dùng “any”, không dùng “some”."],["Nobody didn't call me.","Nobody called me.","“Nobody” đã mang nghĩa phủ định, nên động từ phải ở dạng khẳng định; không dùng hai từ phủ định."],["Can I have any water, please?","Can I have some water, please?","Lời nhờ vả dùng “some”, vì người nói mong nhận được; “any” nghe như hỏi có hay không."]],"quiz":[["There are ___ oranges in the bowl, so help yourself.",["some","any","no","anything"],0,"Câu khẳng định với danh từ đếm được số nhiều “oranges” dùng some, và “help yourself” cho thấy có cam trong bát.",{"any":"“Any” dùng trong phủ định hoặc câu hỏi; câu này là khẳng định nên không hợp.","no":"“No oranges” nói là không có cam, mâu thuẫn với “help yourself” (mời bạn tự lấy).","anything":"“Anything” là đại từ đứng một mình, không đứng trước danh từ “oranges”."}],["I'm sorry, we haven't got ___ tickets left.",["some","no","something","any"],3,"Câu phủ định “haven't got” cần any trước danh từ số nhiều “tickets”, nghĩa là không còn vé nào.",{"some":"“Some” không dùng trong câu phủ định thông thường như “haven't got”.","no":"“No” đã mang nghĩa phủ định, đi với “haven't” sẽ thành phủ định hai lần.","something":"“Something” là đại từ, không đứng trước danh từ “tickets”."}],["Is there ___ milk in the fridge?",["some","any","none","nothing"],1,"Câu hỏi Yes/No về danh từ không đếm được “milk” dùng any, vì người nói chưa biết có hay không.",{"some":"“Some” chỉ dùng trong câu hỏi khi mời hoặc nhờ; ở đây chỉ hỏi có hay không.","nothing":"“Nothing” là đại từ, không đứng trước danh từ “milk”.","none":"“None” là đại từ đứng một mình, không đứng trước danh từ “milk”."}],["There is ___ in the box. It's completely empty.",["something","anything","nothing","everything"],2,"“Completely empty” nghĩa là không có gì, nên dùng nothing với động từ khẳng định “is”.",{"something":"“Something” nghĩa là có một thứ nào đó, trái với “completely empty”.","anything":"“Anything” cần câu phủ định, trong khi câu này là khẳng định “There is”.","everything":"“Everything” nghĩa là mọi thứ đều có trong hộp, trái với “empty”."}]]},{"id":"subjunctive-formal","lvl":"B2","title":"Formal subjunctive, it's time, would rather","vi":"Giả định cách trang trọng, it's time, would rather","exams":["CEFR","VSTEP","IELTS"],"form":"suggest/insist/recommend/demand that + S + (should) + V nguyên mẫu.\nIt's (about/high) time + S + V2 (quá khứ đơn). Would rather + V; would rather + S + V2.\nI'd better (not) + V nguyên mẫu không “to”.","use":"Dùng để đề nghị, yêu cầu, khuyên nhủ một cách trang trọng, nói điều lẽ ra nên làm ngay bây giờ (it's time), hoặc bày tỏ sở thích, lời khuyên mạnh (would rather, had better).","ex":[["The doctor recommended that she rest for a week.","Bác sĩ khuyên cô ấy nên nghỉ ngơi một tuần."],["It's time we left; the bus is coming.","Đã đến lúc chúng ta đi rồi; xe buýt sắp tới."],["I'd rather you didn't smoke here.","Tôi mong bạn đừng hút thuốc ở đây."],["You'd better take an umbrella.","Bạn nên mang theo ô thì hơn."]],"err":[["She recommended that he goes to see a doctor.","She recommended that he (should) go to see a doctor.","Sau suggest/recommend/insist trang trọng dùng nguyên mẫu hoặc “should + V”, không chia -s theo ngôi."],["It's time we go home.","It's time we went home.","Sau “It's time + S” dùng quá khứ đơn dù nghĩa hiện tại: “went”."],["I'd rather to stay at home.","I'd rather stay at home.","Sau “would rather” là nguyên mẫu không “to”."]],"quiz":[["The doctor recommended that she ___ more water.",["drink","drinks","drank","drinking"],0,"Sau recommend that dùng giả định: nguyên mẫu không đổi theo ngôi, nên “she drink”; “recommended” là tín hiệu.",{"drinks":"Sau recommend that dùng nguyên mẫu, không chia -s dù chủ ngữ là “she”.","drank":"Quá khứ “drank” không dùng trong mệnh đề giả định sau recommend that.","drinking":"V-ing không đứng sau chủ ngữ “she” để làm động từ của mệnh đề that."}],["It's time we ___ the meeting; everyone is waiting.",["starts","started","have started","are starting"],1,"It's time + S + V2 chỉ việc nên làm ngay; “everyone is waiting” cho thấy đã đến lúc bắt đầu.",{"starts":"Sau “It's time we” dùng quá khứ đơn, không dùng hiện tại thêm -s.","have started":"Hiện tại hoàn thành không dùng sau “It's time we” trong cấu trúc này.","are starting":"Hiện tại tiếp diễn không đi với “It's time + S”; cần quá khứ đơn."}],["I'd rather you ___ your phone during the lesson.",["don't use","not to use","didn't use","won't use"],2,"Would rather + S + V2 diễn tả mong người khác làm; “you” là chủ ngữ mới nên dùng didn't use.",{"don't use":"Sau “would rather + S” dùng quá khứ đơn, nên “don't use” không đúng.","not to use":"“not to use” không đứng sau chủ ngữ “you” trong cấu trúc này.","won't use":"“won't use” là tương lai, không dùng sau would rather + chủ ngữ mới."}],["The rules demand that every visitor ___ a mask.",["wears","wore","wearing","wear"],3,"Demand that + S + V nguyên mẫu; dù “every visitor” là số ít vẫn dùng wear, không chia -s.",{"wears":"Sau demand that dùng nguyên mẫu, không thêm -s theo “every visitor”.","wore":"Quá khứ “wore” không đúng trong mệnh đề giả định sau demand.","wearing":"V-ing không làm động từ chính của mệnh đề that."}]]},{"id":"time-clauses","lvl":"B1","title":"Time clauses","vi":"Mệnh đề thời gian","exams":["CEFR","VSTEP","TOEIC","IELTS"],"form":"when / while / as soon as / until / before / after / by the time + S + V (hiện tại đơn cho tương lai)\nTương lai: I'll call you when I arrive. (không dùng will sau when)","use":"Dùng để nói một hành động xảy ra lúc nào so với hành động khác. Khi nói về tương lai, mệnh đề thời gian dùng hiện tại đơn, không dùng will.","ex":[["I'll call you as soon as I get home.","Tôi sẽ gọi cho bạn ngay khi về đến nhà."],["She was reading while the children were playing.","Cô ấy đang đọc sách trong lúc bọn trẻ chơi."],["Wait here until the nurse comes.","Hãy đợi ở đây cho đến khi y tá đến."],["By the time we arrived, the film had started.","Khi chúng tôi đến, bộ phim đã bắt đầu rồi."]],"err":[["I will call you when I will arrive.","I will call you when I arrive.","Trong mệnh đề thời gian chỉ tương lai dùng hiện tại đơn, không dùng will."],["Please wait until he will come.","Please wait until he comes.","Sau until dùng hiện tại đơn khi nói về tương lai."],["I fell asleep during I was watching TV.","I fell asleep while I was watching TV.","Sau during là danh từ; trước một mệnh đề phải dùng while."]],"quiz":[["I'll send you the report as soon as I ___ it.",["finish","will finish","am finishing","finished"],0,"Sau as soon as nói về tương lai dùng hiện tại đơn; chủ ngữ “I” nên dùng finish.",{"will finish":"Không dùng will trong mệnh đề sau as soon as khi nói về tương lai.","am finishing":"Hiện tại tiếp diễn không hợp ở mệnh đề thời gian này, vì ý là hoàn thành xong.","finished":"Quá khứ đơn không hợp vì mệnh đề chính dùng “I'll”, nói về tương lai."}],["The phone rang while I ___ a shower.",["had taken","was taking","am taking","take"],1,"Hành động đang diễn ra bị cắt ngang dùng quá khứ tiếp diễn sau while: was taking.",{"had taken":"Quá khứ hoàn thành nói việc tắm đã xong trước đó, không diễn tả việc đang tắm thì điện thoại reo.","am taking":"Hiện tại tiếp diễn sai thì, vì câu chính “rang” ở quá khứ.","take":"Hiện tại đơn sai thì, vì câu kể về một việc đã xảy ra."}],["Please wait here until the doctor ___ you.",["will call","called","calls","would call"],2,"Sau until nói về tương lai dùng hiện tại đơn; chủ ngữ số ít nên calls.",{"will call":"Không dùng will sau until khi nói về việc sẽ xảy ra.","called":"Quá khứ đơn không hợp với lời yêu cầu “Please wait here” ở hiện tại.","would call":"Would call là dạng điều kiện hoặc tương lai trong quá khứ, không hợp ở đây."}],["I fell asleep ___ the long film.",["during","while","when","as soon as"],0,"Sau chỗ trống là cụm danh từ “the long film”, nên dùng giới từ during.",{"while":"While phải đi với một mệnh đề có chủ ngữ và động từ, không đi với cụm danh từ.","when":"When đi với mệnh đề, không đi với cụm danh từ ở vị trí này.","as soon as":"As soon as cũng cần một mệnh đề đầy đủ."}]]},{"id":"verb-object-infinitive","lvl":"B1","title":"Verb + object + infinitive","vi":"Động từ + tân ngữ + động từ nguyên mẫu","exams":["CEFR","VSTEP","IELTS"],"form":"S + want/ask/tell/advise/allow/expect + O + to V.\nS + make/let + O + V (không có to).\nPhủ định: ... + O + not to V.","use":"Dùng khi bạn muốn ai đó làm một việc: yêu cầu, khuyên, cho phép, bắt buộc hoặc mong đợi. Tân ngữ đứng ngay sau động từ chính, rồi mới đến động từ nguyên mẫu.","ex":[["The doctor advised me to rest for a week.","Bác sĩ khuyên tôi nghỉ ngơi một tuần."],["My manager let us leave early on Friday.","Quản lý cho phép chúng tôi về sớm vào thứ Sáu."],["I'd like you to check the results again.","Tôi muốn bạn kiểm tra lại kết quả."],["The nurse told the visitors not to touch the equipment.","Y tá dặn những người đến thăm không được chạm vào thiết bị."]],"err":[["She wants that I help her.","She wants me to help her.","Sau “want” dùng tân ngữ + to V, không dùng “that” + mệnh đề như tiếng Việt “muốn rằng”."],["The teacher made us to repeat the sentence.","The teacher made us repeat the sentence.","Sau “make” và “let” dùng động từ nguyên mẫu không “to”."],["He told me don't open the door.","He told me not to open the door.","Câu phủ định gián tiếp dùng “not to V”, không dùng “don't”."]],"quiz":[["The doctor advised me ___ more water.",["to drink","drink","drinking","that drink"],0,"“Advise + tân ngữ + to V”: dấu hiệu là “advised me” nên động từ sau phải là “to drink”.",{"drink":"Chỉ make và let mới đi với động từ nguyên mẫu không “to”; “advise me” cần “to drink”.","drinking":"Sau “advise + tân ngữ” ta dùng to V, không dùng V-ing trong cấu trúc này.","that drink":"“That” cần một mệnh đề đầy đủ; ở đây câu cần tân ngữ me rồi đến to V."}],["My boss let me ___ home early on Friday.",["to leave","leave","leaving","left"],1,"“Let + tân ngữ + V nguyên mẫu” không có “to”; “let me leave” là cấu trúc đúng.",{"to leave":"Sau “let + tân ngữ” động từ phải ở dạng nguyên mẫu không “to”.","leaving":"V-ing không đi sau “let me”; cần động từ nguyên mẫu.","left":"Dạng quá khứ left không thể đứng sau tân ngữ của “let”."}],["The sad film made everyone ___ at the end.",["cry","to cry","crying","cried"],0,"“Make + O + V” nghĩa là khiến ai làm gì và không có “to”; dấu hiệu là “made everyone”.",{"to cry":"“Make” chủ động không dùng “to” sau tân ngữ everyone.","crying":"V-ing không dùng trong cấu trúc make + O + V.","cried":"Sau tân ngữ phải là nguyên mẫu, không chia quá khứ lần nữa."}],["I'd like you ___ the form before noon.",["sign","signing","signed","to sign"],3,"“Would like + O + to V” là cách yêu cầu lịch sự; dấu hiệu là “I'd like you”.",{"sign":"“Would like” khác “let/make”: sau tân ngữ you phải có “to”.","signing":"“Would like you” không đi với V-ing ở nghĩa mong muốn này.","signed":"Dạng quá khứ phân từ không dùng ở đây, câu cần to V."}]]}];
  const BANK = {"adjectives-adverbs":"c|The nurse spoke ___ to the frightened child.|gently / gentle / gentleness / more gentle|0|Bổ nghĩa cho động từ “spoke” cần trạng từ cách thức, và gently là trạng từ của gentle.|gentle=>“Gentle” là tính từ, không bổ nghĩa cho động từ “spoke”.;;gentleness=>“Gentleness” là danh từ, không dùng làm trạng từ sau động từ.;;more gentle=>“More gentle” là so sánh hơn, không có “than” hay ngữ cảnh so sánh nào.\nc|My sister is a very ___ cook.|nicely / well / goodly / good|3|Trước danh từ “cook” cần tính từ, và good là tính từ tương ứng với “well”.|well=>“Well” là trạng từ, không đứng trước danh từ “cook”.;;goodly=>“Goodly” là từ hiếm, không dùng với nghĩa giỏi trong câu này.;;nicely=>“Nicely” là trạng từ, không đứng trước danh từ “cook”.\nc|This coffee tastes ___. Can I have another cup?|wonderfully / wonderful / wonder / wonderfulness|1|Taste là linking verb nên đi với tính từ wonderful; “another cup” cho thấy cà phê ngon.|wonderfully=>“Wonderfully” là trạng từ, không dùng sau linking verb “tastes”.;;wonder=>“Wonder” là danh từ hoặc động từ, không mô tả vị của cà phê.;;wonderfulness=>“Wonderfulness” là danh từ hiếm, không dùng sau “tastes”.\nc|He drove so ___ that we arrived an hour early.|fastly / faster / fast / fastest|2|Fast vừa là tính từ vừa là trạng từ, không có dạng “fastly”; “so ___ that” dùng dạng gốc.|fastly=>“Fastly” không tồn tại trong tiếng Anh chuẩn.;;faster=>“Faster” là so sánh hơn, không hợp với cấu trúc “so ... that”.;;fastest=>“Fastest” là so sánh nhất, không hợp với cấu trúc “so ... that”.\nc|You look ___. Did you sleep badly last night?|tiredly / tiredness / tire / tired|3|Look là linking verb, nên đi với tính từ tired; “sleep badly” giải thích vì sao trông mệt.|tiredly=>“Tiredly” là trạng từ, không dùng sau linking verb “look”.;;tiredness=>“Tiredness” là danh từ, câu cần tính từ mô tả vẻ mặt.;;tire=>“Tire” là động từ, không mô tả vẻ mặt trong câu này.\nc|The students worked ___ for the exam, so they passed.|hard / hardly / hardness / hardworking|0|Hard là trạng từ chỉ làm việc chăm chỉ; “so they passed” xác nhận họ học chăm.|hardly=>“Hardly” nghĩa là hầu như không, mâu thuẫn với “so they passed”.;;hardness=>“Hardness” là danh từ, không dùng như trạng từ sau “worked”.;;hardworking=>“Hardworking” là tính từ, không bổ nghĩa cho động từ “worked”.\nc|It was a ___ film, and everyone cried at the end.|sadly / sadness / sad / sadden|2|Trước danh từ “film” cần tính từ sad; “everyone cried” gợi nội dung buồn.|sadly=>“Sadly” là trạng từ, không đứng trước danh từ “film”.;;sadness=>“Sadness” là danh từ, không bổ nghĩa cho “film” như một tính từ.;;sadden=>“Sadden” là động từ, không đứng trước danh từ “film” như một tính từ.\nc|The patient is feeling much ___ after the operation.|good / better / well / best|1|Sau “much” cần dạng so sánh hơn; better là so sánh của cả good lẫn well, và “after the operation” cho thấy sự cải thiện.|good=>“Good” không đi với “much” theo nghĩa cải thiện; cần dạng so sánh.;;well=>“Well” không có dạng so sánh với “much” ở vị trí này.;;best=>“Best” là so sánh nhất, không hợp với “much”.\nc|She answered all the questions very ___.|correctly / correct / correction / corrected|0|Bổ nghĩa cho động từ “answered” cần trạng từ correctly.|correct=>“Correct” là tính từ, không bổ nghĩa cho động từ “answered”.;;correction=>“Correction” là danh từ, không đứng sau “very” ở vị trí này.;;corrected=>“Corrected” là dạng động từ, không đứng sau “very” để chỉ cách trả lời.\nc|Please speak more ___. I can't follow you.|slow / slower / slowness / slowly|3|Cấu trúc “more + trạng từ” bổ nghĩa cho “speak”, và slowly là trạng từ.|slow=>“More slow” sai vì slow là tính từ; ở đây cần trạng từ.;;slowness=>“Slowness” là danh từ, không đứng sau “more” trong cấu trúc này.;;slower=>“More slower” sai vì đã có “more”, không thêm dạng so sánh nữa.\nc|That dress looks ___ on you.|beautifully / beautiful / beauty / beautify|1|Look là linking verb nên đi với tính từ beautiful, nói về cái váy trông như thế nào.|beautifully=>“Beautifully” là trạng từ, không dùng sau linking verb “looks”.;;beauty=>“Beauty” là danh từ, không mô tả dáng vẻ như tính từ.;;beautify=>“Beautify” là động từ, không đứng sau “looks on you” ở đây.\nc|The baby was sleeping ___ when I came in.|peaceful / peace / peacefully / peacefulness|2|Bổ nghĩa cho động từ “was sleeping” cần trạng từ peacefully.|peaceful=>“Peaceful” là tính từ, không bổ nghĩa cho động từ “sleeping”.;;peace=>“Peace” là danh từ, không dùng làm trạng từ.;;peacefulness=>“Peacefulness” là danh từ trừu tượng, không đứng sau động từ này.\nc|He's a ___ runner. He finished the race in under an hour.|quickly / quickest / quickness / quick|3|Trước danh từ “runner” cần tính từ quick.|quickly=>“Quickly” là trạng từ, không đứng trước danh từ “runner”.;;quickness=>“Quickness” là danh từ, không mô tả danh từ “runner”.;;quickest=>“Quickest” là so sánh nhất, cần “the” và không có nhóm so sánh.\nc|I arrived ___ for the lecture, so I missed the first part.|late / lateness / latest / lately|0|Late vừa là tính từ vừa là trạng từ nghĩa là trễ; “missed the first part” xác nhận.|lately=>“Lately” nghĩa là gần đây, không phải trễ giờ.;;lateness=>“Lateness” là danh từ, không đứng sau “arrived”.;;latest=>“Latest” là so sánh nhất, không đúng với nghĩa trễ.\nx|Chọn câu đúng|She dances beautiful. / She is dancing beautiful. / She dances beautifully. / She dance beautifully.|2|Bổ nghĩa cho động từ “dances” cần trạng từ beautifully, và chủ ngữ she cần động từ có -s.|She dances beautiful.=>“Beautiful” là tính từ, không bổ nghĩa cho động từ “dances”.;;She is dancing beautiful.=>Đây vẫn dùng tính từ “beautiful” sau động từ, nên sai như câu đầu.;;She dance beautifully.=>Chủ ngữ “She” cần động từ có -s, không dùng “dance” ở đây.\nx|Chọn câu đúng nhất|He felt happily after the news. / He felt happy after the news. / He feeled happy after the news. / He was feel happy after the news.|1|Felt là linking verb nên đi với tính từ happy.|He felt happily after the news.=>Linking verb “felt” đi với tính từ, không đi với trạng từ happily.;;He was feel happy after the news.=>“Was feel” sai cấu trúc; chỉ dùng một động từ chính.;;He feeled happy after the news.=>“Feeled” sai dạng quá khứ; quá khứ bất quy tắc của feel là “felt”.\nx|Chọn câu đúng ngữ pháp|The soup smells nice. / The soup smells nicely. / The soup smell nice. / The soup is smell nice.|0|Smell là linking verb nên đi với tính từ nice; chủ ngữ số ít cần smells.|The soup smells nicely.=>Sau “smells” cần tính từ chứ không dùng trạng từ nicely.;;The soup smell nice.=>Chủ ngữ “The soup” số ít cần động từ “smells”, không phải “smell”.;;The soup is smell nice.=>“Is smell” sai vì hai động từ liền nhau.\nx|Chọn câu viết đúng|Drive careful in the rain. / Drives carefully in the rain. / Drive carefulness in the rain. / Drive carefully in the rain.|3|Bổ nghĩa cho động từ “drive” cần trạng từ carefully, và câu mệnh lệnh dùng động từ nguyên mẫu.|Drive careful in the rain.=>“Careful” là tính từ, không bổ nghĩa cho động từ “drive”.;;Drive carefulness in the rain.=>“Carefulness” là danh từ, không đứng sau động từ như trạng từ.;;Drives carefully in the rain.=>Câu mệnh lệnh dùng “Drive”, không thêm -s.\nx|Chọn câu không có lỗi|The test was hardly difficult, so everyone failed. / The test was very difficult, so everyone failed. / The test was difficultly, so everyone failed. / The test was difficulty, so everyone failed.|1|Sau be dùng tính từ difficult; “very difficult” hợp với “everyone failed”.|The test was hardly difficult, so everyone failed.=>“Hardly difficult” nghĩa là hầu như không khó, mâu thuẫn với “everyone failed”.;;The test was difficultly, so everyone failed.=>“Difficultly” không phải trạng từ chuẩn và không dùng sau be.;;The test was difficulty, so everyone failed.=>“Difficulty” là danh từ, không dùng sau “was” để mô tả bài kiểm tra.\nt|He is a good singer. He sings very ___ (good).|well|Bổ nghĩa cho động từ “sings” cần trạng từ; trạng từ của good là well.\nt|They talked ___ (quiet) so as not to wake the baby.|quietly|Bổ nghĩa cho động từ “talked” cần trạng từ quietly.\nt|The exam was ___ (easy), so I finished quickly.|easy|Sau “was” là linking verb nên dùng tính từ easy.\nt|She is working ___ (hard) this week because of the deadline.|hard|Hard là trạng từ có hình thức giống tính từ, không thêm -ly.\nf|She runs very quick for her age.|quick|quickly|Bổ nghĩa cho động từ “runs” cần trạng từ quickly.\nf|The medicine tastes terribly.|terribly|terrible|Sau linking verb “tastes” dùng tính từ terrible.\nf|My brother plays the guitar good.|good|well|Bổ nghĩa cho động từ “plays” cần trạng từ well.\no|The doctor listened carefully to the patient.|Động từ, giới từ, tân ngữ: trạng từ cách thức thường đứng ngay sau động từ hoặc sau tân ngữ; ở đây trước “to the patient”.","as-as":"c|This phone is ___ expensive as that one.|so / as / than / like|1|So sánh bằng khẳng định dùng as + tính từ + as. Chỗ trống đầu tiên cần “as”, vì phía sau đã có “as that one”.|so=>“So … as” chỉ dùng trong câu phủ định; câu này khẳng định (is), nên phải dùng as … as.;;than=>“Than” đi với dạng so sánh hơn như “more expensive”, còn ở đây có “as” phía sau nên cần as … as.;;like=>“Like” không đứng trước tính từ để so sánh bằng; cấu trúc cần là as + tính từ + as.\nc|The exam wasn't ___ difficult as I expected.|as / than / more / too|0|Câu phủ định so sánh bằng có dạng not as + tính từ + as. Chữ “as I expected” phía sau cho thấy cần “as” ở chỗ trống.|than=>“Than” dùng với dạng so sánh hơn; câu này có “as I expected” nên cần as … as.;;more=>“More difficult” phải đi với “than”, không đi với “as I expected”.;;too=>“Too difficult” nghĩa là quá khó, không tạo được phép so sánh với “as I expected”.\nc|Her handwriting is the same ___ mine.|with / like / as / than|2|Cấu trúc đúng là the same as + danh từ hoặc đại từ. Ở đây “mine” là vế được so sánh nên cần “as”.|with=>Sau “the same” dùng “as” để nối với vế so sánh, không dùng “with”.;;like=>“The same like” là lỗi hay gặp; cấu trúc đúng là the same as.;;than=>“Than” chỉ dùng với dạng so sánh hơn, không đi với “the same”.\nc|My opinion is different ___ yours.|as / with / of / from|3|Tính từ different đi với giới từ “from” (hoặc “to” trong tiếng Anh Anh). Vế sau là “yours” nên chọn “from”.|as=>“Different as” không tồn tại; “as” dùng trong the same as, không dùng với different.;;with=>“Different with” là lỗi hay gặp do tiếng Việt; tính từ different đi với “from”.;;of=>“Of” không đi với different khi so sánh hai ý kiến.\nc|There aren't ___ chairs as students in the room.|as many / as much / so much / more|0|Danh từ đếm được số nhiều như “chairs” đi với as many … as. Chữ “as students” cho thấy đây là so sánh bằng về số lượng.|as much=>“Much” dùng với danh từ không đếm được, mà “chairs” là danh từ đếm được số nhiều.;;so much=>“So much” cũng đi với danh từ không đếm được nên không hợp với “chairs”.;;more=>“More” cần “than” đi sau, trong khi câu này dùng “as students”.\nc|I drink ___ coffee as my sister, about three cups a day.|as many / as much / so many / as more|1|“Coffee” là danh từ không đếm được nên dùng as much … as. Chữ “as my sister” xác nhận đây là so sánh bằng.|as many=>“Many” dùng với danh từ đếm được số nhiều, mà “coffee” là danh từ không đếm được.;;as more=>“As more” không tồn tại trong tiếng Anh; không dùng as với more.;;so many=>“Many” dùng với danh từ đếm được số nhiều, mà “coffee” là danh từ không đếm được.\nc|Dr Lan works as ___ as her colleagues.|hardly / harder / hard / hardest|2|Giữa as … as dùng dạng gốc của trạng từ; “hard” vừa là tính từ vừa là trạng từ, nên không thêm -ly.|hardly=>“Hardly” nghĩa là hầu như không, đổi hẳn nghĩa; trạng từ của “hard” vẫn là “hard”.;;harder=>Giữa as … as phải dùng dạng gốc, không dùng dạng so sánh hơn “harder”.;;hardest=>Dạng so sánh nhất “hardest” không dùng giữa as … as.\nc|Tom speaks English as ___ as a native speaker.|fluent / fluently / more fluently / fluenter|1|Động từ “speaks” cần trạng từ, nên dùng as + trạng từ + as: “as fluently as”. Dạng gốc luôn nằm giữa hai chữ as.|fluent=>Động từ “speaks” cần trạng từ bổ nghĩa, nên “fluent” (tính từ) không phù hợp ở đây.;;more fluently=>Giữa as … as không dùng dạng so sánh hơn “more fluently”.;;fluenter=>“Fluenter” không tồn tại; và giữa as … as cũng không dùng dạng so sánh hơn.\nc|Their house is similar ___ ours.|with / as / to / than|2|Tính từ similar luôn đi với giới từ “to”. Vế “ours” là đối tượng được so sánh nên dùng “similar to”.|with=>“Similar with” là lỗi do dịch từ tiếng Việt; tính từ similar đi với “to”.;;as=>“Similar as” không đúng; cấu trúc cần là similar to hoặc the same as.;;than=>“Than” chỉ dùng với dạng so sánh hơn, không đi với similar.\nc|He isn't the same age ___ me; he's older.|like / than / to / as|3|Cấu trúc the same + danh từ + as: “the same age as me”. Phần “he’s older” chỉ giải thích thêm, không đổi cấu trúc.|like=>“The same age like me” là lỗi hay gặp; sau the same + danh từ dùng “as”.;;than=>“Than” dành cho so sánh hơn, không đi với “the same age”.;;to=>“The same … to” không đúng; cấu trúc là the same + danh từ + as.\nc|Run as ___ as you can to catch the bus.|fast / faster / fastly / fastest|0|As … as đi với dạng gốc; “fast” là trạng từ bất quy tắc nên không thêm -ly. Vì vậy câu đúng là “as fast as you can”.|faster=>Giữa as … as không dùng dạng so sánh hơn “faster”.;;fastly=>“Fastly” không tồn tại; “fast” vừa là tính từ vừa là trạng từ.;;fastest=>Dạng so sánh nhất không dùng giữa as … as.\nc|Take as ___ medicine as the doctor says, no more.|many / much / few / more|1|“Medicine” là danh từ không đếm được, nên dùng as much … as. Cụm “no more” cho biết giới hạn đúng bằng lượng bác sĩ nói.|many=>“Medicine” là danh từ không đếm được nên không đi với “many”.;;few=>“Few” không đi với as … as và cũng dùng cho danh từ đếm được.;;more=>“As more as” không đúng; cần as much … as với danh từ không đếm được.\nc|The new library is as big ___ the old one.|than / that / as / like|2|So sánh bằng cần hai chữ as: as big as. Chữ as đầu đã có, nên chỗ trống phải là “as” thứ hai.|than=>“As big than” trộn hai cấu trúc; so sánh bằng cần as … as.;;that=>“That” không dùng để nối vế so sánh bằng; cần chữ “as” thứ hai.;;like=>“Like” không thay được chữ “as” thứ hai trong cấu trúc as … as.\nc|Is your cough the same ___ yesterday?|as / than / like / with|0|Cấu trúc the same as + mốc so sánh. Ở đây “yesterday” là mốc so sánh nên dùng “the same as yesterday”.|than=>“Than” dành cho so sánh hơn nên không đi với “the same”.;;like=>“The same like yesterday” là lỗi hay gặp; đúng là the same as.;;with=>“The same with” không đúng trong cấu trúc so sánh này; cần “as”.\nx|Chọn câu đúng|Ben is as tall as his brother. / Ben is as taller as his brother. / Ben is as tall than his brother. / Ben is so tall as his brother.|0|So sánh bằng khẳng định có dạng as + tính từ gốc + as. Chỉ câu đầu giữ đúng dạng này.|Ben is as taller as his brother.=>Giữa as … as phải dùng dạng gốc “tall”, không dùng dạng so sánh hơn “taller”.;;Ben is as tall than his brother.=>Chữ “than” đi với so sánh hơn; so sánh bằng cần chữ as thứ hai.;;Ben is so tall as his brother.=>“So … as” chỉ dùng trong câu phủ định; câu khẳng định dùng as … as.\nx|Chọn câu đúng|She ran as fast than she could. / She ran as fastly as she could. / She ran as fast as she could. / She ran so fast like she could.|2|So sánh bằng là as + trạng từ gốc + as; “fast” là trạng từ không đổi dạng, và vế sau nối bằng “as”.|She ran as fast than she could.=>“Than” chỉ đi với dạng so sánh hơn; sau “as fast” phải có chữ “as” thứ hai.;;She ran as fastly as she could.=>“Fast” vừa là tính từ vừa là trạng từ, không có dạng “fastly”.;;She ran so fast like she could.=>“So … like” không phải cấu trúc so sánh bằng; cần “as fast as”.\nx|Chọn câu đúng|There isn't as many traffic today as yesterday. / There isn't so many traffic today as yesterday. / There isn't as much traffic today than yesterday. / There isn't as much traffic today as yesterday.|3|“Traffic” không đếm được nên dùng as much … as, và vế sau phải là chữ “as”. Chỉ một câu thoả cả hai điều kiện.|There isn't as many traffic today as yesterday.=>“Traffic” là danh từ không đếm được nên không đi với “many”.;;There isn't so many traffic today as yesterday.=>“So many” đi với danh từ đếm được, mà “traffic” không đếm được.;;There isn't as much traffic today than yesterday.=>Dùng “as … as” thì vế sau phải là “as”, không phải “than”.\nx|Chọn câu đúng|Our ward is not as busier as it was last week. / Our ward is not as busy as it was last week. / Our ward is not so busy than it was last week. / Our ward is not as busy like it was last week.|1|Phủ định so sánh bằng: not as + tính từ gốc + as. Chỉ câu này giữ đúng tính từ gốc và chữ as thứ hai.|Our ward is not as busier as it was last week.=>Giữa as … as dùng tính từ gốc “busy”, không dùng “busier”.;;Our ward is not so busy than it was last week.=>Cấu trúc not so … as cần chữ “as”, không dùng “than”.;;Our ward is not as busy like it was last week.=>Vế sau của as … as phải là “as”, không phải “like”.\nt|Lan's bag is the same ___ mine.|as|Sau the same dùng “as” để nối với vế được so sánh: the same as mine.\nt|My new job isn't ___ stressful as my old job.|as;so|Câu phủ định so sánh bằng dùng not as/so + tính từ + as, nên chỗ trống là “as” hoặc “so”.\nt|He drives as ___ (careful) as a bus driver.|carefully|Động từ “drives” cần trạng từ, nên đổi “careful” thành “carefully” giữa as … as.\nt|Your pen is similar ___ mine.|to|Tính từ similar đi với giới từ “to”: similar to mine.\nt|My timetable is different ___ my friend's.|from;to|Tính từ different đi với “from” (hoặc “to” trong tiếng Anh Anh).\nf|My room is as small than yours.|than|as|So sánh bằng cần chữ as thứ hai: as small as; “than” chỉ dùng với dạng so sánh hơn.\nf|She is the same age like her cousin.|like|as|Sau the same + danh từ dùng “as”: the same age as her cousin.\nf|He earns as many money as I do.|many|much|“Money” là danh từ không đếm được nên dùng as much … as, không dùng “many”.\no|Lan doesn't have as many friends as her sister.|Cấu trúc not as many + danh từ đếm được số nhiều + as + người so sánh; trợ động từ doesn't đứng trước have.","can-ability":"c|My little sister is only four, but she ___ read already.|cans / can / can to / is can|1|Chủ ngữ “she” vẫn đi với “can” nguyên dạng, và sau đó là động từ “read” không có “to”.|cans=>Động từ khuyết thiếu “can” không thêm -s dù chủ ngữ “she” là ngôi thứ ba số ít.;;can to=>Sau “can” phải dùng động từ nguyên mẫu không “to”, nên “can to read” là sai.;;is can=>Không dùng “is” cùng “can”; “can” đã đóng vai trò trợ động từ rồi.\nc|I'm sorry, I ___ come to the party tomorrow. I have to work.|can't / don't can / can / no can|0|“I'm sorry” và lý do phải đi làm cho thấy cần dạng phủ định “can't” để nói không thể đến.|don't can=>Không dùng “do” với “can”; muốn phủ định chỉ cần thêm “not” vào “can”.;;can=>Câu có “I'm sorry” và “have to work” cho thấy người nói không thể đến, nên cần dạng phủ định.;;no can=>“no can” không phải cấu trúc đúng trong tiếng Anh chuẩn; phủ định của “can” là “can't” hoặc “cannot”.\nc|___ you help me with this heavy box, please?|Do / Are / Can / Does|2|Muốn nhờ ai giúp ta dùng “Can you + V ...?”, và “please” xác nhận đây là lời nhờ vả.|Do=>“Do you help me” sẽ thiếu “can”; để nhờ vả cần động từ khuyết thiếu, không dùng “do”.;;Are=>“Are” cần đi với tính từ hoặc V-ing, không thể đứng trước “help” để nhờ vả.;;Does=>“Does” dùng với he/she/it, và cũng không tạo thành câu nhờ vả với động từ nguyên mẫu.\nc|When my father was young, he ___ run ten kilometres without stopping.|can / cans / is could / could|3|Mệnh đề “when my father was young” chỉ quá khứ, nên dùng “could” để nói khả năng trong quá khứ.|can=>“when ... was young” chỉ quá khứ nên không dùng “can” ở hiện tại.;;cans=>“can” không bao giờ thêm -s, và ở đây còn sai thì.;;is could=>Không dùng “is” trước “could”; “could” tự đứng trước động từ nguyên mẫu.\nc|A: Is it OK if I open the window? B: Yes, you ___.|cans / can / can to / do|1|Trả lời ngắn lặp lại trợ động từ trong câu hỏi: hỏi xin phép bằng “can”, đáp “Yes, you can.”|cans=>“can” không thêm -s, kể cả khi chủ ngữ là “you” hay ngôi thứ ba.;;can to=>“can to” sai vì sau “can” không có “to”, và câu trả lời ngắn không cần động từ sau đó.;;do=>Câu hỏi dùng “open the window” nên trả lời ngắn phải nhắc lại “can”, không dùng “do”.\nc|Ben ___ speak Japanese, but he can speak Korean.|can't / can / couldn't / doesn't can|0|“but” tạo đối lập: vế sau khẳng định “can speak Korean”, vậy vế đầu là “can't speak Japanese”.|can=>Chữ “but” báo hiệu sự đối lập với vế sau “can speak Korean”, nên vế đầu phải phủ định.;;couldn't=>“could” chỉ quá khứ, trong khi vế sau “can speak” ở hiện tại nên vế đầu cũng phải hiện tại.;;doesn't can=>Không dùng “doesn't” với “can”; chỉ cần “can't”.\nc|___ I borrow your pen for a moment?|Do / Could / Am / Would|1|Xin phép làm gì dùng “Could I + V ...?” (lịch sự) hoặc “Can I + V ...?”.|Do=>“Do I borrow” không phải cách xin phép; cần động từ khuyết thiếu “can/could”.;;Am=>“Am” cần đi với tính từ hoặc V-ing, không thể đi trước “borrow”.;;Would=>“Would I borrow” không dùng để xin phép; xin phép thường dùng “Can/Could I ...?”.\nc|The baby is only eight months old. He ___ walk yet.|can / doesn't can / can't / isn't can|2|Em bé 8 tháng và từ “yet” cho thấy chưa làm được, nên dùng “can't walk yet”.|can=>“yet” và tuổi 8 tháng cho thấy em bé chưa đi được, nên cần phủ định.;;doesn't can=>Không dùng trợ động từ “does” với “can”; phủ định của “can” là “can't”.;;isn't can=>“isn't can” không tồn tại; “can” không đi cùng “be”.\nc|I was very tired last night, so I ___ sleep until two o'clock.|can't / can / wasn't can / couldn't|3|“last night” chỉ quá khứ và “so” cho thấy hậu quả không ngủ được, nên dùng “couldn't sleep”.|can't=>“last night” chỉ quá khứ, nên không dùng “can't” ở hiện tại.;;can=>Câu nói mệt mỏi và thức tới hai giờ, nghĩa là không ngủ được, nên khẳng định là sai.;;wasn't can=>Không dùng “wasn't” với “can”; dạng phủ định quá khứ là “couldn't”.\nc|Excuse me, ___ you tell me where the clinic is?|could / did / are / does|0|Với người lạ, “Excuse me” đi kèm “Could you + V ...?” là cách nhờ lịch sự.|did=>“Did you tell me” hỏi về hành động đã xảy ra, không phải lời nhờ lịch sự chỉ đường.;;are=>“Are you tell” sai ngữ pháp vì “are” không đi với động từ nguyên mẫu.;;does=>“Does” chỉ dùng với he/she/it, và không tạo được lời nhờ lịch sự.\nc|Our new nurse ___ speak French and English very well.|cans / does can / can / is can|2|Chủ ngữ ngôi thứ ba vẫn dùng “can” nguyên dạng trong câu khẳng định, rồi đến động từ “speak”.|cans=>“can” không thêm -s với ngôi thứ ba số ít như “nurse”.;;does can=>Câu khẳng định không dùng “does” trước “can”.;;is can=>Không dùng “is” trước “can”; “can” đã là trợ động từ.\nc|You ___ park here. It's a hospital entrance.|can / can't / could to / don't can|1|“You can't + V” nói điều không được phép; lối vào bệnh viện thì cấm đỗ xe.|can=>“It's a hospital entrance” cho thấy ở đây cấm đỗ xe, nên không dùng khẳng định.;;could to=>Sau “could” không có “to”, và cũng không hợp nghĩa cấm đoán.;;don't can=>Không dùng “don't” với “can”; chỉ cần “can't”.\nc|A: ___ you swim when you were ten? B: Yes, I could.|Could / Can / Did / Do|0|“when you were ten” chỉ quá khứ và câu đáp là “Yes, I could”, nên hỏi bằng “Could you swim ...?”.|Can=>Câu có “when you were ten” chỉ quá khứ, nên “Can” (hiện tại) không hợp.;;Did=>“Did you swim” không có “could”, mà câu trả lời lại là “Yes, I could”, nên không khớp.;;Do=>“Do you swim” hỏi hiện tại, trong khi vế sau là “when you were ten”.\nc|Sorry, I ___ hear you. The line is very bad.|can / no / not can / can't|3|Đường truyền xấu nên không nghe được: dùng “can't hear”.|can=>“The line is very bad” cho thấy người nói không nghe được, nên không khẳng định.;;no=>“I no hear” sai ngữ pháp; phủ định phải có “can't” hoặc trợ động từ.;;not can=>Phủ định của “can” là “can't/cannot”, không đặt “not” trước “can”.\nx|Chọn câu đúng: hỏi về khả năng|Can your brother ride a motorbike? / Does your brother can ride a motorbike? / Can your brother rides a motorbike? / Can your brother to ride a motorbike?|0|Câu hỏi với “can”: Can + chủ ngữ + động từ nguyên mẫu, không có do/does hay “to”.|Does your brother can ride a motorbike?=>Không dùng “does” với “can”; “can” tự đảo lên trước chủ ngữ.;;Can your brother rides a motorbike?=>Sau “can” động từ giữ nguyên mẫu “ride”, không thêm -s.;;Can your brother to ride a motorbike?=>Sau “can” không dùng “to”, chỉ cần động từ nguyên mẫu.\nx|Chọn câu đúng: nói về quá khứ|She can't read when she was four. / She couldn't to read when she was four. / She couldn't read when she was four. / She didn't could read when she was four.|2|Quá khứ của “can't” là “couldn't”, theo sau là động từ nguyên mẫu không “to”.|She can't read when she was four.=>“when she was four” chỉ quá khứ nên cần “couldn't”, không dùng “can't”.;;She couldn't to read when she was four.=>Sau “couldn't” dùng động từ nguyên mẫu không “to”.;;She didn't could read when she was four.=>Không dùng “didn't” cùng “could”; “couldn't” đã là dạng phủ định quá khứ.\nx|Chọn câu đúng: nhờ vả lịch sự|Could you to close the door, please? / Could you close the door, please? / Do you could close the door, please? / Could you closing the door, please?|1|Lời nhờ lịch sự: Could + you + động từ nguyên mẫu, không có “to” hay “do”.|Could you to close the door, please?=>Sau “could you” phải dùng động từ nguyên mẫu, không thêm “to”.;;Do you could close the door, please?=>Không dùng “do” cùng “could”; “could” tự đảo lên trước chủ ngữ.;;Could you closing the door, please?=>Sau “could you” phải dùng động từ nguyên mẫu, không dùng V-ing.\nx|Chọn câu đúng: phủ định khả năng|My grandmother cans't use a smartphone. / My grandmother doesn't can use a smartphone. / My grandmother can't to use a smartphone. / My grandmother can't use a smartphone.|3|Phủ định của “can” là “can't” + động từ nguyên mẫu, không thêm “does” hay “to”.|My grandmother cans't use a smartphone.=>“can” không bao giờ thêm -s, kể cả ở dạng phủ định.;;My grandmother doesn't can use a smartphone.=>Không dùng “doesn't” với “can”; phủ định chỉ cần “can't”.;;My grandmother can't to use a smartphone.=>Sau “can't” không dùng “to”, chỉ cần động từ nguyên mẫu.\nt|Maria ___ (can/swim) very fast. She is a champion.|can swim|Chủ ngữ “Maria” đi với “can” nguyên dạng, theo sau là động từ nguyên mẫu “swim”.\nt|I ___ (not/can) understand this question. Please help me.|can't;cannot;can not|Phủ định của “can” là “can't” hoặc “cannot”, không cần trợ động từ.\nt|___ (you/can) lend me your dictionary?|can you;could you|Câu hỏi nhờ vả đảo “can/could” lên trước chủ ngữ “you”.\nt|When I was a child, I ___ (can) climb any tree.|could|“When I was a child” chỉ quá khứ nên “can” đổi thành “could”.\nf|My brother cans cook Italian food.|cans|can|“can” không thêm -s ở ngôi thứ ba số ít.\nf|My sister can speaks English very well.|speaks|speak|Sau “can” dùng động từ nguyên mẫu, không thêm -s.\nf|Do you can swim in the sea?|Do|Can|Câu hỏi với “can” không dùng “do”; “Can you swim ...?” mới đúng.\nf|Yesterday I can't find my wallet anywhere.|can't|couldn't|“Yesterday” chỉ quá khứ nên “can't” phải thành “couldn't”.\no|Could you speak more slowly, please?|“Could” đứng đầu câu hỏi nhờ vả, rồi đến chủ ngữ “you”, động từ nguyên mẫu và “please” ở cuối.\no|Can I use your toilet?|Với “can” xin phép, “can” đứng đầu câu, tiếp đến chủ ngữ “I” và động từ nguyên mẫu.","demonstratives":"c|Look at ___ birds in the tree over there.|those / these / that / this|0|Chim là số nhiều và ở xa (over there), nên dùng “those”.|this=>“This” là số ít và chỉ vật gần, không hợp với “birds” và “over there”.;;these=>“These” là số nhiều nhưng chỉ vật gần, trong khi đàn chim ở xa (over there).;;that=>“That” là số ít, không đi với danh từ số nhiều “birds”.\nc|Dad, ___ is my friend Tom. He is standing next to me.|That / This / Those / These|1|Giới thiệu người đang đứng ngay cạnh mình dùng “this is”; chủ ngữ số ít và có “next to me”.|That=>“That” chỉ người ở xa, trong khi Tom đứng ngay cạnh người nói.;;Those=>“Those” là số nhiều và chỉ người ở xa, không đi với “is” và một người.;;These=>“These” là số nhiều, không đi với “is” và một người.\nc|I can't carry ___ bags. They are too heavy.|that / this / these / it|2|“Bags” là số nhiều và đang ở gần người nói, nên dùng “these”; “They are” cũng xác nhận số nhiều.|this=>“This” là số ít, không đi với “bags” (số nhiều).;;that=>“That” là số ít, không đi với “bags” (số nhiều).;;it=>“It” không đứng trước danh từ để chỉ vật, và là số ít.\nc|Who is ___ man over there, near the door?|these / those / this / that|3|“Man” là số ít và ở xa (over there), nên dùng “that”.|these=>“These” là số nhiều, không đi với “man” và “is”.;;those=>“Those” là số nhiều, không đi với danh từ số ít “man”.;;this=>“This” chỉ người ở gần, trong khi người đàn ông ở xa (over there).\nc|(On the phone) Hello, ___ is Dr Lee. Who is that?|this / that / these / those|0|Khi nói điện thoại, người gọi tự giới thiệu bằng “this is”, còn hỏi người kia bằng “that”.|that=>“That is” dùng để hỏi người ở đầu dây bên kia, không dùng để tự giới thiệu.;;these=>“These” là số nhiều, không đi với “is Dr Lee”.;;those=>“Those” là số nhiều, không đi với “is Dr Lee”.\nc|How much are ___ shoes in the window?|this / those / that / it|1|“Shoes” là số nhiều và đang ở sau cửa kính, tức là xa, nên dùng “those”.|this=>“This” là số ít, không đi với “shoes”.;;that=>“That” là số ít, không đi với “shoes”.;;it=>“It” không đứng trước danh từ để chỉ vật.\nc|A: What's in your hand? B (holding it up): ___ is a new phone.|These / Those / This / That|2|Vật cầm trong tay là gần và số ít, nên trả lời “This is a new phone.”|These=>“These” là số nhiều, không đi với “is” và “a new phone”.;;Those=>“Those” là số nhiều, không đi với “is a new phone”.;;That=>“That” chỉ vật ở xa, còn điện thoại đang ở trong tay người nói.\nc|Are ___ your keys on the table? I can't see them well from here.|this / these / that / those|3|Chìa khóa số nhiều, ở xa trên bàn (nhìn không rõ từ đây), nên dùng “those”.|this=>“This” là số ít, không đi với “keys” và “are”.;;these=>“These” chỉ vật ở gần, trong khi người nói nhìn không rõ từ đây vì chúng ở xa.;;that=>“That” là số ít, không đi với “keys” và “are”.\nc|I don't like ___ weather today. It's too cold.|this / these / those / they|0|“Weather” là danh từ không đếm được, đi với “this” (gần, hiện tại).|these=>“These” dùng với danh từ số nhiều, mà “weather” không đếm được.;;those=>“Those” dùng với danh từ số nhiều, mà “weather” không đếm được.;;they=>“They” là đại từ, không đứng trước danh từ “weather”.\nc|Excuse me, how much is ___ jacket on the far wall, behind the counter?|these / that / those / they|1|“Jacket” là số ít và ở trên kệ cao (xa), nên dùng “that”.|these=>“These” là số nhiều, không đi với “jacket” và “is”.;;those=>“Those” là số nhiều, không đi với “jacket” số ít.;;they=>“They” là đại từ, không đứng trước danh từ “jacket”.\nc|___ days I get up very early because of my new job.|That / Those / These / This|2|“These days” (dạo này) là cụm cố định để nói về giai đoạn hiện tại, “days” là số nhiều.|That=>“That” là số ít, không đi với “days”.;;Those=>“Those days” nói về quá khứ xa, không hợp với thì hiện tại “I get up” và “new job”.;;This=>“This” là số ít, không đi với “days”.\nc|Here is a photo from my holiday. ___ are my grandparents, next to me.|This / Is / That / These|3|Ông bà là số nhiều và tấm ảnh đang ở trong tay (gần), nên dùng “These are …”.|This=>“This” là số ít, không đi với “are” và “grandparents” số nhiều.;;That=>“That” là số ít và chỉ vật ở xa, không đi với “are”.;;Is=>“Is” là động từ, không thể làm chủ ngữ mở đầu câu này.\nc|I'm sorry, I didn't hear ___. Could you say it again?|that / these / those / they|0|Chỉ lại điều người kia vừa nói dùng “that”; số ít vì câu sau dùng “it”.|these=>“These” là số nhiều, trong khi “it” ở câu sau chỉ một điều đã nói.;;those=>“Those” là số nhiều, không hợp với “it” ở câu sau.;;they=>“They” là chủ ngữ, không đứng sau “hear” làm tân ngữ.\nc|Look at ___! It's a beautiful flower. (holding it)|that / this / those / these|1|Người nói đang cầm bông hoa (số ít, gần), nên dùng “this”.|that=>“That” chỉ vật ở xa, trong khi người nói đang cầm bông hoa.;;those=>“Those” là số nhiều và ở xa, không hợp với “a beautiful flower”.;;these=>“These” là số nhiều, không hợp với “It's a beautiful flower”.\nx|Chọn câu đúng|These is my brother. / This are my parents. / Those are my cousins over there. / That is my friends.|2|Cần hòa hợp số: those + are (số nhiều, xa); các câu còn lại sai số giữa đại từ và động từ hoặc danh từ.|These is my brother.=>“These” là số nhiều nhưng đi với “is” và danh từ số ít.;;This are my parents.=>“This” là số ít nhưng đi với “are” và danh từ số nhiều.;;That is my friends.=>“That is” (số ít) không hợp với “my friends” (số nhiều).\nx|Chọn câu đúng|Is this Mr Park? (nghe điện thoại, hỏi người gọi) / Hello, that is Ben speaking. / Hello, these is Ben. / Hello, this is Ben speaking.|3|Khi tự giới thiệu qua điện thoại dùng “This is …”; “that” dùng để hỏi người kia.|Is this Mr Park? (nghe điện thoại, hỏi người gọi)=>Hỏi người ở đầu dây kia phải dùng “Is that …?”, không dùng “this”.;;Hello, that is Ben speaking.=>Tự giới thiệu qua điện thoại dùng “this is”, không dùng “that is”.;;Hello, these is Ben.=>“These” là số nhiều, không đi với “is” và một người.\nx|Chọn câu đúng|What are those? / What's those? / What are that? / What is these?|0|Danh từ số nhiều ở xa hỏi bằng “What are those?”; “are” đi với “those”.|What are that?=>“That” là số ít, không đi với “are”.;;What's those?=>“Those” là số nhiều, không đi với “is” (what's = what is).;;What is these?=>“These” là số nhiều, không đi với “is”.\nx|Chọn câu đúng|This bags are expensive. / Those bags are expensive. / That bags are expensive. / These bag are expensive.|1|Trước “bags” (số nhiều) cần “these/those”, và “are” đi với số nhiều; chỉ câu này đúng cả hai điều.|This bags are expensive.=>“This” là số ít, không đi với “bags” (số nhiều).;;That bags are expensive.=>“That” là số ít, không đi với “bags” (số nhiều).;;These bag are expensive.=>“Bag” thiếu -s trong khi “these … are” cần danh từ số nhiều đi cùng.\nt|___ (this/these) are my new neighbours. They moved here last week.|these|“Neighbours” là số nhiều và đứng gần, nên dùng “these”.\nt|Who is ___ (that/those) woman in the red coat over there?|that|“Woman” là số ít và ở xa (over there), nên dùng “that”.\nt|Look at ___ (this/these) earrings in my hand. They match my dress.|these|Hoa tai là số nhiều và đang ở trong tay (gần), nên dùng “these”.\nt|What are ___ (that/those) boxes behind the desk?|those|“Boxes” là số nhiều và ở xa, nên dùng “those”.\nf|Those is my teacher over there.|Those|That|“Teacher” là số ít, nên dùng “that” thay cho “those”.\nf|Is these your keys on the desk?|Is|Are|“These keys” là số nhiều nên động từ be phải là “are”: “Are these your keys?”.\no|These are my new classmates.|Cụm “these are” đứng đầu, sau đó là danh từ số nhiều “my new classmates”.\no|Is that your umbrella over there?|Câu hỏi đảo “is” trước chủ ngữ “that”, rồi mới đến “your umbrella”.","dependent-prepositions":"c|Whether we go on a picnic depends ___ the weather.|of / at / from / on|3|Động từ “depend” luôn đi với giới từ “on”; chủ ngữ là cả mệnh đề Whether we go nên “depends on” đứng trước the weather.|of=>“Depend of” là lỗi do dịch “phụ thuộc vào” sang “of”; cụm đúng chỉ có “depend on”.;;from=>“Depend from” không tồn tại trong tiếng Anh hiện đại; chỉ có depend on.;;at=>“Depend at” không phải cụm cố định; “at” chỉ vị trí hoặc thời điểm, không đi với depend.\nc|Lan is very good ___ explaining things to patients.|at / in / of / with|0|Nói về kỹ năng làm tốt một việc dùng “good at” + V-ing; explaining là V-ing nên giới từ cần là “at”.|in=>“Good in explaining” là lỗi hay gặp do dịch “giỏi về”; kỹ năng dùng “at”.;;of=>“Good of explaining” dùng sai giới từ; “of” không đi với good khi nói về kỹ năng.;;with=>“Good with” đi với người hay vật bạn xử lý tốt (good with children), không đi với V-ing.\nc|He is afraid ___ flying, so he always travels by train.|from / at / of / for|2|Tính từ “afraid” đi với giới từ “of”, và sau giới từ dùng V-ing: afraid of flying.|from=>“Afraid from” là lỗi do dịch “sợ từ”; không có cụm này trong tiếng Anh.;;at=>“Afraid at” không phải cụm đúng; at không đi với afraid trong cách nói sợ một việc.;;for=>“Afraid for” nghĩa là lo lắng cho an toàn của ai đó, không phải sợ việc bay.\nc|We're looking forward ___ you at the conference.|to see / for seeing / to seeing / of seeing|2|“Look forward to” có “to” là giới từ nên theo sau là V-ing; seeing you là dạng đúng.|to see=>“To see” dùng to V sau “to”, mà ở đây “to” là giới từ nên không dùng động từ nguyên mẫu.;;for seeing=>“For seeing” dùng sai giới từ; cụm cố định chỉ là look forward to.;;of seeing=>“Of seeing” cũng dùng sai giới từ; look forward không đi với of.\nc|What is the reason ___ the delay?|of / about / to / for|3|Danh từ “reason” đi với giới từ “for” khi nói lý do của một sự việc: the reason for the delay.|of=>“Reason of” là lỗi do dịch “lý do của”; danh từ reason cần giới từ for.;;to=>“Reason to” thường đi với động từ nguyên mẫu (a reason to smile), không đi với the delay.;;about=>“Reason about” không phải cụm đúng, vì about không đi với danh từ reason.\nc|She was angry ___ her brother for losing her keys.|with / about / of / on|0|Giận một người dùng “angry with” + người, còn lý do thêm sau bằng for hoặc about.|about=>“Angry about her brother” nghĩa là giận về chuyện của anh ấy, không chỉ rõ giận chính người đó.;;of=>“Angry of” là lỗi do dịch “giận của”; không có cụm này.;;on=>“Angry on” cũng không tồn tại; on không đi với angry.\nc|He was angry ___ the long delay at the airport.|with / to / about / for|2|Giận về một sự việc (delay) dùng “angry about”; “with” chỉ dùng khi tức một người.|with=>“Angry with the delay” coi sự chậm trễ như một người; with chỉ đi với người, không dùng cho sự việc.;;to=>“Angry to” không phải cụm đúng; to không đi với tính từ angry.;;for=>“Angry for” cũng không đúng, vì for không đi với angry khi nói về nguyên nhân.\nc|The nurse apologised ___ the patient for the long wait.|to / for / at / with|0|Cấu trúc đúng là apologise to + người + for + việc; ở đây patient là người nên cần “to”.|for=>“Apologised for the patient” coi bệnh nhân là lý do xin lỗi, rồi lại thêm for lần nữa không hợp.;;at=>“Apologised at” không phải cụm đúng; at không đi với apologise.;;with=>“Apologised with” cũng không đúng, vì with không dùng để chỉ người nhận lời xin lỗi.\nc|I'm interested ___ learning more about nutrition.|on / at / in / for|2|Tính từ “interested” đi với giới từ “in”, sau đó dùng V-ing (learning).|on=>“Interested on” là lỗi do dịch “quan tâm đến” sang on; cụm đúng là in.;;at=>“Interested at” không phải cụm đúng; at không đi với interested.;;for=>“Interested for” cũng sai, vì for không dùng cùng với tính từ interested.\nc|There has been an increase ___ the number of students.|of / to / on / in|3|Danh từ “increase” + “in” khi nói về thay đổi của một đại lượng: an increase in the number.|of=>“Increase of the number” sai vì of đứng sau increase chỉ mức tăng (an increase of 10%).;;on=>“Increase on” không phải cụm đúng với danh từ increase.;;to=>“Increase to” dùng cho động từ (rise to 50), không đi với danh từ này trong câu.\nc|She is very proud ___ her daughter's results.|of / about / for / to|0|Tính từ “proud” đi với “of” + danh từ chỉ điều ta tự hào: proud of her daughter's results.|about=>“Proud about” không phải cụm chuẩn; người học thường nhầm với worried about.;;for=>“Proud for” là lỗi do dịch “tự hào vì”; cụm đúng là proud of.;;to=>“Proud to” chỉ dùng với động từ (proud to be), không đi trước danh từ results.\nc|My sister is married ___ a pilot.|to / with / by / of|0|Tính từ “married” đi với “to”: married to somebody, nghĩa là đã kết hôn với ai.|with=>“Married with” là lỗi do dịch “kết hôn với”; tiếng Anh dùng to.;;by=>“Married by” nghĩa là ai đó chủ hôn, không phải người chồng của cô ấy.;;of=>“Married of” không phải cụm đúng; of không đi với married.\nc|He is keen ___ cycling, so he rides to work every day.|at / to / in / on|3|Tính từ “keen” đi với “on” khi nói thích một hoạt động: keen on cycling.|at=>“Keen at” gợi nghĩa giỏi, nhưng cụm keen at không tồn tại.;;in=>“Keen in” không phải cụm đúng; in thường chỉ lĩnh vực quan tâm sau interested.;;to=>“Keen to” đi với động từ nguyên mẫu (keen to learn), không đi với cycling.\nc|Fruit and vegetables are good ___ your health.|at / for / with / in|1|“Good for” nghĩa là có lợi cho; còn “good at” là giỏi một việc, nên ở đây phải dùng for.|at=>“Good at your health” nghĩa là giỏi về sức khoẻ, sai nghĩa so với có lợi cho sức khoẻ.;;with=>“Good with” đi với người hay vật xử lý tốt (good with children), không nói lợi cho sức khoẻ.;;in=>“Good in your health” không phải cụm đúng; in không đi với good khi nói lợi ích.\nx|Chọn câu đúng (depend)|It depends of the price. / It depends on the price. / It depends to the price. / It depends from the price.|1|Động từ “depend” chỉ đi với giới từ “on”; các giới từ khác không tạo cụm đúng.|It depends of the price.=>“Depends of” là lỗi do dịch “phụ thuộc của”; cụm đúng là depend on.;;It depends to the price.=>“Depends to” không tồn tại; to không đi với depend.;;It depends from the price.=>“Depends from” không phải cụm đúng trong tiếng Anh hiện đại.\nx|Chọn câu đúng (afraid of -ing)|She is afraid of to fly. / She is afraid of flying. / She is afraid from flying. / She is afraid flying.|1|Sau giới từ “of” dùng V-ing, nên “afraid of flying” là dạng đúng.|She is afraid of to fly.=>“Of to fly” dùng to V sau giới từ, điều không được phép.;;She is afraid from flying.=>“Afraid from” dùng sai giới từ; cụm đúng là afraid of.;;She is afraid flying.=>“Afraid flying” thiếu giới từ of, mà afraid cần giới từ trước V-ing.\nx|Chọn câu đúng (discuss)|They discussed about the budget. / They discussed the budget. / They discussed on the budget. / They discussed of the budget.|1|“Discuss” là động từ đi thẳng với tân ngữ, không thêm giới từ như about, on hay of.|They discussed about the budget.=>“Discussed about” thêm giới từ thừa; người Việt hay thêm vì dịch “thảo luận về”.;;They discussed on the budget.=>“Discussed on” cũng thêm giới từ thừa; discuss không cần on.;;They discussed of the budget.=>“Discussed of” cũng thêm giới từ thừa, không có cụm discuss of.\nx|Chọn câu đúng (wait for)|I'm waiting the bus. / I'm waiting for the bus. / I'm waiting to the bus. / I'm waiting from the bus.|1|“Wait” cần giới từ “for” trước tân ngữ: wait for the bus.|I'm waiting the bus.=>“Waiting the bus” thiếu giới từ for; người Việt hay bỏ vì dịch “đợi xe buýt”.;;I'm waiting to the bus.=>“Waiting to the bus” dùng sai giới từ; to không đi với wait trong nghĩa đợi.;;I'm waiting from the bus.=>“Waiting from the bus” dùng sai giới từ; from chỉ nguồn gốc, không phải đối tượng chờ đợi.\nt|We are looking forward to ___ (meet) you next week.|meeting|“To” trong look forward to là giới từ, nên động từ theo sau phải ở dạng V-ing.\nt|She is good at ___ (draw) detailed diagrams.|drawing|Sau giới từ “at” dùng V-ing, vì vậy draw đổi thành drawing.\nt|Thank you for ___ (help) me with the forms yesterday.|helping|Sau giới từ “for” dùng V-ing, nên help đổi thành helping.\nt|He apologised for ___ (be) late to the meeting.|being|Sau giới từ “for” dùng V-ing; động từ be đổi thành being.\nf|She is very good in maths.|in|at|Nói về kỹ năng giỏi môn nào dùng “good at”; “good in” là lỗi do dịch “giỏi về”.\nf|I'm tired for waiting in this queue.|for|of|Mệt mỏi, chán việc gì dùng “tired of” + V-ing; “tired for” là lỗi do dịch “mệt vì”.\nf|He's angry on his sister for breaking his phone.|on|with|Giận một người dùng “angry with” + người; on không đi với angry.\no|She is afraid of speaking in public.|Thứ tự là chủ ngữ + be + tính từ + giới từ cố định (of) + V-ing + cụm trạng ngữ.\no|We are looking forward to hearing from you.|Cấu trúc look forward to + V-ing đứng sau be; hearing from you là cụm V-ing gồm động từ và giới từ.","frequency-adverbs":"c|My sister ___ gets up before six. She loves the early morning.|always / never / rarely / hardly|0|“Loves the early morning” cho thấy cô ấy thích dậy sớm, nên phải là “always”.|never=>“Never” nghĩa là không bao giờ, mâu thuẫn với việc cô ấy thích buổi sáng sớm.;;rarely=>“Rarely” là hiếm khi, không hợp với việc thích dậy sớm.;;hardly=>“Hardly” cần đi với “ever” để có nghĩa gần như không bao giờ, và cũng mâu thuẫn.\nc|Mark is ___ late for class. He is a very punctual student.|usually / never / always / often|1|“Never” đi sau be: “is never late”; “punctual” cho thấy không bao giờ muộn.|usually=>“Usually late” nghĩa là thường muộn, mâu thuẫn với “very punctual”.;;always=>“Always late” nghĩa là lúc nào cũng muộn, mâu thuẫn với “punctual”.;;often=>“Often late” nghĩa là hay muộn, mâu thuẫn với “punctual”.\nc|I ___ drink coffee in the evening because it keeps me awake.|often / always / rarely / usually|2|“Keeps me awake” là lý do tránh cà phê buổi tối, nên “rarely” (hiếm khi) hợp lý.|often=>“Often” là hay uống, trái với lý do vì nó làm mất ngủ.;;always=>“Always” là luôn uống, trái với lý do vì nó làm mất ngủ.;;usually=>“Usually” là thường uống, trái với lý do vì nó làm mất ngủ.\nc|They ___ play football on Sundays, so the park is full of them.|never / rarely / hardly ever / often|3|Công viên đầy người chơi nghĩa là họ chơi thường xuyên, nên chọn “often”.|never=>“Never” là không bao giờ, mâu thuẫn với việc công viên đầy người.;;rarely=>“Rarely” là hiếm khi, mâu thuẫn với việc công viên đầy người.;;hardly ever=>“Hardly ever” là gần như không bao giờ, mâu thuẫn với việc công viên đầy họ.\nc|The doctor is ___ busy on Mondays. Please make an appointment for another day.|always / hardly / never / rarely|0|Khuyên đặt lịch ngày khác nghĩa là thứ Hai bác sĩ luôn bận, nên chọn “always”.|never=>“Never” busy nghĩa là không bao giờ bận, nên không cần đổi sang ngày khác.;;hardly=>“Hardly” cần đi với “ever”, và nghĩa gần như không bao giờ nên không hợp.;;rarely=>“Rarely” busy nghĩa là hiếm khi bận, nên không cần khuyên đổi ngày.\nc|How ___ do you go to the gym? — Three times a week.|much / often / long / many|1|Câu trả lời “three times a week” là tần suất, nên hỏi bằng “How often”.|much=>“How much” hỏi số lượng không đếm được hoặc giá, không hỏi tần suất.;;long=>“How long” hỏi khoảng thời gian, trong khi câu trả lời là tần suất.;;many=>“How many” hỏi số lượng đếm được, không hỏi tần suất.\nc|She ___ goes to the cinema. She prefers watching films at home.|always / usually / rarely / often|2|“Prefers watching films at home” nghĩa là cô ấy ít đi xem phim, nên chọn “rarely”.|usually=>“Usually” là thường đi, mâu thuẫn với việc thích xem phim ở nhà.;;always=>“Always” là luôn đi, mâu thuẫn với việc thích xem phim ở nhà.;;often=>“Often” là hay đi, mâu thuẫn với việc thích xem phim ở nhà.\nc|We ___ have lunch at the canteen, but sometimes we bring food from home.|never / hardly / rarely / usually|3|“But sometimes” cho thấy phần lớn thời gian họ ăn ở căng tin, nên chọn “usually”.|never=>“Never” loại trừ mọi lần, mâu thuẫn với phần “sometimes we bring food”.;;hardly=>“Hardly” cần đi với “ever” và nghĩa gần như không, không hợp ý câu.;;rarely=>“Rarely” là hiếm khi ăn ở căng tin, trái với ý “usually” sau “but sometimes”.\nc|Lan ___ in a hurry in the morning, so she has no time for breakfast.|is always / always is / does always / always does|0|“Be” đi trước trạng từ tần suất: “is always”, và không dùng “does” với “be”.|always is=>Trạng từ không đứng trước “is” khi “is” là động từ be chính.;;does always=>“Does always” sai vì “in a hurry” đi với “be”, không dùng trợ động từ “do”.;;always does=>“Always does” sai vì “in a hurry” đi với “be”, không dùng trợ động từ “do”.\nc|My brother ___ his homework before dinner.|does usually / usually does / is usually / usually do|1|“Does” là động từ thường, trạng từ đứng trước nó; chủ ngữ số ít nên dùng “does”.|does usually=>Trạng từ không đứng sau động từ thường “does” trong câu khẳng định.;;is usually=>“Is usually” không hợp vì “his homework” cần động từ “do”, không phải “be”.;;usually do=>“Do” sai vì chủ ngữ “my brother” là số ít, cần “does”.\nc|I'm sorry, I ___ eat meat. I'm a vegetarian.|am never / do always / never / don't never|2|“Eat” là động từ thường nên trạng từ “never” đứng trước nó; vegetarian nghĩa là không bao giờ ăn thịt.|am never=>“Am never eat” sai vì không dùng “be” trước động từ thường “eat”.;;do always=>“Do always eat meat” nghĩa là luôn ăn thịt, trái với “vegetarian”.;;don't never=>“Don't never” là phủ định kép; “never” tự nó đã phủ định.\nc|A: ___ do you call your parents? B: Every Sunday.|How long / How many / How much / How often|3|“Every Sunday” là tần suất, nên hỏi bằng “How often”.|How long=>“How long” hỏi thời gian kéo dài bao lâu, không hỏi tần suất.;;How much=>“How much” hỏi số lượng hoặc giá, không hợp với “every Sunday”.;;How many=>“How many” cần danh từ đếm được theo sau, và không hỏi tần suất.\nc|He visits his dentist ___ a year, in January and in July.|twice / once / three times / every|0|Tháng Một và tháng Bảy là hai lần, nên dùng “twice a year”.|once=>“Once” là một lần, trong khi có hai lần (January và July).;;three times=>“Three times” là ba lần, trong khi chỉ có hai tháng được nêu.;;every=>“Every a year” sai ngữ pháp, “every” không đi với “a year” như vậy.\nc|Does she often ___ to the gym after work?|goes / go / going / to go|1|Sau trợ động từ “does” và trạng từ “often”, động từ ở dạng nguyên mẫu: “go”.|goes=>“Goes” sai vì đã có “does” chia số ít rồi, động từ chính giữ nguyên mẫu.;;going=>“Going” sai vì sau “does” không dùng dạng V-ing.;;to go=>“To go” sai vì sau “does” không dùng to-infinitive.\nx|Chọn câu đúng|I go always to the market on Saturday. / I am always go to the market on Saturday. / I always go to the market on Saturday. / Always I go to the market on Saturday.|2|Trạng từ tần suất đứng trước động từ thường: “I always go”.|I go always to the market on Saturday.=>“Always” không đứng sau động từ “go” như trong tiếng Việt.;;I am always go to the market on Saturday.=>Không dùng “am” trước động từ thường “go”.;;Always I go to the market on Saturday.=>“Always” ít khi đứng đầu câu như vậy; vị trí tự nhiên là trước “go”.\nx|Chọn câu đúng|She usually is happy at work. / She is usually happy at work. / She usually be happy at work. / She happy is usually at work.|1|Với “be”, trạng từ đứng sau: “is usually happy”.|She usually is happy at work.=>“Usually” không đứng trước “is” khi là động từ be.;;She usually be happy at work.=>“Be” sai dạng; chủ ngữ “she” cần “is”.;;She happy is usually at work.=>Trật tự sai: tính từ “happy” phải đứng sau “is usually”, không đứng trước “is”.\nx|Chọn câu đúng|He never drinks coffee. / He never doesn't drink coffee. / He doesn't never drink coffee. / He never drink coffee.|0|“Never” đã phủ định nên động từ ở dạng khẳng định, chia -s theo “he”.|He doesn't never drink coffee.=>Phủ định kép “doesn't never” sai trong tiếng Anh chuẩn.;;He never doesn't drink coffee.=>“Never doesn't” là phủ định kép, sai.;;He never drink coffee.=>“Drink” thiếu -s vì chủ ngữ “he” là số ít.\nx|Chọn câu đúng|Our teacher always is kind to new students. / Our teacher is always kind to new students. / Our teacher always kind to new students. / Our teacher does always be kind to new students.|1|Trạng từ tần suất đứng sau “be”: “is always kind”; câu có “be” thì không cần trợ động từ.|Our teacher always is kind to new students.=>Trạng từ “always” phải đứng sau “is”, không đứng trước động từ “be”.;;Our teacher always kind to new students.=>Thiếu động từ “is”; tính từ “kind” cần “be” đi trước.;;Our teacher does always be kind to new students.=>Không dùng “does” với động từ “be”; câu khẳng định chỉ cần “is”.\nt|My mother ___ (never / eat) fast food.|never eats|“Never” đứng trước động từ thường, động từ chia -s vì chủ ngữ số ít.\nt|They ___ (always / be) friendly to new patients.|are always|“Be” chia “are” và trạng từ “always” đứng sau “are”.\nt|How ___ (often) do you wash your hands at work?|often|Hỏi về tần suất dùng cấu trúc “How often”.\nt|I go to the dentist ___ a year. (2 times)|twice|“Twice” nghĩa là hai lần, đi với “a year”.\nf|I go to the gym three time a week.|time|times|Sau số từ lớn hơn hai dùng “times” (số nhiều): “three times a week”.\nf|My sister never eat meat on Fridays.|eat|eats|Chủ ngữ “my sister” là số ít nên động từ sau “never” phải chia “eats”.\no|She is rarely late for work.|Trạng từ tần suất “rarely” đứng sau động từ be “is” và trước tính từ “late”.\no|We usually have dinner at seven.|Trạng từ tần suất “usually” đứng trước động từ thường “have”.","have-got":"c|My sister ___ got two small children.|has / have / is / does|0|Chủ ngữ “my sister” là she nên dùng “has got” để nói sở hữu.|have=>Chủ ngữ “my sister” là ngôi thứ ba số ít nên cần “has”, không phải “have”.;;is=>“is got” không phải cấu trúc đúng vì “got” đi với “have/has”.;;does=>“does got” không tồn tại; “have got” không dùng trợ động từ “do”.\nc|We ___ got a big garden behind our house.|have / has / are / do|0|Chủ ngữ “we” đi với “have got”; “has got” chỉ dùng cho he/she/it.|has=>Chủ ngữ “we” đi với “have”, không đi với “has”.;;are=>“are got” sai; “got” đi sau “have/has”.;;do=>“do got” không phải cấu trúc đúng của “have got”.\nc|I ___ got any money with me. Can you pay for the coffee?|hasn't / don't / haven't / not|2|Chủ ngữ “I” và nhờ người khác trả tiền cho thấy phủ định “haven't got any”.|hasn't=>Chủ ngữ “I” đi với “haven't”, không dùng “hasn't”.;;don't=>“don't got” không dùng trong tiếng Anh chuẩn viết ở trình độ này.;;not=>Thiếu trợ động từ; phải có “haven't” trước “got”.\nc|A: ___ you got a pen? B: Yes, I have.|Do / Have / Are / Has|1|Câu trả lời ngắn “Yes, I have” tương ứng với câu hỏi “Have you got ...?”.|Do=>Câu trả lời “Yes, I have” cho thấy câu hỏi dùng “Have you got ...?”, không phải “Do”.;;Are=>“Are you got” sai vì “got” đi với “have”.;;Has=>“Has” chỉ dùng với he/she/it, không dùng với “you”.\nc|Dan ___ got a car, so he goes to work by bus.|haven't / hasn't / doesn't / isn't|1|“goes to work by bus” cho thấy Dan không có xe, nên dùng phủ định “hasn't got”.|haven't=>Chủ ngữ “Dan” là he nên phải dùng “hasn't”, không phải “haven't”.;;doesn't=>“doesn't got” không phải cấu trúc chuẩn của “have got”.;;isn't=>“isn't got” sai vì “got” đi sau “have/has”.\nc|I'm not well today. I ___ a terrible headache.|'ve got / 'm got / has got / getting|0|“I'm not well today” báo hiệu bệnh hiện tại, nên dùng “I've got a headache”.|'m got=>“I'm got” sai vì “got” đi với “have”, không đi với “am”.;;has got=>Chủ ngữ “I” đi với “have got”, không dùng “has got”.;;getting=>“I getting” thiếu trợ động từ và không diễn đạt “đang bị đau đầu”.\nc|___ your brother got a girlfriend?|Has / Have / Does / Is|0|“your brother” là he nên câu hỏi dùng “Has + S + got ...?”.|Have=>Chủ ngữ “your brother” là ngôi thứ ba số ít nên cần “Has”.;;Does=>“Does ... got” không phải cấu trúc đúng; “does” đi với “have” không có “got”.;;Is=>“Is ... got” sai vì “got” không đi với “be”.\nc|We ___ lunch in the canteen at twelve every day.|have got / have / are having got / has|1|“have lunch” là hoạt động ăn trưa thói quen (“every day”), nên không thêm “got”.|have got=>“have got” không dùng cho bữa ăn; dùng “have lunch” thôi.;;are having got=>Cấu trúc “having got” không dùng với nghĩa ăn uống.;;has=>Chủ ngữ “we” đi với “have”, không dùng “has”.\nc|My mother ___ a shower every morning before breakfast.|has got / have / has / is having got|2|“has a shower” là hoạt động hằng ngày (“every morning”) và chủ ngữ là she.|has got=>“have a shower” là hoạt động, nên không dùng “has got”.;;have=>Chủ ngữ “my mother” là ngôi thứ ba số ít nên dùng “has”.;;is having got=>Cấu trúc “is having got” không tồn tại.\nc|Do you ___ any brothers or sisters?|have / have got / has / having|0|Sau “Do you” dùng “have” nguyên mẫu: “Do you have any brothers or sisters?”.|have got=>Sau “Do you” dùng “have”, không dùng “have got”.;;has=>Sau “do” động từ giữ nguyên mẫu “have”, không dùng “has”.;;having=>Sau “do” dùng nguyên mẫu, không dùng -ing.\nc|He ___ have a car, so he takes the bus to the clinic.|don't / hasn't / isn't / doesn't|3|Sau “have” nguyên mẫu dùng “doesn't” cho he: “He doesn't have a car”.|don't=>Chủ ngữ “he” đi với “doesn't”, không dùng “don't”.;;hasn't=>Sau “hasn't” phải có “got”, không có động từ “have”.;;isn't=>“isn't have” không phải cấu trúc đúng của “have”.\nc|She ___ blue eyes and long brown hair.|has got / have got / is got / gets|0|Miêu tả ngoại hình ngôi thứ ba dùng “has got” (hoặc “has”): “She has got blue eyes”.|have got=>Chủ ngữ “she” cần “has got”, không phải “have got”.;;is got=>“is got” sai; “got” đi với “have/has”.;;gets=>“gets” nghĩa là nhận hay lấy, không diễn tả đặc điểm cơ thể.\nc|A: Has the doctor got time now? B: No, she ___.|haven't / doesn't / isn't / hasn't|3|Câu hỏi “Has the doctor got ...?” nên trả lời ngắn “No, she hasn't.”.|haven't=>Chủ ngữ “she” đi với “hasn't”, không phải “haven't”.;;doesn't=>Câu hỏi dùng “Has ... got”, nên trả lời ngắn cũng dùng “hasn't”.;;isn't=>“isn't” không phải trợ động từ của “have got”.\nc|My neighbours ___ a lovely dog called Max.|has / are / does / have|3|“My neighbours” số nhiều nên dùng “have” (hoặc “have got”).|has=>Chủ ngữ “my neighbours” là số nhiều nên dùng “have”.;;are=>“are a dog” sai nghĩa; muốn nói sở hữu cần “have”.;;does=>“does” không thể làm động từ chính cho nghĩa “có”.\nx|Chọn câu đúng: nói không có con|They haven't got any children. / They hasn't got any children. / They don't got any children. / They haven't any got children.|0|Phủ định của “have got” là haven't/hasn't + got, theo ngôi.|They hasn't got any children.=>Chủ ngữ “they” đi với “haven't”, không phải “hasn't”.;;They don't got any children.=>“don't got” không dùng trong tiếng Anh chuẩn; dùng “haven't got” hoặc “don't have”.;;They haven't any got children.=>Từ “got” phải đứng ngay sau “haven't”, không đặt sau “any”.\nx|Chọn câu đúng: hỏi về bệnh|Do you got a sore throat? / Have you got a sore throat? / Are you got a sore throat? / Do you have got a sore throat?|1|Câu hỏi với “have got” đảo “have” lên trước chủ ngữ.|Do you got a sore throat?=>Không dùng “do” với “got”; chọn “Have you got ...?”.;;Are you got a sore throat?=>“got” không đi với “are”, mà phải đi với “have/has”.;;Do you have got a sore throat?=>Không trộn “do” với “got”: dùng “Have you got ...?” hoặc “Do you have ...?”.\nx|Chọn câu đúng: câu hỏi với do/does|Does your mother has a car? / Does your mother got a car? / Does your mother have a car? / Do your mother have a car?|2|Với do/does dùng “have” nguyên mẫu và “Does” cho ngôi thứ ba số ít.|Does your mother has a car?=>Sau “does” động từ giữ nguyên mẫu “have”, không dùng “has”.;;Does your mother got a car?=>“got” không đi sau “does”; dùng “have” nguyên mẫu.;;Do your mother have a car?=>Chủ ngữ “your mother” là ngôi thứ ba số ít nên cần “Does”, không phải “Do”.\nx|Chọn câu đúng: hoạt động hằng ngày|My uncle has got a nap after lunch every day. / My uncle have a nap after lunch every day. / My uncle is have a nap after lunch every day. / My uncle has a nap after lunch every day.|3|Ngủ trưa là hành động thói quen nên dùng “has a nap”; chủ ngữ “My uncle” là ngôi thứ ba số ít.|My uncle has got a nap after lunch every day.=>“have got” chỉ dùng cho sở hữu hay bệnh, không dùng cho hành động như ngủ trưa.;;My uncle have a nap after lunch every day.=>Chủ ngữ “My uncle” là ngôi thứ ba số ít nên phải dùng “has”.;;My uncle is have a nap after lunch every day.=>Không dùng “is” trước “have”; thì hiện tại đơn chỉ cần “has”.\nt|My brother ___ (have got) a new bike.|has got;'s got|Chủ ngữ “my brother” là he nên dùng “has got”.\nt|I ___ (not/have got) any sisters. I only have brothers.|haven't got;have not got;'ve not got|Phủ định của “I have got” là “I haven't got”.\nt|___ (she/have got) a headache? She looks tired.|has she got|Câu hỏi đảo “Has” lên trước “she”: “Has she got ...?”.\nt|What time do you ___ (have) breakfast?|have|Sau “do you” dùng “have” nguyên mẫu cho hoạt động ăn sáng.\nf|She have got three sisters.|have|has|Chủ ngữ “she” là ngôi thứ ba số ít nên dùng “has got”.\nf|My parents hasn't got a car, so they take the bus.|hasn't|haven't|“My parents” là they, nên dùng “haven't got”, không dùng “hasn't”.\nf|He don't have a car, so he takes the bus.|don't|doesn't|Chủ ngữ “he” đi với “doesn't” trước “have”.\nf|Has you got a pen I can borrow?|Has|Have|Chủ ngữ “you” đi với “Have”, không dùng “Has”.\no|Has your brother got a bike?|“Has” đứng đầu, rồi chủ ngữ “your brother”, sau đó là “got” và tân ngữ.\no|I haven't got any money.|Chủ ngữ “I” + “haven't” + “got” + “any money” trong câu phủ định.","imperatives":"c|___ the window, please. It's cold.|Close / Closing / To close / You closing|0|Câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu; “please” và lý do “It's cold” cho thấy đây là lời nhờ đóng cửa sổ.|Closing=>Câu mệnh lệnh dùng động từ nguyên mẫu, không dùng dạng V-ing như “Closing” ở đầu câu.;;To close=>Mệnh lệnh không dùng “to” trước động từ; chỉ cần động từ nguyên mẫu đứng đầu câu.;;You closing=>Dạng này không phải câu hoàn chỉnh; mệnh lệnh cần động từ nguyên mẫu, không có chủ ngữ.\nc|___ late for the interview tomorrow!|Not be / Don't be / Aren't / No be|1|Mệnh lệnh phủ định là “Don't + V”. Với “be” ta nói “Don't be late”, giống như với mọi động từ khác.|Not be=>Phủ định của mệnh lệnh phải là “Don't” + V; “Not” đứng một mình ở đầu câu là sai.;;Aren't=>Mệnh lệnh không dùng “aren't”; ta cần “Don't be” với động từ nguyên mẫu “be”.;;No be=>“No” không dùng để tạo câu mệnh lệnh phủ định; phải dùng “Don't” trước động từ.\nc|It's a lovely day. ___ go to the park!|Let / Let to / Let's / We|2|“Let's + V” dùng để rủ người khác cùng làm; ngữ cảnh “lovely day” và “go to the park” là một lời đề nghị.|Let=>“Let” đứng riêng sẽ cần tân ngữ phía sau; lời rủ cùng đi phải là “Let's” (let us).;;Let to=>“Let to” không phải cấu trúc rủ rê; lời rủ cùng làm phải là “Let's” (let us) + động từ.;;We=>“We go” là câu trần thuật, không phải lời rủ; ở đây cần “Let's” trước “go”.\nc|Please ___ your phone in the exam room.|switching off / to switch off / switches off / switch off|3|Sau “Please” ta dùng động từ nguyên mẫu không “to”, và không thêm đuôi -s hay -ing vào động từ.|switching off=>Sau “Please” là động từ nguyên mẫu, không dùng V-ing.;;to switch off=>Không dùng “to” sau “please”; mệnh lệnh dùng động từ nguyên mẫu trần.;;switches off=>Mệnh lệnh không chia động từ theo ngôi; “switches” có đuôi -s là sai.\nc|The floor is wet. ___ run!|Don't / Not / Doesn't / No|0|“The floor is wet” là lý do để cấm, nên dùng “Don't + V” để nói “đừng chạy”.|Not=>“Not” không thể đứng một mình trước động từ trong mệnh lệnh; phải có trợ động từ “Do”.;;Doesn't=>“Doesn't” dùng cho chủ ngữ ngôi thứ ba số ít; mệnh lệnh không có chủ ngữ nên dùng “Don't”.;;No=>“No” không đi với động từ để cấm đoán như thế này; câu cần “Don't” + động từ.\nc|Nurse: ___ this medicine twice a day, please.|Taking / Take / You take / Takes|1|Lời dặn thuốc dùng mệnh lệnh: động từ nguyên mẫu đứng đầu câu, kèm “please” cho lịch sự.|Taking=>Lời dặn của y tá là mệnh lệnh, dùng động từ nguyên mẫu, không dùng V-ing.;;You take=>Mệnh lệnh thường bỏ chủ ngữ “you”; thêm vào nghe thiếu tự nhiên trong lời dặn lịch sự.;;Takes=>Mệnh lệnh không chia ngôi, nên “Takes” có đuôi -s là sai.\nc|I'm tired. Let's ___ a taxi.|to take / taking / take / takes|2|Cấu trúc cố định là “Let's + V nguyên mẫu”; không chia động từ và không thêm “to”.|to take=>Sau “Let's” không dùng “to”; động từ ở dạng nguyên mẫu trần.;;taking=>Sau “Let's” là động từ nguyên mẫu, không phải V-ing.;;takes=>“Let's” không đi với động từ thêm -s; ta dùng nguyên mẫu “take”.\nc|The room is full. ___ wait outside.|Let's / Doesn't / Please not / We|0|Phòng đã đầy nên cả hai cùng ra chờ ngoài: lời rủ “Let's + V” hợp với ngữ cảnh.|Doesn't=>“Doesn't” là trợ động từ ngôi thứ ba, không mở đầu một mệnh lệnh hay lời rủ.;;Please not=>“Please not wait” không phải cấu trúc đúng; phủ định cần “Don't”, mà ở đây ý là rủ nhau chờ ngoài.;;We=>“We wait outside” là câu kể, không phải lời rủ “Let's”.\nc|It's raining. ___ go out without an umbrella.|Lets / Not / Doesn't / Don't|3|Trời mưa nên cần lời cấm nhẹ: “Don't go out…”. “Let's” sẽ trái nghĩa với ngữ cảnh.|Lets=>“Lets” thiếu dấu lược và nghĩa rủ cùng đi ra ngoài không hợp khi trời mưa.;;Not=>“Not” không đứng một mình để mở đầu mệnh lệnh phủ định.;;Doesn't=>“Doesn't” là trợ động từ ngôi thứ ba, không dùng cho mệnh lệnh.\nc|___ careful with that knife!|Be / Being / Are / Is|0|Mệnh lệnh khẳng định với tính từ dùng “Be + adj”; câu không có chủ ngữ và có dấu “!”.|Being=>V-ing không mở đầu câu mệnh lệnh; cần động từ nguyên mẫu “Be”.;;Are=>“Are” cần chủ ngữ “you”; mệnh lệnh dùng “Be”.;;Is=>“Is” dùng với chủ ngữ số ít, không dùng trong mệnh lệnh.\nc|___ me your passport, please.|Showing / To show / Show / Shows|2|Câu có “please” và tân ngữ “me” nên là lời yêu cầu: động từ nguyên mẫu “Show” đứng đầu câu.|Showing=>Mệnh lệnh dùng động từ nguyên mẫu, không dùng V-ing ở đầu câu.;;To show=>Không có “to” ở đầu mệnh lệnh; chỉ cần động từ nguyên mẫu.;;Shows=>Mệnh lệnh không thêm -s; chủ ngữ ngầm hiểu là “you”.\nc|Let's ___ too much coffee tonight.|not drink / don't drink / no drink / not to drink|0|Phủ định của “Let's” là “Let's not + V”; “don't” hoặc “to” đều không xuất hiện ở đây.|don't drink=>“Don't” không đi sau “Let's”; dạng phủ định đúng là “Let's not + V”.;;no drink=>“No” không dùng để phủ định động từ sau “Let's”; phải dùng “not”.;;not to drink=>Sau “Let's not” là động từ nguyên mẫu không “to”.\nc|Doctor: ___ afraid. It won't hurt.|Not be / Aren't / Not / Don't be|3|Bác sĩ trấn an bệnh nhân bằng mệnh lệnh phủ định với “be”: “Don't be afraid.”|Not be=>“Not be” thiếu trợ động từ “Do” nên không phải mệnh lệnh phủ định đúng.;;Aren't=>“Aren't” không dùng để mở đầu mệnh lệnh phủ định; ta cần “Don't be”.;;Not=>“Not afraid” không chuyển thành mệnh lệnh; cần “Don't be afraid”.\nc|Mum: Tom, ___ your shoes in the house!|not wear / no wearing / wear not / don't wear|3|Mẹ gọi tên và cấm con: mệnh lệnh phủ định “Don't + V”. Tên gọi “Tom” đặt đầu câu, không chuyển thành chủ ngữ.|not wear=>“Not” đứng một mình không mở đầu được câu mệnh lệnh phủ định; thiếu “do”.;;no wearing=>“No wearing” là biển cấm kiểu danh từ, không hợp với câu nói trực tiếp “Tom, …”.;;wear not=>Trật tự “wear not” là cổ ngữ; tiếng Anh hiện đại dùng “don't wear”.\nx|Chọn câu đúng (nhắc nhở)|Not forget your keys. / Don't forget your keys. / Don't to forget your keys. / You don't forget your keys.|1|Mệnh lệnh phủ định đúng là “Don't + V”, không có chủ ngữ và không có “to”.|Not forget your keys.=>Thiếu “Don't”; mệnh lệnh phủ định không bắt đầu bằng “Not”.;;Don't to forget your keys.=>Sau “Don't” là động từ nguyên mẫu không “to”.;;You don't forget your keys.=>Dạng này là câu kể hoặc câu hỏi sai; mệnh lệnh phủ định không cần chủ ngữ “You”.\nx|Chọn câu đúng (lời rủ)|Let's to meet at six o'clock. / Let meet at six o'clock. / Let's meet at six o'clock. / Let's meeting at six o'clock.|2|“Let's” = “let us”, theo sau là động từ nguyên mẫu không “to”: “Let's meet”.|Let's to meet at six o'clock.=>Sau “Let's” phải là động từ nguyên mẫu không “to”, nên “to meet” là sai.;;Let meet at six o'clock.=>Thiếu “'s”; “Let's” là dạng rút gọn của “let us”, không thể bỏ.;;Let's meeting at six o'clock.=>Sau “Let's” dùng động từ nguyên mẫu, không dùng V-ing.\nx|Chọn câu đúng (lời nhờ lịch sự)|Please sit down and wait here. / Please sitting down and wait here. / Please you sit down and wait here. / Please to sit down and wait here.|0|Mệnh lệnh lịch sự: “Please” + động từ nguyên mẫu; hai động từ nối bằng “and” đều ở dạng nguyên mẫu.|Please sitting down and wait here.=>Sau “Please” là động từ nguyên mẫu, không dùng V-ing.;;Please you sit down and wait here.=>Mệnh lệnh không đặt chủ ngữ “you” ngay sau “please”.;;Please to sit down and wait here.=>Không dùng “to” sau “please”; cần động từ nguyên mẫu trần.\nx|Chọn câu đúng (rủ phủ định)|Let's no be late for the meeting. / Let's don't be late for the meeting. / Let's not to be late for the meeting. / Let's not be late for the meeting.|3|Phủ định của lời rủ là “Let's not + V”; đây là dạng chuẩn và an toàn cho người học.|Let's no be late for the meeting.=>“No” không phủ định động từ ở đây; phải dùng “not”.;;Let's don't be late for the meeting.=>“Don't” không đi sau “Let's”; dùng “Let's not”.;;Let's not to be late for the meeting.=>Sau “Let's not” là động từ nguyên mẫu không “to”.\nt|___ (not / open) the box. It's fragile.|don't open;do not open|Mệnh lệnh phủ định: Don't + động từ nguyên mẫu; “fragile” cho thấy lời cảnh báo.\nt|Let's ___ (go) to the cinema tonight.|go|Sau “Let's” dùng động từ nguyên mẫu không “to”.\nt|Please ___ (be) careful with the hot water.|be|Mệnh lệnh với “be” giữ nguyên dạng “be”, không dùng “are” hay “is”.\nt|___ (not / shout), please. The patients are resting.|don't shout;do not shout|Cảnh báo ở bệnh viện dùng mệnh lệnh phủ định “Don't + V”.\nf|Not touch the screen.|Not|Don't|Mệnh lệnh phủ định bắt đầu bằng “Don't”, không phải “Not”.\nf|Let's going to the beach on Sunday.|going|go|Sau “Let's” là động từ nguyên mẫu, không dùng V-ing.\no|Please open the window.|Mệnh lệnh lịch sự: Please + động từ + tân ngữ.\no|Let's not wait for him.|Phủ định của lời rủ: Let's + not + động từ, rồi đến phần còn lại.","in-case-unless":"c|Lan wrote down the patient's number ___ she forgot it later.|if / in case / unless / provided|1|“In case” diễn tả việc làm trước để phòng ngừa; câu kể ở quá khứ (wrote down) nên mệnh đề sau dùng past simple.|if=>“If she forgot it later” chỉ điều kiện sau đó mới viết, trong khi cô ấy ghi số trước để phòng quên.;;unless=>“Unless she forgot” nghĩa là trừ khi cô ấy quên, làm câu vô lý về nghĩa.;;provided=>“Provided she forgot” nghĩa là miễn là cô ấy quên, không hợp với hành động ghi lại để phòng ngừa.\nc|You can't enter the lab ___ you wear a coat.|in case / as long as / because / unless|3|Cấm vào trừ một ngoại lệ là mặc áo choàng, đó là nghĩa của “unless” (= if you don't wear a coat).|in case=>“In case you wear a coat” nghĩa là phòng khi bạn mặc áo, không nêu được điều kiện để được vào.;;as long as=>“As long as you wear” nghĩa là miễn là bạn mặc, sẽ đảo ngược ý: mặc áo thì bị cấm.;;because=>“Because you wear a coat” nêu lý do bị cấm, trái với ý thông thường của quy định phòng thí nghiệm.\nc|You can borrow my laptop ___ you bring it back by Friday.|unless / in case / although / as long as|3|“As long as” = miễn là, nêu điều kiện duy nhất để được mượn; sau nó dùng hiện tại đơn (you bring).|unless=>“Unless you bring it back” nghĩa là trừ khi bạn mang trả, làm câu cho mượn nhưng lại ngầm không cho.;;in case=>“In case you bring it back” nghĩa là phòng khi bạn trả lại, không nêu điều kiện cho phép mượn.;;although=>“Although” nghĩa là mặc dù, tạo ý tương phản không hợp lý với việc trả máy đúng hạn.\nc|Unless it ___ tomorrow, we will have the picnic in the park.|will rain / rains / doesn't rain / rained|1|Sau “unless” dùng hiện tại đơn khẳng định để nói về tương lai; “tomorrow” cho thấy đây là điều kiện tương lai.|will rain=>“Will rain” không dùng trong mệnh đề điều kiện sau unless; phải dùng hiện tại đơn.;;doesn't rain=>“Doesn't rain” thành phủ định kép, vì unless đã mang nghĩa if … not.;;rained=>“Rained” là quá khứ, không hợp với “tomorrow” và với câu điều kiện về tương lai.\nc|Bring some water in case you ___ thirsty during the walk.|will be / would be / are / being|2|Sau “in case” dùng hiện tại đơn khi câu chính là lệnh nói về tương lai gần; “are” đúng thì và đúng chủ ngữ.|will be=>Không dùng “will” ngay sau “in case”; đây là lỗi hay gặp vì người Việt dịch “sẽ”.;;would be=>“Would be” là thì quá khứ giả định, không hợp với mệnh lệnh ở hiện tại (Bring).;;being=>“Being” không có trợ động từ, nên mệnh đề sau “in case” không có động từ chia.\nc|I always keep a spare key in case I ___ locked out.|get / will get / got / am getting|0|Thói quen hiện tại (always keep) đi với “in case” + hiện tại đơn; “get locked out” là một sự việc có thể xảy ra.|will get=>“Will get” không dùng sau in case, vì mệnh đề này đã chỉ khả năng ở tương lai.;;got=>“Got” là quá khứ đơn, không hợp với “always keep” ở hiện tại.;;am getting=>“Am getting” là tiếp diễn, nghĩa là đang bị khoá ngoài, không phải khả năng chung.\nc|We took a taxi in case the last bus ___ early that night.|leaves / will leave / would leave / left|3|Câu kể ở quá khứ (took), nên sau “in case” dùng past simple để nói điều có thể xảy ra vào lúc đó.|leaves=>“Leaves” là hiện tại, lệch thì với động từ chính “took” ở quá khứ.;;will leave=>“Will leave” không dùng sau in case, và cũng lệch với thì quá khứ của câu chính.;;would leave=>“Would leave” không dùng sau in case; chỉ cần past simple để diễn tả khả năng đó.\nc|You may use your phone in class ___ it is on silent.|in case / unless / otherwise / provided that|3|“Provided that” = miễn là, nêu điều kiện duy nhất để được dùng điện thoại; động từ sau nó ở hiện tại đơn (is).|in case=>“In case it is on silent” nghĩa là phòng khi nó ở chế độ im lặng, không nêu được điều kiện cho phép.;;unless=>“Unless it is on silent” nghĩa là trừ khi nó im lặng thì mới cấm, đảo ngược điều cần diễn đạt.;;otherwise=>“Otherwise” là trạng từ, không nối hai mệnh đề và không đứng trước “it is” như một liên từ.\nc|___ you study harder, you won't pass the exam.|As long as / Unless / In case / Provided|1|“Unless you study harder” = nếu bạn không học chăm hơn; mệnh đề chính phủ định (won't pass) hợp với nghĩa trừ khi.|As long as=>“As long as you study harder” cần mệnh đề chính khẳng định như you will pass, không phải won't pass.;;In case=>“In case you study harder” nghĩa là phòng khi bạn học chăm hơn, không có nghĩa logic ở đây.;;Provided=>“Provided you study harder” nghĩa là miễn là bạn học chăm hơn, cũng đòi hỏi kết quả khẳng định.\nc|She won't go to the party ___ she is invited.|as long as / in case / unless / because|2|“Unless she is invited” = nếu cô ấy không được mời; câu phủ định ở mệnh đề chính hợp với “unless”.|as long as=>“As long as she is invited” nghĩa là miễn là được mời, nên chính câu sẽ phải là cô ấy sẽ đi.;;in case=>“In case she is invited” nghĩa là phòng khi được mời, không phù hợp với việc quyết định không đi.;;because=>“Because she is invited” nêu lý do cô ấy không đi là vì được mời, nghe vô lý.\nc|Take a jumper with you ___ it gets cold tonight.|in case / unless / as long as / though|0|Mang áo trước để phòng khi trời lạnh là phòng ngừa, nên dùng “in case” + hiện tại đơn (gets).|unless=>“Unless it gets cold” nghĩa là trừ khi trời lạnh, câu thành nghĩa mang áo nếu trời không lạnh.;;as long as=>“As long as it gets cold” nghĩa là miễn là trời lạnh, làm lệnh mang áo trở nên thừa.;;though=>“Though it gets cold” nghĩa là dù trời lạnh, tạo ý nghĩa tương phản không hợp.\nc|Providing the results ___ ready, the doctor will call you.|are / will be / would be / being|0|“Providing” = miễn là, đi với hiện tại đơn; chủ ngữ “the results” số nhiều nên dùng “are”.|will be=>“Will be” không dùng sau providing, vì mệnh đề điều kiện dùng hiện tại đơn cho tương lai.;;would be=>“Would be” là dạng giả định, không hợp với câu điều kiện thật ở tương lai gần.;;being=>“Being” không phải động từ chia, nên mệnh đề điều kiện này thiếu động từ chính.\nc|___ fire, use the stairs, not the lift.|In case of / In case / Unless / Provided|0|“In case of” + danh từ (fire) là cấu trúc trong biển báo; sau nó không có mệnh đề đầy đủ.|In case=>“In case” cần một mệnh đề đầy đủ (in case there is a fire), không đứng thẳng trước danh từ.;;Unless=>“Unless fire” thiếu chủ ngữ và động từ, mà unless cần mệnh đề đầy đủ.;;Provided=>“Provided fire” cũng thiếu mệnh đề đầy đủ và nghĩa là miễn là, không hợp với biển báo.\nc|We can go swimming this weekend, ___ the weather is warm.|in case / unless / as long as / until|2|Việc đi bơi chỉ xảy ra nếu thời tiết ấm, nên dùng “as long as” (= miễn là) + hiện tại đơn.|in case=>“In case the weather is warm” nghĩa là phòng khi thời tiết ấm, không biểu thị điều kiện để đi bơi.;;unless=>“Unless the weather is warm” nghĩa là trừ khi trời ấm thì mới đi, làm ngược nghĩa dự định.;;until=>“Until” chỉ mốc thời gian chờ đến khi, không biểu thị điều kiện như câu này cần.\nx|Chọn câu đúng (unless)|Unless you don't hurry, we'll be late. / Unless you hurry, we'll be late. / Unless you will hurry, we'll be late. / If unless you hurry, we'll be late.|1|“Unless” = if … not, nên động từ sau nó khẳng định và ở hiện tại đơn, không có “will”.|Unless you don't hurry, we'll be late.=>“Unless … don't” thành phủ định kép, vì unless đã mang nghĩa phủ định.;;Unless you will hurry, we'll be late.=>“Unless you will hurry” dùng will trong mệnh đề điều kiện, điều không được phép.;;If unless you hurry, we'll be late.=>“If unless” là hai liên từ điều kiện liền nhau, không tồn tại trong tiếng Anh.\nx|Chọn câu đúng (in case, tương lai)|She will leave early in case there will be heavy traffic. / She will leave early in case there would be heavy traffic. / She will leave early in case there is heavy traffic. / She will leave early in case of there is heavy traffic.|2|Sau “in case” dùng hiện tại đơn khi nói về khả năng ở tương lai; “there is” là dạng đúng.|She will leave early in case there will be heavy traffic.=>“There will be” không dùng sau “in case”; mệnh đề này không dùng will.;;She will leave early in case there would be heavy traffic.=>“There would be” dùng quá khứ giả định, không hợp với “will leave” ở tương lai.;;She will leave early in case of there is heavy traffic.=>“In case of” phải đi với danh từ, nên không thể theo sau bằng mệnh đề “there is”.\nx|Chọn câu đúng (as long as)|You can stay here as long as you will be quiet. / You can stay here as long as you would be quiet. / You can stay here as long as you quiet. / You can stay here as long as you are quiet.|3|Sau “as long as” dùng hiện tại đơn, và cần động từ “are” với tính từ quiet.|You can stay here as long as you will be quiet.=>“Will be” không dùng sau as long as, vì điều kiện tương lai dùng hiện tại đơn.;;You can stay here as long as you would be quiet.=>“Would be” là dạng giả định, không hợp với một điều kiện thật ở hiện tại.;;You can stay here as long as you quiet.=>“You quiet” thiếu động từ to be, nên mệnh đề không đầy đủ.\nx|Chọn câu đúng (in case, quá khứ)|He took a map in case he gets lost. / He took a map in case of he got lost. / He took a map in case he would get lost. / He took a map in case he got lost.|3|Câu kể quá khứ (took), nên sau “in case” dùng past simple (got) để chỉ khả năng lúc đó.|He took a map in case he gets lost.=>“Gets lost” là hiện tại, lệch thì với động từ chính ở quá khứ.;;He took a map in case of he got lost.=>“In case of he got” sai vì in case of cần danh từ, không đi với một mệnh đề.;;He took a map in case he would get lost.=>“Would get” không dùng sau “in case”; chỉ cần past simple.\nt|Take a book in case the train ___ (be) late.|is|Sau “in case” dùng hiện tại đơn cho khả năng ở tương lai, và chủ ngữ “the train” số ít nên dùng “is”.\nt|You won't pass the test unless you ___ (revise).|revise|Sau “unless” dùng hiện tại đơn khẳng định, không thêm “don't” hay “will”; chủ ngữ you nên giữ nguyên “revise”.\nt|I'll lend you my notes provided that you ___ (give) them back on Monday.|give|Sau “provided that” dùng hiện tại đơn cho tương lai; chủ ngữ you nên dùng “give”.\nt|We packed sandwiches in case we ___ (not find) a café.|didn't find;did not find|Câu chính ở quá khứ (packed), nên sau “in case” dùng past simple phủ định “didn't find”.\nf|Take an umbrella in case it rained tomorrow.|rained|rains|Lệnh Take ở hiện tại và “tomorrow” là tương lai, nên sau “in case” phải dùng hiện tại đơn “rains”.\nf|You can use my car if long as you drive carefully.|if|as|Cụm đúng là “as long as”, nghĩa là miễn là; “if long as” không tồn tại trong tiếng Anh.\nf|We'll go camping providing the weather would be good.|would|is|Sau “providing” dùng hiện tại đơn cho điều kiện ở tương lai, nên “would be” phải đổi thành “is”.\no|Don't forget your charger in case your phone dies.|Câu mệnh lệnh đứng trước, rồi đến “in case” + mệnh đề (chủ ngữ + động từ hiện tại đơn) nêu lý do phòng ngừa.\no|Unless the doctor agrees, you cannot leave the ward.|Mệnh đề “Unless + chủ ngữ + động từ” đứng đầu, theo sau là dấu phẩy và mệnh đề chính nêu kết quả.","modals-deduction":"c|Ann has worked since six this morning and hasn't eaten. She ___ be exhausted.|can't / must / mustn't / must to|1|Bằng chứng rất rõ (làm việc từ sáng, chưa ăn) nên dùng must để nói gần như chắc chắn là đúng.|can't=>Can't nghĩa là chắc chắn không thể, trái với bằng chứng cho thấy cô ấy rất mệt.;;mustn't=>Mustn't diễn tả điều bị cấm, không dùng để suy đoán về trạng thái hiện tại.;;must to=>Sau modal must không có “to”, chỉ dùng động từ nguyên mẫu trực tiếp.\nc|That ___ be Dr Lee. He is on holiday in Spain this week.|must / might / can't / mustn't|2|Bác sĩ đang đi nghỉ ở Tây Ban Nha nên ta chắc chắn đó không phải ông ấy, vì vậy dùng can't.|must=>Must nói chắc chắn là đúng, nhưng câu sau cho biết ông ấy đang ở nơi khác.;;might=>Might chỉ là khả năng yếu, không hợp khi bằng chứng cho thấy gần như không thể.;;mustn't=>Mustn't là lệnh cấm, người ta không dùng nó để suy đoán phủ định.\nc|I don't know where Mai is. She ___ be at the library, or she may be at the gym.|must / can't / mustn't / might|3|Người nói chỉ đoán và đưa hai khả năng, nên dùng might (không chắc) thay vì must hay can't.|must=>Must thể hiện sự chắc chắn, mâu thuẫn với “I don't know” và hai khả năng được nêu.;;can't=>Can't loại trừ hoàn toàn khả năng, nhưng người nói còn đưa ra nơi cô ấy có thể ở.;;mustn't=>Mustn't nghĩa là cấm đoán, không hợp với việc đoán vị trí của Mai.\nc|A: Who is calling? B: I'm not sure. It ___ be my sister, or it might be the bank.|could / can't / must / mustn't|0|Người nói đưa ra hai khả năng và nói “not sure”, nên chọn could, một modal chỉ khả năng không chắc.|can't=>Can't phủ nhận hoàn toàn, nhưng người nói vẫn nghĩ đó có thể là chị gái mình.;;must=>Must chỉ sự chắc chắn, không hợp với “I'm not sure” và khả năng thứ hai.;;mustn't=>Mustn't là cấm đoán, không dùng để đoán ai đang gọi.\nc|Listen! Someone is typing in the office. The manager ___ working late.|must be / must / can't be / must been|0|Đoán hành động đang diễn ra dùng must be + V-ing; tiếng gõ phím là bằng chứng rõ ràng.|must=>Thiếu be, vì “working” ở dạng V-ing cần have/be đi cùng modal.;;can't be=>Can't be nghĩa là chắc chắn không, trái với tiếng gõ phím đang nghe thấy.;;must been=>Sau must phải là be, không phải dạng quá khứ phân từ “been” ở câu này.\nc|The surgery door is locked and the lights are off. The doctor ___ be seeing patients.|must / might / can't / may to|2|Cửa khóa và đèn tắt cho thấy gần như chắc chắn bác sĩ không đang khám bệnh, nên dùng can't be.|must=>Must be nói chắc chắn là có, trái với cửa khóa và đèn tắt.;;might=>Might be nghe như vẫn có khả năng lớn, yếu hơn mức chắc chắn mà bằng chứng cho thấy.;;may to=>Sau may không dùng “to”, và nghĩa cũng không hợp với bằng chứng ở đây.\nc|There's a jacket on the chair and a cup of tea on the desk. Someone ___ be nearby.|can't / mustn't / might / shan't|2|Áo khoác và cốc trà gợi ý có người, nhưng chưa chắc, nên might là phù hợp nhất trong các lựa chọn.|can't=>Can't loại trừ khả năng có người ở gần, trái với áo khoác và cốc trà.;;mustn't=>Mustn't là cấm đoán, không dùng để đoán sự việc đang xảy ra.;;shan't=>Shan't là dạng phủ định của shall, không dùng trong suy đoán như vậy.\nc|Zoe is the best swimmer in our club, so she ___ be afraid of water.|must / mustn't / can't / might|2|Giỏi bơi nhất câu lạc bộ nên gần như chắc chắn cô ấy không sợ nước; chọn can't be.|must=>Must be nói chắc chắn là cô ấy sợ nước, trái hẳn với bằng chứng.;;mustn't=>Mustn't là cấm đoán, người bản ngữ không dùng nó để suy đoán phủ định.;;might=>Might be chỉ là khả năng yếu, chưa đủ mạnh khi có từ “so” nêu hệ quả rõ ràng.\nc|Nobody is sure, but the new nurse ___ be from Canada. Her accent sounds similar.|can't / must / mustn't / may|3|Câu nói nobody is sure, chỉ là khả năng không chắc, nên dùng may thay vì must hoặc can't.|can't=>Can't nghĩa là chắc chắn không phải, nhưng giọng nói lại giống người Canada.;;must=>Must thể hiện chắc chắn, mâu thuẫn với “Nobody is sure”.;;mustn't=>Mustn't là cấm đoán, không dùng để đoán xuất xứ của một người.\nc|Perhaps Ken is at the gym. He ___ be there, because his bag isn't in the office.|must / could / can't / mustn't|1|Mở đầu bằng “Perhaps” và bằng chứng yếu (chỉ thiếu cái túi), nên chỉ là khả năng: could be.|must=>Must quá chắc chắn, trái với “Perhaps” ở đầu câu.;;can't=>Can't loại hẳn khả năng Ken ở phòng gym, trái với “Perhaps”.;;mustn't=>Mustn't là cấm đoán, không dùng khi đoán Ken đang ở đâu.\nc|I'm not certain that Dan is busy, but he ___ be, because he has two reports to finish.|can't / might / mustn't / must to|1|Người nói không chắc chắn, chỉ nêu lý do có thể, nên dùng might be.|can't=>Can't phủ nhận hoàn toàn, trái với lý do hai bản báo cáo cần hoàn thành.;;mustn't=>Mustn't là cấm đoán, không dùng trong suy đoán về hiện tại.;;must to=>Sau must không có “to”, và must cũng quá chắc chắn so với “not certain”.\nc|You look just like Sam, so you ___ be his sister.|can't / might not / mustn't / must|3|Giống hệt Sam, một bằng chứng mạnh nên suy đoán gần như chắc chắn: must be.|can't=>Can't nói chắc chắn không phải chị em, mâu thuẫn với việc trông giống hệt.;;might not=>Might not nghĩa là có thể không phải, yếu và trái với từ “so” chỉ kết luận.;;mustn't=>Mustn't là cấm đoán, không dùng để suy đoán danh tính.\nc|He left the ward only two minutes ago, so he ___ be far away.|can't / must / mustn't / shall|0|Chỉ mới đi hai phút nên gần như chắc chắn chưa đi xa; dùng can't be.|must=>Must be nói chắc chắn đã đi xa, trái với mốc thời gian chỉ hai phút.;;mustn't=>Mustn't là cấm đoán, không dùng để suy đoán vị trí.;;shall=>Shall dùng cho đề nghị hoặc tương lai trang trọng, không phải suy đoán.\nx|Chọn câu đúng|He must working today; his car is here. / He must be working today; his car is here. / He must to be working today; his car is here. / He must been working today; his car is here.|1|Để đoán việc đang diễn ra dùng must be + V-ing; xe của anh ấy ở đây là bằng chứng.|He must working today; his car is here.=>Thiếu be trước working, cấu trúc must + V-ing không đúng ngữ pháp.;;He must to be working today; his car is here.=>Sau must không thêm “to” trước be.;;He must been working today; his car is here.=>“Been” là dạng quá khứ phân từ, phải dùng must have been mới đúng ý quá khứ.\nx|Chọn câu đúng, nói điều không thể|That mustn't be true; he is in Hue. / That not can be true; he is in Hue. / That can't to be true; he is in Hue. / That can't be true; he is in Hue.|3|Phủ định của suy đoán must là can't + be; he is in Hue là bằng chứng.|That mustn't be true; he is in Hue.=>Mustn't là cấm đoán, không dùng để nói điều gì không thể đúng.;;That not can be true; he is in Hue.=>Not đặt trước can sai trật tự; phải là can't hoặc cannot.;;That can't to be true; he is in Hue.=>Sau can't không có “to” trước be.\nx|Chọn câu đúng, nói khả năng phủ định|She may not be at home. / She not may be at home. / She may not at home. / She doesn't may be at home.|0|Phủ định của may đặt not ngay sau may, rồi dùng be: may not be.|She not may be at home.=>Not không đứng trước may trong câu khẳng định đoán này.;;She may not at home.=>Thiếu động từ be sau may not nên câu không hoàn chỉnh.;;She doesn't may be at home.=>Không dùng doesn't với modal, vì modal tự thay đổi cho phủ định.\nx|Chọn câu đúng, đoán việc đang diễn ra|He could to be sleeping now. / He could sleeping now. / He could be sleeping now. / He could is sleeping now.|2|Đoán hành động đang diễn ra: could + be + V-ing, tức could be sleeping.|He could to be sleeping now.=>Sau could không dùng “to” trước be hay động từ khác.;;He could sleeping now.=>Thiếu be nên V-ing không thể đứng một mình sau modal.;;He could is sleeping now.=>Sau modal phải là be nguyên mẫu, không phải is.\nt|He has a big house and three cars. He ___ (must / be) rich.|must be|Bằng chứng rõ ràng nên dùng must + be để nói gần như chắc chắn.\nt|That isn't Tom; he is abroad. That ___ (can't / be) Tom.|can't be;cannot be|Biết chắc anh ấy ở nước ngoài, nên dùng can't be để nói điều không thể.\nt|The baby is crying. She ___ (might / be) hungry.|might be;may be;could be|Chỉ đoán nguyên nhân, không chắc chắn, nên dùng might/may/could + be.\nt|The lights are on in the lab. Someone ___ (must / work) there.|must be working|Đoán việc đang diễn ra dùng must + be + V-ing, bằng chứng là đèn đang sáng.\nf|She mustn't be a doctor; she is only sixteen.|mustn't|can't|Phủ định của suy đoán must là can't, vì mustn't chỉ điều bị cấm.\nf|He might is at the bank now.|is|be|Sau modal might phải dùng động từ nguyên mẫu be, không dùng is.\nf|She has been up all night, so she must be very tiring.|tiring|tired|Nói về cảm giác của cô ấy cần tính từ tired; tiring nghĩa là làm người khác mệt.\no|He must be waiting for us outside.|Modal đứng sau chủ ngữ, rồi be + V-ing: must be waiting.\no|That can't be her new house.|Can't đứng sau that, theo sau là be và cụm danh từ.","passive-reporting":"c|My bag ___ on the train yesterday.|got stolen / got steal / got stealing / was stole|0|Get-passive có dạng get/got + V3 và dùng cho sự việc không mong muốn; “yesterday” cho thấy ta dùng got + stolen.|got steal=>Sau “get” phải dùng V3, nhưng “steal” là nguyên mẫu nên không thể tạo thành câu bị động.;;got stealing=>Sau “get” trong bị động không dùng V-ing; “stealing” không mang nghĩa bị lấy mất.;;was stole=>Cấu trúc bị động cần V3 là “stolen”, còn “stole” chỉ là dạng quá khứ đơn của động từ.\nc|It is believed ___ the old bridge was built in 1850.|to / that / for / of|1|Cấu trúc It is believed that + mệnh đề; chủ ngữ giả “It” đi với “that” và mệnh đề “the old bridge was built”.|to=>Sau “It is believed” phải có mệnh đề đầy đủ, nên “to” không phù hợp với chủ ngữ giả “It”.;;for=>Giới từ “for” không đi sau “It is believed” để dẫn một mệnh đề.;;of=>“of” là giới từ nên không thể mở đầu một mệnh đề có chủ ngữ và động từ.\nc|The suspect is said ___ in the city centre.|living / that lives / to live / live|2|Dạng S + is said + to V dùng cho hành động hiện tại; chủ ngữ “The suspect” đứng trước “is said” nên cần “to live”.|living=>Sau “is said” cần động từ nguyên mẫu có “to”, không dùng V-ing ở cấu trúc này.;;that lives=>Khi chủ ngữ thật “The suspect” đứng đầu câu thì không dùng “that + mệnh đề” sau “is said”.;;live=>Thiếu “to”; cấu trúc đúng là S + is said + to + V.\nc|The ancient temple is thought ___ over 800 years ago.|to be built / to have built / being built / to have been built|3|Hành động xây dựng xảy ra trước lúc người ta “think”, nên dùng to have been built; “800 years ago” là tín hiệu.|to be built=>Đây là hiện tại bị động, không hợp với “over 800 years ago” là mốc đã qua trước hiện tại.;;to have built=>Ngôi đền không tự xây nên cần bị động “been built”, không phải chủ động “built”.;;being built=>V-ing không đi sau “is thought” và không diễn tả hành động đã xảy ra từ lâu.\nc|You are ___ to wear a uniform in the clinic.|suppose / supposed / supposing / supposes|1|Be supposed to + V chỉ quy định hay điều được mong đợi; chủ ngữ “You” và trợ từ “are” đòi hỏi dạng supposed.|suppose=>“are suppose to” sai; phải dùng V3 “supposed” sau “be” để chỉ quy định.;;supposing=>V-ing không dùng sau “are” với nghĩa quy định, và “supposing to” không có trong tiếng Anh.;;supposes=>Sau “are” không dùng động từ chia ngôi “supposes”; cần dạng V3.\nc|The patient ___ discharged this morning, so the bed is free now.|gets / get / got / getting|2|Sự việc đã xong lúc sáng nên dùng quá khứ đơn got + discharged; “this morning” và “the bed is free” là manh mối.|gets=>“gets” là hiện tại thường, không hợp với “this morning” là sự việc đã xảy ra.;;get=>Dạng nguyên mẫu “get” không dùng làm động từ chính chia thì ở câu khẳng định quá khứ.;;getting=>“getting” thiếu trợ động từ nên không thể làm động từ chính của câu.\nc|It ___ that the company will close two factories next year.|reports / is reporting / has report / is reported|3|Cấu trúc It is reported that + mệnh đề dùng cho bản tin; “that the company will close” là mệnh đề đi sau.|reports=>Chủ ngữ giả “It” không thực hiện hành động báo cáo, nên cần bị động “is reported”.;;is reporting=>Dạng tiếp diễn chủ động không đúng nghĩa; ở đây cần bị động “is reported”.;;has report=>“has report” sai ngữ pháp vì sau “has” phải là V3 “reported”.\nc|He is rumoured ___ the country last night.|to have left / to leave / having left / that has left|0|Hành động rời đi xảy ra trước lúc có tin đồn nên dùng to have + V3; “last night” là tín hiệu quá khứ.|to leave=>Hiện tại không hợp với “last night”; hành động rời đi đã xảy ra trước nên cần “to have left”.;;having left=>Dạng V-ing không đi sau “is rumoured” để tạo cấu trúc tường thuật.;;that has left=>Khi chủ ngữ “He” đứng đầu câu, không dùng “that has left” sau “is rumoured”.\nc|The meeting ___ start at nine, but the manager is late.|supposed to / was supposed to / is supposing to / was suppose to|1|Was supposed to + V chỉ kế hoạch lẽ ra phải xảy ra nhưng chưa thành; “but the manager is late” cho thấy ý đó.|supposed to=>Thiếu động từ “be”; “supposed to” không thể đứng một mình làm động từ chính ở câu này.;;is supposing to=>Cấu trúc “be supposing to” không tồn tại với nghĩa kế hoạch hay quy định.;;was suppose to=>Sau “was” phải có V3 là “supposed”, thiếu chữ -d là sai dạng.\nc|The film is expected ___ a lot of awards next month.|winning / that wins / to win / win|2|Dự đoán về tương lai dùng is expected to + V; “next month” cho thấy hành động chưa xảy ra nên không cần to have.|winning=>V-ing không đi sau “is expected”; cấu trúc cần động từ nguyên mẫu có “to”.;;that wins=>Chủ ngữ “The film” đã đứng đầu câu nên không dùng “that wins” sau “is expected”.;;win=>Thiếu “to”; cấu trúc đúng là S + is expected + to V.\nc|She didn't ___ invited to the party, so she stayed at home.|got / getting / gets / get|3|Phủ định get-passive dùng didn't get + V3; “didn't” đã mang thì quá khứ nên động từ theo sau là get.|got=>Sau “didn't” phải dùng nguyên mẫu “get”, không dùng quá khứ “got”.;;getting=>Sau “didn't” không dùng V-ing; trợ động từ đòi hỏi động từ nguyên mẫu.;;gets=>Sau “didn't” không chia ngôi ba số ít “gets” vì trợ động từ đã mang thì.\nc|It is ___ that the new vaccine reduces the risk by half.|claimed / claiming / claim / claims|0|Cấu trúc It is + V3 + that + mệnh đề, vì thế động từ claim phải ở dạng claimed ở vị trí trống.|claiming=>V-ing sau “is” sẽ thành thì tiếp diễn chủ động, không đúng nghĩa tường thuật bị động.;;claim=>Sau “is” cần V3; “claim” là nguyên mẫu nên không thành bị động.;;claims=>Chia ngôi “claims” sau “is” là sai ngữ pháp, cần V3 “claimed”.\nc|The missing climbers are believed ___ trapped by the snow.|to had been / to have been / to being / been|1|Việc bị mắc kẹt xảy ra trước lúc người ta tin, nên dùng to have been + V3; “trapped” ở sau là V3.|to had been=>Sau “to” phải dùng “have”, không dùng “had”; “to had been” sai dạng.;;to being=>“to being” không dùng ở cấu trúc này; cần dạng hoàn thành “to have been”.;;been=>Thiếu “to have”, nên “are believed been” không tạo được cấu trúc đúng.\nc|Be careful with that glass, or it will ___ broken.|gets / got / get / getting|2|Will + get + V3 chỉ điều có thể xảy ra ngoài ý muốn; “will” đòi hỏi nguyên mẫu “get” theo sau.|gets=>Sau “will” phải dùng nguyên mẫu “get”, không thêm -s.;;got=>Sau “will” không dùng quá khứ “got”; cần nguyên mẫu.;;getting=>Sau “will” không dùng V-ing; cần nguyên mẫu “get”.\nc|They say he is a brilliant surgeon. = He ___ a brilliant surgeon.|says to be / is said that is / is saying to be / is said to be|3|Chuyển “They say he is” sang bị động: He is said to be; hiện tại nên dùng to be, không cần to have.|says to be=>Chủ ngữ “He” là người được nói đến, không phải người nói, nên cần bị động “is said”.;;is said that is=>Không dùng “is said that is”; thiếu chủ ngữ cho mệnh đề sau “that”.;;is saying to be=>Dạng tiếp diễn chủ động không tạo ra nghĩa “người ta nói rằng anh ấy”.\nx|Chọn câu đúng (tin tức)|Ten people are reported to have been injured. / Ten people are reported to been injured. / It is reported ten people to be injured. / Ten people reported to have been injured.|0|Bị động tường thuật cần be + V3 rồi mới đến to have been + V3, nên câu đầy đủ là “are reported to have been injured”.|Ten people are reported to been injured.=>Thiếu “have” trước “been”; cấu trúc đúng là to have been + V3.;;It is reported ten people to be injured.=>Sau chủ ngữ giả “It” phải là “that + mệnh đề”, không dùng “to be”.;;Ten people reported to have been injured.=>Thiếu “are”; không có động từ “be” thì không phải câu bị động.\nx|Chọn câu đúng (quá khứ)|She is said to win a prize last year. / She is said to have won a prize last year. / She says to have won a prize last year. / It is said she to have won a prize last year.|1|Mốc “last year” cho thấy hành động xảy ra trước hiện tại, nên dùng S + is said + to have + V3.|She is said to win a prize last year.=>Hiện tại “to win” không hợp với “last year”; cần dạng hoàn thành.;;She says to have won a prize last year.=>“She says” là chủ động và sai nghĩa; ý đúng là người ta nói về cô ấy.;;It is said she to have won a prize last year.=>Sau “It is said” không dùng chủ ngữ + to V; phải là “that she won”.\nx|Chọn câu đúng (get)|He got marry in a small church. / He got to marry by a small church. / He got married in a small church. / He was got married in a small church.|2|Get-passive dùng got + V3 để nói về thay đổi trạng thái, nên “got married” là đúng và chỉ cần một trợ động từ.|He got marry in a small church.=>Sau “got” phải là V3 “married”, không dùng nguyên mẫu “marry”.;;He got to marry by a small church.=>“got to marry by” sai nghĩa và sai giới từ; không phải bị động.;;He was got married in a small church.=>Không dùng “was” và “got” cùng lúc; chỉ chọn một trong hai.\nx|Chọn câu đúng (quy định)|We are suppose to arrive before eight. / We supposed to arrive before eight. / We are supposed arrive before eight. / We are supposed to arrive before eight.|3|Be supposed to + V diễn tả điều được yêu cầu; cần đủ ba phần: are + supposed + to + arrive.|We are suppose to arrive before eight.=>Phải có -d: dạng V3 “supposed” sau “are”.;;We supposed to arrive before eight.=>Thiếu “are”; “supposed to” không đứng một mình làm động từ chính.;;We are supposed arrive before eight.=>Thiếu “to” giữa “supposed” và “arrive”; cấu trúc là be supposed to V.\nt|My car got ___ (steal) last week.|stolen|Sau get trong bị động ta dùng V3, và V3 của steal là stolen.\nt|She is said ___ (be) very kind to her patients.|to be|Hành động ở hiện tại nên dùng S + is said + to V, tức là to be.\nt|The old bridge is believed ___ (build) in the 1700s.|to have been built|Việc xây cầu xảy ra trước hiện tại nên dùng to have been + V3: to have been built.\nt|You are ___ (suppose) to switch off your phone in the ward.|supposed|Sau be dùng V3 của suppose, nên đáp án là supposed để chỉ quy định.\nf|The nurse is believed to worked abroad for ten years.|worked|have worked|Sau “to” phải dùng nguyên mẫu; hành động đã xảy ra trước nên dùng to have worked.\nf|He got hurting while he was playing football.|hurting|hurt|Get-passive cần V3; V3 của hurt là hurt, không dùng V-ing.\nf|The bakery is say to be closing down.|say|said|Bị động tường thuật dùng be + V3, nên sau “is” phải là said, không phải say.\no|It is believed that the thief entered through the window.|Mở đầu bằng chủ ngữ giả It, rồi is believed, tiếp theo là that + mệnh đề.\no|She is said to have worked for a famous hospital.|Chủ ngữ + is said + to have + V3 + thông tin bổ sung.","past-perfect":"c|When we got to the cinema, the film ___ already.|had started / has started / was starting / starts|0|Phim bắt đầu trước lúc chúng tôi đến rạp, với “already”, nên dùng had started.|has started=>Câu kể về quá khứ (“got to”), nên không dùng hiện tại hoàn thành “has started”.;;was starting=>Quá khứ tiếp diễn nói việc đang diễn ra, không nói việc đã xong trước khi đến.;;starts=>Hiện tại đơn không phù hợp với mốc quá khứ “when we got to the cinema”.\nc|She was upset because she ___ her keys.|has lost / had lost / was losing / loses|1|Việc mất chìa khóa xảy ra trước lúc buồn, nên dùng had lost để giải thích nguyên nhân.|has lost=>Hiện tại hoàn thành không phù hợp vì cả câu kể về quá khứ với “was upset”.;;was losing=>Quá khứ tiếp diễn nói việc đang xảy ra, không nói việc đã mất trước khi buồn.;;loses=>Hiện tại đơn lệch thì với “was upset” trong câu quá khứ.\nc|The floor was wet because someone ___ it.|has mopped / is mopping / had mopped / mops|2|Việc lau sàn xảy ra trước tình trạng ướt trong quá khứ, nên dùng had mopped.|has mopped=>Hiện tại hoàn thành không hợp với mệnh đề chính ở quá khứ “was wet”.;;is mopping=>Hiện tại tiếp diễn lệch thì với “was wet” và không chỉ việc đã làm trước đó.;;mops=>Hiện tại đơn nói thói quen, không giải thích tình trạng sàn ướt trong quá khứ.\nc|I couldn't open the door because I ___ my key at home.|have left / was leaving / leave / had left|3|Việc để quên chìa khóa xảy ra trước việc không mở được cửa, nên dùng had left.|have left=>Hiện tại hoàn thành lệch thì với “couldn't open” ở quá khứ.;;was leaving=>Quá khứ tiếp diễn không diễn tả việc để quên chìa khóa đã xảy ra trước đó.;;leave=>Hiện tại đơn không phù hợp với câu kể về quá khứ “couldn't”.\nc|Lan had never ___ sushi before she visited Tokyo.|eaten / ate / eat / eating|0|Cấu trúc had never + V3 chỉ việc chưa từng làm trước một mốc; V3 của eat là eaten.|ate=>Sau had phải dùng quá khứ phân từ (eaten), không dùng quá khứ đơn “ate”.;;eat=>Sau had không dùng động từ nguyên mẫu; cần dạng V3.;;eating=>Sau had không dùng V-ing; quá khứ hoàn thành cần V3.\nc|The teacher asked why I ___ the homework.|haven't done / hadn't done / didn't done / don't do|1|Mệnh đề sau “asked” ở quá khứ nói việc chưa làm trước đó, nên dùng hadn't done.|haven't done=>“Asked” ở quá khứ nên động từ trong mệnh đề tường thuật lùi thành hadn't done.;;didn't done=>Sau didn't phải dùng nguyên mẫu (do), không dùng V3 “done”.;;don't do=>Hiện tại đơn lệch thì với “asked” ở quá khứ.\nc|Hoa ___ in Hue for ten years before she moved to Hanoi.|has lived / lives / had lived / was lived|2|Mười năm sống ở Huế kết thúc trước lúc chuyển đi, nên dùng quá khứ hoàn thành had lived.|has lived=>Hiện tại hoàn thành không hợp với “before she moved” là mốc quá khứ.;;lives=>Hiện tại đơn lệch thì với “moved” ở quá khứ.;;was lived=>Dạng bị động “was lived” sai vì ở đây là hành động chủ động.\nc|___ you ever met him before the party?|Have / Do / Were / Had|3|Hỏi về trải nghiệm trước một mốc quá khứ dùng Had + S + V3, nên chọn Had.|Have=>Hiện tại hoàn thành không hợp với mốc quá khứ “before the party”.;;Do=>“Do” cần động từ nguyên mẫu, còn câu có “met” nên không đúng.;;Were=>“Were” không đi với V3 “met” để tạo thì hoàn thành.\nc|When I called, Minh ___ already left.|had / has / was / did|0|Minh rời đi trước lúc tôi gọi, với “already left” là V3, nên chỗ trống cần had.|has=>Câu kể về quá khứ (“called”), nên “has already left” là lệch thì.;;was=>“Was already left” là dạng bị động không phù hợp nghĩa, Minh tự rời đi.;;did=>“Did already left” sai vì sau did phải dùng nguyên mẫu.\nc|He said he ___ the report the day before.|has finished / had finished / finishes / was finish|1|Sau “said” trong quá khứ, việc đã xong trước đó lùi về had finished; “the day before” xác nhận.|has finished=>Câu tường thuật sau “said” ở quá khứ nên không giữ hiện tại hoàn thành.;;finishes=>Hiện tại đơn lệch thì với “said” và “the day before”.;;was finish=>Cấu trúc “was finish” sai ngữ pháp; cần had + V3.\nc|I ___ my breakfast before I left home.|have eaten / am eating / had eaten / eat|2|Ăn sáng xong trước khi rời nhà, “before I left” là việc sau, nên dùng had eaten.|have eaten=>Hiện tại hoàn thành lệch thì với “left” ở quá khứ.;;am eating=>Hiện tại tiếp diễn sai thì vì câu kể về việc đã xảy ra.;;eat=>Hiện tại đơn không phù hợp với mốc quá khứ “left home”.\nc|She felt sorry because she ___ so rude to him.|has been / is / will be / had been|3|Việc cư xử thô lỗ xảy ra trước lúc hối tiếc, nên dùng had been.|has been=>Hiện tại hoàn thành lệch thì với “felt” ở quá khứ.;;is=>Hiện tại đơn không phù hợp với câu kể lại cảm giác quá khứ.;;will be=>Tương lai không hợp với việc đã xảy ra trước khi cô ấy cảm thấy hối tiếc.\nc|By the time we reached the station, the train ___.|had left / has left / leaves / was leave|0|“By the time + quá khứ đơn” đi với quá khứ hoàn thành: tàu đã rời trước khi chúng tôi tới.|has left=>Hiện tại hoàn thành lệch thì với “reached” ở quá khứ.;;leaves=>Hiện tại đơn nói lịch trình, không nói việc đã xảy ra trước.;;was leave=>“Was leave” sai ngữ pháp; thì đúng là had left.\nc|I ___ never been abroad before I got this job.|have / had / was / did|1|“Before I got this job” là mốc quá khứ, nên chỗ trống cần had trong had never been.|have=>Hiện tại hoàn thành không hợp với “before I got this job” ở quá khứ.;;was=>“Was never been” không tồn tại; cần had never been.;;did=>“Did never been” sai vì did không đi với V3.\nx|Chọn câu đúng|When I arrived, the lesson had already begun. / When I arrived, the lesson has already begun. / When I arrived, the lesson had already began. / When I arrived, the lesson already had begin.|0|Bài học bắt đầu trước lúc tôi đến, nên cần had + V3 (had begun) với “already” đứng giữa.|When I arrived, the lesson has already begun.=>Mệnh đề “arrived” ở quá khứ nên không dùng hiện tại hoàn thành “has begun”.;;When I arrived, the lesson had already began.=>Sau had phải dùng V3 “begun”, không dùng quá khứ đơn “began”.;;When I arrived, the lesson already had begin.=>Dạng này lệch: cần had + V3 (had begun), không dùng nguyên mẫu “begin”.\nx|Chọn câu đúng|They didn't had eaten all day, so they were hungry. / They hadn't eaten all day, so they were hungry. / They hadn't ate all day, so they were hungry. / They haven't eaten all day, so they were hungry.|1|Phủ định quá khứ hoàn thành là hadn't + V3: hadn't eaten, giải thích việc đói trong quá khứ.|They didn't had eaten all day, so they were hungry.=>Didn't đi với nguyên mẫu, không đi với had eaten; cấu trúc bị trộn lẫn.;;They hadn't ate all day, so they were hungry.=>Sau hadn't phải dùng V3 “eaten”, không dùng quá khứ đơn “ate”.;;They haven't eaten all day, so they were hungry.=>Hiện tại hoàn thành lệch thì với “were hungry” ở quá khứ.\nx|Chọn câu đúng|After she has finished work, she went shopping. / After she had finish work, she went shopping. / After she had finished work, she went shopping. / After had she finished work, she went shopping.|2|Việc xong trước việc đi mua sắm dùng had finished; việc sau dùng quá khứ đơn went.|After she has finished work, she went shopping.=>“Has finished” lệch thì với mệnh đề chính “went” ở quá khứ.;;After she had finish work, she went shopping.=>Sau had cần V3 “finished”, không dùng nguyên mẫu “finish”.;;After had she finished work, she went shopping.=>Trong mệnh đề phụ với After, had không đảo lên trước chủ ngữ.\nx|Chọn câu đúng|Did you studied English before you came here? / Have you studied English before you came here? / Had you study English before you came here? / Had you studied English before you came here?|3|Câu hỏi quá khứ hoàn thành đảo had trước chủ ngữ và dùng V3: Had you studied.|Did you studied English before you came here?=>Sau did phải dùng nguyên mẫu “study”, không dùng “studied”.;;Have you studied English before you came here?=>Hiện tại hoàn thành lệch thì với “came” ở quá khứ.;;Had you study English before you came here?=>Sau had phải là V3 “studied”, không phải nguyên mẫu “study”.\nt|By the time I got home, my family ___ (have) dinner.|had had|“By the time I got home” là mốc quá khứ, bữa tối xong trước đó, nên dùng had had.\nt|She ___ (not / see) the film before, so she enjoyed it.|hadn't seen;had not seen|Việc chưa xem trước thời điểm quá khứ dùng hadn't seen, V3 của see là seen.\nt|The doctor ___ (leave) before we reached the clinic.|had left|Bác sĩ rời đi trước khi chúng tôi đến, nên dùng had left.\nt|___ (you / finish) the report before the meeting started?|had you finished|Hỏi việc xảy ra trước một mốc quá khứ, dạng câu hỏi là Had + S + V3.\nf|When I got there, the shop had close.|close|closed|Sau had phải dùng V3, nên “close” đổi thành “closed”.\nf|He told me he has met her before.|has|had|Sau “told” ở quá khứ, hiện tại hoàn thành lùi thành “had met”.\nf|I was late because I have forgotten my phone.|have|had|Câu kể về quá khứ, nên “have forgotten” đổi thành “had forgotten”.\nf|She hadn't never been abroad before 2020.|never|ever|Hadn't đã là phủ định; dùng thêm “never” thành phủ định kép, nên đổi sang “ever”.\no|By the time we arrived, the concert had already finished.|Mệnh đề By the time + quá khứ đơn đứng trước, rồi chủ ngữ + had + already + V3.\no|She hadn't eaten anything before the exam.|Phủ định quá khứ hoàn thành: chủ ngữ + hadn't + V3 + tân ngữ, rồi cụm “before the exam”.","present-perfect-continuous":"c|I ___ for the bus for twenty minutes, and it still hasn't come.|have been waiting / wait / am waiting / waited|0|Hành động đợi bắt đầu trong quá khứ và vẫn kéo dài, có “for twenty minutes” và “still hasn't come”, nên dùng have been waiting.|wait=>Thì hiện tại đơn không đi với “for twenty minutes” để nói việc kéo dài đến hiện tại; câu cần dạng hoàn thành tiếp diễn.;;am waiting=>Hiện tại tiếp diễn chỉ nói hành động ngay lúc này, không nối khoảng thời gian “for twenty minutes” từ quá khứ.;;waited=>Quá khứ đơn nói hành động đã chấm dứt, nhưng “it still hasn't come” cho thấy việc đợi vẫn tiếp diễn.\nc|Nam's hands are covered in soil. He ___ in the garden since six o'clock.|digs / has been digging / dug / is digging|1|Có mốc “since six o'clock” và tay còn dính đất, nên cần has been digging cho việc kéo dài đến hiện tại.|digs=>Hiện tại đơn nói thói quen; “since six o'clock” cần thì hoàn thành, không dùng hiện tại đơn.;;dug=>Quá khứ đơn không đi với “since six o'clock” để nói việc kéo dài đến bây giờ.;;is digging=>Hiện tại tiếp diễn không kết hợp với “since”; mốc thời gian trong quá khứ cần have/has been + V-ing.\nc|How long ___ studying English?|are you / do you / have you been / did you been|2|Hỏi thời gian kéo dài đến hiện tại dùng How long + have you been + V-ing; sau blank có “studying” nên cần “been”.|are you=>Câu hỏi “How long” về quãng thời gian đến nay cần have you been, không dùng hiện tại tiếp diễn.;;do you=>Hiện tại đơn “do you” thiếu dạng V-ing và không diễn tả khoảng thời gian kéo dài đến hiện tại.;;did you been=>“Did” đi với động từ nguyên mẫu, không đi với “been”; cấu trúc này sai hoàn toàn.\nc|I ___ Mr Hoang since 2015, and he is a very kind man.|have been knowing / know / am knowing / have known|3|“Know” là động từ trạng thái, đi với “since 2015” nên dùng hiện tại hoàn thành đơn: have known.|have been knowing=>“Know” là động từ chỉ trạng thái nên không dùng ở dạng tiếp diễn, dù có “since”.;;know=>Hiện tại đơn không đi với “since 2015” để nói mối quen biết kéo dài từ quá khứ.;;am knowing=>Động từ trạng thái “know” không chia tiếp diễn, và “since” cần thì hoàn thành.\nc|Why are your eyes red? ___ you been crying?|Have / Are / Did / Do|0|Vừa khóc xong còn thấy mắt đỏ nên dùng hoàn thành tiếp diễn; câu hỏi mở đầu bằng Have vì có “you been crying”.|Are=>“Are you been” sai cấu trúc; trước “been” phải có trợ động từ have/has.;;Did=>“Did” cần động từ nguyên mẫu, không đi với “been” nên câu này sai ngữ pháp.;;Do=>“Do you been” không tồn tại; thì hoàn thành tiếp diễn bắt đầu bằng Have/Has.\nc|I ___ three emails this morning, so I can have a break now.|have been writing / have written / am writing / write|1|Có con số “three emails” và đã xong để nghỉ, nên dùng hiện tại hoàn thành đơn: have written.|have been writing=>Có số lượng “three emails” đã hoàn tất nên dùng hoàn thành đơn, không nhấn mạnh quá trình.;;am writing=>Hiện tại tiếp diễn nói việc đang viết, trong khi câu nói đã xong và được nghỉ.;;write=>Hiện tại đơn nói thói quen, không hợp với “this morning” và kết quả đếm được.\nc|The nurse ___ since 7 a.m., so she is very tired.|works / worked / has been working / is working|2|Mốc “since 7 a.m.” cùng hệ quả “very tired” ở hiện tại cho thấy phải dùng has been working.|works=>Hiện tại đơn nói thói quen và không đi với “since 7 a.m.” để chỉ việc kéo dài.;;worked=>Quá khứ đơn không giải thích được việc cô ấy đang mệt ở hiện tại sau khoảng thời gian dài.;;is working=>Hiện tại tiếp diễn không dùng với “since”; cần nối mốc 7 a.m. với hiện tại.\nc|It ___ all day, so the streets are full of puddles.|has been rain / have been raining / is been raining / has been raining|3|“All day” và kết quả là đường đầy vũng nước nên dùng has been raining; “it” đi với has.|has been rain=>Sau “been” phải là V-ing; “rain” ở đây là danh từ/nguyên mẫu nên sai dạng.;;have been raining=>Chủ ngữ “it” là ngôi thứ ba số ít nên dùng has, không dùng have.;;is been raining=>“Is been” không tồn tại; trợ động từ đúng với “been” là have/has.\nc|They ___ for their exams for weeks, so they are very stressed.|have been preparing / has been preparing / are been preparing / been preparing|0|“They” là số nhiều nên dùng have been preparing, và “for weeks” cho thấy việc kéo dài đến nay.|has been preparing=>Chủ ngữ “they” là số nhiều nên phải dùng have, không dùng has.;;are been preparing=>“Are been” không đúng; sau trợ động từ have mới đến “been”.;;been preparing=>Thiếu trợ động từ have; chỉ có “been preparing” thì không thành câu hoàn chỉnh.\nc|My neighbours ___ loud music since midnight, and I can't sleep.|play / have been playing / played / are playing|1|Việc phát nhạc bắt đầu từ nửa đêm và vẫn tiếp diễn tới giờ (“since midnight”, “can't sleep”), nên dùng have been playing.|play=>Hiện tại đơn nói thói quen, không nối mốc “since midnight” với hiện tại.;;played=>Quá khứ đơn chỉ việc đã kết thúc, trong khi tôi vẫn đang không ngủ được vì tiếng nhạc.;;are playing=>Hiện tại tiếp diễn không đi với “since midnight”; cần have been playing để nối quá khứ với hiện tại.\nc|She has been teaching here ___ 2018.|for / from / since / during|2|“2018” là một mốc thời gian nên dùng “since”; “for” dành cho khoảng thời gian.|for=>“For” đi với khoảng thời gian (three years), không đi với mốc “2018”.;;from=>“From 2018” không dùng với thì hoàn thành tiếp diễn để nói đến hiện tại.;;during=>“During” đi với danh từ chỉ giai đoạn, không đi với một mốc năm cụ thể ở đây.\nc|He has been waiting ___ two hours.|for / since / ago / from|0|“Two hours” là một khoảng thời gian nên đi với “for”, không dùng “since”.|since=>“Since” đi với mốc thời gian (since nine), không đi với khoảng “two hours”.;;ago=>“Ago” dùng với quá khứ đơn (two hours ago) chứ không đứng sau “waiting” theo cách này.;;from=>“From two hours” không tự nhiên; để nói khoảng thời gian dùng “for”.\nc|How long has she ___ for the clinic?|working / been working / worked / be working|1|Sau “has” thì hoàn thành tiếp diễn cần “been + V-ing”, nên chọn been working.|working=>Thiếu “been”; sau has phải là been rồi mới đến V-ing trong thì này.;;worked=>“Has worked” là hoàn thành đơn; ở đây trước blank là has và cần có “been” trước V-ing.;;be working=>Sau “has” phải dùng phân từ “been”, không dùng nguyên mẫu “be”.\nc|Who ___ in my chair? It's still warm!|is sitting / sits / has been sit / has been sitting|3|Ghế vẫn còn ấm là kết quả nhìn thấy của hành động vừa diễn ra, nên dùng has been sitting.|is sitting=>Hiện tại tiếp diễn không giải thích được ghế còn ấm sau khi người đó vừa ngồi.;;sits=>Hiện tại đơn nói thói quen, không hợp với việc vừa xảy ra và để lại ghế ấm.;;has been sit=>Sau “been” phải là V-ing (sitting), không dùng nguyên mẫu.\nx|Chọn câu đúng|She has been cooking since noon. / She has been cook since noon. / She is cooking since noon. / She has cooking since noon.|0|Hoàn thành tiếp diễn gồm have/has + been + V-ing; câu đúng có đủ ba phần và “since noon”.|She has been cook since noon.=>Sau “been” phải dùng V-ing (cooking), không dùng nguyên mẫu.;;She is cooking since noon.=>Hiện tại tiếp diễn không đi với “since”; cần has been cooking.;;She has cooking since noon.=>Thiếu “been” giữa has và cooking nên cấu trúc bị sai.\nx|Chọn câu đúng|How long are you living here? / How long have you been living here? / How long you have been living here? / How long have you living here?|1|Câu hỏi đúng đảo have trước chủ ngữ và giữ đủ been + V-ing: have you been living.|How long are you living here?=>“How long” hỏi quãng thời gian đến nay, nên không dùng hiện tại tiếp diễn.;;How long you have been living here?=>Trong câu hỏi, trợ động từ have phải đứng trước chủ ngữ “you”.;;How long have you living here?=>Thiếu “been” giữa have you và living nên sai cấu trúc.\nx|Chọn câu đúng|I have want a new phone for months. / I am wanting a new phone for months. / I have wanted a new phone for months. / I want a new phone for months.|2|“Want” là động từ trạng thái, đi với “for months” nên dùng hiện tại hoàn thành đơn: have wanted.|I have want a new phone for months.=>Sau “have” cần V3 (wanted), không dùng nguyên mẫu “want”.;;I am wanting a new phone for months.=>“Want” là động từ trạng thái, không chia tiếp diễn; “for months” cần hoàn thành.;;I want a new phone for months.=>Hiện tại đơn không đi với “for months” để nói việc kéo dài từ quá khứ đến nay.\nx|Chọn câu đúng|We haven't been sleep well lately. / We hasn't been sleeping well lately. / We don't been sleeping well lately. / We haven't been sleeping well lately.|3|Phủ định là haven't/hasn't + been + V-ing, và “we” đi với haven't; “lately” xác nhận thì này.|We haven't been sleep well lately.=>Sau “been” cần V-ing (sleeping), không dùng nguyên mẫu.;;We hasn't been sleeping well lately.=>Chủ ngữ “we” phải dùng haven't, không dùng hasn't.;;We don't been sleeping well lately.=>“Don't” không đi với “been”; phủ định đúng là haven't been.\nt|He ___ (study) medicine since September.|has been studying;'s been studying|Mốc “since September” cho thấy việc học kéo dài đến nay, nên dùng has been studying.\nt|How long ___ (you / wait) here?|have you been waiting|Hỏi quãng thời gian đến nay: How long + have you been + V-ing.\nt|My hands are covered in flour because I ___ (bake) all afternoon.|have been baking;'ve been baking|Hành động kéo dài cả buổi chiều và còn dấu vết ở hiện tại nên dùng have been baking.\nt|The patient ___ (not / eat) properly for three days.|hasn't been eating;has not been eating|“For three days” nối quá khứ với hiện tại; phủ định là hasn't been eating.\nf|She has been wait for the bus since eight.|wait|waiting|Sau “been” phải dùng dạng V-ing, nên “wait” đổi thành “waiting”.\nf|They has been working here for ten years.|has|have|Chủ ngữ “they” số nhiều nên dùng “have been”, không dùng “has”.\nf|We have been knowing each other since 2010.|knowing|known|“Know” là động từ trạng thái nên dùng “have known”, không dùng dạng tiếp diễn.\nf|I have been living here since five years.|since|for|“Five years” là khoảng thời gian nên đi với “for”, “since” chỉ đi với mốc thời gian.\no|How long have you been learning English?|Câu hỏi How long: từ để hỏi, rồi have đảo trước chủ ngữ you, sau đó been + V-ing.\no|I have been waiting for you since nine o'clock.|Trật tự: chủ ngữ + have been + V-ing + đối tượng, rồi đến cụm chỉ mốc thời gian “since nine o'clock”.","pronouns":"c|My brother is a doctor. ___ works at a big hospital.|He / Him / His / They|0|Chỗ trống là chủ ngữ của “works” và thay cho “My brother” (nam, một người), nên dùng “He”.|Him=>“Him” là đại từ tân ngữ, không thể đứng trước động từ “works” làm chủ ngữ.;;His=>“His” là sở hữu, nghĩa là “của anh ấy”, không thể làm chủ ngữ ở đây.;;They=>“They” là số nhiều; “My brother” là một người nên cần “He”.\nc|I like Sara. I often talk to ___.|she / her / hers / herself|1|Sau giới từ “to” dùng đại từ tân ngữ; “Sara” là nữ nên chọn “her”.|she=>“She” là đại từ chủ ngữ; sau giới từ “to” cần đại từ tân ngữ.;;hers=>“Hers” nghĩa là “của cô ấy”, không dùng thay cho người sau “to”.;;herself=>“Herself” là đại từ phản thân, chỉ dùng khi chủ ngữ và tân ngữ là cùng một người.\nc|Tom and I are friends. ___ study together every day.|Us / Them / We / They|2|“Tom and I” gồm cả người nói, nên khi thay thế làm chủ ngữ dùng “We”.|Us=>“Us” là tân ngữ, không đứng đầu câu làm chủ ngữ cho “study”.;;Them=>“Them” chỉ người khác, không gồm người nói; “Tom and I” là “chúng tôi”.;;They=>“They” là ngôi thứ ba; người nói nằm trong “Tom and I” nên phải dùng “We”.\nc|Ms Brown is our English teacher. We really like ___.|she / hers / they / her|3|“Ms Brown” là một phụ nữ và đứng sau động từ “like” làm tân ngữ, nên dùng “her”.|she=>“She” là chủ ngữ; sau động từ “like” cần đại từ tân ngữ.;;hers=>“Hers” nghĩa là “của cô ấy”, không chỉ người được yêu mến.;;they=>“They” là số nhiều; “Ms Brown” chỉ một người nên không hợp.\nc|The children are noisy. Please tell ___ to be quiet.|them / they / their / it|0|“The children” là số nhiều và làm tân ngữ của “tell”, nên thay bằng “them”.|they=>“They” là chủ ngữ; sau động từ “tell” cần tân ngữ.;;their=>“Their” là sở hữu, phải đi kèm danh từ phía sau.;;it=>“It” chỉ một vật hoặc một con vật; “The children” là nhiều người nên cần “them”.\nc|This is a present for Hoa and Nam. I bought it for ___.|they / them / their / themselves|1|“Hoa and Nam” là hai người, đứng sau giới từ “for”, nên thay bằng “them”.|they=>Sau giới từ “for” không dùng đại từ chủ ngữ “they”.;;their=>“Their” là sở hữu, cần danh từ theo sau, ví dụ “their house”.;;themselves=>“Themselves” chỉ dùng khi chủ ngữ là chính họ; chủ ngữ ở đây là “I”.\nc|I can't find my keys. Can you help ___?|I / my / me / mine|2|Người nhận sự giúp đỡ là người nói, đứng sau động từ “help”, nên dùng tân ngữ “me”.|I=>Sau động từ “help” cần đại từ tân ngữ, không dùng chủ ngữ “I”.;;my=>“My” là sở hữu và cần danh từ đi sau, ví dụ “my keys”.;;mine=>“Mine” nghĩa là “của tôi”, không chỉ người được giúp đỡ.\nc|Look at that red bus! ___ is very big.|He / Him / They / It|3|“That red bus” là một vật; chỗ trống là chủ ngữ của “is”, nên dùng “It”.|He=>“He” dành cho người nam; chiếc xe buýt là vật nên không dùng “he”.;;Him=>“Him” là đại từ tân ngữ, không làm chủ ngữ trước “is”.;;They=>“They” là số nhiều, trong khi “that red bus” chỉ là một chiếc xe.\nc|Who is at the door? ___ me. I forgot my key.|It's / I'm / They're / Me is|0|Cấu trúc trả lời quen thuộc là “It's + đại từ tân ngữ”: “It's me.”|I'm=>Trả lời “Ai đó?” ta nói “It's me”, không nói “I'm me”.;;They're=>“They're” là số nhiều, không hợp khi người nói chỉ có một mình.;;Me is=>“Me is” sai ngữ pháp; phải có chủ ngữ “It” và động từ “is”.\nc|Between you and ___, I don't like the idea.|I / me / my / mine|1|“Between” là giới từ nên theo sau là đại từ tân ngữ, cả với “you and me”.|I=>Sau giới từ “between” dùng tân ngữ; “between you and I” thường bị xem là sai.;;my=>“My” là sở hữu, cần danh từ phía sau.;;mine=>“Mine” nghĩa là “của tôi”, không chỉ người nói.\nc|Anna and Ben live near us. We often visit ___.|they / their / them / us|2|Người được thăm là “Anna and Ben” (hai người), đứng sau “visit”, nên dùng “them”.|they=>“They” là chủ ngữ; sau động từ “visit” cần tân ngữ.;;their=>“Their” là sở hữu và cần danh từ đi sau.;;us=>“Us” là chúng tôi; người được thăm là Anna và Ben, không phải chúng tôi.\nc|I phoned the clinic, but ___ didn't answer.|them / we / their / they|3|Chỗ trống là chủ ngữ của “didn't answer”; “they” chỉ những người làm việc ở phòng khám.|them=>“Them” là tân ngữ, không đứng trước động từ “didn't answer” làm chủ ngữ.;;we=>“We” gồm cả người nói, trong khi người không nghe máy là nhân viên phòng khám.;;their=>“Their” là sở hữu, không làm chủ ngữ.\nc|My phone is old, so I want to change ___.|it / he / its / them|0|“My phone” là một vật, đứng sau động từ “change” làm tân ngữ, nên dùng “it”.|he=>“He” dành cho nam; điện thoại là vật nên cần “it”.;;its=>“Its” là sở hữu, cần danh từ theo sau.;;them=>“My phone” là một vật nên không dùng số nhiều “them”.\nc|Our grandma lives in the country. She often sends ___ fruit.|we / us / ours / ourselves|1|Sau động từ “sends” cần đại từ tân ngữ chỉ người nhận: “us”; “She” là bà, “us” là chúng tôi.|we=>“We” là đại từ chủ ngữ; sau “sends” cần tân ngữ.;;ours=>“Ours” nghĩa là “của chúng tôi”, không chỉ người nhận trái cây.;;ourselves=>“Ourselves” chỉ dùng khi chủ ngữ cũng là “we”; ở đây chủ ngữ là bà.\nx|Chọn câu đúng (chủ ngữ và tân ngữ)|Me know he, and him know I. / I know he, and him knows me. / I know him, and he knows me. / Me know him, and he know I.|2|Chủ ngữ dùng “I/he”, tân ngữ dùng “him/me”; “he” cần động từ “knows”.|Me know he, and him know I.=>Dùng sai đại từ: chủ ngữ phải là “I” và “he”, tân ngữ phải là “him” và “me”.;;I know he, and him knows me.=>Tân ngữ của “know” phải là “him”, và chủ ngữ của “knows” phải là “he”.;;Me know him, and he know I.=>Chủ ngữ “Me” sai; tân ngữ “I” sai và “knows” cần chia theo “he”.\nx|Chọn câu đúng (sau giới từ)|She gave it to we yesterday. / Her gave it to us yesterday. / She gave them to we yesterday. / She gave it to us yesterday.|3|Chủ ngữ “She” và sau giới từ “to” dùng tân ngữ “us”.|She gave it to we yesterday.=>Sau giới từ “to” dùng tân ngữ “us”, không dùng chủ ngữ “we”.;;Her gave it to us yesterday.=>“Her” là tân ngữ, không làm chủ ngữ trước “gave”.;;She gave them to we yesterday.=>Sau “to” phải là “us”; và “them” không hợp với “it” khi chỉ một vật.\nx|Chọn câu đúng (send me)|Can you send me the report? / Can you send I the report? / Can you send my the report? / Can me send you the report?|0|Người nhận là người nói, dùng tân ngữ “me”; trật tự: send + me + the report.|Can you send I the report?=>Sau “send” cần tân ngữ “me”, không dùng “I”.;;Can you send my the report?=>“My” là sở hữu, cần danh từ phía sau, không thay cho người nhận.;;Can me send you the report?=>Chủ ngữ của câu hỏi phải là “you” hoặc “I”, không phải “me”.\nx|Chọn câu đúng (and me)|They invited my wife and I to dinner. / They invited my wife and me to dinner. / Them invited my wife and me to dinner. / They invited me wife and my to dinner.|1|“My wife and me” là tân ngữ của “invited”, nên dùng “me”, giống như khi chỉ có “me”.|They invited my wife and I to dinner.=>“My wife and I” là tân ngữ của “invited” nên cần “me”.;;Them invited my wife and me to dinner.=>“Them” là tân ngữ, không làm chủ ngữ đứng trước “invited”.;;They invited me wife and my to dinner.=>Trật tự và đại từ đều sai: dạng đúng là “my wife and me”.\nt|I don't know that man. Do you know ___ (he)?|him|Sau động từ “know” dùng đại từ tân ngữ “him”.\nt|Mr and Mrs Lee are kind. ___ (they) own a small shop.|they|Chỗ trống là chủ ngữ của “own”, nên dùng đại từ chủ ngữ “they”.\nt|My sister and I like pizza. ___ (we) eat it every Friday.|we|“My sister and I” gồm cả người nói, thay bằng chủ ngữ “we”.\nt|The nurse is kind. I always thank ___ (she) after the visit.|her|Sau động từ “thank” dùng đại từ tân ngữ “her”; “nurse” ở đây là nữ vì có “she”.\nf|Him is my uncle. He lives in Hue.|Him|He|“Him” là tân ngữ; làm chủ ngữ đứng trước “is” phải dùng “He”.\nf|I don't know they very well.|they|them|Sau động từ “know” cần đại từ tân ngữ “them”.\no|We often visit them at the weekend.|Chủ ngữ + trạng từ tần suất + động từ + tân ngữ + trạng ngữ thời gian.\no|She told me about it.|Chủ ngữ + động từ + tân ngữ (me) + giới từ + tân ngữ (it).","quantifiers-2":"c|___ student in the class has a locker.|All / Both / Every / Either|2|“Student” là danh từ số ít và động từ “has” cũng số ít, nên dùng every. Câu nói về mọi học sinh trong lớp.|All=>“All” đi với danh từ số nhiều (all students), nhưng “student” ở đây là số ít.;;Both=>“Both” chỉ dùng cho hai người, mà một lớp học có nhiều học sinh.;;Either=>“Either” nghĩa là một trong hai, không hợp khi nói về cả lớp.\nc|___ my parents are teachers.|Every / Both / Each / Either|1|Hai người cùng làm một nghề thì dùng both + danh từ số nhiều. Động từ “are” cũng số nhiều.|Every=>“Every” cần danh từ số ít, còn “parents” là số nhiều.;;Each=>“Each” cần danh từ số ít hoặc đi với “of”, nên không đứng trước “my parents”.;;Either=>“Either” nghĩa là một trong hai và cần động từ số ít, không hợp với “are teachers”.\nc|___ of the two shirts fits me; they are both too small.|Neither / Either / Every / Both|0|Cả hai áo đều không vừa, nên dùng neither of the two + động từ số ít. Chữ “too small” cho thấy nghĩa phủ định.|Either=>“Either” mang nghĩa khẳng định (cái nào cũng được), trong khi câu nói cả hai đều không vừa.;;Every=>“Every” không dùng với “of the two”; chỉ dùng cho nhóm từ ba trở lên.;;Both=>“Both of the two shirts fits” sai vì “both” đi với động từ số nhiều “fit”.\nc|You can take the bus or the train. ___ is fine.|Either / Neither / Every / Both|0|Có hai lựa chọn và cái nào cũng được nên dùng either. Chữ “or” báo hiệu có hai khả năng.|Neither=>“Neither” nghĩa là không cái nào ổn, mâu thuẫn với ý “có thể đi bằng cái nào”.;;Every=>“Every” cần danh từ đi sau và không dùng cho hai đối tượng.;;Both=>“Both” đi với động từ số nhiều “are”, nhưng câu dùng “is”; nghĩa cũng không khớp ý chọn một trong hai.\nc|It rained ___ day yesterday, so we stayed at home.|every / all / each / both|1|Mưa suốt cả ngày hôm qua nên dùng all day. “Yesterday” chỉ một ngày cụ thể.|every=>“Every day yesterday” vô lý vì “yesterday” chỉ một ngày; “every day” nghĩa là ngày nào cũng vậy.;;each=>“Each day” nhấn mạnh từng ngày riêng lẻ, không hợp với một ngày hôm qua.;;both=>“Both day” sai vì “both” cần danh từ số nhiều và chỉ hai đối tượng.\nc|I go to the gym ___ morning before work.|all / every / both / neither|1|Thói quen lặp lại mỗi ngày dùng every + danh từ số ít: every morning. Cụm “before work” cũng chỉ thói quen.|all=>“All morning” nghĩa là suốt buổi sáng, không nói về thói quen lặp lại hằng ngày.;;both=>“Both morning” sai vì “both” cần danh từ số nhiều.;;neither=>“Neither morning” không hợp nghĩa và cần hai đối tượng.\nc|___ of the nurses has a badge.|All / Every / Both / Each|3|Động từ “has” là số ít, nên chọn each of + danh từ số nhiều + động từ số ít. Every và all không phù hợp với “of the nurses has”.|All=>“All of the nurses” đi với động từ số nhiều “have”, nhưng câu dùng “has”.;;Every=>“Every of” là lỗi hay gặp; every không đi trực tiếp với “of” (phải dùng every one of).;;Both=>“Both of the nurses” đi với động từ số nhiều “have”, trong khi ở đây là “has”.\nc|All ___ in this building are students.|resident / the residents / each resident / every residents|1|Sau all dùng danh từ số nhiều có “the”: all the residents. Động từ “are” cũng cho thấy chủ ngữ số nhiều.|resident=>“Resident” là số ít, nhưng “all” cần danh từ số nhiều và có “the”.;;each resident=>“All each resident” không ghép được; all không đi với each.;;every residents=>“Every” đi với danh từ số ít, nên “every residents” sai.\nc|Everybody ___ ready for the test now.|are / were / is / be|2|Everybody, everyone, everything luôn đi với động từ số ít. Chữ “now” cho biết thì hiện tại, nên dùng “is”.|are=>“Everybody” là đại từ số ít nên dùng “is”, không dùng “are”.;;were=>“Were” là thì quá khứ và số nhiều, không hợp với “now”.;;be=>“Be” không chia thì nên không dùng được làm động từ chính ở đây.\nc|Neither answer ___ correct, so try again.|are / is / be / were|1|Neither + danh từ số ít đi với động từ số ít: neither answer is. Cụm “try again” cho thấy thì hiện tại.|are=>“Neither answer” là số ít nên động từ phải là “is”.;;be=>“Be” không chia nên không dùng làm động từ chính trong câu này.;;were=>“Were” là quá khứ số nhiều, không hợp với “try again” (hiện tại).\nc|I like ___ the teachers at this school; they are very kind.|all / every / each / either|0|Câu nói về mọi giáo viên, danh từ số nhiều có “the”, nên dùng all the teachers.|every=>“Every the teachers” sai vì every không đứng trước “the” và cần danh từ số ít.;;each=>“Each the teachers” sai; each không đứng trực tiếp trước “the teachers” (phải là each of).;;either=>“Either” chỉ dùng cho hai đối tượng, không dùng cho cả nhóm giáo viên.\nc|I can speak both English ___ French.|or / nor / and / with|2|Cặp both … and … nối hai thứ cùng làm một việc. Chữ “both” báo hiệu phải có “and”.|or=>“Both … or” sai; both luôn đi với “and”.;;nor=>“Nor” đi với neither (neither … nor), không đi với both.;;with=>“With” không nối hai ngôn ngữ trong cấu trúc both … and.\nc|You can use ___ method; they both work well.|both / neither / all / either|3|Hai cách đều dùng được, và danh từ “method” là số ít nên chọn either method. “Both” cần “methods”.|both=>“Both method” sai vì “both” cần danh từ số nhiều (both methods).;;neither=>“Neither method” nghĩa là không cái nào, mâu thuẫn với “they both work well”.;;all=>“All method” sai; all cần danh từ số nhiều và dùng cho nhóm lớn hơn hai.\nc|There are two exits, but ___ door is open.|every / both / neither / all|2|Chữ “but” cho thấy ý ngược lại: cả hai cửa đều không mở. Dùng neither + danh từ số ít: neither door is open.|every=>“Every door is open” trái với “but” và nói về nhiều cửa, không phải hai.;;both=>“Both door” sai vì “both” cần danh từ số nhiều.;;all=>“All door” sai vì all cần danh từ số nhiều.\nx|Chọn câu đúng|Every student has to bring a dictionary. / Every students have to bring a dictionary. / All student has to bring a dictionary. / Each students has to bring a dictionary.|0|Every + danh từ số ít + động từ số ít. Chỉ câu đầu giữ đúng cả danh từ lẫn động từ.|Every students have to bring a dictionary.=>Every phải đi với danh từ số ít, nên không dùng “students” và “have”.;;All student has to bring a dictionary.=>All cần danh từ số nhiều; “student has” là số ít nên không khớp.;;Each students has to bring a dictionary.=>Each cần danh từ số ít, nên “students” sai.\nx|Chọn câu đúng|Both my sister lives in Hue. / Both of my sisters live in Hue. / Both of my sister live in Hue. / Both of my sisters lives in Hue.|1|Both of + my + danh từ số nhiều + động từ số nhiều. Chỉ câu này đúng cả hai vế.|Both my sister lives in Hue.=>Both cần danh từ số nhiều và động từ số nhiều.;;Both of my sister live in Hue.=>Sau “both of” danh từ phải số nhiều: “my sisters”.;;Both of my sisters lives in Hue.=>Both đi với động từ số nhiều “live”, không phải “lives”.\nx|Chọn câu đúng|I don't like neither of these hotels. / I like not either of these hotels. / I don't like either of these hotels. / I don't like either these hotels.|2|Câu phủ định với don't dùng either of + danh từ số nhiều. Neither tự nó đã mang nghĩa phủ định.|I don't like neither of these hotels.=>Câu đã có “don't” nên không dùng thêm “neither”; đó là phủ định kép.;;I like not either of these hotels.=>Trợ động từ “don't” phải đứng trước động từ chính; “like not” không tự nhiên.;;I don't like either these hotels.=>Sau either cần có “of” khi đi cùng “these hotels”.\nx|Chọn câu đúng|All of patients are waiting outside. / All the patients is waiting outside. / Every of the patients are waiting outside. / All of the patients are waiting outside.|3|All of the + danh từ số nhiều + động từ số nhiều. Chỉ câu này đủ “the” và đúng động từ.|All of patients are waiting outside.=>Sau all of cần có “the/my/these”: all of the patients.;;All the patients is waiting outside.=>Chủ ngữ “all the patients” là số nhiều nên động từ phải là “are”.;;Every of the patients are waiting outside.=>Every không đi trực tiếp với “of”, và “are” không khớp với every.\nt|I have two phones, but ___ of them works.|neither|Chữ “but” và “works” (số ít) cho thấy nghĩa phủ định cho cả hai, nên dùng neither of them.\nt|Take ___ of these two roads; it doesn't matter which one you choose.|either|Hai con đường, chọn đường nào cũng được nên dùng either of.\nt|___ morning I drink a glass of water.|every;each|Thói quen lặp lại mỗi sáng dùng every + danh từ số ít.\nt|Each of the nurses ___ (have) a key.|has|Each (of) luôn đi với động từ số ít, nên chia “has”.\nt|Everybody ___ (like) the new canteen.|likes|Everybody là số ít nên động từ thêm -s: likes.\nt|___ the milk in the fridge has gone off, so we need to buy more.|all|All đi với danh từ không đếm được “milk”; nghĩa là toàn bộ sữa đã hỏng.\nf|Everyone in my class have a laptop.|have|has|Everyone là đại từ số ít nên động từ phải là has.\nf|Both of the three students passed the test.|Both|All|Both chỉ dùng cho hai đối tượng; ba người trở lên dùng all.\nf|Both of the doctors is on duty today.|is|are|Both đi với động từ số nhiều: both of the doctors are.\nf|All of we are nurses at this clinic.|we|us|Sau giới từ “of” dùng đại từ tân ngữ: all of us.\no|Each of the students has a different timetable.|Each of + the + danh từ số nhiều đứng làm chủ ngữ, và động từ “has” chia số ít.","relative-nondefining":"c|My grandfather, ___ is 90, still walks every morning.|who / that / which / whom|0|Dùng “who” cho người, làm chủ ngữ trong mệnh đề có dấu phẩy; dấu hiệu là “grandfather” và dấu phẩy.|that=>Sau dấu phẩy không dùng “that”; mệnh đề này thêm thông tin phụ.;;which=>“Which” dùng cho vật, còn grandfather là người.;;whom=>“Whom” là tân ngữ, nhưng ở đây từ cần thay thế đang làm chủ ngữ.\nc|The new library, ___ opened last month, has a quiet study room.|that / which / what / who|1|“Which” dùng cho vật trong mệnh đề không xác định; dấu hiệu là dấu phẩy sau “library”.|that=>Sau dấu phẩy không được dùng “that”.;;what=>“What” không làm đại từ quan hệ, nên không nối được mệnh đề.;;who=>“Who” chỉ người, còn library là vật.\nc|Mr Tran, ___ daughter is a nurse, works at the clinic.|who's / which / whose / whom|2|“Whose + danh từ” chỉ sở hữu; “whose daughter” nghĩa là con gái của ông Tran.|who's=>“Who's” là who is, không phù hợp: “who is daughter” sai nghĩa.;;which=>“Which” chỉ vật, không thể chỉ người.;;whom=>“Whom” là tân ngữ, không đứng trước danh từ daughter.\nc|We stayed in Da Lat, ___ the weather is cool all year.|which / that / when / where|3|“Where” thay cho “in + địa điểm”; dấu hiệu là Da Lat và dấu phẩy.|which=>“Which the weather is cool” thiếu giới từ in; không nối được.;;that=>Sau dấu phẩy không dùng “that”, và “that” không chỉ nơi chốn ở đây.;;when=>“When” chỉ thời gian, còn Da Lat là nơi chốn.\nc|I'll never forget 2019, ___ I met my husband.|when / where / that / who|0|“When” thay cho “in + thời gian”; “2019” là mốc thời gian.|where=>“Where” chỉ nơi chốn, còn 2019 là thời gian.;;that=>Sau dấu phẩy hoặc giới từ không dùng “that” trong mệnh đề quan hệ này.;;who=>“Who” chỉ người, mà 2019 là năm.\nc|She passed her IELTS test, ___ surprised everyone.|that / which / what / who|1|“Which” thay cho cả mệnh đề “passed her IELTS test”, không chỉ một danh từ.|that=>Sau dấu phẩy không dùng “that” để nói về cả mệnh đề.;;what=>“What” không dùng làm đại từ quan hệ nối hai mệnh đề.;;who=>“Who” chỉ người, còn ở đây là cả sự việc cô ấy đỗ.\nc|My manager, ___ I work closely, is very supportive.|whom / who / with whom / that with|2|Giới từ đứng trước whom trong văn trang trọng: “with whom I work”; manager là người.|whom=>Thiếu giới từ with ở phía trước; cụm “work with” cần giới từ ở đây.;;who=>Thiếu giới từ with, và “who” không đi sau giới từ.;;that with=>“That” không dùng trong mệnh đề này; cũng không đặt sau giới từ.\nc|The report, in ___ she explains the results, is online.|whom / that / whose / which|3|Sau giới từ in dùng “which” cho vật; “in which” thay cho “in the report”.|whom=>“Whom” chỉ người, còn report là vật.;;that=>“That” không đứng sau giới từ in.;;whose=>“Whose” chỉ sở hữu, không dùng sau in ở đây.\nc|Dr Park, ___ I met at the conference, is giving a talk.|whom / whose / which / where|0|“Whom” làm tân ngữ cho “met”; Dr Park là người được gặp.|whose=>“Whose” cần danh từ ngay sau, mà I không phải danh từ.;;which=>“Which” chỉ vật; Dr Park là người.;;where=>“Where” chỉ nơi chốn, không dùng cho người.\nc|Hue, ___ is famous for its food, attracts many tourists.|that / where / which / whose|2|“Which” làm chủ ngữ cho “is famous”; Hue là địa danh nên thêm thông tin phụ.|that=>Sau dấu phẩy hoặc giới từ không dùng “that” trong mệnh đề quan hệ này.;;where=>“Where” cần mệnh đề đầy đủ ngay sau, mà ở đây thiếu chủ ngữ.;;whose=>“Whose” cần có danh từ đứng ngay sau, mà câu này chưa có.\nc|The company, ___ founder is a doctor, sells herbal tea.|who / which / that / whose|3|“Whose + danh từ” chỉ người sáng lập của công ty; “founder” đứng ngay sau.|who=>“Who” chỉ người, không đứng trước danh từ founder.;;which=>“Which” không đứng trước danh từ founder khi chỉ sở hữu.;;that=>“That” không chỉ sở hữu và không dùng sau dấu phẩy.\nc|The clinic, ___ my mother works, is hiring.|which / where / when / whose|1|“Where” thay cho “at the clinic”; dấu hiệu là nơi chốn và dấu phẩy.|which=>“Which my mother works” thiếu giới từ at hoặc in nên câu sai.;;when=>“When” chỉ thời gian, còn clinic là nơi chốn.;;whose=>“Whose” cần danh từ ngay sau và chỉ sở hữu.\nc|The lift was out of order, ___ meant we had to climb the stairs.|what / that / which / who|2|“Which” thay cho cả mệnh đề “the lift was out of order”.|what=>“What” không làm đại từ quan hệ.;;that=>Sau dấu phẩy hoặc giới từ không dùng “that” trong mệnh đề quan hệ này.;;who=>“Who” chỉ người, ở đây chỉ cả sự việc.\nc|My grandmother, to ___ I owe a lot, lives in Hue.|whom / who / that / which|0|Giới từ + “whom” cho người; “to whom I owe a lot” dùng văn trang trọng.|who=>Sau giới từ to dùng “whom”, không dùng “who”.;;that=>Sau dấu phẩy hoặc giới từ không dùng “that” trong mệnh đề quan hệ này.;;which=>“Which” chỉ vật, còn grandmother là người.\nx|Chọn câu đúng: người anh duy nhất|My brother, who he works in Hanoi, is a vet. / My brother, who works in Hanoi, is a vet. / My brother, that works in Hanoi, is a vet. / My brother, which works in Hanoi, is a vet.|1|Mệnh đề không xác định đặt giữa hai dấu phẩy và dùng “who” cho người.|My brother, that works in Hanoi, is a vet.=>Mệnh đề giữa hai dấu phẩy không dùng “that”.;;My brother, which works in Hanoi, is a vet.=>“Which” chỉ vật, còn brother là người.;;My brother, who he works in Hanoi, is a vet.=>Lặp thêm đại từ he sau who; who đã đóng vai chủ ngữ rồi.\nx|Chọn câu đúng: bình luận về cả sự việc|She didn't answer, that worried me. / She didn't answer, what worried me. / She didn't answer, which worried me. / She didn't answer, who worried me.|2|“Which” thay cho cả mệnh đề trước; chỉ phương án này dùng đại từ đúng.|She didn't answer, that worried me.=>“That” không dùng sau dấu phẩy để chỉ cả mệnh đề.;;She didn't answer, what worried me.=>“What” không làm đại từ quan hệ.;;She didn't answer, who worried me.=>“Who” chỉ người, còn đây là cả sự việc cô ấy không trả lời.\nx|Chọn câu đúng: nói về con sông|The Mekong, which flows through Vietnam, is very long. / The Mekong, that flows through Vietnam, is very long. / The Mekong, it flows through Vietnam, is very long. / The Mekong, which it flows through Vietnam, is very long.|0|Con sông là vật nên dùng “which”, không lặp đại từ.|The Mekong, that flows through Vietnam, is very long.=>Không dùng “that” sau dấu phẩy trong mệnh đề không xác định.;;The Mekong, it flows through Vietnam, is very long.=>Thiếu đại từ quan hệ; hai mệnh đề bị nối sai bằng dấu phẩy.;;The Mekong, which it flows through Vietnam, is very long.=>Lặp đại từ it; which đã thay thế chủ ngữ.\nx|Chọn câu đúng: sở hữu|Mrs Cole, who's son is a surgeon, lives next door. / Mrs Cole, whose her son is a surgeon, lives next door. / Mrs Cole, whom son is a surgeon, lives next door. / Mrs Cole, whose son is a surgeon, lives next door.|3|“Whose + danh từ” chỉ sở hữu; không thêm đại từ sở hữu khác.|Mrs Cole, who's son is a surgeon, lives next door.=>“Who's” là who is, không phải sở hữu; cần “whose”.;;Mrs Cole, whose her son is a surgeon, lives next door.=>Không lặp thêm “her” sau “whose” vì whose đã chỉ sở hữu.;;Mrs Cole, whom son is a surgeon, lives next door.=>“Whom” không chỉ sở hữu; cần “whose”.\nt|My aunt, ___ is a midwife, is visiting us tomorrow. (who / which)|who|Aunt là người, làm chủ ngữ trong mệnh đề có dấu phẩy, nên dùng “who”.\nt|He lost his keys, ___ was annoying. (who / which)|which|“Which” thay cho cả sự việc đánh mất chìa khóa, không chỉ một người.\nt|The village, ___ my parents were born, is by the sea. (where / which)|where|Village là nơi chốn; “where” thay cho “in the village”.\nt|Dr Mai, to ___ I spoke yesterday, is on leave. (who / whom)|whom|Sau giới từ “to” dùng “whom” cho người.\nf|Dr Nam, who's clinic is nearby, is my cousin.|who's|whose|“Who's” là who is; chỉ sự sở hữu (clinic của Dr Nam) phải dùng “whose”.\nf|The clinic, who opened in May, is already busy.|who|which|Clinic là vật, nên dùng “which” thay cho “who”.\no|My brother, who lives in Osaka, is a chef.|Mệnh đề who đứng ngay sau danh từ brother, giữa hai dấu phẩy.","some-any":"c|There are ___ oranges in the bowl, so help yourself.|some / any / no / anything|0|Câu khẳng định với danh từ đếm được số nhiều “oranges” dùng some, và “help yourself” cho thấy có cam trong bát.|any=>“Any” dùng trong phủ định hoặc câu hỏi; câu này là khẳng định nên không hợp.;;no=>“No oranges” nói là không có cam, mâu thuẫn với “help yourself” (mời bạn tự lấy).;;anything=>“Anything” là đại từ đứng một mình, không đứng trước danh từ “oranges”.\nc|I'm sorry, we haven't got ___ tickets left.|some / no / something / any|3|Câu phủ định “haven't got” cần any trước danh từ số nhiều “tickets”, nghĩa là không còn vé nào.|some=>“Some” không dùng trong câu phủ định thông thường như “haven't got”.;;no=>“No” đã mang nghĩa phủ định, đi với “haven't” sẽ thành phủ định hai lần.;;something=>“Something” là đại từ, không đứng trước danh từ “tickets”.\nc|Is there ___ milk in the fridge?|some / any / none / nothing|1|Câu hỏi Yes/No về danh từ không đếm được “milk” dùng any, vì người nói chưa biết có hay không.|some=>“Some” chỉ dùng trong câu hỏi khi mời hoặc nhờ; ở đây chỉ hỏi có hay không.;;nothing=>“Nothing” là đại từ, không đứng trước danh từ “milk”.;;none=>“None” là đại từ đứng một mình, không đứng trước danh từ “milk”.\nc|There is ___ in the box. It's completely empty.|something / anything / nothing / everything|2|“Completely empty” nghĩa là không có gì, nên dùng nothing với động từ khẳng định “is”.|something=>“Something” nghĩa là có một thứ nào đó, trái với “completely empty”.;;anything=>“Anything” cần câu phủ định, trong khi câu này là khẳng định “There is”.;;everything=>“Everything” nghĩa là mọi thứ đều có trong hộp, trái với “empty”.\nc|Would you like ___ more rice?|every / no / anything / some|3|Lời mời “Would you like ...?” dùng some dù là câu hỏi, vì người nói mong nhận câu trả lời “có”.|no=>“No” tạo nghĩa phủ định, không hợp với lời mời.;;anything=>“Anything” là đại từ, không đứng trước danh từ “rice”.;;every=>“Every” đi với danh từ đếm được số ít, không đi với danh từ không đếm được “rice”.\nc|I didn't see ___ at the station, so I went home.|anybody / somebody / nobody / everybody|0|Câu phủ định “didn't see” đi với anybody, nghĩa là không thấy ai ở nhà ga.|somebody=>“Didn't see somebody” không dùng trong phủ định thông thường; cần anybody.;;nobody=>“Nobody” cộng với “didn't” tạo hai phủ định, sai trong tiếng Anh chuẩn.;;everybody=>“Everybody” nghĩa là mọi người, không hợp với “so I went home”.\nc|She has ___ friends in this city, so she feels lonely.|some / any / no / a lot|2|Nghĩa phủ định với động từ khẳng định “has” dùng no; “feels lonely” xác nhận cô ấy không có bạn nào.|some=>“Some friends” nghĩa là có vài người bạn, mâu thuẫn với “feels lonely”.;;any=>“Any” cần đi với “doesn't have”, còn “has any” không tự nhiên ở câu khẳng định này.;;a lot=>“A lot” cần “of” trước danh từ: “a lot of friends”.\nc|I'm looking for my keys, but I can't find them ___.|somewhere / anywhere / nowhere / everywhere|1|Câu phủ định “can't find” đi với anywhere, nghĩa là không tìm thấy ở đâu cả.|somewhere=>“Somewhere” trái với “can't find” vì ngụ ý đã biết chỗ nào đó.;;nowhere=>“Nowhere” cộng với “can't” tạo hai phủ định, không đúng trong tiếng Anh chuẩn.;;everywhere=>“Everywhere” nghĩa là ở mọi nơi, không hợp với “can't find them”.\nc|There was ___ interesting on the news last night, so I watched it.|something / anything / some / nothing|0|Câu khẳng định “There was ...” với đại từ ghép dùng something, và “so I watched it” cho thấy có tin hay.|anything=>“Anything” dùng trong phủ định hoặc câu hỏi, không dùng sau “There was” khẳng định.;;some=>“Some” cần danh từ đi sau, ở đây chỉ có tính từ “interesting”.;;nothing=>“Nothing interesting” nghĩa là không có gì hay, mâu thuẫn với “so I watched it”.\nc|___ is perfect, but we try our best every day.|Somebody / Anybody / Everybody / Nobody|3|Nghĩa là không ai hoàn hảo, nên dùng nobody; “but we try our best” hợp với ý nhận xét chung đó.|Somebody=>“Somebody is perfect” nghĩa là có một người hoàn hảo, ý rất lạ.;;Anybody=>“Anybody” không đứng làm chủ ngữ khẳng định với nghĩa không ai.;;Everybody=>“Everybody is perfect” nói ai cũng hoàn hảo, trái với ý “try our best”.\nc|I've got ___ to tell you: the lesson is cancelled.|any / something / nothing / anything|1|Câu khẳng định, có một tin cụ thể sắp nói (dấu hai chấm báo trước), nên dùng đại từ something.|any=>“Any” cần danh từ đi sau hoặc câu phủ định; ở đây là câu khẳng định và không có danh từ.;;nothing=>“Nothing” nghĩa là không có gì, mâu thuẫn với việc sắp nói một tin cụ thể.;;anything=>“Anything” dùng trong phủ định hoặc câu hỏi; câu khẳng định “I've got ... to tell you” cần something.\nc|The hotel is full. There are ___ rooms available.|any / some / no / anything|2|“The hotel is full” cho thấy không còn phòng nào, nên dùng no rooms với động từ khẳng định “are”.|any=>“Any” cần câu phủ định như “aren't any”; “There are any” sai.;;some=>“Some rooms” nghĩa là còn vài phòng, mâu thuẫn với “is full”.;;anything=>“Anything” là đại từ, không đứng trước danh từ “rooms”.\nc|Have you got ___ plans for the weekend?|some / a / something / any|3|Câu hỏi trung tính về danh từ số nhiều “plans” dùng any, vì chưa biết có kế hoạch hay không.|some=>“Some” chỉ dùng trong câu hỏi khi mời hoặc nhờ; đây là câu hỏi thông tin.;;something=>“Something” là đại từ, không đứng trước danh từ “plans”.;;a=>“A” không đứng trước danh từ số nhiều “plans”.\nc|Everyone in the class ___ finished the test.|has / have / are / were|0|Đại từ ghép “everyone” luôn đi với động từ số ít, nên cần has trong thì hiện tại hoàn thành.|have=>“Have” dùng với chủ ngữ số nhiều, còn “everyone” là số ít.;;are=>“Are” không đi với “finished” để tạo thì hiện tại hoàn thành.;;were=>“Were” là quá khứ của be, không tạo được cấu trúc đúng với “finished” ở đây.\nx|Chọn câu đúng|I don't need no help. / I don't need some help. / I don't need any help. / I need not any help.|2|Câu phủ định “don't need” đi với any; không dùng “no” hay “some” ở đây.|I don't need no help.=>“Don't ... no” là hai phủ định, sai trong tiếng Anh chuẩn.;;I don't need some help.=>“Some help” không dùng sau “don't need” trong câu phủ định thông thường.;;I need not any help.=>“Need not any” không tự nhiên; phải nói “don't need any” hoặc “need no”.\nx|Chọn câu đúng nhất|Is there anybodies at home? / Is there anybody at home? / Are there anybody at home? / Is there some body at home?|1|Từ ghép anybody viết liền và là số ít, nên câu hỏi dùng “Is there anybody ...?”.|Is there anybodies at home?=>“Anybodies” không tồn tại; anybody không có dạng số nhiều.;;Are there anybody at home?=>“Are” sai vì anybody là số ít, phải đi với “Is”.;;Is there some body at home?=>“Some body” tách rời nghĩa là “một cơ thể”, không phải “một người”.\nx|Chọn câu đúng ngữ pháp|There isn't anything to eat. / There isn't something to eat. / There's anything to eat. / There isn't nothing to eat.|0|Phủ định “isn't” đi với anything; hai từ phủ định “isn't nothing” sai.|There isn't nothing to eat.=>“Isn't nothing” có hai phủ định, không đúng trong tiếng Anh chuẩn.;;There isn't something to eat.=>“Isn't something” không dùng trong phủ định thông thường; cần anything.;;There's anything to eat.=>“There's anything” là câu khẳng định, nhưng anything không dùng như vậy.\nx|Chọn câu viết đúng|Would you like something biscuits? / Would you like biscuits some? / Would you like somes biscuits? / Would you like some biscuits?|3|Lời mời dùng some đứng trước danh từ số nhiều “biscuits”.|Would you like biscuits some?=>Some phải đứng trước danh từ, không đứng sau “biscuits”.;;Would you like somes biscuits?=>“Somes” không tồn tại; some không thêm -s.;;Would you like something biscuits?=>“Something” là đại từ, không đứng trước danh từ “biscuits”.\nx|Chọn câu không có lỗi|She didn't go nowhere last night. / She went nowhere interesting last night. / She went anywhere interesting last night. / She didn't went anywhere last night.|1|“Went nowhere” có động từ khẳng định + nowhere; còn “didn't go nowhere” có hai phủ định.|She didn't go nowhere last night.=>“Didn't go nowhere” là phủ định kép, sai trong tiếng Anh chuẩn.;;She went anywhere interesting last night.=>“Went anywhere” là khẳng định, any không dùng như vậy với nghĩa không đi đâu.;;She didn't went anywhere last night.=>“Didn't went” sai vì sau “didn't” động từ phải ở dạng nguyên mẫu.\nt|I haven't got ___ (some/any) sugar in my tea.|any|Câu phủ định “haven't got” đi với any trước danh từ không đếm được “sugar”.\nt|There is ___ (no/any) milk left, so I'll go to the shop.|no|Động từ “is” ở dạng khẳng định nên dùng no; “go to the shop” cho thấy hết sữa.\nt|Would you like ___ (some/any) soup?|some|Lời mời dùng some dù là câu hỏi, vì mong nhận câu trả lời “có”.\nt|I couldn't see ___ (somebody/anybody) in the waiting room.|anybody;anyone|Câu phủ định “couldn't see” đi với anybody hoặc anyone, nghĩa là không thấy ai.\nf|There aren't some chairs in the hall.|some|any|Câu phủ định “aren't” cần any thay cho some.\nf|I can see anybody outside the window, so it's quiet.|anybody|nobody|Ý là không thấy ai nên cần nobody; anybody trong câu khẳng định thành nghĩa khác.\nf|Everybody are here, so we can start.|are|is|Từ ghép với -body là số ít nên cần is.\no|There isn't anything interesting on TV tonight.|Phủ định “isn't” + anything + tính từ: tính từ đứng sau đại từ ghép.","subjunctive-formal":"c|The doctor recommended that she ___ more water.|drink / drinks / drank / drinking|0|Sau recommend that dùng giả định: nguyên mẫu không đổi theo ngôi, nên “she drink”; “recommended” là tín hiệu.|drinks=>Sau recommend that dùng nguyên mẫu, không chia -s dù chủ ngữ là “she”.;;drank=>Quá khứ “drank” không dùng trong mệnh đề giả định sau recommend that.;;drinking=>V-ing không đứng sau chủ ngữ “she” để làm động từ của mệnh đề that.\nc|It's time we ___ the meeting; everyone is waiting.|starts / started / have started / are starting|1|It's time + S + V2 chỉ việc nên làm ngay; “everyone is waiting” cho thấy đã đến lúc bắt đầu.|starts=>Sau “It's time we” dùng quá khứ đơn, không dùng hiện tại thêm -s.;;have started=>Hiện tại hoàn thành không dùng sau “It's time we” trong cấu trúc này.;;are starting=>Hiện tại tiếp diễn không đi với “It's time + S”; cần quá khứ đơn.\nc|I'd rather you ___ your phone during the lesson.|don't use / not to use / didn't use / won't use|2|Would rather + S + V2 diễn tả mong người khác làm; “you” là chủ ngữ mới nên dùng didn't use.|don't use=>Sau “would rather + S” dùng quá khứ đơn, nên “don't use” không đúng.;;not to use=>“not to use” không đứng sau chủ ngữ “you” trong cấu trúc này.;;won't use=>“won't use” là tương lai, không dùng sau would rather + chủ ngữ mới.\nc|The rules demand that every visitor ___ a mask.|wears / wore / wearing / wear|3|Demand that + S + V nguyên mẫu; dù “every visitor” là số ít vẫn dùng wear, không chia -s.|wears=>Sau demand that dùng nguyên mẫu, không thêm -s theo “every visitor”.;;wore=>Quá khứ “wore” không đúng trong mệnh đề giả định sau demand.;;wearing=>V-ing không làm động từ chính của mệnh đề that.\nc|You'd better ___ now, or you'll miss the train.|leave / to leave / leaving / left|0|Had better + V nguyên mẫu không “to”; vế “or you'll miss the train” cho thấy lời khuyên mạnh.|to leave=>Sau “had better” là nguyên mẫu không “to”.;;leaving=>V-ing không đi sau “had better”; cần nguyên mẫu.;;left=>Quá khứ “left” không dùng sau “had better” vì đã có “had”.\nc|I'd rather ___ at home than go to the party.|to stay / stay / staying / stayed|1|Cùng chủ ngữ “I” nên dùng would rather + V nguyên mẫu; vế sau “go” cũng nguyên mẫu để song song.|to stay=>Sau “would rather” không dùng “to”; cần nguyên mẫu.;;staying=>V-ing không đi sau “would rather”; cần nguyên mẫu.;;stayed=>Quá khứ “stayed” chỉ dùng khi có chủ ngữ mới sau rather, ở đây thì không.\nc|My advisor recommended that I ___ my thesis topic.|changes / to change / change / changing|2|Recommend that + S + V nguyên mẫu, nên “I change”; không dùng “to” hay chia theo ngôi.|changes=>Sau recommend that dùng nguyên mẫu, không chia -s theo ngôi.;;to change=>“to change” không đứng sau chủ ngữ “I” trong mệnh đề that.;;changing=>V-ing không dùng làm động từ chính của mệnh đề that.\nc|It's high time the government ___ something about pollution.|does / do / will do / did|3|It's high time + S + V2 phê phán điều đáng ra phải làm; do đó “the government did”.|does=>Hiện tại “does” không dùng sau “It's high time” dù nói chuyện hiện nay.;;do=>Nguyên mẫu “do” không đúng; sau “high time + S” cần quá khứ đơn.;;will do=>Tương lai không dùng sau “It's high time + S”.\nc|'Shall I call him tonight?' 'I'd rather you ___ him tomorrow.'|called / calling / to call / are calling|0|Would rather + S + V2 nói điều mình muốn người khác làm ở hiện tại hoặc tương lai: “called … tomorrow”.|calling=>V-ing không dùng sau chủ ngữ “you” với would rather.;;to call=>“to call” không đi sau would rather + chủ ngữ mới.;;are calling=>Hiện tại tiếp diễn không dùng sau would rather + S; cần quá khứ đơn.\nc|You'd better ___ late for the interview.|don't be / not be / not to be / aren't|1|Phủ định của had better là had better not + V; “be late” giữ nguyên mẫu, không dùng “to”.|don't be=>Không dùng trợ động từ “don't” sau “had better”; phủ định đặt “not” sau better.;;not to be=>Sau “had better not” là nguyên mẫu không “to”.;;aren't=>“aren't” không đi sau “You'd better”; cần not + nguyên mẫu.\nc|The committee recommended that the hospital ___ more nurses.|hires / hired / hire / to hire|2|Recommend that + S + V nguyên mẫu; “the hospital hire” chứ không phải “hires”.|hires=>Sau recommend that dùng nguyên mẫu, không chia -s theo “the hospital”.;;hired=>Quá khứ “hired” không đúng trong mệnh đề giả định sau recommend.;;to hire=>“to hire” không đứng sau chủ ngữ “the hospital” trong mệnh đề that.\nc|It's about time you ___ for the exam instead of watching TV.|study / studies / are studying / studied|3|It's about time + S + V2 nhắc việc nên làm ngay; “instead of watching TV” cho thấy phàn nàn.|study=>Nguyên mẫu “study” không đúng; sau “It's about time + S” cần quá khứ đơn.;;studies=>Hiện tại “studies” không dùng sau “It's about time + S”.;;are studying=>Hiện tại tiếp diễn không đi với “It's about time + S”.\nc|The teacher insisted that Tom ___ the exam.|retake / retakes / retook / to retake|0|Insist that + S + V nguyên mẫu, nên “Tom retake”; đây là cách nói trang trọng.|retakes=>Sau insist that dùng nguyên mẫu, không chia -s theo “Tom”.;;retook=>Quá khứ “retook” không dùng trong mệnh đề giả định sau insist.;;to retake=>“to retake” không đứng sau chủ ngữ “Tom” trong mệnh đề that.\nc|I demand that he ___ immediately.|apologises / apologise / apologised / apologising|1|Demand that + S + V nguyên mẫu; yêu cầu mạnh “immediately” đi với dạng giả định “he apologise”.|apologises=>Sau demand that dùng nguyên mẫu, không chia -s theo “he”.;;apologised=>Quá khứ “apologised” không dùng trong mệnh đề giả định sau demand.;;apologising=>V-ing không làm động từ chính của mệnh đề that.\nc|You didn't warn me. I'd rather you ___ me about the delay yesterday.|told / tell / had told / tells|2|Với việc đã qua dùng would rather + S + had + V3; “yesterday” cho thấy ý tiếc nuối.|told=>Quá khứ đơn “told” trong cấu trúc này chỉ hiện tại hoặc tương lai, không diễn tả việc đã qua với “yesterday”.;;tell=>Nguyên mẫu “tell” không phù hợp với việc đã qua “yesterday”.;;tells=>Hiện tại “tells” không hợp với mốc “yesterday” đã qua.\nx|Chọn câu đúng (suggest)|The doctor suggested him to take a few days off. / The doctor suggested that he to take a few days off. / The doctor suggested that he taking a few days off. / The doctor suggested that he take a few days off.|3|Suggest that + S + V nguyên mẫu, nên “that he take” là dạng đúng; không dùng him to V.|The doctor suggested him to take a few days off.=>Suggest không đi với “him to + V”; phải dùng that-clause hoặc V-ing.;;The doctor suggested that he to take a few days off.=>Có “to” thừa sau chủ ngữ “he”; mệnh đề that cần nguyên mẫu không “to”.;;The doctor suggested that he taking a few days off.=>V-ing không thể làm động từ chính của mệnh đề that sau chủ ngữ “he”.\nx|Chọn câu đúng (it's time)|It's time we updated our website. / It's time we are updating our website. / It's time we to update our website. / It's time we will update our website.|0|It's time + S + V2 là cấu trúc cố định; “we updated” dù ý nghĩa là hiện tại.|It's time we are updating our website.=>Hiện tại tiếp diễn không dùng sau “It's time we”; cần quá khứ đơn.;;It's time we to update our website.=>“to” thừa sau chủ ngữ “we”; không thể dùng với chủ ngữ mới.;;It's time we will update our website.=>Tương lai “will” không dùng sau “It's time + S”.\nx|Chọn câu đúng (would rather)|I'd rather you don't to park here. / I'd rather you didn't park here. / I'd rather you not parked here. / I'd rather to you didn't park here.|1|Would rather + S + didn't + V nói điều mình mong người khác không làm; chỉ cần quá khứ đơn.|I'd rather you don't to park here.=>Câu này sai cả thì lẫn “to” thừa; cấu trúc cần quá khứ đơn “didn't park”.;;I'd rather you not parked here.=>Phủ định “not parked” không tạo được cấu trúc đúng; dùng “didn't park”.;;I'd rather to you didn't park here.=>“to” thừa trước “you”; sau “would rather” không có “to”.\nx|Chọn câu đúng (had better)|You'd better don't drive in this fog. / You'd better not to drive in this fog. / You'd better not drive in this fog. / You'd better to not drive in this fog.|2|Had better not + V nguyên mẫu; mọi lựa chọn có “to” hoặc “don't” đều sai.|You'd better don't drive in this fog.=>Không dùng “don't” sau had better; phủ định đặt “not” sau better.;;You'd better not to drive in this fog.=>Sau “had better not” là nguyên mẫu không “to”.;;You'd better to not drive in this fog.=>Vị trí “to not” là sai; sau had better chỉ đặt “not + V” và không có “to”.\nt|It's time we ___ (leave) for the airport.|left|Sau It's time + chủ ngữ ta dùng quá khứ đơn, nên leave thành left.\nt|The manager insisted that every employee ___ (attend) the training.|attend|Sau insist that dùng giả định nên động từ giữ nguyên mẫu: attend, không thêm -s.\nt|I'd rather you ___ (not tell) anyone about this.|didn't tell;did not tell|Would rather + chủ ngữ mới dùng quá khứ đơn; phủ định là didn't tell.\nt|You'd better ___ (take) an umbrella; it looks like rain.|take|Had better đi với động từ nguyên mẫu không to, nên đáp án là take.\nf|I'd rather stayed at home tonight.|stayed|stay|Khi cùng chủ ngữ, would rather đi với nguyên mẫu, không dùng quá khứ.\nf|It's time we go home; it's very late.|go|went|It's time + S dùng quá khứ đơn nên go phải đổi thành went.\nf|You had better asking the manager first.|asking|ask|Sau had better là nguyên mẫu không to, nên dùng ask chứ không phải asking.\no|I'd rather you didn't use your phone here.|Would rather + chủ ngữ mới + didn't + V nói điều mình mong người khác không làm.\no|The teacher insisted that every student be on time.|Insisted that + chủ ngữ + nguyên mẫu be; thứ tự: chủ ngữ, động từ chính, that, mệnh đề.","time-clauses":"c|I'll send you the report as soon as I ___ it.|finish / will finish / am finishing / finished|0|Sau as soon as nói về tương lai dùng hiện tại đơn; chủ ngữ “I” nên dùng finish.|will finish=>Không dùng will trong mệnh đề sau as soon as khi nói về tương lai.;;am finishing=>Hiện tại tiếp diễn không hợp ở mệnh đề thời gian này, vì ý là hoàn thành xong.;;finished=>Quá khứ đơn không hợp vì mệnh đề chính dùng “I'll”, nói về tương lai.\nc|The phone rang while I ___ a shower.|had taken / was taking / am taking / take|1|Hành động đang diễn ra bị cắt ngang dùng quá khứ tiếp diễn sau while: was taking.|had taken=>Quá khứ hoàn thành nói việc tắm đã xong trước đó, không diễn tả việc đang tắm thì điện thoại reo.;;am taking=>Hiện tại tiếp diễn sai thì, vì câu chính “rang” ở quá khứ.;;take=>Hiện tại đơn sai thì, vì câu kể về một việc đã xảy ra.\nc|Please wait here until the doctor ___ you.|will call / called / calls / would call|2|Sau until nói về tương lai dùng hiện tại đơn; chủ ngữ số ít nên calls.|will call=>Không dùng will sau until khi nói về việc sẽ xảy ra.;;called=>Quá khứ đơn không hợp với lời yêu cầu “Please wait here” ở hiện tại.;;would call=>Would call là dạng điều kiện hoặc tương lai trong quá khứ, không hợp ở đây.\nc|I fell asleep ___ the long film.|during / while / when / as soon as|0|Sau chỗ trống là cụm danh từ “the long film”, nên dùng giới từ during.|while=>While phải đi với một mệnh đề có chủ ngữ và động từ, không đi với cụm danh từ.;;when=>When đi với mệnh đề, không đi với cụm danh từ ở vị trí này.;;as soon as=>As soon as cũng cần một mệnh đề đầy đủ.\nc|I read a magazine ___ I was waiting for the bus.|during / until / by / while|3|Hai hành động xảy ra cùng lúc, sau chỗ trống là mệnh đề “I was waiting”, nên dùng while.|during=>During đi với danh từ, không đi với mệnh đề.;;until=>Until nghĩa là cho đến khi, không hợp với hai hành động đồng thời.;;by=>By không dùng để nối mệnh đề như vậy trong câu này.\nc|By the time Lan woke up, her roommate ___ for work.|leaves / has left / had left / will leave|2|“By the time” + quá khứ đơn (woke up) thì việc xảy ra trước đó dùng quá khứ hoàn thành; việc đi làm xong trước lúc Lan thức dậy.|leaves=>Hiện tại đơn không hợp vì cả câu nói về quá khứ (woke up), hành động đi làm đã xảy ra trước đó.;;has left=>Hiện tại hoàn thành gắn với hiện tại, không hợp với mốc quá khứ “woke up” trong câu này.;;will leave=>Thì tương lai không phù hợp vì mốc thời gian “woke up” đã ở quá khứ rồi.\nc|By the time Mum gets home, I ___ the dinner.|will cook / am cooking / cooked / will have cooked|3|Việc nấu sẽ xong trước mốc “Mum gets home” trong tương lai, nên dùng will have cooked.|will cook=>Will cook chỉ quyết định tương lai, không diễn tả việc đã xong trước mốc.;;am cooking=>Am cooking diễn tả đang nấu, không nói đến việc hoàn thành trước mốc.;;cooked=>Quá khứ đơn sai vì sự việc thuộc về tương lai.\nc|I'll tell her the news when she ___ tomorrow.|arrived / will arrive / arrives / is arriving|2|Sau when nói về tương lai dùng hiện tại đơn; từ “tomorrow” là dấu hiệu thời gian.|arrived=>Quá khứ đơn không hợp với “tomorrow”.;;will arrive=>Không dùng will trong mệnh đề thời gian khi nói về tương lai.;;is arriving=>Hiện tại tiếp diễn không dùng sau when trong mệnh đề này.\nc|She was cooking dinner when her brother ___.|arrived / was arriving / had arrived / arrives|0|Hành động ngắn cắt ngang việc đang diễn ra dùng quá khứ đơn: arrived.|was arriving=>Quá khứ tiếp diễn dùng cho việc đang diễn ra, không phải cho hành động ngắn cắt ngang.;;had arrived=>Quá khứ hoàn thành nói việc xảy ra trước đó, không hợp với ý cắt ngang.;;arrives=>Hiện tại đơn sai thì với câu kể quá khứ.\nc|I won't go out until it ___ raining.|will stop / stopped / stop / stops|3|Sau until nói về tương lai dùng hiện tại đơn: stops.|will stop=>Không dùng will sau until khi nói về tương lai.;;stopped=>Quá khứ đơn không hợp với “won't”, vì ý nói về tương lai.;;stop=>Chủ ngữ “it” số ít nên động từ hiện tại đơn phải thêm s: stops.\nc|He had already left ___ I arrived at the office.|until / after / while / before|3|Việc anh ấy rời đi xảy ra trước việc tôi đến, nên dùng before.|until=>Until nghĩa cho đến khi, không hợp với hành động đã hoàn thành.;;after=>After sẽ đảo ngược thứ tự: tôi đến rồi anh ấy mới rời đi.;;while=>While chỉ hai việc xảy ra cùng lúc, trong khi đây là việc xảy ra trước.\nc|___ she finished her homework, she watched a film.|Before / Until / After / During|2|Làm bài xong rồi mới xem phim, nên dùng After; mệnh đề đứng đầu câu có dấu phẩy.|Before=>Before sẽ đảo ngược thứ tự: xem phim trước khi làm bài xong.;;Until=>Until nghĩa cho đến khi, không hợp với một hành động hoàn thành rồi làm việc khác.;;During=>During đi với danh từ, không đi với mệnh đề.\nc|The nurse will give you the injection after the doctor ___ your blood pressure.|will check / has checked / checking / checked|1|Việc kiểm tra xong trước khi tiêm, nên dùng hiện tại hoàn thành sau after: has checked.|will check=>Không dùng will sau after khi nói về tương lai.;;checking=>Checking thiếu trợ động từ, không đúng ngữ pháp ở mệnh đề này.;;checked=>Quá khứ đơn không hợp vì mệnh đề chính “will give” nói về tương lai.\nc|___ you see Mr Hale, please give him this letter.|When / During / Until / Despite|0|Sau chỗ trống là mệnh đề “you see Mr Hale”, nên chọn liên từ When; ý là vào lúc bạn gặp ông ấy.|During=>During cần danh từ phía sau, không đi với mệnh đề.;;Until=>Until nghĩa là cho đến khi, không hợp với lời nhờ đưa thư.;;Despite=>Despite là giới từ chỉ sự nhượng bộ, không hợp nghĩa.\nc|I'll go home after I ___ my shift.|will finish / have finished / finishing / finishes|1|Việc xong trước khi về nhà, dùng hiện tại hoàn thành sau after: have finished.|will finish=>Không dùng will sau after khi nói về tương lai.;;finishing=>Finishing thiếu trợ động từ nên không thành mệnh đề đầy đủ.;;finishes=>Finishes không hợp với chủ ngữ I, phải là finish hoặc have finished.\nx|Chọn câu đúng|I'll text you when I will get home. / I'll text you when I get home. / I text you when I will get home. / I'll text you when I'll get home.|1|Mệnh đề thời gian chỉ tương lai dùng hiện tại đơn; mệnh đề chính mới dùng will.|I'll text you when I will get home.=>Dùng will trong mệnh đề when là lỗi thường gặp.;;I text you when I will get home.=>Mệnh đề chính cũng sai thì, và mệnh đề when vẫn dùng will.;;I'll text you when I'll get home.=>Dùng I'll trong mệnh đề when sai vì cần hiện tại đơn.\nx|Chọn câu đúng về while và during|She fell asleep while the lecture. / She fell asleep during the lecture was boring. / She fell asleep during the lecture. / She fell asleep while the lecture boring.|2|During đi với cụm danh từ “the lecture”; while cần mệnh đề đầy đủ.|She fell asleep while the lecture.=>While cần mệnh đề đủ chủ ngữ và động từ, ở đây “the lecture” chỉ là danh từ.;;She fell asleep during the lecture was boring.=>During không đi trước một mệnh đề như “the lecture was boring”.;;She fell asleep while the lecture boring.=>Mệnh đề sau while thiếu động từ be nên không hoàn chỉnh.\nx|Chọn câu đúng, nói về tương lai|As soon as the results will come, I will tell you. / As soon as the results are coming, will I tell you. / As soon as the results come, I tell you tomorrow. / As soon as the results come, I will tell you.|3|Mệnh đề as soon as dùng hiện tại đơn, mệnh đề chính dùng will.|As soon as the results will come, I will tell you.=>Dùng will trong mệnh đề as soon as là sai.;;As soon as the results are coming, will I tell you.=>Hiện tại tiếp diễn không đúng trong mệnh đề này và câu chính bị đảo trật tự.;;As soon as the results come, I tell you tomorrow.=>Mệnh đề chính nói về tương lai nên cần will, không dùng hiện tại đơn.\nx|Chọn câu đúng, kể chuyện quá khứ|I was having breakfast when the phone rang. / I had breakfast when the phone was ringing. / I was have breakfast when the phone rang. / When I was having breakfast the phone ringing.|0|Việc đang diễn ra dùng quá khứ tiếp diễn, hành động cắt ngang dùng quá khứ đơn.|I had breakfast when the phone was ringing.=>Đảo thì: hành động ngắn lại dùng tiếp diễn, khiến nghĩa bị sai.;;I was have breakfast when the phone rang.=>Sau was phải là V-ing, không phải động từ nguyên mẫu have.;;When I was having breakfast the phone ringing.=>Mệnh đề chính thiếu động từ chia đúng thì nên không hoàn chỉnh.\nt|When I ___ (see) Anna tomorrow, I'll give her your message.|see;have seen|Sau when nói về tương lai dùng hiện tại đơn, không dùng will; “tomorrow” là dấu hiệu.\nt|Don't open the door until the nurse ___ (say) so.|says;has said|Sau until nói về tương lai dùng hiện tại đơn; chủ ngữ số ít nên thêm s.\nt|I was reading a book when the lights ___ (go) out.|went|Hành động ngắn cắt ngang việc đang đọc dùng quá khứ đơn: went.\nt|While Dad ___ (wash) the car, I was cleaning the windows.|was washing|Hai việc diễn ra cùng lúc trong quá khứ nên dùng quá khứ tiếp diễn sau while.\nf|I'll call you until I get there.|until|when|Until chỉ việc kéo dài đến một mốc; ở đây gọi một lần vào lúc đến nơi nên dùng when.\nf|I'll call you as soon as I arrived.|arrived|arrive|Mệnh đề as soon as nói về tương lai nên dùng hiện tại đơn arrive.\nf|By the time we arrived, the concert already started.|started|had started|Việc đã xảy ra trước một mốc quá khứ dùng quá khứ hoàn thành.\no|We will start the meeting when everyone has arrived.|Mệnh đề chính với will đứng trước, rồi mệnh đề when dùng hiện tại hoàn thành.\no|While I was cooking, the phone rang.|While + quá khứ tiếp diễn đứng đầu, có dấu phẩy rồi mới đến quá khứ đơn.","verb-object-infinitive":"c|The doctor advised me ___ more water.|to drink / drink / drinking / that drink|0|“Advise + tân ngữ + to V”: dấu hiệu là “advised me” nên động từ sau phải là “to drink”.|drink=>Chỉ make và let mới đi với động từ nguyên mẫu không “to”; “advise me” cần “to drink”.;;drinking=>Sau “advise + tân ngữ” ta dùng to V, không dùng V-ing trong cấu trúc này.;;that drink=>“That” cần một mệnh đề đầy đủ; ở đây câu cần tân ngữ me rồi đến to V.\nc|My boss let me ___ home early on Friday.|to leave / leave / leaving / left|1|“Let + tân ngữ + V nguyên mẫu” không có “to”; “let me leave” là cấu trúc đúng.|to leave=>Sau “let + tân ngữ” động từ phải ở dạng nguyên mẫu không “to”.;;leaving=>V-ing không đi sau “let me”; cần động từ nguyên mẫu.;;left=>Dạng quá khứ left không thể đứng sau tân ngữ của “let”.\nc|The sad film made everyone ___ at the end.|cry / to cry / crying / cried|0|“Make + O + V” nghĩa là khiến ai làm gì và không có “to”; dấu hiệu là “made everyone”.|to cry=>“Make” chủ động không dùng “to” sau tân ngữ everyone.;;crying=>V-ing không dùng trong cấu trúc make + O + V.;;cried=>Sau tân ngữ phải là nguyên mẫu, không chia quá khứ lần nữa.\nc|I'd like you ___ the form before noon.|sign / signing / signed / to sign|3|“Would like + O + to V” là cách yêu cầu lịch sự; dấu hiệu là “I'd like you”.|sign=>“Would like” khác “let/make”: sau tân ngữ you phải có “to”.;;signing=>“Would like you” không đi với V-ing ở nghĩa mong muốn này.;;signed=>Dạng quá khứ phân từ không dùng ở đây, câu cần to V.\nc|The nurse told Mr Hale ___ smoke in the ward.|not to / don't / do not to / no to|0|Phủ định của “tell + O + to V” là “not to V”; dấu hiệu là “told Mr Hale … smoke”.|don't=>“Don't” chỉ dùng trong lời nói trực tiếp, không dùng sau “told Mr Hale”.;;do not to=>“Do not” và “to” không đi cùng nhau trong cấu trúc gián tiếp.;;no to=>“No to” không phải cách phủ định đúng của to V trong tiếng Anh.\nc|We expect the delivery ___ on Monday.|arrive / to arrive / arriving / that arrive|1|“Expect + O + to V”: delivery là tân ngữ nên động từ theo sau phải là “to arrive”.|arrive=>“Expect + O” cần “to”; chỉ make/let mới bỏ “to”.;;arriving=>V-ing không dùng sau “expect + tân ngữ” trong nghĩa mong đợi.;;that arrive=>“That arrive” sai vì mệnh đề sau that cần chia động từ (that it will arrive).\nc|The rules don't allow people ___ in the lab.|eating / eat / to eat / that eat|2|“Allow + O + to V”, khác với “let + O + V”; “allow people” cần “to eat”.|eating=>“Allow + tân ngữ” đi với to V; V-ing chỉ dùng khi không có tân ngữ.;;eat=>“Allow” không bỏ “to” như “let”, nên “allow people eat” sai.;;that eat=>“That” không dùng sau “allow people” trong cấu trúc này.\nc|Her parents wouldn't let her ___ out late.|to go / going / goes / go|3|“Let + O + V” nên sau “let her” là “go”; “wouldn't let her” là dấu hiệu rõ ràng.|to go=>“Let” không dùng “to” sau tân ngữ her.;;going=>V-ing sai vì “let her” cần nguyên mẫu.;;goes=>Không chia ngôi số ít sau tân ngữ; động từ ở dạng nguyên mẫu.\nc|I want ___ the meeting notes by tomorrow.|you to send / that you send / you send / for you sending|0|“Want + O + to V” thay cho “want that” trong tiếng Việt “muốn bạn gửi”; câu cần “you to send”.|that you send=>Sau “want” không dùng “that” + mệnh đề, hãy dùng tân ngữ + to V.;;you send=>Thiếu “to” sau tân ngữ; “want” không giống “let” hay “make” nên không bỏ “to”.;;for you sending=>“For you sending” không đúng cấu trúc của “want”.\nc|What made you ___ medicine?|to study / study / studying / studied|1|“Make + O + V”: “What made you study…?” hỏi về nguyên nhân khiến ai làm gì.|to study=>Sau “made you” động từ ở dạng nguyên mẫu không “to”.;;studying=>V-ing không đi sau tân ngữ của “make”.;;studied=>Câu hỏi đã có “made”, động từ chính không chia quá khứ lần nữa.\nc|The manager asked the staff ___ the fire exits clear.|keep / keeping / to keep / kept|2|“Ask + O + to V” để đưa ra yêu cầu; “asked the staff” nên theo sau là “to keep”.|keep=>“Ask + O” giữ “to”; chỉ make/let dùng nguyên mẫu trần.;;keeping=>V-ing không dùng sau “asked the staff”.;;kept=>Dạng quá khứ không thể đứng sau tân ngữ; cần to V.\nc|Anna persuaded her brother ___ a gym.|join / joining / that join / to join|3|“Persuade + O + to V”: thuyết phục ai làm gì; “persuaded her brother” cần “to join”.|join=>“Persuade + O” cần to V, không dùng nguyên mẫu trần.;;joining=>V-ing sai vì sau “persuaded her brother” phải là to V.;;that join=>“That join” thiếu chủ ngữ và không phù hợp với “persuade”.\nc|The sign warns visitors ___ on the grass.|don't walk / not to walk / to not walking / no walk|1|Phủ định của to V là “not to V”; “warns visitors not to walk” là cấu trúc đúng.|don't walk=>“Don't” không dùng sau “warns visitors”; cần “not to”.;;to not walking=>“To not walking” trộn lẫn to V và V-ing, sai ngữ pháp.;;no walk=>“No walk” không phải dạng phủ định của động từ.\nc|Would you like me ___ the window?|open / opening / to open / that open|2|“Would you like me to V?” là cách đề nghị giúp đỡ lịch sự; “like me” đòi “to open”.|open=>Sau “would like me” cần “to”; câu này không dùng nguyên mẫu trần.;;opening=>V-ing không đi với “would like + O”.;;that open=>“That open” không phải mệnh đề hoàn chỉnh.\nx|Chọn câu đúng: yêu cầu ai đó chờ|She told me to wait outside. / She told me wait outside. / She told that I wait outside. / She told me waiting outside.|0|“Tell + O + to V” là cấu trúc chuẩn; chỉ phương án 1 có đủ tân ngữ me và to wait.|She told me wait outside.=>Sau “told me” phải có “to” trước động từ.;;She told that I wait outside.=>“Told that” sai; “tell” cần tân ngữ me trước.;;She told me waiting outside.=>V-ing không dùng sau “told me” trong cấu trúc yêu cầu.\nx|Chọn câu đúng: cho phép dùng xe|My mother let me to use her car. / My mother let me use her car. / My mother let me using her car. / My mother let that I use her car.|1|“Let + O + V” không có “to”, nên “let me use” là đúng.|My mother let me to use her car.=>Sau “let me” không dùng “to”; động từ để ở dạng nguyên mẫu.;;My mother let me using her car.=>V-ing không dùng sau “let + tân ngữ”.;;My mother let that I use her car.=>“Let that I” không đúng ngữ pháp tiếng Anh.\nx|Chọn câu đúng: sự mong đợi|He expects that I to be on time. / He expects me being on time. / He expects me to be on time. / He expects I to be on time.|2|“Expect + O (me) + to V”; chỉ có phương án này dùng đúng dạng tân ngữ và to V.|He expects that I to be on time.=>Không trộn “that I” với “to”; chọn một cấu trúc thôi.;;He expects me being on time.=>V-ing không dùng sau “expects me” trong cấu trúc này.;;He expects I to be on time.=>Tân ngữ phải là me, không phải I, nên sai.\nx|Chọn câu đúng: lời bác sĩ cảnh báo|The doctor warned him to not lifting heavy boxes. / The doctor warned him don't lift heavy boxes. / The doctor warned him not lift heavy boxes. / The doctor warned him not to lift heavy boxes.|3|Phủ định của to V là “not to V”; “warned him not to lift” đúng cấu trúc.|The doctor warned him to not lifting heavy boxes.=>“To not lifting” trộn to V và V-ing.;;The doctor warned him don't lift heavy boxes.=>“Don't” không dùng trong câu gián tiếp sau “warned him”.;;The doctor warned him not lift heavy boxes.=>Thiếu “to” sau not; phải là “not to lift”.\nt|The coach made the team ___ (run) five laps.|run|Sau “make + tân ngữ” dùng động từ nguyên mẫu không “to”, nên điền “run”.\nt|I'd like you ___ (call) the patient's family today.|to call|“Would like + tân ngữ you” cần to V, nên đáp án là “to call”.\nt|The nurse told the visitors ___ (not / make) any noise.|not to make|Phủ định gián tiếp dùng “not to + V” sau tân ngữ the visitors.\nt|My teacher doesn't allow us ___ (use) phones in class.|to use|“Allow + tân ngữ us” đi với to V, khác với “let us use”.\nf|They let us taking photos inside the museum.|taking|take|Sau “let + tân ngữ” động từ ở dạng nguyên mẫu, không dùng V-ing.\nf|My boss asked me finishing the report today.|finishing|to finish|“Ask + tân ngữ” cần to V; V-ing là lỗi thường gặp.\no|I would like you to join us for dinner.|Cấu trúc “would like + tân ngữ + to V”: tân ngữ you đứng trước to join."};
  const THEORY = {"adjectives-adverbs":{"summary":"Tính từ bổ nghĩa cho danh từ, còn trạng từ chỉ cách thức bổ nghĩa cho động từ và thường được tạo bằng cách thêm -ly vào tính từ.","formulas":[{"label":"Tính từ trước danh từ","pattern":"adjective + noun","ex":"She gave a quick answer."},{"label":"Trạng từ cách thức (-ly)","pattern":"verb + adjective + -ly","ex":"She answered quickly."},{"label":"Tạo trạng từ có biến đổi chính tả","pattern":"-y → -ily; -le → -ly; -ic → -ically","ex":"happy → happily, simple → simply, basic → basically"},{"label":"Từ bất quy tắc","pattern":"good → well; fast, hard, late, early (không đổi)","ex":"He plays well. They worked hard."},{"label":"Sau linking verb","pattern":"be/feel/look/seem/sound/taste + adjective","ex":"The soup smells delicious."}],"uses":[{"title":"Mô tả người, vật","detail":"Tính từ đứng trước danh từ hoặc sau động từ be.","ex":"He is a kind nurse.","exvi":"Anh ấy là một y tá tốt bụng."},{"title":"Cách một hành động diễn ra","detail":"Trạng từ cách thức đứng sau động từ hoặc sau tân ngữ.","ex":"She spoke softly to the patient.","exvi":"Cô ấy nói nhẹ nhàng với bệnh nhân."},{"title":"Sau feel, look, sound, seem","detail":"Những động từ này chỉ trạng thái nên đi với tính từ.","ex":"You sound happy today.","exvi":"Hôm nay giọng bạn nghe vui đấy."},{"title":"Good và well","detail":"Good là tính từ, well là trạng từ; well còn là tính từ khi nói về sức khỏe.","ex":"I don't feel well. I slept well.","exvi":"Tôi thấy không khỏe. Tôi ngủ ngon."},{"title":"Fast, hard, late","detail":"Các từ này có hình thức giống nhau cho tính từ và trạng từ.","ex":"He drives fast. It was a fast car.","exvi":"Anh ấy lái nhanh. Đó là chiếc xe nhanh."}],"signals":["quickly","carefully","well","hard","fast","late","badly","happily"],"cautions":["Không thêm -ly cho fast, hard, late: “He runs fast”, không nói “fastly”.","“Hardly” nghĩa là “hầu như không”, còn “lately” nghĩa là “gần đây”; không phải trạng từ của hard và late.","Sau feel, look, seem, sound, taste dùng tính từ: “She looks tired”, không nói “She looks tiredly”.","Một số tính từ đã tận cùng -ly như friendly, lovely, lonely; chúng không phải trạng từ."]},"as-as":{"summary":"Dùng as + tính từ/trạng từ + as để nói hai thứ bằng nhau, và the same as / different from / similar to để nói giống hay khác.","formulas":[{"label":"Bằng nhau","pattern":"S + be + as + adj + as + noun/pronoun","ex":"Minh is as tall as his father."},{"label":"Không bằng nhau","pattern":"S + be + not as/so + adj + as","ex":"The room isn't as big as I expected."},{"label":"Với trạng từ","pattern":"S + V + as + adv + as","ex":"She speaks as clearly as a teacher."},{"label":"Số lượng","pattern":"as many + plural noun + as / as much + uncountable noun + as","ex":"I have as many friends as you."},{"label":"Giống và khác","pattern":"the same (+ noun) as / different from / similar to","ex":"Her bag is the same as mine."}],"uses":[{"title":"Hai thứ bằng nhau","detail":"Dùng as + tính từ gốc + as khi mức độ của hai thứ như nhau.","ex":"This sofa is as comfortable as that one.","exvi":"Ghế sofa này thoải mái bằng cái kia."},{"title":"Không bằng","detail":"Dùng not as … as khi vế đầu kém hơn vế sau.","ex":"Tea isn't as strong as coffee.","exvi":"Trà không đậm bằng cà phê."},{"title":"Số lượng bằng nhau","detail":"Dùng as many với danh từ đếm được số nhiều và as much với danh từ không đếm được.","ex":"There is as much rice as noodles.","exvi":"Có lượng gạo bằng lượng mì."},{"title":"Giống hay khác","detail":"Dùng the same as, similar to cho điều giống nhau và different from cho điều khác nhau.","ex":"My job is different from yours.","exvi":"Công việc của tôi khác công việc của bạn."},{"title":"Càng nhiều càng tốt","detail":"Dùng as … as possible để nói mức tối đa có thể.","ex":"Drink as much water as possible.","exvi":"Hãy uống càng nhiều nước càng tốt."}],"signals":["as … as","not as … as","not so … as","the same as","different from","similar to","as many … as","as much … as"],"cautions":["Giữa as … as luôn dùng dạng gốc của tính từ: “as tall as”, không phải “as taller as”.","“The same as” cần “the”; “different” đi với “from” (hoặc “to” trong tiếng Anh Anh), không dùng “with”.","“As many” đi với danh từ đếm được số nhiều, “as much” đi với danh từ không đếm được: “as many chairs”, “as much water”.","Dạng so sánh hơn với “than” (taller than) đã học ở bài so sánh; ở đây chỉ nói về sự bằng nhau."]},"can-ability":{"summary":"“Can” là động từ khuyết thiếu: luôn đứng trước động từ nguyên mẫu không “to”, không đổi dạng theo ngôi, và “could” là dạng quá khứ hoặc dạng lịch sự hơn.","formulas":[{"label":"Khẳng định","pattern":"S + can + V","ex":"My brother can cook very well."},{"label":"Phủ định","pattern":"S + can't (cannot) + V","ex":"I can't open this window."},{"label":"Câu hỏi Yes/No","pattern":"Can + S + V?","ex":"Can you hear me?"},{"label":"Quá khứ","pattern":"S + could / couldn't + V","ex":"He couldn't walk until he was two."},{"label":"Xin phép, nhờ vả lịch sự","pattern":"Could I / Could you + V ...?","ex":"Could you open the door, please?"}],"uses":[{"title":"Khả năng hiện tại","detail":"Dùng “can” để nói ai đó biết làm gì hoặc làm được gì.","ex":"Nurses can take blood pressure.","exvi":"Y tá có thể đo huyết áp."},{"title":"Khả năng trong quá khứ","detail":"Dùng “could” cho điều ai đó làm được hoặc biết làm trong quá khứ nói chung.","ex":"My grandfather could play the violin.","exvi":"Ông tôi đã biết chơi vĩ cầm."},{"title":"Xin phép","detail":"Hỏi “Can I ...?” khi muốn được cho phép, “Could I ...?” thì lịch sự hơn.","ex":"Can I sit here?","exvi":"Tôi ngồi đây được không?"},{"title":"Yêu cầu, nhờ vả","detail":"“Can you ...?” là nhờ bình thường, “Could you ...?” là nhờ lịch sự.","ex":"Could you speak more slowly?","exvi":"Bạn nói chậm hơn được không?"},{"title":"Cho phép và cấm","detail":"“You can ...” là được phép, “You can't ...” là không được phép.","ex":"You can't smoke in the hospital.","exvi":"Bạn không được hút thuốc trong bệnh viện."}],"signals":["can","can't","cannot","could","couldn't","please","how well","at the age of five"],"cautions":["Không thêm -s và không dùng “to”: “She can swim”, không phải “She cans to swim”.","Câu hỏi và phủ định không dùng “do/does/did”: “Can you swim?”, “I can't swim”.","“can” không có dạng tương lai hay hoàn thành; dùng “be able to” khi cần, nhưng ở trình độ A1 chưa cần học.","“Could I ...?” nghe lịch sự hơn “Can I ...?”; “could” ở đây không mang nghĩa quá khứ."]},"demonstratives":{"summary":"This/these chỉ vật hoặc người ở gần, that/those chỉ vật hoặc người ở xa; this và that dùng với số ít, these và those dùng với số nhiều.","formulas":[{"label":"Gần, số ít","pattern":"This + is + noun","ex":"This is my pen."},{"label":"Gần, số nhiều","pattern":"These + are + noun","ex":"These are my pens."},{"label":"Xa, số ít","pattern":"That + is + noun","ex":"That is a hospital."},{"label":"Xa, số nhiều","pattern":"Those + are + noun","ex":"Those are my friends."},{"label":"Đi với danh từ","pattern":"this/that + singular noun; these/those + plural noun","ex":"Those students are late."},{"label":"Câu hỏi","pattern":"What's this/that? What are these/those?","ex":"What are those?"}],"uses":[{"title":"Vật ở gần","detail":"Dùng this/these cho vật bạn có thể chạm tới hoặc đang cầm.","ex":"This coffee is hot.","exvi":"Ly cà phê này nóng."},{"title":"Vật ở xa","detail":"Dùng that/those cho vật ở cách xa người nói.","ex":"That building is the library.","exvi":"Tòa nhà kia là thư viện."},{"title":"Giới thiệu người","detail":"Giới thiệu ai đó bên cạnh mình thì dùng “this is”.","ex":"Mum, this is my teacher, Mr Hall.","exvi":"Mẹ ơi, đây là thầy giáo con, thầy Hall."},{"title":"Nói điện thoại","detail":"Người nói tự giới thiệu bằng “this is”, hỏi người kia bằng “is that”.","ex":"Hello, this is Lan. Is that Ben?","exvi":"A lô, Lan đây. Có phải Ben đó không?"},{"title":"Đứng một mình","detail":"This/that/these/those có thể đứng một mình thay cho danh từ đã rõ.","ex":"These are mine, and those are yours.","exvi":"Những cái này là của tôi, còn những cái kia là của bạn."}],"signals":["here","there","over there","near","far","this morning","these days","that day"],"cautions":["Số nhiều: “this” → “these”, “that” → “those”; đừng nói “this books”.","Phát âm “this /ðɪs/” ngắn, “these /ðiːz/” dài; hai từ nghĩa khác nhau.","Chỉ nói “this is” để giới thiệu người, tránh “he is” khi họ đang đứng cạnh bạn.","Không dùng “is this” để hỏi tên người ở đầu dây điện thoại, hãy dùng “Is that …?”."]},"dependent-prepositions":{"summary":"Nhiều động từ, tính từ và danh từ đi với một giới từ cố định, và sau giới từ ta dùng danh từ hoặc V-ing, không dùng to V.","formulas":[{"label":"Động từ + giới từ","pattern":"depend on / listen to / wait for / belong to + noun","ex":"We are waiting for the results."},{"label":"Tính từ + giới từ","pattern":"good at / afraid of / interested in / proud of / keen on / married to","ex":"She is proud of her students."},{"label":"Danh từ + giới từ","pattern":"reason for / increase in / solution to / damage to / difference between","ex":"There is a solution to this problem."},{"label":"Giới từ + V-ing","pattern":"preposition + V-ing","ex":"He is interested in studying nursing."},{"label":"Hai giới từ (người / việc)","pattern":"apologise to + person + for + thing; angry with + person + about + thing","ex":"She apologised to him for being late."}],"uses":[{"title":"Học theo cụm cố định","detail":"Giới từ không đoán được từ tiếng Việt, nên học cả cụm động từ hoặc tính từ với giới từ.","ex":"My plan depends on the budget.","exvi":"Kế hoạch của tôi phụ thuộc vào ngân sách."},{"title":"Giới từ rồi V-ing","detail":"Sau mọi giới từ dùng danh từ hoặc dạng V-ing, kể cả “to” trong look forward to.","ex":"She is good at solving problems.","exvi":"Cô ấy giỏi giải quyết vấn đề."},{"title":"Cặp giới từ đổi nghĩa","detail":"Một tính từ có thể đi với giới từ khác nhau để đổi nghĩa hoặc đối tượng (người hay việc).","ex":"Fruit is good for you, but he is good at cooking.","exvi":"Trái cây tốt cho bạn, còn anh ấy giỏi nấu ăn."},{"title":"Động từ không cần giới từ","detail":"Một số động từ như discuss, explain to, marry không thêm giới từ mà người Việt hay thêm.","ex":"We discussed the problem.","exvi":"Chúng tôi đã thảo luận vấn đề đó."}],"signals":["depend on","good at","afraid of","interested in","reason for","angry with / about","look forward to","in charge of"],"cautions":["Người Việt hay dịch từng chữ nên chọn sai giới từ: “interested in”, không phải “interested on”.","Sau giới từ luôn dùng V-ing: “afraid of flying”, không dùng “afraid of to fly”.","“Look forward to”, “be used to”, “object to” có “to” là giới từ, nên theo sau là V-ing: “look forward to meeting”.","Một số động từ không dùng giới từ: “discuss the plan”, không phải “discuss about the plan”."]},"frequency-adverbs":{"summary":"Trạng từ tần suất (always, usually, often, sometimes, rarely, never) nói việc xảy ra bao lâu một lần và thường đứng giữa chủ ngữ và động từ thường, hoặc sau “be”.","formulas":[{"label":"Trước động từ thường","pattern":"S + adverb + V","ex":"He often reads in bed."},{"label":"Sau động từ be","pattern":"S + be + adverb","ex":"They are usually at home."},{"label":"Phủ định bằng never","pattern":"S + never + V (khẳng định)","ex":"I never eat breakfast."},{"label":"Hỏi về tần suất","pattern":"How often + do/does + S + V?","ex":"How often does she cycle?"},{"label":"Cụm chỉ tần suất","pattern":"every day / once a week / twice a month","ex":"I see my dentist twice a year."},{"label":"Thang tần suất","pattern":"always > usually > often > sometimes > rarely > never","ex":"We rarely go to the cinema."}],"uses":[{"title":"Thói quen hằng ngày","detail":"Dùng với thì hiện tại đơn để kể thói quen và mức độ thường xuyên.","ex":"My father usually cooks dinner.","exvi":"Bố tôi thường nấu bữa tối."},{"title":"Với động từ be","detail":"Trạng từ đứng sau am/is/are và trước tính từ hoặc danh từ.","ex":"The nurse is always kind.","exvi":"Cô y tá lúc nào cũng tử tế."},{"title":"Hỏi và đáp tần suất","detail":"Hỏi bằng “How often” và trả lời bằng cụm như “every day”.","ex":"How often do you exercise? Three times a week.","exvi":"Bạn tập thể dục bao lâu một lần? Ba lần một tuần."},{"title":"Cụm tần suất cuối câu","detail":"Cụm như “every day” hoặc “twice a week” thường đứng cuối câu.","ex":"We have a meeting every Monday.","exvi":"Chúng tôi họp vào mỗi thứ Hai."},{"title":"Sometimes linh hoạt","detail":"Sometimes có thể đứng đầu hoặc cuối câu, còn always/never thì không.","ex":"Sometimes I walk to work.","exvi":"Thỉnh thoảng tôi đi bộ đến chỗ làm."}],"signals":["always","usually","often","sometimes","rarely","never","every day","twice a week"],"cautions":["Đừng đặt trạng từ sau động từ thường như tiếng Việt: nói “I always go”, không nói “I go always”.","“Never” đã phủ định, nên không dùng cùng “don't”: “I never smoke”.","“Usually/often” trong câu hỏi đứng sau chủ ngữ: “Do you often cook?”.","“Every day” (cụm) khác “everyday” (tính từ: everyday life)."]},"have-got":{"summary":"“Have got” và “have” đều nói về sở hữu, quan hệ và bệnh tật, còn các hoạt động như ăn uống, tắm rửa chỉ dùng “have” (không “got”) và chia với “do/does”.","formulas":[{"label":"Khẳng định (have got)","pattern":"I/you/we/they + have got; he/she/it + has got","ex":"He has got brown eyes."},{"label":"Phủ định (have got)","pattern":"haven't got / hasn't got","ex":"I haven't got any brothers."},{"label":"Câu hỏi (have got)","pattern":"Have/Has + S + got ...?","ex":"Has your sister got a job?"},{"label":"Trả lời ngắn","pattern":"Yes, S + have/has. / No, S + haven't/hasn't.","ex":"Yes, I have. / No, she hasn't."},{"label":"Dạng với do/does","pattern":"S + have / don't have / doesn't have; Do/Does + S + have ...?","ex":"Do you have a car?"},{"label":"Have + hoạt động","pattern":"have + breakfast / a shower / a rest","ex":"I have breakfast at seven."}],"uses":[{"title":"Sở hữu","detail":"Dùng “have got” hoặc “have” để nói ai có đồ vật gì.","ex":"We've got a small flat.","exvi":"Chúng tôi có một căn hộ nhỏ."},{"title":"Gia đình và quan hệ","detail":"Dùng để nói ai có anh chị em, con cái hay bạn bè.","ex":"She's got two children.","exvi":"Cô ấy có hai con."},{"title":"Đặc điểm ngoại hình","detail":"Dùng “have got” để miêu tả tóc, mắt hay các đặc điểm cơ thể.","ex":"He's got short black hair.","exvi":"Anh ấy có mái tóc đen ngắn."},{"title":"Bệnh và triệu chứng","detail":"Nói mình hay ai đó bị đau hoặc bị bệnh gì.","ex":"I've got a sore throat.","exvi":"Tôi bị đau họng."},{"title":"Bữa ăn và hoạt động","detail":"Dùng “have” không có “got” cho bữa ăn, tắm rửa, nghỉ ngơi và chia với do/does.","ex":"Do you have breakfast at home?","exvi":"Bạn có ăn sáng ở nhà không?"}],"signals":["have got","has got","haven't got","hasn't got","I've got","she's got","any","a lot of"],"cautions":["“has got” chỉ dùng với he/she/it: “She has got”, không phải “She have got”.","Không trộn “do/does” với “got”: “Do you have a pen?” hoặc “Have you got a pen?”, không phải “Do you have got”.","Với bữa ăn, tắm rửa: “have breakfast”, “have a shower”, không dùng “have got breakfast”.","“I've got” là viết tắt của “I have got”, còn “She's got” là “She has got” (đừng nhầm với “She is”)."]},"imperatives":{"summary":"Câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu (không có chủ ngữ), còn “Let's” dùng để rủ cả người nói và người nghe cùng làm.","formulas":[{"label":"Mệnh lệnh khẳng định","pattern":"V (nguyên mẫu) + ...","ex":"Close the window."},{"label":"Mệnh lệnh phủ định","pattern":"Don't + V + ...","ex":"Don't be late."},{"label":"Lịch sự với please","pattern":"Please + V / V + ..., please","ex":"Please sit down."},{"label":"Rủ rê","pattern":"Let's + V + ...","ex":"Let's start now."},{"label":"Rủ rê phủ định","pattern":"Let's not + V + ...","ex":"Let's not wait here."}],"uses":[{"title":"Ra lệnh, yêu cầu","detail":"Nói thẳng việc cần người khác làm, bằng động từ nguyên mẫu.","ex":"Stand up, please.","exvi":"Làm ơn đứng lên."},{"title":"Hướng dẫn, chỉ đường","detail":"Dùng khi đưa các bước làm hoặc chỉ đường.","ex":"Turn left at the bank.","exvi":"Rẽ trái ở ngân hàng."},{"title":"Cảnh báo, cấm","detail":"Dùng Don't để cấm hoặc cảnh báo nguy hiểm.","ex":"Don't smoke here.","exvi":"Đừng hút thuốc ở đây."},{"title":"Lời dặn của bác sĩ, y tá","detail":"Rất hay gặp trong lời dặn dùng thuốc và chăm sóc người bệnh.","ex":"Drink plenty of water.","exvi":"Hãy uống nhiều nước."},{"title":"Rủ ai cùng làm","detail":"Let's gồm cả người nói; dùng để đề nghị cùng làm.","ex":"Let's take a break.","exvi":"Mình nghỉ giải lao nhé."}],"signals":["please","don't","let's","let's not","always","never"],"cautions":["Không thêm chủ ngữ: nói “Sit down”, không nói “You sit down” (trừ khi muốn nhấn mạnh người nhận).","Phủ định dùng “Don't” + V, không dùng “Not” hoặc “No” + V.","“Let's” + V không “to”: “Let's go”, không phải “Let's to go”.","Câu mệnh lệnh không “please” dễ nghe cộc lốc; thêm “please” và giọng nhẹ nhàng khi nhờ người khác."]},"in-case-unless":{"summary":"“In case” nói về việc phòng ngừa làm trước, còn “unless”, “as long as”, “provided (that)” nêu điều kiện và đều đi với hiện tại đơn khi nói về tương lai.","formulas":[{"label":"In case (phòng khi, hiện tại/tương lai)","pattern":"S + V (will/imperative) + in case + S + present simple","ex":"I'll take a coat in case it gets cold."},{"label":"In case (kể chuyện quá khứ)","pattern":"S + V-ed + in case + S + past simple","ex":"We left early in case there was heavy traffic."},{"label":"In case of + danh từ","pattern":"In case of + noun, S + V","ex":"In case of fire, use the stairs."},{"label":"Unless = if … not","pattern":"Unless + S + present simple, S + will + V","ex":"Unless you hurry, you'll miss the train."},{"label":"As long as / provided (that)","pattern":"as long as / provided (that) / providing + S + present simple","ex":"You can park here provided that you pay."}],"uses":[{"title":"Phòng ngừa trước","detail":"“In case” cho biết ta làm việc đó trước, vì sự việc kia có thể xảy ra.","ex":"Keep a spare key in case you lose yours.","exvi":"Hãy giữ chìa khoá dự phòng phòng khi bạn làm mất chìa của mình."},{"title":"Điều kiện phủ định","detail":"“Unless” nghĩa là “nếu không”, chỉ một ngoại lệ duy nhất.","ex":"She won't call unless there is an emergency.","exvi":"Cô ấy sẽ không gọi trừ khi có trường hợp khẩn cấp."},{"title":"Điều kiện duy nhất","detail":"“As long as” và “provided” nghĩa là “miễn là”, chỉ khi điều kiện đó đúng.","ex":"You can use my laptop as long as you are careful.","exvi":"Bạn có thể dùng máy tính của tôi miễn là bạn cẩn thận."},{"title":"Biển báo, quy định","detail":"“In case of” + danh từ hay gặp trong thông báo và hướng dẫn an toàn.","ex":"In case of emergency, press the red button.","exvi":"Trong trường hợp khẩn cấp, hãy bấm nút đỏ."}],"signals":["in case","in case of","unless","as long as","so long as","provided (that)","providing (that)","if not"],"cautions":["Không dùng “will” sau “in case”, “unless”, “as long as”, “provided”: “in case it rains”, không phải “in case it will rain”.","“Unless” = “if … not”, nên không thêm “not”: “Unless you study, you'll fail”, không phải “unless you don't study”.","“In case” khác “if”: “in case it rains” là mang ô trước, “if it rains” là mới làm khi mưa.","Quá khứ: “in case” + past simple, ví dụ “He took a map in case he got lost”."]},"modals-deduction":{"summary":"Với must, can't, might, may, could + động từ nguyên mẫu, bạn nói mức độ chắc chắn của mình về một điều đang xảy ra hoặc đang đúng ở hiện tại.","formulas":[{"label":"Chắc chắn là đúng","pattern":"S + must + be / V","ex":"You must be hungry after that walk."},{"label":"Chắc chắn là không đúng","pattern":"S + can't + be / V","ex":"She can't be at work; it's Sunday."},{"label":"Có thể (không chắc)","pattern":"S + might / may / could + be / V","ex":"They might be at the library."},{"label":"Đang diễn ra (tiếp diễn)","pattern":"S + must / can't / might + be + V-ing","ex":"He must be studying for the exam."},{"label":"Có thể không","pattern":"S + might not / may not + be / V","ex":"She might not be at home."}],"uses":[{"title":"Gần như chắc chắn","detail":"Dùng must khi bằng chứng rõ ràng khiến bạn gần như chắc chắn.","ex":"He has a fever and a cough. He must be ill.","exvi":"Anh ấy sốt và ho. Chắc hẳn anh ấy bị ốm."},{"title":"Gần như chắc chắn là không","detail":"Dùng can't khi bạn nghĩ điều đó không thể đúng.","ex":"That can't be her car; hers is blue.","exvi":"Đó không thể là xe của cô ấy; xe cô ấy màu xanh."},{"title":"Có thể, không chắc","detail":"Dùng might, may hoặc could khi bạn chỉ đoán, khả năng khoảng 50%.","ex":"Tom may be in the canteen.","exvi":"Có thể Tom đang ở căng tin."},{"title":"Đoán việc đang xảy ra","detail":"Thêm be + V-ing để đoán hành động đang diễn ra ngay lúc này.","ex":"The baby is quiet. She could be sleeping.","exvi":"Em bé im lặng. Có thể bé đang ngủ."},{"title":"Đoán trạng thái","detail":"Dùng be + tính từ hoặc danh từ để đoán trạng thái, nghề nghiệp, danh tính.","ex":"That man might be a new teacher.","exvi":"Người đàn ông đó có thể là giáo viên mới."}],"signals":["must be","can't be","might be","may be","could be","probably","perhaps","I'm sure","I doubt"],"cautions":["Phủ định của must (suy đoán) là “can't”, không phải “mustn't”: “He can't be home”.","Sau modal là động từ nguyên mẫu không “to”: “must be”, không “must to be”.","“Could” trong bài này nói khả năng ở hiện tại, không phải khả năng trong quá khứ.","Để suy đoán về quá khứ phải dùng must have + V3 (đã học ở phần modals-past)."]},"passive-reporting":{"summary":"Bị động tường thuật và get-passive giúp ta nói về người/vật chịu tác động mà không cần nêu người thực hiện hành động.","formulas":[{"label":"Get-passive","pattern":"S + get/got + V3","ex":"She got promoted last month."},{"label":"It + bị động + that","pattern":"It + is/was + said/believed/reported/thought/expected + that + S + V","ex":"It is believed that the bridge was built in 1850."},{"label":"Chủ ngữ + to V (cùng thời / sau)","pattern":"S + is/are + said/believed/thought + to + V","ex":"The doctor is said to be very kind."},{"label":"Chủ ngữ + to have V3 (trước đó)","pattern":"S + is/are + said/believed + to have + V3","ex":"The temple is thought to have been built in 1200."},{"label":"Be supposed to","pattern":"S + be + supposed to + V","ex":"We are supposed to arrive before eight."}],"uses":[{"title":"Sự việc bất ngờ, ngoài ý muốn","detail":"Get + V3 thường dùng trong văn nói, nhấn vào điều xảy ra với ai đó.","ex":"My phone got stolen on the bus.","exvi":"Điện thoại của tôi bị trộm trên xe buýt."},{"title":"Thay đổi trạng thái","detail":"Get + V3 cũng diễn tả việc trở nên như thế nào, như get married hoặc get dressed.","ex":"They got married in a small church.","exvi":"Họ kết hôn trong một nhà thờ nhỏ."},{"title":"Tin đồn, quan điểm chung","detail":"Dùng It is said/believed that… khi không muốn nêu rõ ai nói hay ai tin.","ex":"It is reported that the company will close two factories.","exvi":"Có thông tin rằng công ty sẽ đóng cửa hai nhà máy."},{"title":"Đưa chủ ngữ lên đầu câu","detail":"Dùng S + is said to V để câu gọn hơn và nhấn mạnh người hay vật được nói đến.","ex":"The film is expected to win many awards.","exvi":"Bộ phim được kỳ vọng sẽ giành nhiều giải."},{"title":"Quy định và kỳ vọng","detail":"Be supposed to chỉ điều ai đó phải làm theo quy định hoặc theo kế hoạch.","ex":"Visitors are supposed to wear a mask.","exvi":"Khách tham quan phải đeo khẩu trang."}],"signals":["it is said that","it is believed that","is reported to","is thought to","is expected to","is rumoured to","get + V3","was supposed to"],"cautions":["Sau “get” luôn dùng V3: “got stolen”, không phải “got steal”. Phủ định và nghi vấn dùng trợ động từ: “didn't get paid”.","Với S + is said to…, hành động xảy ra trước dùng “to have + V3”: “is said to have left”, không dùng “to left”.","Không trộn hai cấu trúc: “It is said that he is rich” hoặc “He is said to be rich”, không phải “He is said that…”.","“be supposed to” đọc là /səˈpəʊzd tuː/, phải có -d: “is supposed to”, không viết “is suppose to”."]},"past-perfect":{"summary":"Quá khứ hoàn thành cho biết một việc đã xảy ra xong trước một thời điểm hoặc một việc khác trong quá khứ.","formulas":[{"label":"Khẳng định","pattern":"S + had + V3","ex":"They had left before I arrived."},{"label":"Phủ định","pattern":"S + hadn't + V3","ex":"She hadn't eaten anything all day."},{"label":"Nghi vấn","pattern":"Had + S + V3?","ex":"Had you met him before the party?"},{"label":"Trả lời ngắn","pattern":"Yes, S + had. / No, S + hadn't.","ex":"Yes, I had. We met in 2019."},{"label":"Với mốc thời gian","pattern":"By the time + past simple, S + had + V3","ex":"By the time we got there, the shop had closed."}],"uses":[{"title":"Việc xảy ra trước","detail":"Hai việc trong quá khứ: việc xảy ra trước dùng quá khứ hoàn thành, việc sau dùng quá khứ đơn.","ex":"When I got home, my sister had cooked dinner.","exvi":"Khi tôi về nhà, chị tôi đã nấu xong bữa tối."},{"title":"Giải thích nguyên nhân","detail":"Giải thích lý do cho một tình huống trong quá khứ bằng việc đã xảy ra trước đó.","ex":"He was late because he had missed the bus.","exvi":"Anh ấy đến muộn vì đã lỡ xe buýt."},{"title":"Trải nghiệm trước một mốc","detail":"Nói về điều đã hoặc chưa từng xảy ra tính đến một thời điểm trong quá khứ.","ex":"I had never seen snow before I moved to Germany.","exvi":"Trước khi chuyển sang Đức, tôi chưa từng thấy tuyết."},{"title":"Tường thuật","detail":"Trong câu gián tiếp, thì quá khứ đơn hoặc hiện tại hoàn thành lùi thành quá khứ hoàn thành.","ex":"She told me she had sent the money.","exvi":"Cô ấy bảo cô ấy đã gửi tiền rồi."},{"title":"Với by the time, before, after","detail":"Các từ nối này thường đi cùng quá khứ hoàn thành để chỉ thứ tự trước sau.","ex":"By the time the ambulance came, the patient had recovered.","exvi":"Khi xe cứu thương tới, bệnh nhân đã hồi phục."}],"signals":["already","just","never","before","after","by the time","when","because","until then","by then"],"cautions":["Nếu chỉ có một hành động và thứ tự đã rõ, dùng quá khứ đơn: “I visited Hue last year”.","Với “before/after”, thứ tự đã rõ nên quá khứ đơn vẫn đúng: “After I ate, I left”; hoàn thành giúp nhấn mạnh hơn.","Sau had phải dùng V3: gone, seen, eaten, không dùng went, saw, ate.","Đừng dùng had + V3 với mốc thời gian chỉ quá khứ (yesterday, last year) khi chỉ có một việc đơn lẻ."]},"present-perfect-continuous":{"summary":"Thì này nhấn mạnh quá trình đang kéo dài hoặc vừa diễn ra gần đây, nối quá khứ với hiện tại.","formulas":[{"label":"Khẳng định","pattern":"S + have/has been + V-ing","ex":"They have been working since eight."},{"label":"Phủ định","pattern":"S + haven't/hasn't been + V-ing","ex":"I haven't been sleeping well lately."},{"label":"Nghi vấn","pattern":"Have/Has + S + been + V-ing?","ex":"Have you been waiting long?"},{"label":"Hỏi thời gian kéo dài","pattern":"How long + have/has + S + been + V-ing?","ex":"How long have you been studying English?"},{"label":"Trả lời ngắn","pattern":"Yes, S + have/has. / No, S + haven't/hasn't.","ex":"Yes, I have. I've been here since nine."}],"uses":[{"title":"Kéo dài đến hiện tại","detail":"Nhấn mạnh khoảng thời gian một hành động đã diễn ra và vẫn đang tiếp tục.","ex":"He has been teaching here for ten years.","exvi":"Ông ấy đã dạy ở đây được mười năm."},{"title":"Vừa xong, còn dấu vết","detail":"Hành động vừa kết thúc nhưng kết quả vẫn thấy được ở hiện tại.","ex":"Your eyes are red. Have you been crying?","exvi":"Mắt bạn đỏ. Bạn vừa khóc à?"},{"title":"Lặp lại gần đây","detail":"Diễn tả việc lặp đi lặp lại trong thời gian gần đây, thường với recently/lately.","ex":"I've been going to the gym a lot lately.","exvi":"Dạo này tôi đi tập gym rất nhiều."},{"title":"Giải thích cảm giác hiện tại","detail":"Dùng để giải thích vì sao ai đó mệt, bẩn, ướt hoặc bận ngay lúc này.","ex":"I'm exhausted because I've been cleaning all day.","exvi":"Tôi kiệt sức vì đã dọn dẹp cả ngày."},{"title":"Đối lập với hoàn thành đơn","detail":"Dùng tiếp diễn cho quá trình, dùng hoàn thành đơn cho số lượng hay kết quả.","ex":"I've been painting the wall. I've painted two rooms.","exvi":"Tôi đang sơn tường. Tôi đã sơn xong hai phòng."}],"signals":["for","since","all day","all morning","how long","lately","recently","these days","this week"],"cautions":["Động từ chỉ trạng thái (know, like, love, want, believe) thường không dùng tiếp diễn: “I have known him for years”.","Khi có số lượng hoặc kết quả hoàn tất (“three emails”, “a book”), dùng hiện tại hoàn thành đơn.","“For” + khoảng thời gian, “since” + mốc thời gian; đừng dùng “since” với “two hours”.","Ngôi he/she/it dùng “has been”, các ngôi còn lại dùng “have been”."]},"pronouns":{"summary":"Đại từ chủ ngữ đứng trước động từ, còn đại từ tân ngữ đứng sau động từ hoặc sau giới từ.","formulas":[{"label":"Đại từ chủ ngữ","pattern":"I / you / he / she / it / we / they + V","ex":"They live near the station."},{"label":"Đại từ tân ngữ sau động từ","pattern":"V + me / you / him / her / it / us / them","ex":"My teacher knows us."},{"label":"Sau giới từ","pattern":"Preposition + me / him / her / us / them","ex":"This letter is for you and me."},{"label":"Hai tân ngữ","pattern":"V + object pronoun + noun","ex":"Pass me the salt."},{"label":"Trả lời nhanh","pattern":"It's + me / him / her / us / them","ex":"Who's there? It's us."}],"uses":[{"title":"Thay danh từ làm chủ ngữ","detail":"Dùng đại từ chủ ngữ để khỏi lặp lại danh từ đã nhắc.","ex":"Anna is a nurse. She works at night.","exvi":"Anna là y tá. Cô ấy làm ca đêm."},{"title":"Thay danh từ làm tân ngữ","detail":"Dùng đại từ tân ngữ sau động từ để chỉ người hoặc vật chịu hành động.","ex":"I see him every morning.","exvi":"Sáng nào tôi cũng gặp anh ấy."},{"title":"Sau giới từ","detail":"Sau mọi giới từ đều dùng đại từ tân ngữ, kể cả khi có “and”.","ex":"Sit next to me.","exvi":"Ngồi cạnh tôi nhé."},{"title":"Nói về vật và động vật","detail":"Vật và nhiều con vật dùng “it” và “they/them”, không dùng he hoặc she.","ex":"I love my new phone. It is very fast.","exvi":"Tôi thích điện thoại mới. Nó rất nhanh."},{"title":"Trả lời “Ai đó?”","detail":"Khi trả lời ngắn dùng đại từ tân ngữ sau “It's”.","ex":"It's me.","exvi":"Tôi đây."}],"signals":["I","me","he","him","she","her","we","us","they","them"],"cautions":["Tiếng Anh luôn cần chủ ngữ: nói “It is hot”, không nói “Is hot”.","Sau giới từ dùng me, him, her, us, them, kể cả “between you and me”.","“You” và “it” giống nhau ở dạng chủ ngữ và tân ngữ.","Không lặp chủ ngữ: nói “My brother works here”, không nói “My brother he works here”."]},"quantifiers-2":{"summary":"Each, every, all dùng cho nhóm; both, either, neither dùng cho hai đối tượng, và mỗi từ đòi hỏi danh từ và động từ số ít hay số nhiều khác nhau.","formulas":[{"label":"Each / every","pattern":"each / every + singular noun + singular verb","ex":"Every room has a window."},{"label":"All","pattern":"all (of) + the/my + plural or uncountable noun","ex":"All the rooms have a window."},{"label":"Both","pattern":"both (of) + the/my + plural noun + plural verb","ex":"Both of my sisters live in Hue."},{"label":"Either / neither","pattern":"either / neither + singular noun; either / neither of + plural noun + singular verb","ex":"Neither of the doors is open."},{"label":"Cặp liên từ","pattern":"both … and … / either … or … / neither … nor …","ex":"She speaks both English and French."}],"uses":[{"title":"Every: mọi người, mọi lần","detail":"Every nhìn cả nhóm như một khối, dùng với danh từ số ít và cả cho tần suất.","ex":"Every nurse wears a uniform.","exvi":"Y tá nào cũng mặc đồng phục."},{"title":"Each: từng cá nhân","detail":"Each nhấn mạnh từng người một, và có thể dùng each of + danh từ số nhiều.","ex":"Each of the patients has a bed.","exvi":"Từng bệnh nhân đều có một giường."},{"title":"All: toàn bộ","detail":"All đi với danh từ số nhiều hoặc không đếm được, và chỉ cả khoảng thời gian như all day.","ex":"We worked all night.","exvi":"Chúng tôi làm việc suốt đêm."},{"title":"Both: cả hai","detail":"Both nói về hai người hay hai vật cùng làm hoặc cùng có một điều.","ex":"Both doors are open.","exvi":"Cả hai cánh cửa đều mở."},{"title":"Either / neither: một trong hai","detail":"Either nghĩa là cái nào cũng được; neither nghĩa là không cái nào, và bản thân đã mang nghĩa phủ định.","ex":"Neither answer is correct.","exvi":"Cả hai đáp án đều không đúng."}],"signals":["each","every","all","both","either","neither","all day","every day"],"cautions":["Sau every và each là danh từ số ít, động từ cũng số ít: “Every student has …”, không phải “Every students have …”.","Neither đã mang nghĩa phủ định, nên không thêm “not”: “Neither of them is …”, không phải “Neither of them isn't …”.","“All day” là suốt ngày, còn “every day” là ngày nào cũng vậy: “I work all day” khác “I work every day”.","Both, either, neither chỉ dùng cho hai đối tượng; từ ba trở lên dùng all, any, none."]},"relative-nondefining":{"summary":"Mệnh đề quan hệ không xác định thêm thông tin phụ cho danh từ đã rõ, luôn đứng giữa dấu phẩy và không dùng “that”.","formulas":[{"label":"who / which","pattern":"N (người/vật), who/which + V ...,","ex":"My brother, who is a vet, lives in Hue."},{"label":"whose","pattern":"N, whose + danh từ + V ...,","ex":"Mr Tran, whose daughter is a nurse, works here."},{"label":"where / when","pattern":"N (nơi chốn/thời gian), where/when + S + V ...,","ex":"Hue, where I was born, is a lovely city."},{"label":"which chỉ cả mệnh đề","pattern":"S + V, which + V ...","ex":"He lost his keys, which was annoying."},{"label":"Giới từ + whom / which","pattern":"N, giới từ + whom/which + S + V ...,","ex":"My manager, with whom I work, is kind."}],"uses":[{"title":"Thêm thông tin phụ","detail":"Danh từ đã rõ là ai hoặc cái gì, mệnh đề chỉ bổ sung thêm.","ex":"My grandfather, who is 90, still walks every day.","exvi":"Ông tôi, năm nay 90 tuổi, vẫn đi bộ mỗi ngày."},{"title":"Nói thêm về tên riêng","detail":"Tên người, địa danh luôn đi với mệnh đề không xác định.","ex":"Hanoi, which is the capital, is very busy.","exvi":"Hà Nội, thủ đô của nước ta, rất nhộn nhịp."},{"title":"Bình luận cả câu","detail":"“Which” thay cho cả ý ở mệnh đề trước, không chỉ một danh từ.","ex":"She passed the exam, which surprised everyone.","exvi":"Cô ấy đỗ kỳ thi, điều làm mọi người bất ngờ."},{"title":"Sở hữu và nơi chốn","detail":"Dùng whose, where, when để nói về quyền sở hữu, nơi chốn, thời điểm.","ex":"The clinic, where my mother works, is hiring.","exvi":"Phòng khám nơi mẹ tôi làm đang tuyển người."},{"title":"Văn trang trọng","detail":"Giới từ đứng trước whom/which cho văn viết trang trọng.","ex":"The report, in which she explains the results, is online.","exvi":"Bản báo cáo, trong đó cô ấy giải thích kết quả, có trên mạng."}],"signals":["who","which","whose","whom","where","when","commas"],"cautions":["Không dùng “that” trong mệnh đề không xác định: “My car, which is red, …”.","Không bỏ được đại từ quan hệ ở loại này, và luôn có dấu phẩy hai bên.","Không lặp đại từ: “the book, which I bought it” là sai.","Chỉ dùng “which” (không dùng “what”) để nói về cả mệnh đề."]},"some-any":{"summary":"Some dùng trong câu khẳng định, any dùng trong câu phủ định và câu hỏi, no thay cho not any, và các từ ghép theo cùng quy tắc.","formulas":[{"label":"Some (khẳng định)","pattern":"some + plural noun / uncountable noun","ex":"We bought some eggs and some milk."},{"label":"Any (phủ định, nghi vấn)","pattern":"not ... any / Is/Are there any ...?","ex":"There aren't any chairs. Do you have any water?"},{"label":"No (nghĩa phủ định)","pattern":"no + noun (động từ ở dạng khẳng định)","ex":"There is no sugar in the tin."},{"label":"Từ ghép với some/any","pattern":"some/any + one / body / thing / where","ex":"I need something to eat. Did you go anywhere?"},{"label":"Từ ghép với no/every","pattern":"no/every + one / body / thing / where","ex":"Nobody knows the answer. Everything is ready."}],"uses":[{"title":"Some trong câu khẳng định","detail":"Nói về một lượng không rõ, không cần đếm chính xác.","ex":"There is some juice in the fridge.","exvi":"Có một ít nước ép trong tủ lạnh."},{"title":"Any trong phủ định và câu hỏi","detail":"Dùng any khi phủ nhận hoặc hỏi xem có hay không.","ex":"I haven't got any brothers.","exvi":"Tôi không có anh em trai nào."},{"title":"Some trong lời mời, lời nhờ","detail":"Khi mong câu trả lời là “có”, ta vẫn dùng some trong câu hỏi.","ex":"Can I have some water, please?","exvi":"Cho tôi xin ít nước được không?"},{"title":"No thay cho not any","detail":"No mạnh hơn, đi với động từ khẳng định.","ex":"We have no classes on Friday.","exvi":"Chúng tôi không có tiết nào vào thứ Sáu."},{"title":"Any trong câu khẳng định","detail":"Any nghĩa là “bất kỳ” khi nói không phân biệt.","ex":"You can ask any nurse on the ward.","exvi":"Bạn có thể hỏi bất kỳ y tá nào trong khoa."}],"signals":["some","any","no","somebody","anyone","nothing","anywhere","everything"],"cautions":["Câu phủ định có “not” hoặc “never” thì dùng any, không dùng no: “I don't have any pens”, không nói “I don't have no pens”.","Từ ghép với -body và -one dùng động từ số ít: “Everyone is here”, “Nobody knows”.","Dùng some trong câu hỏi khi đề nghị hoặc nhờ vả: “Would you like some rice?”","Khác với much/many/a few đã học ở quantifiers; ở đây chỉ nói some/any/no và các từ ghép."]},"subjunctive-formal":{"summary":"Các cấu trúc này dùng dạng động từ đặc biệt (nguyên mẫu hoặc quá khứ) để nói về mong muốn, đề nghị và lời khuyên thay vì thông tin có thật.","formulas":[{"label":"Giả định sau suggest/insist/recommend/demand","pattern":"S + suggest/insist/recommend/demand + that + S + (should) + V","ex":"The manager insisted that he be on time."},{"label":"It's time + quá khứ đơn","pattern":"It's (about/high) time + S + V2","ex":"It's high time you started revising."},{"label":"Would rather (cùng chủ ngữ)","pattern":"S + would rather (not) + V","ex":"I'd rather stay at home tonight."},{"label":"Would rather (khác chủ ngữ)","pattern":"S + would rather + S + V2 (hiện tại/tương lai); S + would rather + S + had + V3 (quá khứ)","ex":"I'd rather you didn't tell anyone."},{"label":"Had better","pattern":"S + had better (not) + V","ex":"You'd better not drive in this fog."}],"uses":[{"title":"Đề nghị, yêu cầu trang trọng","detail":"Động từ trong mệnh đề that giữ nguyên mẫu, bất kể ngôi hay thì của câu chính.","ex":"The rules demand that every visitor wear a mask.","exvi":"Quy định yêu cầu mọi khách tham quan phải đeo khẩu trang."},{"title":"Đã đến lúc làm gì","detail":"It's time + S + quá khứ đơn diễn tả việc đáng ra phải làm ngay bây giờ.","ex":"It's time we updated our website.","exvi":"Đã đến lúc chúng ta cập nhật trang web."},{"title":"Sở thích của bản thân","detail":"Would rather + V diễn tả điều mình thích làm hơn, dùng cùng chủ ngữ.","ex":"I'd rather have tea than coffee.","exvi":"Tôi thích uống trà hơn cà phê."},{"title":"Mong người khác làm hoặc không làm","detail":"Would rather + chủ ngữ mới + quá khứ đơn nói điều mình muốn ở người khác.","ex":"I'd rather you didn't park here.","exvi":"Tôi mong bạn đừng đỗ xe ở đây."},{"title":"Lời khuyên mạnh","detail":"Had better + V nguyên mẫu nói điều nên làm kẻo gặp hậu quả.","ex":"You'd better leave now, or you'll miss the train.","exvi":"Bạn nên đi ngay, kẻo lỡ chuyến tàu."}],"signals":["suggest that","insist that","recommend that","demand that","it's time","it's high time","would rather","had better"],"cautions":["Sau suggest/recommend/insist/demand + that, không chia -s: “recommended that she take”, không phải “takes”. Phủ định là “not + V”.","Không nói “suggest him to do”; hãy nói “suggest that he do/should do” hoặc “suggest doing”.","“It's time we went” vẫn nói về hiện tại hoặc việc cần làm ngay, dù dùng quá khứ đơn; “high time” nhấn mạnh việc đã hơi muộn.","Sau “would rather” và “had better” là nguyên mẫu không “to”; phủ định đặt “not” sau rather/better: “I'd rather not go”, “You'd better not go”."]},"time-clauses":{"summary":"Mệnh đề thời gian bắt đầu bằng when, while, until, before, after, as soon as hoặc by the time và cho biết hành động chính xảy ra lúc nào, thường dùng hiện tại đơn thay cho tương lai.","formulas":[{"label":"Tương lai với hiện tại đơn","pattern":"will + V + when / as soon as / until / before / after + S + V(s)","ex":"I'll phone you when I finish work."},{"label":"Hiện tại hoàn thành chỉ việc xong trước","pattern":"when / after / as soon as + S + have/has + V3, S + will + V","ex":"I'll leave after I have finished this report."},{"label":"Quá khứ: hai hành động đồng thời","pattern":"S + was/were + V-ing + while + S + was/were + V-ing","ex":"He was cooking while she was studying."},{"label":"Quá khứ: hành động cắt ngang","pattern":"While + S + was/were + V-ing, S + V2","ex":"While I was walking home, it started to rain."},{"label":"By the time","pattern":"By the time + S + V, S + will have + V3 / had + V3","ex":"By the time you arrive, I will have left."}],"uses":[{"title":"Tương lai, không dùng will","detail":"Sau when, as soon as, until, before, after dùng hiện tại đơn để nói việc sẽ xảy ra.","ex":"We'll start when everyone arrives.","exvi":"Chúng ta sẽ bắt đầu khi mọi người đến."},{"title":"Ngay khi: as soon as","detail":"As soon as nghĩa là ngay sau khi, hai việc xảy ra gần như liền nhau.","ex":"Call me as soon as the results are ready.","exvi":"Gọi cho tôi ngay khi có kết quả."},{"title":"Cho đến khi: until","detail":"Until nói hành động hoặc trạng thái kéo dài đến một thời điểm rồi dừng.","ex":"Stay in bed until you feel better.","exvi":"Hãy nằm nghỉ cho đến khi bạn thấy khỏe hơn."},{"title":"While trong lúc, during trong suốt","detail":"While đi với một mệnh đề; during đi với danh từ, cụm danh từ.","ex":"I met her during the conference.","exvi":"Tôi gặp cô ấy trong hội nghị."},{"title":"Việc xong trước một thời điểm","detail":"By the time nói việc đã hoặc sẽ hoàn thành trước một mốc.","ex":"By the time I got there, they had gone.","exvi":"Khi tôi đến nơi thì họ đã đi rồi."}],"signals":["when","while","as soon as","until","before","after","by the time","once","as","whenever"],"cautions":["Không dùng will sau when, as soon as, until, before, after: “when I arrive”, không phải “when I will arrive”.","“While” đi với mệnh đề (S + V); “during” đi với danh từ: “during the lesson”.","Mệnh đề thời gian đứng đầu câu thì có dấu phẩy: “When I arrive, I'll call you.”","Câu hỏi “When will you arrive?” là câu hỏi, khác với mệnh đề thời gian nên vẫn dùng will."]},"verb-object-infinitive":{"summary":"Nhiều động từ cần một tân ngữ (người) ngay sau chúng, rồi mới đến động từ nguyên mẫu: “want/ask/tell… + O + to V”, còn “make/let + O + V” thì bỏ “to”.","formulas":[{"label":"Nhóm dùng to V","pattern":"S + want / ask / tell / advise / allow / expect + O + to V","ex":"She asked me to open the window."},{"label":"Nhóm make / let","pattern":"S + make / let + O + V (nguyên mẫu không to)","ex":"The film made everyone laugh."},{"label":"Phủ định","pattern":"S + verb + O + not to V","ex":"He told us not to worry."},{"label":"Lời đề nghị lịch sự","pattern":"S + would like / would prefer + O + to V","ex":"I'd like you to meet my sister."},{"label":"Câu hỏi","pattern":"Do you want + O + to V? / What do you want + O + to do?","ex":"What do you want me to do?"}],"uses":[{"title":"Yêu cầu, ra lệnh","detail":"Dùng ask, tell, order để nói bạn muốn ai làm gì.","ex":"The teacher told the class to open their books.","exvi":"Cô giáo bảo cả lớp mở sách ra."},{"title":"Khuyên bảo","detail":"Dùng advise, encourage, remind khi đưa lời khuyên hoặc nhắc nhở.","ex":"The doctor advised him to stop smoking.","exvi":"Bác sĩ khuyên anh ấy bỏ thuốc lá."},{"title":"Cho phép, mong đợi","detail":"Allow, expect, want đi với tân ngữ và to V.","ex":"The rules don't allow students to use phones.","exvi":"Quy định không cho học sinh dùng điện thoại."},{"title":"Bắt buộc hoặc cho phép (make/let)","detail":"Sau make và let, động từ đứng sau tân ngữ không có “to”.","ex":"Her parents let her stay out late.","exvi":"Bố mẹ cô ấy cho cô ấy ở ngoài đến khuya."},{"title":"Mong muốn lịch sự","detail":"“Would like + O + to V” nhẹ nhàng hơn “want + O + to V”.","ex":"I'd like you to send me the file today.","exvi":"Tôi muốn bạn gửi cho tôi tệp đó trong hôm nay."}],"signals":["want","ask","tell","advise","allow","expect","would like","make","let","remind"],"cautions":["Không nói “want that you come”; hãy nói “want you to come”.","Chỉ “make” và “let” bỏ “to”; “allow”, “advise”, “ask” vẫn giữ “to”.","Phủ định đặt “not” trước “to”: “told me not to go”, không phải “told me don't go”.","Nếu cùng chủ ngữ thì không cần tân ngữ: “I want to go”, nhưng “I want him to go”."]}};
  const GX_ADD = {"adjectives-adverbs":{"mistakes":[{"wrong":"My mother cooks very good.","right":"My mother cooks very well.","bad":"good","fix":"well","why":"Bổ nghĩa cho động từ “cooks” cần trạng từ “well”. Tiếng Việt dùng “giỏi/tốt” cho cả hai nên dễ nhầm."},{"wrong":"She looks very happily today.","right":"She looks very happy today.","bad":"happily","fix":"happy","why":"Sau “look” (trông có vẻ) dùng tính từ, không dùng trạng từ. Hãy nghĩ “look = be” về trạng thái."},{"wrong":"He runs fastly in the park.","right":"He runs fast in the park.","bad":"fastly","fix":"fast","why":"“Fast” vừa là tính từ vừa là trạng từ, không thêm -ly. Cũng như “hard” và “late”."},{"wrong":"They studied hardly for the test.","right":"They studied hard for the test.","bad":"hardly","fix":"hard","why":"“Hardly” nghĩa là hầu như không, không phải trạng từ của “hard”. Muốn nói chăm chỉ dùng “hard”."},{"wrong":"The driver drove careful.","right":"The driver drove carefully.","bad":"careful","fix":"carefully","why":"Bổ nghĩa cho động từ “drove” cần trạng từ có -ly. Tiếng Việt không đổi hình thức từ nên dễ quên."},{"wrong":"The music sounds beautifully tonight.","right":"The music sounds beautiful tonight.","bad":"beautifully","fix":"beautiful","why":"“Sound” là linking verb chỉ cảm nhận nên đi với tính từ “beautiful”, không dùng trạng từ."},{"wrong":"The teacher explained the lesson clear.","right":"The teacher explained the lesson clearly.","bad":"clear","fix":"clearly","why":"Bổ nghĩa cho động từ “explained” cần trạng từ “clearly”. Tiếng Việt dùng một từ “rõ” cho cả hai nên dễ nhầm."},{"wrong":"The pizza smells deliciously.","right":"The pizza smells delicious.","bad":"deliciously","fix":"delicious","why":"Smell, taste là linking verb khi mô tả mùi vị, nên đi với tính từ chứ không dùng trạng từ."}],"contrast":{"title":"good hay well?","a":"good (tính từ)","b":"well (trạng từ)","rows":[["Từ loại","Tính từ, bổ nghĩa danh từ: “a good doctor”.","Trạng từ, bổ nghĩa động từ: “She works well.”"],["Vị trí","Trước danh từ hoặc sau be/feel/look: “The food is good.”","Sau động từ hoặc tân ngữ: “He speaks English well.”"],["Sức khỏe","Dùng “feel good” khi vui, dễ chịu: “I feel good.”","Dùng “well” (tính từ) khi khỏe mạnh: “I don't feel well.”"],["Trong câu hỏi","“How was the trip?” – “Good.”","“How did she sing?” – “Well.”"]],"ex":[["She is a good swimmer.","She swims well."],["The film was good.","He understands the film well."]],"tip":"Có danh từ hoặc be/look/feel thì chọn good; có động từ hành động thì chọn well.","quiz":[{"t":"c","q":"My grandfather is a very ___ chess player.","opts":["goodly","well","good","nicely"],"a":2,"why":"Trước danh từ “player” cần tính từ good.","wrong":{"well":"“Well” là trạng từ, không đứng trước danh từ.","goodly":"“Goodly” không dùng với nghĩa giỏi trong câu này.","nicely":"“Nicely” là trạng từ, không đứng trước danh từ."}},{"t":"c","q":"She cooks really ___, so her restaurant is always full.","opts":["well","goods","good","goodly"],"a":0,"why":"Bổ nghĩa cho động từ “cooks” cần trạng từ well.","wrong":{"good":"“Good” là tính từ, không bổ nghĩa cho động từ “cooks”.","goods":"“Goods” là danh từ nghĩa là hàng hóa.","goodly":"“Goodly” không dùng trong nghĩa này."}},{"t":"c","q":"The curry smells ___. I'm very hungry now.","opts":["well","good","goodly","goodness"],"a":1,"why":"Smell là linking verb nên dùng tính từ good; “I'm very hungry” gợi món ăn thơm.","wrong":{"well":"“Well” là trạng từ, không đứng sau “smells” khi mô tả mùi.","goodly":"“Goodly” không dùng làm tính từ chỉ mùi trong câu này.","goodness":"“Goodness” là danh từ, không dùng sau “smells”."}},{"t":"c","q":"The weather was ___, so we went to the beach.","opts":["well","goodness","goodly","good"],"a":3,"why":"Sau be dùng tính từ good để mô tả thời tiết; “so we went to the beach” cho thấy trời đẹp.","wrong":{"well":"“Well” là trạng từ (hoặc tính từ chỉ sức khỏe), không dùng để nói thời tiết đẹp.","goodness":"“Goodness” là danh từ, không đứng sau “was” để mô tả thời tiết.","goodly":"“Goodly” là từ cổ, không dùng với nghĩa tốt đẹp trong câu này."}},{"t":"c","q":"He ran ___ in the final race, and the crowd cheered.","opts":["fasting","fastly","fast","fasten"],"a":2,"why":"Fast vừa là tính từ vừa là trạng từ, nên “ran fast” đúng.","wrong":{"fastly":"“Fastly” không tồn tại.","fasting":"“Fasting” nghĩa là nhịn ăn, không liên quan.","fasten":"“Fasten” là động từ nghĩa là buộc chặt."}},{"t":"c","q":"That plan sounds ___! Let's try it tomorrow.","opts":["interestingly","interest","interested","interesting"],"a":3,"why":"Sound là linking verb nên đi với tính từ interesting; “Let's try it” cho thấy kế hoạch hay.","wrong":{"interestingly":"“Interestingly” là trạng từ, không đứng sau linking verb “sounds”.","interest":"“Interest” là danh từ, không mô tả kế hoạch.","interested":"“Interested” mô tả người cảm thấy hứng thú, không mô tả kế hoạch."}},{"t":"c","q":"She looks ___ in that photo. What a lovely smile!","opts":["happy","happiness","happily","happiest"],"a":0,"why":"Look là linking verb nên đi với tính từ happy; “lovely smile” hợp ý.","wrong":{"happily":"“Happily” là trạng từ, không đứng sau “looks”.","happiness":"“Happiness” là danh từ, không mô tả dáng vẻ.","happiest":"“Happiest” là dạng so sánh nhất, cần có “the” và không hợp với “looks ... in that photo”."}},{"t":"c","q":"You did ___ in the interview. I'm very proud of you.","opts":["good","well","goodly","best"],"a":1,"why":"Bổ nghĩa cho động từ “did” cần trạng từ well.","wrong":{"good":"“Good” là tính từ, không đứng sau động từ “did” theo nghĩa này.","goodly":"“Goodly” là từ hiếm, không dùng ở đây.","best":"“Best” là dạng so sánh nhất; sau “did” cần dạng trạng từ nguyên mức “well”."}}]}},"as-as":{"mistakes":[{"wrong":"My bag is as heavier as yours.","right":"My bag is as heavy as yours.","bad":"heavier","fix":"heavy","why":"Giữa as … as dùng tính từ ở dạng gốc. Đừng thêm -er: “as heavy as”, không phải “as heavier as”."},{"wrong":"She is taller as her mother.","right":"She is taller than her mother.","bad":"as","fix":"than","why":"Dạng so sánh hơn “taller” đi với “than”. Chữ “as” chỉ dùng trong so sánh bằng: “as tall as”."},{"wrong":"He has same car as me.","right":"He has the same car as me.","bad":"","fix":"the","why":"Tiếng Việt nói “giống” không cần mạo từ, nhưng tiếng Anh phải nói “the same … as”. Thiếu “the” là lỗi rất hay gặp."},{"wrong":"Your idea is different with mine.","right":"Your idea is different from mine.","bad":"with","fix":"from","why":"Tính từ different đi với “from” (hoặc “to” trong tiếng Anh Anh). Đừng dịch “khác với” thành “different with”."},{"wrong":"I have as much friends as you.","right":"I have as many friends as you.","bad":"much","fix":"many","why":"“Friends” là danh từ đếm được số nhiều nên dùng “as many”. “As much” chỉ dùng với danh từ không đếm được."},{"wrong":"This test is not so difficult than the last one.","right":"This test is not so difficult as the last one.","bad":"than","fix":"as","why":"Cấu trúc not so/as + tính từ + as luôn kết thúc bằng “as”. “Than” chỉ đi với dạng so sánh hơn."},{"wrong":"He is not as tall like his brother.","right":"He is not as tall as his brother.","bad":"like","fix":"as","why":"So sánh bằng cần hai chữ “as”: “as tall as”. Đừng dùng “like” thay chữ as thứ hai dù tiếng Việt nói “giống như”."},{"wrong":"She sings as beautiful as a bird.","right":"She sings as beautifully as a bird.","bad":"beautiful","fix":"beautifully","why":"Động từ “sings” cần trạng từ nên giữa as … as dùng “beautifully”. Tính từ chỉ dùng sau động từ be hay look."}],"contrast":{"title":"as … as hay … than?","a":"as + adj + as","b":"adj-er/more + than","rows":[["Ý nghĩa","Hai thứ bằng nhau: as tall as","Hai thứ khác nhau, một thứ hơn: taller than"],["Dạng tính từ","Luôn dạng gốc: as heavy as","Dạng so sánh hơn: heavier than, more expensive than"],["Từ nối ở cuối","Chữ as thứ hai: as old as me","Chữ than: older than me"],["Phủ định","not as … as nghĩa là kém hơn: “not as tall as Hoa” (thấp hơn Hoa)","not … -er than nghĩa là không hơn: “not taller than Hoa” (có thể bằng nhau)"]],"ex":[["Hoa is as tall as Lan.","Hoa is taller than Lan."],["The bus is as fast as the train.","The bus is slower than the train."]],"tip":"Bằng nhau thì “as … as” (hai chữ as, tính từ nguyên mẫu ở giữa); hơn kém thì “-er/more … than”.","quiz":[{"q":"Ann is 1.70 m and Bao is 1.70 m. Bao is ___ Ann.","opts":["as tall as","taller than","as taller as","more tall as"],"a":0,"why":"Hai người cao bằng nhau nên dùng as + tính từ gốc + as: “as tall as”.","wrong":{"taller than":"Hai người cùng 1.70 m nên không ai cao hơn; “taller than” sai nghĩa.","as taller as":"Giữa as … as phải dùng tính từ gốc, không dùng dạng “taller”.","more tall as":"“More tall” không tồn tại và “as” không đi với dạng so sánh hơn."}},{"q":"Tuan is 28 and Hoa is 25. Tuan is ___ Hoa.","opts":["as old as","older than","as older as","oldest than"],"a":1,"why":"Hai tuổi khác nhau, Tuan nhiều tuổi hơn nên dùng dạng so sánh hơn: “older than”.","wrong":{"as old as":"Tuổi hai người khác nhau nên không thể so sánh bằng.","as older as":"Giữa as … as không dùng dạng so sánh hơn “older”.","oldest than":"“Oldest” là so sánh nhất và không đi với “than”."}},{"q":"The red bag costs £40 and the blue one costs £40. The red bag is as expensive ___ the blue one.","opts":["than","like","as","to"],"a":2,"why":"Hai túi cùng giá nên so sánh bằng. Sau “as expensive” bắt buộc là chữ “as” thứ hai.","wrong":{"than":"“Than” dùng với dạng so sánh hơn; câu này đã có “as expensive” nên cần “as”.","like":"“Like” không thay được chữ as thứ hai trong so sánh bằng.","to":"“As expensive to” không phải cấu trúc so sánh bằng; cần chữ as."}},{"q":"Our clinic is smaller ___ the hospital.","opts":["as","than","that","like"],"a":1,"why":"“Smaller” là dạng so sánh hơn nên đi với “than”, không dùng “as”.","wrong":{"as":"“As” dùng cho so sánh bằng; “smaller” là dạng so sánh hơn nên cần “than”.","that":"“That” không dùng để nối vế so sánh hơn; phải dùng “than”.","like":"“Like” nghĩa là giống như, không dùng sau dạng so sánh hơn."}},{"q":"Is your bag the same ___ mine?","opts":["than","with","as","like"],"a":2,"why":"Cấu trúc cố định là the same as + vế so sánh. Chữ “mine” là vế được so sánh.","wrong":{"than":"“Than” chỉ dùng với dạng so sánh hơn, không đi với “the same”.","with":"“The same with” là lỗi do dịch từ tiếng Việt; đúng là the same as.","like":"“The same like” không đúng; sau the same dùng “as”."}},{"q":"The two answers are almost identical. Answer A is ___ answer B.","opts":["similar with","similar to","similar as","similar than"],"a":1,"why":"Tính từ similar luôn đi với “to”: similar to + danh từ; “almost identical” cho thấy hai thứ giống nhau.","wrong":{"similar with":"“Similar with” là lỗi do dịch “giống với”; đúng là similar to.","similar as":"“As” đi với the same (the same as), không đi với similar.","similar than":"“Than” chỉ dùng sau dạng so sánh hơn, không đi với similar."}},{"q":"There isn't ___ water in the bottle as I thought.","opts":["as much","as many","so many","more many"],"a":0,"why":"“Water” không đếm được nên dùng as much … as. Chữ “as I thought” là vế sau của cấu trúc.","wrong":{"as many":"“Water” là danh từ không đếm được nên không dùng “many”.","so many":"“Many” chỉ dùng với danh từ đếm được số nhiều, mà “water” không đếm được.","more many":"“More many” không tồn tại trong tiếng Anh."}},{"q":"She is not as ___ as her sister at maths.","opts":["good","well","better","best"],"a":0,"why":"Sau “is” cần tính từ, và giữa as … as dùng dạng gốc: “as good as”.","wrong":{"well":"“Well” là trạng từ; sau “is” cần tính từ “good”.","better":"Giữa as … as không dùng dạng so sánh hơn “better”.","best":"Giữa as … as không dùng dạng so sánh nhất “best”."}}]}},"can-ability":{"mistakes":[{"wrong":"I can speaking English and French.","right":"I can speak English and French.","bad":"speaking","fix":"speak","why":"Sau “can” luôn là động từ nguyên mẫu, không thêm -ing. Đừng nghĩ “đang nói” như tiếng Việt “có thể đang nói”."},{"wrong":"When I was young, I can run very fast.","right":"When I was young, I could run very fast.","bad":"can","fix":"could","why":"“When I was young” nói về quá khứ nên phải dùng “could”. Tiếng Việt chỉ nói “có thể” cho mọi thì, nên dễ quên đổi."},{"wrong":"I am can swim, but my brother can't.","right":"I can swim, but my brother can't.","bad":"am can","fix":"can","why":"“can” là động từ khuyết thiếu, không đi cùng “am/is/are”. Tiếng Việt “là” không liên quan ở đây, đừng thêm “am”."},{"wrong":"Can I to ask you a question?","right":"Can I ask you a question?","bad":"to ask","fix":"ask","why":"Sau “Can I” chỉ dùng động từ nguyên mẫu không “to”. Cấu trúc “muốn + to V” dễ làm ta thêm “to” nhầm."},{"wrong":"Could you opened the window, please?","right":"Could you open the window, please?","bad":"opened","fix":"open","why":"“could” không phải là thì quá khứ ở đây, và sau “could” luôn dùng nguyên mẫu. Không chia động từ chính thành “opened”."},{"wrong":"A: Can you drive? B: Yes, I do.","right":"A: Can you drive? B: Yes, I can.","bad":"do","fix":"can","why":"Trả lời ngắn phải lặp lại trợ động từ trong câu hỏi: hỏi “Can you...?” thì đáp “Yes, I can.”, không đáp “do”."},{"wrong":"A: Can you ski? B: No, I don't can.","right":"A: Can you ski? B: No, I can't.","bad":"don't can","fix":"can't","why":"Phủ định của “can” là “can't”, không dùng “don't”. Người Việt hay thêm “do” khi phủ định vì quen cấu trúc với “do”."},{"wrong":"Excuse me, you help me, please?","right":"Excuse me, can you help me, please?","bad":"","fix":"can","why":"Muốn nhờ lịch sự phải có “can/could” đứng đầu câu. Chỉ nói “you help me” không thành câu hỏi nhờ vả đúng."}],"contrast":{"title":"Can hay could?","a":"can","b":"could","rows":[["Thời gian","“can”: khả năng ở hiện tại. Ví dụ: I can swim now.","“could”: khả năng trong quá khứ nói chung. Ví dụ: I could swim at six."],["Xin phép","“Can I ...?” thân mật, nói với bạn bè, người nhà.","“Could I ...?” lịch sự hơn, dùng với người lạ hoặc cấp trên."],["Nhờ vả","“Can you ...?” bình thường, thân mật.","“Could you ...?” lịch sự, nhẹ nhàng. Nghĩa không phải quá khứ."],["Phủ định","can't / cannot: không thể bây giờ.","couldn't: đã không thể trong quá khứ."]],"ex":[["Can you help me with this bag?","Could you help me with this bag, please?"],["I can ride a bike now.","I couldn't ride a bike when I was six."]],"tip":"Quá khứ hoặc muốn lịch sự thì “could”; hiện tại hoặc thân mật thì “can”.","quiz":[{"q":"My grandfather is 90, but he ___ still read without glasses.","opts":["can","could","cans","can to"],"a":0,"why":"“is 90” và “still” chỉ hiện tại, nên dùng “can” để nói khả năng hiện tại.","wrong":{"could":"“is 90” và “still” nói hiện tại nên dùng “can”; “could” thành quá khứ hoặc điều kiện.","cans":"“can” không thêm -s ở ngôi thứ ba.","can to":"Sau “can” không có “to”."}},{"q":"In 2010, I ___ speak only a little English.","opts":["can","could","am can","cans"],"a":1,"why":"“In 2010” chỉ quá khứ, nên khả năng quá khứ dùng “could”.","wrong":{"can":"“In 2010” là quá khứ, nên “can” hiện tại không hợp.","am can":"“can” không đi cùng “am”.","cans":"“can” không thêm -s và sai thì."}},{"q":"A new employee says to the boss: “___ I use your computer for a minute?”","opts":["Can't","Do","Could","Am"],"a":2,"why":"Người nói là nhân viên mới xin phép sếp, nên dùng “Could I ...?” cho lịch sự.","wrong":{"Can't":"Đây là lời xin phép, không phải lời phủ định; “Can't I” thành câu hỏi khác hẳn.","Do":"“Do I use” không dùng để xin phép trong tình huống này.","Am":"“Am” không đi trước động từ nguyên mẫu “use”."}},{"q":"Yesterday the nurse ___ find the patient's file, so she called the doctor.","opts":["can't","can","didn't can","couldn't"],"a":3,"why":"“Yesterday” chỉ quá khứ và “so she called” cho thấy không tìm được, nên dùng “couldn't”.","wrong":{"can't":"“Yesterday” là quá khứ nên cần “couldn't”, không phải “can't”.","can":"Câu nói cô ấy phải gọi bác sĩ, nghĩa là không tìm thấy, nên không khẳng định.","didn't can":"Không dùng “didn't” cùng “can”."}},{"q":"A friend asks: “___ you come to my party on Saturday?”","opts":["Can","Are","Do","Does"],"a":0,"why":"Hỏi bạn thân xem đến được không dùng “Can you + V ...?”.","wrong":{"Are":"“Are you come” sai ngữ pháp vì “are” không đi với động từ nguyên mẫu.","Do":"Hỏi khả năng đến dự tiệc cần “can”, không dùng “do”.","Does":"“Does” chỉ dùng với he/she/it, và không hỏi về khả năng."}},{"q":"A: Can your son swim? B: No, he ___.","opts":["doesn't","can't","isn't","can"],"a":1,"why":"Trả lời ngắn cho “Can ...?” phải lặp lại “can”, ở dạng phủ định là “can't”.","wrong":{"doesn't":"Câu trả lời ngắn cần lặp lại “can”, nên “doesn't” không khớp.","isn't":"“isn't” không phải trợ động từ của “can”.","can":"Câu trả lời “No” cần dạng phủ định."}},{"q":"I'm very sorry, but I ___ speak very loudly. I have a sore throat.","opts":["can","don't can","can't","am not can"],"a":2,"why":"“Sore throat” là lý do không nói to được, nên dùng “can't speak”.","wrong":{"can":"“sore throat” cho thấy người nói không thể nói to, nên không khẳng định.","don't can":"Không dùng “don't” cùng “can”.","am not can":"“am not can” sai vì “can” không đi với “be”."}},{"q":"A teenager to her mum: “___ I stay at Lan's house tonight?”","opts":["Can","Am","Are","Does"],"a":0,"why":"Xin phép người thân trong nhà, thân mật, nên dùng “Can I + V ...?”.","wrong":{"Am":"“Am I stay” sai vì “am” không đi với động từ nguyên mẫu.","Are":"“Are” không đi với chủ ngữ “I” và động từ nguyên mẫu “stay”.","Does":"“Does” chỉ dùng với he/she/it, không hợp chủ ngữ “I”."}}]}},"demonstratives":{"mistakes":[{"wrong":"I like this shoes. They are comfortable.","right":"I like these shoes. They are comfortable.","bad":"this","fix":"these","why":"“Shoes” là số nhiều nên dùng “these”. Tiếng Việt không đổi “này” theo số lượng nên dễ quên."},{"wrong":"Who is this man standing at the gate over there?","right":"Who is that man standing at the gate over there?","bad":"this","fix":"that","why":"Người đứng ở xa (over there) dùng “that”; “this” chỉ người hoặc vật ở gần người nói."},{"wrong":"Hello, that is Mai speaking.","right":"Hello, this is Mai speaking.","bad":"that","fix":"this","why":"Qua điện thoại, người gọi tự giới thiệu bằng “this is”. “That” chỉ dùng để hỏi người ở đầu dây kia."},{"wrong":"What is those on the table?","right":"What are those on the table?","bad":"is","fix":"are","why":"“Those” là số nhiều nên đi với “are”. Nhớ: this/that + is, these/those + are."},{"wrong":"That's my parents over there.","right":"Those are my parents over there.","bad":"That's","fix":"Those are","why":"“Parents” là số nhiều và ở xa nên dùng “those are”. “That's” chỉ dùng cho một người hoặc vật."},{"wrong":"Those days I am very busy at work.","right":"These days I am very busy at work.","bad":"Those","fix":"These","why":"“These days” nghĩa là “dạo này”, nói về hiện tại. “Those days” nói về quá khứ xa."},{"wrong":"Excuse me, how much is these bag?","right":"Excuse me, how much is this bag?","bad":"these","fix":"this","why":"“Bag” là số ít nên dùng “this”. “These” chỉ đi với danh từ số nhiều và “are”."},{"wrong":"This my brother, Nam.","right":"This is my brother, Nam.","bad":"","fix":"is","why":"Tiếng Việt nói “Đây anh tôi” được, nhưng tiếng Anh cần động từ “is” sau “this”."}],"contrast":{"title":"This hay that? (gần hay xa)","a":"this / these (gần)","b":"that / those (xa)","rows":[["Khoảng cách","Gần người nói, chạm tới được: This is my desk.","Xa người nói: That is the library."],["Số nhiều","these: These shoes are new.","those: Those shoes are old."],["Điện thoại","Tự giới thiệu: This is Anna.","Hỏi người kia: Is that Mark?"],["Thời gian","This morning, these days (hiện tại).","That day, those days (quá khứ)."]],"ex":[["This is my bag.","That is your bag."],["These are my keys.","Those are your keys."]],"tip":"This/these = ở đây, gần tôi. That/those = ở kia, xa tôi. Số nhiều: this → these, that → those, và đổi “is” sang “are”.","quiz":[{"t":"c","q":"The pen in my hand is blue. ___ pen is blue.","opts":["That","This","These","Those"],"a":1,"why":"Cây bút đang cầm trong tay (gần, số ít) nên dùng “this”.","wrong":{"That":"“That” chỉ vật ở xa, còn bút đang ở trong tay.","Those":"“Those” là số nhiều và chỉ vật ở xa, không hợp với “pen”.","These":"“These” là số nhiều, không đi với danh từ số ít “pen”."}},{"t":"c","q":"The cars on the other side of the road are old. ___ cars are old.","opts":["This","That","These","Those"],"a":3,"why":"Xe ở bên kia đường (xa) và là số nhiều nên dùng “those”.","wrong":{"This":"“This” là số ít và chỉ vật gần, không hợp với “cars”.","These":"“These” chỉ vật ở gần, trong khi xe ở bên kia đường.","That":"“That” là số ít, không đi với “cars”."}},{"t":"c","q":"You answer a call and say your name: Hello, ___ is Kim.","opts":["this","that","these","those"],"a":0,"why":"Tự giới thiệu qua điện thoại dùng “this is”.","wrong":{"that":"“That” dùng để hỏi người ở đầu dây bên kia, không dùng để tự giới thiệu.","these":"“These” là số nhiều, không đi với “is” và tên một người.","those":"“Those” là số nhiều, không đi với “is” và tên một người."}},{"t":"c","q":"You call a clinic and ask who answered: Hello, is ___ Dr Evans?","opts":["this","these","that","those"],"a":2,"why":"Hỏi người ở đầu dây bên kia bằng “Is that …?”.","wrong":{"this":"“This” dùng khi người nói tự giới thiệu, không dùng để hỏi người kia.","these":"“These” là số nhiều, không đi với “is” và một người.","those":"“Those” là số nhiều, không đi với “is” và một người."}},{"t":"c","q":"Holding two apples: ___ apples are for you.","opts":["That","This","Those","These"],"a":3,"why":"Hai quả táo đang cầm (gần, số nhiều) nên dùng “these”.","wrong":{"That":"“That” là số ít và chỉ vật ở xa.","This":"“This” là số ít, không đi với “apples”.","Those":"“Those” chỉ vật ở xa, trong khi táo đang cầm trên tay."}},{"t":"c","q":"I'm sorry, ___ is the wrong answer. (the answer the student just gave)","opts":["that","these","those","they"],"a":0,"why":"“That” thay cho điều vừa được nói, và “is” cần chủ ngữ số ít.","wrong":{"these":"“These” là số nhiều, không đi với “is”.","those":"“Those” là số nhiều, không đi với “is”.","they":"“They” là số nhiều, không đi với “is”."}},{"t":"c","q":"Who are ___ girls standing at the gate over there?","opts":["this","that","those","these"],"a":2,"why":"“Girls” là số nhiều và đứng ở xa (over there), nên dùng “those”.","wrong":{"this":"“This” là số ít, không đi với “girls” và “are”.","that":"“That” là số ít, không đi với “girls” và “are”.","these":"“These” chỉ người ở gần, trong khi các cô gái ở xa (over there)."}},{"t":"c","q":"A: Which dress do you prefer? B: I prefer ___ one in my hand.","opts":["those","this","these","that"],"a":1,"why":"Cái váy đang cầm trong tay người nói (gần, số ít) nên dùng “this one”.","wrong":{"those":"“Those” là số nhiều và chỉ vật xa, không đi với “one”.","that":"“That” chỉ vật ở xa, trong khi váy đang ở trong tay người nói.","these":"“These” là số nhiều, không đi với “one” (số ít)."}}]}},"dependent-prepositions":{"mistakes":[{"wrong":"She is allergic at penicillin.","right":"She is allergic to penicillin.","bad":"at","fix":"to","why":"“Allergic” luôn đi với “to”. Người Việt hay dùng “at” hoặc “with” vì dịch “dị ứng với”."},{"wrong":"He is good in drawing.","right":"He is good at drawing.","bad":"in","fix":"at","why":"Giỏi một kỹ năng dùng “good at”, rồi V-ing. Đừng dịch “giỏi về” thành “in”."},{"wrong":"We discussed about the problem yesterday.","right":"We discussed the problem yesterday.","bad":"discussed about","fix":"discussed","why":"“Discuss” đi thẳng với tân ngữ, không có “about”. Tiếng Việt “thảo luận về” khiến ta thêm “about”."},{"wrong":"I'm looking forward to meet you.","right":"I'm looking forward to meeting you.","bad":"meet","fix":"meeting","why":"“To” trong “look forward to” là giới từ, nên theo sau là V-ing. Đừng nhầm với “to” của động từ nguyên mẫu."},{"wrong":"I'm afraid from dogs.","right":"I'm afraid of dogs.","bad":"from","fix":"of","why":"Sợ cái gì dùng “afraid of”. “From” là lỗi do dịch “sợ từ”, hãy nhớ afraid of."},{"wrong":"He depends of his parents for money.","right":"He depends on his parents for money.","bad":"of","fix":"on","why":"“Depend” chỉ đi với “on”. Người học hay thêm “of” vì dịch “phụ thuộc của”."},{"wrong":"I'm waiting you outside the clinic.","right":"I'm waiting for you outside the clinic.","bad":"","fix":"for","why":"“Wait” cần “for” trước tân ngữ. Tiếng Việt “đợi bạn” không có giới từ nên ta hay quên."},{"wrong":"She is married with a doctor.","right":"She is married to a doctor.","bad":"with","fix":"to","why":"Kết hôn với ai dùng “married to”. Người Việt hay dùng “with” vì nghĩ “với”."}],"contrast":{"title":"Angry with hay angry about?","a":"angry with","b":"angry about","rows":[["Đối tượng","Giận một người, ví dụ “angry with my brother”.","Giận một sự việc, ví dụ “angry about the delay”."],["Theo sau là","Người hoặc đại từ chỉ người: with him, with the nurse.","Danh từ chỉ sự việc hoặc V-ing: about the price, about being late."],["Dùng cùng lúc","“Angry with sb” rồi thêm “about sth”: angry with him about the noise.","“Angry about sth” có thể đứng riêng không có người."],["Từ tương tự","annoyed with sb / pleased with sb.","annoyed about sth / worried about sth."]],"ex":[["She is angry with her brother.","She is angry about the noise."],["I'm angry with my manager.","I'm angry about the new rule."]],"tip":"“With” cho người, “about” cho việc. Cần cả hai thì: angry with someone about something.","quiz":[{"q":"Dr Hall was angry ___ the nurse for forgetting the form.","opts":["about","with","of","to"],"a":1,"why":"Giận một người (the nurse) dùng “angry with”; phần lý do sau đó là for forgetting.","wrong":{"about":"“Angry about the nurse” coi cô y tá như một sự việc, không chỉ rõ giận cô ấy.","of":"“Angry of” là lỗi do dịch “giận của”; không có cụm này trong tiếng Anh.","to":"“Angry to” cũng không đúng; to không đi với tính từ angry."}},{"q":"Dr Hall was angry ___ the missing form.","opts":["with","to","for","about"],"a":3,"why":"Giận về một sự việc (the missing form) dùng “angry about”; with chỉ dành cho người.","wrong":{"with":"“Angry with the missing form” coi tờ phiếu như một người, trong khi with đi với người.","to":"“Angry to” không phải cụm đúng với tính từ angry.","for":"“Angry for” dùng sai giới từ; for không đi với angry khi nêu nguyên nhân."}},{"q":"Mai is angry ___ her sister, who borrowed her car without asking.","opts":["with","about","of","to"],"a":0,"why":"Người bị giận là em gái (her sister), nên dùng “angry with”.","wrong":{"about":"“Angry about her sister” nghĩa là giận về chuyện của cô em, không chỉ ra giận chính em.","of":"“Angry of” là lỗi do dịch; cụm đúng không có of.","to":"“Angry to” cũng không đúng; to không đi với angry."}},{"q":"Mai is angry ___ the rise in rent.","opts":["with","for","about","of"],"a":2,"why":"Giận về sự việc (the rise in rent) dùng “angry about”.","wrong":{"with":"“Angry with the rise” coi sự tăng giá như một người, trong khi with đi với người.","for":"“Angry for” dùng sai giới từ; for không đi với angry khi nêu nguyên nhân.","of":"“Angry of” là lỗi do dịch; không có cụm này."}},{"q":"She is interested ___ working abroad.","opts":["at","on","in","for"],"a":2,"why":"Tính từ “interested” đi với “in”, rồi V-ing: interested in working.","wrong":{"at":"“Interested at” không phải cụm đúng; at không đi với interested.","on":"“Interested on” là lỗi do dịch “quan tâm đến”; cụm đúng là in.","for":"“Interested for” cũng không đúng; for không đi với interested."}},{"q":"He insisted ___ paying for the coffee.","opts":["of","on","to","at"],"a":1,"why":"Động từ “insist” đi với “on”, rồi V-ing: insist on paying.","wrong":{"of":"“Insisted of” là lỗi do dịch “khăng khăng của”; cụm đúng là insist on.","to":"“Insisted to paying” dùng to trước V-ing, không phải cụm đúng của insist.","at":"“Insisted at” không phải cụm đúng; at không đi với động từ insist."}},{"q":"The storm caused serious damage ___ the hospital roof.","opts":["of","to","on","at"],"a":1,"why":"Danh từ “damage” đi với “to” khi nói vật bị hư hại: damage to the roof.","wrong":{"of":"“Damage of the roof” là lỗi do dịch “thiệt hại của”; danh từ damage cần giới từ to.","on":"“Damage on” không phải cụm đúng; on không đi với danh từ damage.","at":"“Damage at” chỉ nơi chốn chung chung, không phải cấu trúc damage + to + vật bị hại."}},{"q":"She apologised ___ him for the mistake.","opts":["with","for","to","at"],"a":2,"why":"Xin lỗi ai dùng “apologise to” + người, rồi “for” + việc; him là người nên cần to.","wrong":{"with":"“Apologised with him” dùng sai giới từ; with không chỉ người nhận lời xin lỗi.","for":"“Apologised for him” nghĩa là xin lỗi thay cho anh ấy, đổi nghĩa so với câu.","at":"“Apologised at him” nghe như nhìn hay nói gay gắt vào anh ấy, không phải xin lỗi."}}]}},"frequency-adverbs":{"mistakes":[{"wrong":"She plays often tennis on Sundays.","right":"She often plays tennis on Sundays.","bad":"plays often","fix":"often plays","why":"Trạng từ tần suất đứng trước động từ thường, không đứng ngay sau nó. Tiếng Việt “chơi thường xuyên” dễ khiến bạn đảo ngược."},{"wrong":"He usually is tired after work.","right":"He is usually tired after work.","bad":"usually is","fix":"is usually","why":"Với động từ “be”, trạng từ đứng sau “be”: “is usually”. Chỉ động từ thường mới có trạng từ đứng trước."},{"wrong":"I don't never eat breakfast at home.","right":"I never eat breakfast at home.","bad":"don't never","fix":"never","why":"“Never” đã mang nghĩa phủ định, không thêm “don't”. Tiếng Việt “không bao giờ không” dễ gây nhầm."},{"wrong":"I am often go to the cinema with friends.","right":"I often go to the cinema with friends.","bad":"am often","fix":"often","why":"“Go” là động từ thường, không cần “am”. Chỉ dùng “be” khi sau nó là tính từ, danh từ hoặc nơi chốn."},{"wrong":"How much often do you study English?","right":"How often do you study English?","bad":"much often","fix":"often","why":"Hỏi tần suất chỉ cần “How often”, không thêm “much”. Đừng dịch từng chữ “bao nhiêu thường xuyên”."},{"wrong":"I phone my mother one time a week.","right":"I phone my mother once a week.","bad":"one time","fix":"once","why":"Một lần nói “once”, hai lần nói “twice”. Từ ba lần mới dùng “three times”."},{"wrong":"I run everyday before work.","right":"I run every day before work.","bad":"everyday","fix":"every day","why":"Trạng từ chỉ tần suất viết tách: “every day”. “Everyday” là tính từ, như “everyday life”."},{"wrong":"Tom never late for school.","right":"Tom is never late for school.","bad":"","fix":"is","why":"Tiếng Anh cần động từ “is” trước tính từ “late”; “never” đứng sau “is”. Tiếng Việt không cần “là” trước tính từ."}],"contrast":{"title":"Trước động từ thường hay sau be?","a":"adverb + V (trước động từ thường)","b":"be + adverb (sau động từ be)","rows":[["Động từ thường","Trạng từ đứng trước: I always go.","Không đứng sau động từ: tránh I go always."],["Động từ be","Không đứng trước be: tránh She always is.","Trạng từ đứng sau: She is always late."],["Phủ định","Never đứng trước V, không thêm don't: I never go.","Be + never: She is never late."],["Câu hỏi","Trạng từ sau chủ ngữ: Do you often go?","Be: Are you often late?"]],"ex":[["He always walks to work.","He is always on time."],["I never eat meat.","I am never hungry at night."]],"tip":"Be là “trục”: trạng từ đứng sau be; với động từ thường, trạng từ đứng trước động từ.","quiz":[{"t":"c","q":"My manager ___ in the office on Friday afternoons. He works from home.","opts":["is never","never is","does never","is no"],"a":0,"why":"“Be” đi trước “never”, chủ ngữ số ít nên dùng “is never”.","wrong":{"never is":"“Never” không đứng trước “is” khi “is” là động từ be chính.","does never":"“Does never” sai vì không dùng “does” với “in the office” (động từ be).","is no":"“Is no” sai vì phủ định tần suất cần “never” chứ không phải “no”."}},{"t":"c","q":"The students ___ homework in the evening, even on Sundays.","opts":["usually not do","do usually","are usually","usually do"],"a":3,"why":"Trạng từ đứng trước động từ thường “do”: “usually do”.","wrong":{"usually not do":"“Usually not do” sai trật tự phủ định; phải dùng “don't usually do” và nghĩa cũng mâu thuẫn với “even on Sundays”.","do usually":"“Do usually” để trạng từ sau động từ thường, sai vị trí.","are usually":"“Are usually homework” sai vì “homework” cần động từ “do”, không phải “be”."}},{"t":"c","q":"The nurse ___ polite to every patient.","opts":["always is","always","is always","does always"],"a":2,"why":"Câu cần động từ be; trạng từ đứng sau “is”: “is always polite”.","wrong":{"always is":"Trạng từ không đứng trước “is” khi “is” là động từ be chính.","always":"Thiếu động từ “be” trước tính từ “polite”.","does always":"“Does always” sai vì “polite” đi với “be”, không dùng “do”."}},{"t":"c","q":"I ___ meet my cousins on Sundays. We have lunch together.","opts":["am often","often","do often","often am"],"a":1,"why":"“Meet” là động từ thường, trạng từ đứng trước nó; vì thế chỉ cần “often”.","wrong":{"am often":"“Am often meet” sai vì không dùng “be” trước động từ thường “meet”.","often am":"“Often am” sai vì không dùng “am” trước động từ “meet” và đảo vị trí.","do often":"“Do often meet” sai vì câu khẳng định không cần trợ động từ “do”."}},{"t":"c","q":"Which is correct for Tom (tần suất: 0%, không bao giờ)?","opts":["Tom doesn't never eat fish.","Tom never eat fish.","Tom never eats fish.","Tom eats never fish."],"a":2,"why":"“Never” đứng trước động từ và động từ chia -s theo “Tom”.","wrong":{"Tom doesn't never eat fish.":"Phủ định kép “doesn't never” sai trong tiếng Anh chuẩn.","Tom never eat fish.":"“Eat” thiếu -s vì chủ ngữ “Tom” là số ít.","Tom eats never fish.":"“Never” không đứng sau động từ “eats” trong câu này."}},{"t":"c","q":"Linh ___ to bed before ten. She is a very early sleeper.","opts":["always goes","goes always","is always","does always"],"a":0,"why":"“Go” là động từ thường nên trạng từ đứng trước: “always goes” (thêm -es theo “Linh”).","wrong":{"goes always":"Trạng từ “always” đứng sau động từ thường là sai vị trí.","is always":"“Is always to bed” sai vì “go to bed” dùng động từ “go”, không dùng “be”.","does always":"“Does always” không dùng trong câu khẳng định thường."}},{"t":"c","q":"Our neighbours ___ at home at weekends. They travel a lot.","opts":["rarely at","are rarely","rarely be","do rarely"],"a":1,"why":"Cần động từ “be” (“at home”), và trạng từ đứng sau “are”: “are rarely at home”.","wrong":{"rarely at":"Thiếu động từ “be” trước “at home”.","rarely be":"“Be” không chia theo chủ ngữ “Our neighbours” nên sai.","do rarely":"“Do rarely at home” sai vì “at home” đi với “be”, không dùng “do”."}},{"t":"c","q":"I ___ to work by bike, even in winter.","opts":["go always","always go","am always go","always am"],"a":1,"why":"“Go” là động từ thường nên trạng từ đứng trước: “always go”.","wrong":{"go always":"Trạng từ “always” đứng sau động từ thường là sai vị trí.","am always go":"Không dùng “be” trước động từ thường “go”.","always am":"“Am” không phải động từ chính của câu này; cần “always go”."}}]}},"have-got":{"mistakes":[{"wrong":"My mother have two sisters and a brother.","right":"My mother has two sisters and a brother.","bad":"have","fix":"has","why":"Ngôi thứ ba số ít (he/she/it) dùng “has”. Tiếng Việt không chia động từ nên người học hay quên “has”."},{"wrong":"She doesn't has a car, so she walks to work.","right":"She doesn't have a car, so she walks to work.","bad":"has","fix":"have","why":"Sau “doesn't” động từ trở về nguyên mẫu: “doesn't have”. Đừng chia lần thứ hai bằng “has”."},{"wrong":"Does he has a brother or a sister?","right":"Does he have a brother or a sister?","bad":"has","fix":"have","why":"Sau “does” dùng “have” nguyên mẫu vì “does” đã mang dấu ngôi thứ ba rồi."},{"wrong":"I have got breakfast at seven every day.","right":"I have breakfast at seven every day.","bad":"have got","fix":"have","why":"“have got” chỉ dùng cho sở hữu hay bệnh, không dùng cho bữa ăn. Ăn sáng là “have breakfast”."},{"wrong":"She is have a cold, so she stays at home.","right":"She has a cold, so she stays at home.","bad":"is have","fix":"has","why":"Không dùng “is” cùng “have”. Tiếng Việt “bị cảm” không có “là”, nên đừng thêm “is” trước “have”."},{"wrong":"A: Have they got a garden? B: No, they don't.","right":"A: Have they got a garden? B: No, they haven't.","bad":"don't","fix":"haven't","why":"Câu hỏi dùng “Have they got ...?” thì câu trả lời ngắn phủ định là “No, they haven't.”, không dùng “don't”."},{"wrong":"I don't have got a car, but my brother has.","right":"I haven't got a car, but my brother has.","bad":"don't have got","fix":"haven't got","why":"Không trộn “don't” với “got”. Chọn “haven't got” hoặc “don't have”, đừng gộp cả ba."},{"wrong":"My brother got two small children now.","right":"My brother has got two small children now.","bad":"","fix":"has","why":"Nói sở hữu hiện tại cần “has got” hoặc “has”. “got” một mình là quá khứ của “get” (nhận được)."}],"contrast":{"title":"Have got hay have (do/does)?","a":"have got","b":"have (do/does)","rows":[["Câu hỏi","“have got”: đảo trợ động từ. Have you got a pen?","“have”: dùng do/does. Do you have a pen?"],["Phủ định","“have got”: haven't/hasn't got. I haven't got time.","“have”: don't/doesn't have. I don't have time."],["Dùng cho hoạt động","Không dùng “got” cho ăn uống, tắm rửa.","Dùng được: have breakfast, have a shower."],["Phong cách","Phổ biến trong tiếng Anh Anh, nói hằng ngày.","Dùng chung cho cả Anh và Mỹ, cũng cho văn viết."]],"ex":[["Have you got any brothers?","Do you have any brothers?"],["She hasn't got a car.","She doesn't have a car."]],"tip":"Có “got” thì không có do/does; có do/does thì bỏ “got”. Ăn uống, tắm rửa chỉ dùng “have”.","quiz":[{"q":"___ your parents got a house in the countryside?","opts":["Have","Do","Does","Has"],"a":0,"why":"“your parents” là they, nên dùng “Have ... got ...?”.","wrong":{"Do":"Có “got” trong câu, nên không dùng “do”; “do” phải đi với “have” không có “got”.","Does":"“Does” dùng với ngôi thứ ba số ít, mà “your parents” là số nhiều.","Has":"“Has” dùng cho he/she/it, không phải “your parents”."}},{"q":"I ___ any coffee left. Can you buy some?","opts":["don't have got","haven't got","hasn't got","doesn't have"],"a":1,"why":"“I” đi với “haven't got” hoặc “don't have”; trong các lựa chọn chỉ “haven't got” đúng.","wrong":{"don't have got":"Không trộn “don't” với “got”.","hasn't got":"Chủ ngữ “I” đi với “haven't”, không phải “hasn't”.","doesn't have":"Chủ ngữ “I” đi với “don't”, không phải “doesn't”."}},{"q":"She ___ lunch with her colleagues at noon every day.","opts":["has got","have got","has","is got"],"a":2,"why":"Bữa ăn là hoạt động nên chỉ dùng “has” cho ngôi thứ ba số ít.","wrong":{"has got":"“have got” không dùng cho bữa ăn.","have got":"“have got” không dùng cho bữa ăn, và “she” cần “has”.","is got":"“is got” không phải cấu trúc đúng."}},{"q":"My brother ___ have a mobile phone, so he uses mine.","opts":["hasn't","don't","haven't","doesn't"],"a":3,"why":"Sau “have” nguyên mẫu, ngôi thứ ba dùng “doesn't have”.","wrong":{"hasn't":"“hasn't” cần đi với “got”, không đi với “have”.","don't":"Chủ ngữ “my brother” là he nên cần “doesn't”.","haven't":"“haven't” dùng cho I/you/we/they và cũng cần “got”."}},{"q":"A: Has Tom got a bike? B: No, he ___.","opts":["hasn't","doesn't","isn't","haven't"],"a":0,"why":"Câu hỏi “Has Tom got ...?” nên trả lời ngắn “No, he hasn't.”.","wrong":{"doesn't":"Câu hỏi dùng “Has ... got”, nên trả lời ngắn phải dùng “hasn't”.","isn't":"“isn't” không phải trợ động từ của “have got”.","haven't":"Chủ ngữ “he” cần “hasn't”, không dùng “haven't”."}},{"q":"Poor Tom! He ___ a high temperature.","opts":["have got","has got","is got","does got"],"a":1,"why":"Nói ai đó đang bị sốt dùng “has got” cho ngôi thứ ba số ít “He”.","wrong":{"have got":"Chủ ngữ “He” cần “has got”, không phải “have got”.","is got":"“got” đi với “have/has”, không đi với “is”.","does got":"Không dùng “does” cùng “got”."}},{"q":"What time does your son ___ breakfast?","opts":["has","have got","have","has got"],"a":2,"why":"Sau “does” dùng động từ nguyên mẫu “have”; bữa ăn không dùng “got”.","wrong":{"has":"Sau “does” động từ phải ở dạng nguyên mẫu, không thêm -s.","have got":"“have got” không dùng cho bữa ăn và không đi sau “does”.","has got":"“has got” không dùng cho bữa ăn và không đi sau “does”."}},{"q":"How many brothers ___ you got?","opts":["have","do","are","has"],"a":0,"why":"“you ... got” đi với “have”: “How many brothers have you got?”.","wrong":{"do":"Có “got” nên không dùng “do”.","are":"“are you got” sai vì “got” đi với “have”.","has":"Chủ ngữ “you” cần “have”, không dùng “has”."}}]}},"imperatives":{"mistakes":[{"wrong":"You open your books, please.","right":"Open your books, please.","bad":"You","fix":"(bỏ)","why":"Mệnh lệnh không cần chủ ngữ “you”; động từ nguyên mẫu đứng đầu câu. Tiếng Việt hay nói “Các bạn mở sách ra”, nên dễ thêm “you”."},{"wrong":"Not talk in the library.","right":"Don't talk in the library.","bad":"Not","fix":"Don't","why":"Mệnh lệnh phủ định cần “Don't” + động từ nguyên mẫu. Không dùng “Not” hay “No” thay cho “Don't”."},{"wrong":"Let's to start the lesson now.","right":"Let's start the lesson now.","bad":"to","fix":"(bỏ)","why":"Sau “Let's” là động từ nguyên mẫu không “to”. Hãy nhớ “Let's” = “let us” rồi mới đến động từ trần."},{"wrong":"Please to sit down here.","right":"Please sit down here.","bad":"to","fix":"(bỏ)","why":"Sau “please” dùng động từ nguyên mẫu trần, không thêm “to”. “Please” chỉ là từ làm câu lịch sự hơn."},{"wrong":"Don't to run on the stairs.","right":"Don't run on the stairs.","bad":"to","fix":"(bỏ)","why":"Sau “Don't” cũng là động từ nguyên mẫu không “to”. Người Việt hay thêm “to” vì quen với “đừng phải…”."},{"wrong":"Let's we go home now.","right":"Let's go home now.","bad":"we","fix":"(bỏ)","why":"“Let's” đã có nghĩa “let us”, nên không thêm chủ ngữ “we”; sau “Let's” chỉ có động từ nguyên mẫu."},{"wrong":"Don't be to late for class.","right":"Don't be late for class.","bad":"to","fix":"(bỏ)","why":"“Be late” là một cụm hoàn chỉnh; không chèn “to” vào giữa. Cấu trúc: Don't + be + tính từ."},{"wrong":"Please closing the door.","right":"Please close the door.","bad":"closing","fix":"close","why":"Mệnh lệnh dùng động từ nguyên mẫu, không dùng V-ing. Sau “please” không thêm -ing hay -s."}],"contrast":{"title":"Câu mệnh lệnh hay Let's?","a":"Imperative (V / Don't + V)","b":"Let's + V","rows":[["Ai làm?","Người nghe làm: “Open the door.”","Cả người nói và người nghe cùng làm: “Let's open the door.”"],["Ý nghĩa","Ra lệnh, nhờ, hướng dẫn, cảnh báo","Đề nghị, rủ rê, gợi ý cùng làm"],["Phủ định","Don't + V: “Don't wait.”","Let's not + V: “Let's not wait.”"],["Giọng điệu","Có thể cộc, thêm “please” cho lịch sự","Thân mật, mềm mại, mang tính chia sẻ"]],"ex":[["Sit down and relax.","Let's sit down and relax."],["Don't go home yet.","Let's not go home yet."]],"tip":"Chỉ bảo người khác làm thì dùng động từ nguyên mẫu; mình làm cùng thì thêm “Let's” phía trước.","quiz":[{"q":"It's nearly lunchtime. ___ have a sandwich together.","opts":["Let's","Have","Don't","We"],"a":0,"why":"“Together” cho thấy cả hai người cùng làm, nên cần lời rủ “Let's + V”.","wrong":{"Have":"Không có “Let's” thì chỉ là lệnh cho người nghe, không rủ cả hai cùng ăn như ngữ cảnh “together”.","Don't":"“Don't have a sandwich together” lại cấm cùng ăn, trái với ngữ cảnh.","We":"“We have a sandwich” là câu kể, không phải lời rủ."}},{"q":"Doctor to a patient: ___ the form, please.","opts":["Let's fill in","Fill in","Filling in","We fill in"],"a":1,"why":"Chỉ bệnh nhân điền biểu mẫu nên dùng mệnh lệnh trực tiếp, không dùng “Let's”.","wrong":{"Let's fill in":"“Let's” nghĩa là bác sĩ cũng điền; thực tế chỉ bệnh nhân điền biểu mẫu.","Filling in":"V-ing không dùng làm mệnh lệnh; cần động từ nguyên mẫu.","We fill in":"“We fill in” là câu kể và chủ ngữ “we” không hợp với lời yêu cầu bệnh nhân."}},{"q":"The film is boring. ___ watch it any more.","opts":["Let's","Don't us","Let's not","Not let's"],"a":2,"why":"Cả hai cùng thôi xem phim, nên dùng “Let's not + V”. “Any more” đi với phủ định.","wrong":{"Let's":"“Let's watch it any more” sai nghĩa; “any more” cần phủ định.","Don't us":"“Don't us watch” không phải cấu trúc đúng trong tiếng Anh.","Not let's":"“Not let's” sai trật tự; phủ định đúng là “Let's not”."}},{"q":"Nurse to a child: ___ be afraid. It's only a small injection.","opts":["Let's","Not","No","Don't"],"a":3,"why":"Y tá chỉ dặn bệnh nhi, không rủ cùng sợ, nên dùng mệnh lệnh phủ định “Don't be afraid”.","wrong":{"Let's":"“Let's be afraid” rủ cùng sợ, trái hẳn với ý trấn an.","Not":"“Not” không đứng một mình mở đầu mệnh lệnh phủ định.","No":"“No” không dùng được trước động từ “be” trong câu mệnh lệnh."}},{"q":"It's late. ___ go home now.","opts":["Let's","Not","To","Lets"],"a":0,"why":"Cả hai cùng về nhà; câu cần lời rủ “Let's + V”.","wrong":{"Not":"“Not go home” không phải mệnh lệnh đúng; thiếu “Don't”.","To":"“To go home” không mở đầu câu mệnh lệnh hay lời rủ.","Lets":"“Lets go” thiếu dấu lược; “Let's” là dạng rút gọn của “let us”."}},{"q":"Teacher to the class: ___ your homework on the desk.","opts":["Let's put","Put","To put","Putting"],"a":1,"why":"Giáo viên ra lệnh cho học sinh, nên dùng mệnh lệnh trực tiếp với động từ nguyên mẫu.","wrong":{"Let's put":"“Let's put” nghĩa giáo viên cũng để bài; thực tế chỉ học sinh nộp bài.","To put":"“To put” không mở đầu câu mệnh lệnh.","Putting":"V-ing không dùng làm mệnh lệnh."}},{"q":"Let's ___ in the hospital car park. It's full.","opts":["don't wait","not to wait","not wait","no waiting"],"a":2,"why":"Phủ định của lời rủ là “Let's not + V” với động từ nguyên mẫu trần.","wrong":{"don't wait":"“Don't” không đi sau “Let's”; dạng đúng là “Let's not”.","not to wait":"Sau “Let's not” là động từ trần, không có “to”.","no waiting":"“No waiting” kiểu biển cấm không đi sau “Let's”."}},{"q":"Excuse me, ___ me the time, please?","opts":["let's tell","telling","you tell","could you tell"],"a":3,"why":"“Excuse me” và dấu “?” cho thấy lời nhờ lịch sự với người lạ, nên dùng “could you + V”.","wrong":{"let's tell":"“Let's tell” nghĩa là cả hai cùng nói, không phải nhờ người lạ cho biết giờ.","telling":"V-ing không dùng để mở đầu một lời nhờ; cần “could you + V”.","you tell":"Thiếu “could” nên chưa thành câu hỏi lịch sự."}}]}},"in-case-unless":{"mistakes":[{"wrong":"I'll take an umbrella in case it will rain.","right":"I'll take an umbrella in case it rains.","bad":"will rain","fix":"rains","why":"Sau “in case” dùng hiện tại đơn, không dùng “will”. Người Việt hay dịch “phòng khi trời sẽ mưa” nên thêm will."},{"wrong":"Unless you don't study, you will fail.","right":"Unless you study, you will fail.","bad":"don't study","fix":"study","why":"“Unless” đã có nghĩa “if … not”, nên không thêm “don't”. Nghĩ “unless = nếu không” là đủ phủ định rồi."},{"wrong":"I took a coat in case it is cold.","right":"I took a coat in case it was cold.","bad":"is","fix":"was","why":"Câu kể ở quá khứ (took) thì mệnh đề sau “in case” cũng ở past simple. Đừng để nguyên “is” theo thói quen."},{"wrong":"Take a taxi in case of it rains.","right":"Take a taxi in case it rains.","bad":"case of","fix":"case","why":"“In case of” chỉ đi với danh từ (in case of rain). Trước một mệnh đề đầy đủ như “it rains” chỉ dùng “in case”."},{"wrong":"You can borrow it as long you return it.","right":"You can borrow it as long as you return it.","bad":"","fix":"as","why":"Cụm cố định là “as long as” với hai chữ “as”. Người học hay bỏ chữ “as” thứ hai vì nghĩ “as long” đã đủ."},{"wrong":"You can stay as long as you will pay.","right":"You can stay as long as you pay.","bad":"will pay","fix":"pay","why":"Sau “as long as” dùng hiện tại đơn dù nói về tương lai. Không dùng “will” trong mệnh đề điều kiện."},{"wrong":"You can come provide that you are quiet.","right":"You can come provided that you are quiet.","bad":"provide","fix":"provided","why":"Liên từ đúng là “provided (that)” hoặc “providing (that)”, không phải “provide”. Nhớ đuôi -d hoặc -ing."},{"wrong":"Take a coat in case if it gets cold.","right":"Take a coat in case it gets cold.","bad":"case if","fix":"case","why":"“In case” đã là liên từ nên không thêm “if”. Người Việt hay ghép hai từ vì cả hai đều dịch là “nếu / phòng khi”."}],"contrast":{"title":"In case hay if?","a":"in case","b":"if","rows":[["Ý nghĩa","Phòng ngừa: làm trước vì việc đó có thể xảy ra, ví dụ “I'll take an umbrella in case it rains”.","Điều kiện: chỉ làm khi việc đó xảy ra, ví dụ “I'll open it if it rains”."],["Thứ tự hành động","Hành động chính xảy ra trước sự việc, có khi sự việc không hề xảy ra.","Hành động chính xảy ra sau khi điều kiện đúng."],["Có xảy ra không","Chưa chắc sự việc xảy ra; chỉ đề phòng.","Nếu điều kiện không có thì hành động không xảy ra."],["Thì động từ","Hiện tại đơn (hiện tại/tương lai) hoặc past simple (kể quá khứ); không dùng “will”.","Hiện tại đơn trong mệnh đề if, mệnh đề chính dùng “will”."]],"ex":[["I'll take my umbrella in case it rains.","I'll open my umbrella if it rains."],["She keeps painkillers in case she gets a headache.","She takes painkillers if she gets a headache."]],"tip":"“In case” là chuẩn bị trước khi chưa có gì xảy ra; “if” là phản ứng sau khi điều đó đã xảy ra.","quiz":[{"q":"I'll take my umbrella ___ it rains. (I want to be ready before the rain starts.)","opts":["if","in case","unless","as long as"],"a":1,"why":"Chuẩn bị ô trước khi mưa là phòng ngừa nên dùng “in case”; chú ý ý trong ngoặc “before the rain starts”.","wrong":{"if":"“If it rains” nghĩa là chỉ mang ô sau khi mưa đã rơi, trái với việc chuẩn bị trước.","unless":"“Unless it rains” nghĩa là trừ khi mưa mới không mang ô, ngược nghĩa với câu.","as long as":"“As long as it rains” nghĩa là miễn là trời mưa, không phải phòng ngừa."}},{"q":"I'll open my umbrella ___ it starts to rain. (I will do it only at that moment.)","opts":["in case","unless","as long as","if"],"a":3,"why":"Hành động chỉ xảy ra sau khi mưa bắt đầu là điều kiện thực sự nên dùng “if”.","wrong":{"in case":"“In case it starts to rain” nghĩa là mở ô trước khi mưa, trái với ý chỉ mở sau.","unless":"“Unless it starts to rain” nghĩa là trừ khi mưa mới không mở, đảo ngược ý.","as long as":"“As long as” nghĩa là miễn là, không hợp với một tình huống chỉ xảy ra một lần."}},{"q":"Ana carries a charger ___ her phone dies. (She has it with her even when the phone is fine.)","opts":["unless","if","in case","as long as"],"a":2,"why":"Ana luôn mang theo sạc dù điện thoại còn pin, nghĩa là phòng ngừa, nên dùng “in case”.","wrong":{"unless":"“Unless her phone dies” nghĩa là trừ khi điện thoại hết pin thì mới mang sạc, vô lý.","if":"“If her phone dies” nghĩa là chỉ mang sạc khi điện thoại đã hết pin, không hợp với ý luôn mang.","as long as":"“As long as her phone dies” nghĩa là miễn là điện thoại hết pin, không logic."}},{"q":"The pharmacist will call you ___ your medicine arrives. (Only after it arrives.)","opts":["in case","if","unless","although"],"a":1,"why":"Cô dược sĩ chỉ gọi sau khi thuốc về, nên là điều kiện thật với “if”.","wrong":{"in case":"“In case your medicine arrives” nghĩa là gọi trước phòng khi thuốc về, không hợp với chỉ gọi sau.","unless":"“Unless your medicine arrives” nghĩa là trừ khi thuốc về thì không gọi, ngược lại nội dung.","although":"“Although” nghĩa là mặc dù, tạo ý tương phản không hợp với việc gọi sau khi thuốc về."}},{"q":"You won't get a refund ___ you have the receipt.","opts":["unless","in case","as long as","because"],"a":0,"why":"Không được hoàn tiền trừ khi có hoá đơn, nên dùng “unless” (= if you don't have).","wrong":{"in case":"“In case you have the receipt” nghĩa là phòng khi bạn có hoá đơn, không nêu được ngoại lệ.","as long as":"“As long as you have” nghĩa là miễn là có hoá đơn thì sẽ không được hoàn tiền, ngược nghĩa.","because":"“Because you have” nêu lý do không được hoàn tiền là vì có hoá đơn, vô lý."}},{"q":"You can use the car ___ you drive slowly.","opts":["in case","unless","until","as long as"],"a":3,"why":"Cho dùng xe với một điều kiện duy nhất là lái chậm, nên dùng “as long as”.","wrong":{"in case":"“In case you drive slowly” nghĩa là phòng khi bạn lái chậm, không nêu điều kiện cho phép.","unless":"“Unless you drive slowly” nghĩa là trừ khi bạn lái chậm thì mới được dùng, ngược lại điều cần diễn đạt.","until":"“Until you drive slowly” nghĩa là cho dùng đến khi bạn lái chậm, nghe vô lý."}},{"q":"Nam took a map in case he ___ lost.","opts":["gets","will get","got","would get"],"a":2,"why":"Câu kể ở quá khứ (took) nên sau “in case” dùng past simple (got) để chỉ khả năng lúc đó.","wrong":{"gets":"“Gets” là hiện tại nên lệch thì với “took” ở quá khứ.","will get":"“Will get” không dùng sau in case, và cũng lệch thì với câu chính ở quá khứ.","would get":"“Would get” không dùng sau in case; chỉ cần past simple."}},{"q":"Unless the test ___ negative, the patient must stay in isolation.","opts":["is","isn't","will be","would be"],"a":0,"why":"“Unless” = if … not, nên động từ sau nó khẳng định ở hiện tại đơn; chủ ngữ “the test” số ít dùng “is”.","wrong":{"isn't":"“Isn't” thành phủ định kép với unless, đảo ngược nghĩa của câu.","will be":"“Will be” không dùng sau unless; mệnh đề điều kiện dùng hiện tại đơn.","would be":"“Would be” là dạng giả định, không hợp với điều kiện thật ở hiện tại."}}]}},"modals-deduction":{"mistakes":[{"wrong":"She must to be at home now.","right":"She must be at home now.","bad":"must to","fix":"must","why":"Sau must dùng động từ nguyên mẫu không “to”. Người Việt hay thêm “to” vì nghĩ giống “phải”."},{"wrong":"He mustn't be at work; it's Sunday.","right":"He can't be at work; it's Sunday.","bad":"mustn't","fix":"can't","why":"Khi suy đoán, phủ định của must là “can't”. “Mustn't” chỉ điều bị cấm, không phải điều chắc chắn không đúng."},{"wrong":"She must be sleep now; the house is silent.","right":"She must be sleeping now; the house is silent.","bad":"sleep","fix":"sleeping","why":"Đoán việc đang diễn ra dùng must be + V-ing. Không bỏ nguyên mẫu “sleep” sau be."},{"wrong":"They might are at the bank.","right":"They might be at the bank.","bad":"are","fix":"be","why":"Sau might (và may, could, must) dùng nguyên mẫu “be”, không chia theo chủ ngữ."},{"wrong":"You must tired after such a long flight.","right":"You must be tired after such a long flight.","bad":"","fix":"be","why":"Tiếng Việt nói “bạn chắc mệt” không cần động từ, nhưng tiếng Anh cần “be” sau must trước tính từ."},{"wrong":"She maybe at home now.","right":"She may be at home now.","bad":"maybe","fix":"may be","why":"“Maybe” là trạng từ (có lẽ), đứng đầu câu. Sau chủ ngữ cần modal “may be” gồm hai từ."},{"wrong":"She doesn't might be at home.","right":"She might not be at home.","bad":"doesn't might","fix":"might not","why":"Modal không đi với do/does. Phủ định bằng cách thêm not sau modal: might not be."},{"wrong":"His light is on, so he must working late.","right":"His light is on, so he must be working late.","bad":"","fix":"be","why":"Dạng tiếp diễn của suy đoán là modal + be + V-ing. Thiếu “be” là lỗi hay gặp."}],"contrast":{"title":"must be hay might be?","a":"must / can't be","b":"might / may / could be","rows":[["Mức chắc chắn","Gần chắc chắn (khoảng 95%): “She must be ill.”","Không chắc, khoảng 50%: “She might be ill.”"],["Bằng chứng","Có bằng chứng rõ ràng, suy ra kết luận hợp lý.","Chỉ là phỏng đoán, có thể đúng hoặc sai."],["Phủ định","Dùng can't: “He can't be at home.”","Dùng might not hoặc may not: “He might not be home.”"],["Từ đi kèm","I'm sure, obviously, so, because...","perhaps, maybe, I don't know, I'm not sure"]],"ex":[["She has a fever and a cough. She must be ill.","She isn't at her desk. She might be ill."],["That can't be Ben; he's in Hue this week.","That might not be Ben; I can't see well."]],"tip":"Must và can't: có bằng chứng, gần chắc chắn. Might, may, could: chỉ đoán. Không dùng mustn't để suy đoán.","quiz":[{"t":"c","q":"The patient has lost five kilos and is very pale, so I'm sure he ___ be seriously ill.","opts":["might","must","mustn't","can't"],"a":1,"why":"Bằng chứng rõ (sụt cân, xanh xao) và “I'm sure” nên dùng must, không dùng might.","wrong":{"might":"Might chỉ là khả năng yếu, không hợp với “I'm sure”.","mustn't":"Mustn't là cấm đoán, không dùng để suy đoán.","can't":"Can't nói không thể bị bệnh nặng, trái với bằng chứng."}},{"t":"c","q":"I have no idea where she is. She ___ be in the lift, or she may be late.","opts":["might","must","can't","mustn't"],"a":0,"why":"Người nói không biết (no idea) và đưa hai khả năng, nên dùng might.","wrong":{"must":"Must là quá chắc chắn trong khi người nói không biết.","can't":"Can't loại hẳn khả năng, trong khi người nói còn gợi ý cô ấy ở thang máy.","mustn't":"Mustn't là cấm đoán, không dùng để đoán vị trí."}},{"t":"c","q":"The coat is far too small. It ___ be Lena's; she is very tall.","opts":["must","might","could","can't"],"a":3,"why":"Áo quá nhỏ, Lena rất cao nên gần như chắc chắn không phải của cô ấy: can't.","wrong":{"must":"Must nói chắc chắn là của Lena, trái với bằng chứng.","might":"Might vẫn để ngỏ khả năng, yếu hơn mức chắc chắn mà bằng chứng đưa ra.","could":"Could cũng chỉ là khả năng, không đủ mạnh so với bằng chứng rõ ràng."}},{"t":"c","q":"Perhaps the shop is closed. It ___ be closed, but let's go and see.","opts":["must","can't","may","mustn't"],"a":2,"why":"Từ “perhaps” và “let's go and see” cho thấy người nói không chắc, nên dùng may.","wrong":{"must":"Must quá chắc chắn, mâu thuẫn với “let's go and see”.","can't":"Can't nói chắc chắn không đóng cửa, trong khi người nói đang nghĩ ngược lại.","mustn't":"Mustn't là cấm đoán, không dùng để đoán việc cửa hàng đóng."}},{"t":"c","q":"She isn't in her room. She ___ at the canteen.","opts":["might be","might","might to be","might been"],"a":0,"why":"Sau modal might dùng be nguyên mẫu, đoán vị trí: might be at the canteen.","wrong":{"might":"Thiếu be, trước giới từ at cần động từ be.","might to be":"Sau modal không dùng “to”.","might been":"“Been” là quá khứ phân từ, không dùng sau might ở nghĩa hiện tại."}},{"t":"c","q":"I'm not sure the bus is on time. It ___ be on time today.","opts":["mustn't","might not","doesn't might","not might"],"a":1,"why":"Phủ định của khả năng yếu là might not, đặt not sau modal.","wrong":{"mustn't":"Mustn't là cấm đoán, không diễn tả khả năng.","doesn't might":"Modal không dùng với does/doesn't.","not might":"Not phải đứng sau modal, không đứng trước."}},{"t":"c","q":"Listen! The baby ___ crying again.","opts":["must be","must","must being","must is"],"a":0,"why":"Đoán hành động đang diễn ra: must + be + V-ing; “Listen!” là bằng chứng.","wrong":{"must":"Thiếu be trước crying, không có dạng modal + V-ing trực tiếp.","must being":"Sau modal không dùng being cho trường hợp này.","must is":"Sau modal phải dùng be, không dùng is."}},{"t":"c","q":"A: Why is nobody here? B: They ___ having lunch; it's twelve o'clock.","opts":["can't be","mustn't","must be","must to be"],"a":2,"why":"Mười hai giờ là giờ ăn trưa, nên suy ra họ chắc đang ăn: must be having.","wrong":{"can't be":"Can't be nói họ không thể đang ăn trưa, trái với giờ giấc.","mustn't":"Mustn't là cấm đoán, không dùng để suy đoán.","must to be":"Sau must không có “to” trước be."}}]}},"passive-reporting":{"mistakes":[{"wrong":"My phone got steal on the bus.","right":"My phone got stolen on the bus.","bad":"steal","fix":"stolen","why":"Sau “get” trong bị động cần V3 (stolen). Người Việt hay giữ nguyên động từ vì tiếng Việt không đổi dạng."},{"wrong":"The painter is believed to live in Paris in 1900.","right":"The painter is believed to have lived in Paris in 1900.","bad":"live","fix":"have lived","why":"Việc xảy ra trước lúc người ta tin cần “to have + V3”. Mốc “in 1900” là tín hiệu quá khứ."},{"wrong":"He is said that he is a good surgeon.","right":"He is said to be a good surgeon.","bad":"that he is","fix":"to be","why":"Chủ ngữ đã là “He” thì dùng “to be”, không dùng “that + mệnh đề”. Tiếng Việt “người ta nói rằng” dễ làm ta thêm “that”."},{"wrong":"They are supposed to being quiet in the library.","right":"They are supposed to be quiet in the library.","bad":"being","fix":"be","why":"Sau “supposed to” là động từ nguyên mẫu, không dùng V-ing. Hãy nhớ “to” đi với nguyên mẫu."},{"wrong":"He didn't got paid on time.","right":"He didn't get paid on time.","bad":"got","fix":"get","why":"Sau “didn't” động từ luôn ở nguyên mẫu, nên dùng “get paid”. Không để quá khứ hai lần."},{"wrong":"He is suppose to call me tonight.","right":"He is supposed to call me tonight.","bad":"suppose","fix":"supposed","why":"Cần V3 “supposed” sau “be”. Khi nói, âm -d bị nuốt nên dễ viết thiếu."},{"wrong":"It is reported that three people injured in the crash.","right":"It is reported that three people were injured in the crash.","bad":"","fix":"were","why":"Mệnh đề sau “that” cần động từ bị động “were injured”. Tiếng Việt “bị” không cần trợ động từ như tiếng Anh."},{"wrong":"Everyone is expected arrive by nine.","right":"Everyone is expected to arrive by nine.","bad":"","fix":"to","why":"Sau “is expected” phải có “to” trước động từ nguyên mẫu. Cấu trúc: be expected to V."}],"contrast":{"title":"It is said that… hay He is said to…?","a":"It is said that + mệnh đề","b":"S + is said to + V","rows":[["Chủ ngữ","Chủ ngữ giả “It”; thông tin nằm trong mệnh đề sau “that”.","Chủ ngữ thật của câu đứng đầu (“He”, “The nurse”)."],["Động từ sau","Mệnh đề có thì riêng: “It is said that she works abroad.”","Dùng to V hoặc to have + V3: “She is said to work abroad.”"],["Hành động xảy ra trước","Dùng thì quá khứ trong mệnh đề: “that she worked there”.","Dùng “to have + V3”: “She is said to have worked there.”"],["Phong cách","Hơi dài, thường gặp trong tin tức và văn bản chính thức.","Gọn hơn, nhấn mạnh người hay vật được nói đến."]],"ex":[["It is believed that the thief entered through the window.","The thief is believed to have entered through the window."],["It is said that the doctor speaks five languages.","The doctor is said to speak five languages."]],"tip":"Có “It” thì cần “that” và mệnh đề; có chủ ngữ thật thì dùng “to V” hoặc “to have V3”.","quiz":[{"q":"It is said ___ the new clinic opens next month.","opts":["to","for","that","having"],"a":2,"why":"Vì chủ ngữ giả “It” đứng đầu nên cần “that + mệnh đề”; mệnh đề đó là “the new clinic opens”.","wrong":{"to":"Sau chủ ngữ giả “It” phải là mệnh đề, nên “to” không phù hợp.","for":"Giới từ “for” không dẫn mệnh đề sau “It is said”.","having":"V-ing không dùng sau “It is said”, câu cần mệnh đề đầy đủ."}},{"q":"The new clinic is said ___ next month.","opts":["to open","that opens","opening","open"],"a":0,"why":"Chủ ngữ “The new clinic” đứng đầu nên dùng is said + to V cho hành động sắp tới; không cần to have.","wrong":{"that opens":"Chủ ngữ thật đã đứng đầu câu nên không thêm “that + mệnh đề”.","opening":"Sau “is said” cần “to + V”, không dùng V-ing.","open":"Thiếu “to”; cấu trúc đúng là is said to open."}},{"q":"She moved abroad in 2010. = She is believed ___ abroad in 2010.","opts":["to move","to have moved","to be moved","to moving"],"a":1,"why":"Hành động chuyển ra nước ngoài xảy ra trước hiện tại, nên dùng to have + V3 (to have moved); “in 2010” là gợi ý.","wrong":{"to move":"Hiện tại “to move” không hợp với mốc “in 2010” đã qua.","to be moved":"Dạng bị động “to be moved” đổi nghĩa thành bị chuyển đi, không đúng ý câu.","to moving":"Sau “to” phải là nguyên mẫu; “moving” là V-ing nên sai."}},{"q":"Mr Lee is thought ___ in Hue as a child.","opts":["to live","to have lived","that lived","living"],"a":1,"why":"Việc sống ở Hue xảy ra trước hiện tại, nên dùng to have + V3; “as a child” là dấu hiệu quá khứ.","wrong":{"to live":"“To live” chỉ hiện tại, không hợp với “as a child” là thời đã qua.","that lived":"Chủ ngữ thật “Mr Lee” đã đứng đầu câu nên không thêm “that + mệnh đề”.","living":"V-ing không đi sau “is thought” trong cấu trúc tường thuật."}},{"q":"My laptop ___ stolen at the station last week.","opts":["get","gets","got","getting"],"a":2,"why":"Get-passive: got + stolen; mốc “last week” cho biết phải dùng quá khứ got.","wrong":{"get":"Sự việc đã xảy ra nên dùng quá khứ “got”; “get” là nguyên mẫu.","gets":"Hiện tại “gets” không hợp với “last week” là mốc quá khứ.","getting":"“getting” thiếu trợ động từ nên không thể làm động từ chính."}},{"q":"You ___ to hand in the form by Friday.","opts":["supposed","are supposed","suppose","are suppose"],"a":1,"why":"Be supposed to chỉ điều được yêu cầu; “hand in the form by Friday” là quy định phải làm.","wrong":{"supposed":"Thiếu động từ “be” nên câu không có động từ chính.","suppose":"Dạng “suppose” không dùng làm quy định, cần be + supposed.","are suppose":"Thiếu -d; sau “are” cần V3 supposed."}},{"q":"'Why isn't he here?' 'He ___ to be at the meeting at nine, but he's late.'","opts":["was supposed","is supposing","supposes","has supposed"],"a":0,"why":"Kế hoạch lẽ ra đã xảy ra nhưng không thành, nên dùng was supposed to; “but he's late” cho thấy ý đó.","wrong":{"is supposing":"Không có cấu trúc “be supposing to” trong nghĩa này.","supposes":"“supposes” là động từ chủ động nên không diễn tả kỳ vọng hay quy định.","has supposed":"“has supposed” là hiện tại hoàn thành chủ động, sai nghĩa và sai cấu trúc."}},{"q":"They ___ to have been the best team in the league last year.","opts":["said","say","are saying","are said"],"a":3,"why":"Chủ ngữ thật “They” + to have been (đã xảy ra trước), nên phải dùng bị động are said.","wrong":{"said":"Thiếu “are”; không có động từ be thì không phải bị động.","say":"Dạng chủ động “say” không hợp vì chủ ngữ “They” là đội bóng được nói tới.","are saying":"Dạng tiếp diễn chủ động không tạo được cấu trúc tường thuật bị động."}}]}},"past-perfect":{"mistakes":[{"wrong":"When we arrived, the film was already started.","right":"When we arrived, the film had already started.","bad":"was","fix":"had","why":"Người Việt hay dùng “be + V3” theo nghĩa bị động. Ở đây phim tự bắt đầu trước, cần had + V3."},{"wrong":"He told me he has lost his wallet the day before.","right":"He told me he had lost his wallet the day before.","bad":"has","fix":"had","why":"Sau “told” ở quá khứ, hiện tại hoàn thành lùi thành quá khứ hoàn thành. Tiếng Việt không đổi thì nên dễ quên."},{"wrong":"After she had got home, she had cooked dinner.","right":"After she had got home, she cooked dinner.","bad":"had cooked","fix":"cooked","why":"Chỉ việc xảy ra trước mới dùng had + V3. Việc xảy ra sau dùng quá khứ đơn; đừng dùng had cho cả hai."},{"wrong":"She had called me two days ago.","right":"She called me two days ago.","bad":"had called","fix":"called","why":"Chỉ có một việc, kèm mốc rõ “two days ago”, nên dùng quá khứ đơn. Đừng dùng “had” chỉ vì việc đó đã qua lâu."},{"wrong":"I didn't had lunch before the meeting.","right":"I hadn't had lunch before the meeting.","bad":"didn't","fix":"hadn't","why":"Muốn nói “chưa ăn trước đó” dùng hadn't + V3. Người Việt hay lấy didn't vì quen quá khứ đơn."},{"wrong":"By the time I arrive, the bus had gone.","right":"By the time I arrived, the bus had gone.","bad":"arrive","fix":"arrived","why":"Cả câu kể về quá khứ nên mệnh đề sau “by the time” dùng quá khứ đơn. Tiếng Việt không chia động từ nên dễ quên."},{"wrong":"Before I came here, I have never eaten pho.","right":"Before I came here, I had never eaten pho.","bad":"have","fix":"had","why":"“Before I came” là mốc quá khứ, nên “chưa từng ăn” cũng phải lùi về had never + V3."},{"wrong":"He had took the medicine before lunch.","right":"He had taken the medicine before lunch.","bad":"took","fix":"taken","why":"Sau “had” phải dùng V3: take - took - taken. Người học hay lấy dạng quá khứ đơn “took” vì nhầm hai cột động từ bất quy tắc."}],"contrast":{"title":"Quá khứ hoàn thành hay quá khứ đơn?","a":"had + V3","b":"V2 / V-ed","rows":[["Thứ tự","Việc xảy ra trước: When I arrived, he had left.","Việc xảy ra sau, hoặc nối tiếp: He left, then I arrived."],["Số hành động","Cần hai việc trong quá khứ để so sánh trước sau.","Một hành động đơn lẻ vẫn dùng được: I left at six."],["Mốc thời gian","Dùng với by the time, already, never…before.","Dùng với yesterday, last week, ago."],["Tường thuật","Lùi thì từ quá khứ đơn: He said he had left.","Câu trực tiếp hoặc việc đang kể: He left early."]],"ex":[["When I arrived, the train had left.","When I arrived, the train left."],["She had cooked dinner before she watched TV.","She cooked dinner, then she watched TV."]],"tip":"Có hai việc trong quá khứ thì việc xảy ra trước dùng had + V3, việc xảy ra sau dùng quá khứ đơn.","quiz":[{"t":"c","q":"She ___ never flown before that trip, so she felt nervous.","opts":["had","has","did","was"],"a":0,"why":"“Before that trip” là mốc quá khứ, nên “never flown” cần trợ động từ had.","wrong":{"has":"Hiện tại hoàn thành lệch thì với “felt” ở quá khứ.","did":"“Did never flown” sai vì did đi với nguyên mẫu.","was":"“Was never flown” thành dạng bị động, sai nghĩa."}},{"t":"c","q":"Yesterday I ___ my grandmother, then I went to the market.","opts":["had visited","visited","have visited","was visited"],"a":1,"why":"“Yesterday” và hai việc kể theo thứ tự nên dùng quá khứ đơn visited.","wrong":{"had visited":"Hai việc nối tiếp theo thứ tự kể thì cả hai dùng quá khứ đơn.","have visited":"Hiện tại hoàn thành không đi với “yesterday”.","was visited":"Dạng bị động sai nghĩa vì chủ ngữ tự đi thăm bà."}},{"t":"c","q":"She ___ to Hue two years ago.","opts":["had moved","has moved","moved","moves"],"a":2,"why":"“Ago” đi với quá khứ đơn, vì chỉ có một việc đã xảy ra với mốc rõ ràng.","wrong":{"had moved":"Có “two years ago” và chỉ một việc nên dùng quá khứ đơn.","has moved":"Hiện tại hoàn thành không đi với “ago”.","moves":"Hiện tại đơn không hợp với “two years ago”."}},{"t":"c","q":"By the time Dad got home, we ___ already eaten.","opts":["have","were","did","had"],"a":3,"why":"“By the time + quá khứ đơn” cần quá khứ hoàn thành: ăn xong trước khi bố về, nên chọn had.","wrong":{"have":"Hiện tại hoàn thành lệch thì với “got home” ở quá khứ.","were":"“Were already eaten” thành bị động, sai nghĩa.","did":"“Did already eaten” sai vì did đi với nguyên mẫu."}},{"t":"c","q":"Why was he angry? Because nobody ___ him about the change.","opts":["had told","has told","had tell","did told"],"a":0,"why":"Việc không ai báo xảy ra trước lúc anh giận, nên dùng had told với V3 đúng.","wrong":{"has told":"Hiện tại hoàn thành lệch thì với “was angry” ở quá khứ.","had tell":"Sau had phải dùng V3 “told”, không dùng nguyên mẫu.","did told":"Sau did phải dùng nguyên mẫu “tell”, không dùng “told”."}},{"t":"c","q":"The patient ___ eaten since the morning, so the nurse called the doctor.","opts":["didn't","hadn't","hasn't","wasn't"],"a":1,"why":"Việc không ăn kéo dài đến trước lúc y tá gọi bác sĩ, nên dùng hadn't + V3.","wrong":{"didn't":"“Didn't eaten” sai vì sau didn't phải dùng nguyên mẫu.","hasn't":"Hiện tại hoàn thành lệch thì với “called” ở quá khứ.","wasn't":"“Wasn't eaten” thành bị động, sai nghĩa."}},{"q":"___ the shop already closed when you got there?","opts":["Has","Did","Had","Is"],"a":2,"why":"Hỏi việc đóng cửa xảy ra trước lúc bạn đến (“when you got there”), nên dùng Had + S + V3.","wrong":{"Has":"Hiện tại hoàn thành lệch thì với “got there” ở quá khứ.","Did":"“Did the shop already closed” sai vì sau did phải dùng nguyên mẫu “close”.","Is":"Hiện tại đơn lệch thì với “when you got there” ở quá khứ."}},{"t":"c","q":"She said she ___ the money to her brother the week before.","opts":["has sent","sends","was sent","had sent"],"a":3,"why":"Tường thuật sau “said”, việc “the week before” lùi thành quá khứ hoàn thành had sent.","wrong":{"has sent":"Sau “said” ở quá khứ không giữ hiện tại hoàn thành.","sends":"Hiện tại đơn lệch thì với “said” và “the week before”.","was sent":"Dạng bị động sai nghĩa vì cô ấy là người gửi."}}]}},"present-perfect-continuous":{"mistakes":[{"wrong":"We are studying English since last year.","right":"We have been studying English since last year.","bad":"are","fix":"have been","why":"Có “since” thì không dùng hiện tại tiếp diễn. Tiếng Việt “đang học từ năm ngoái” không đổi thì, nhưng tiếng Anh phải đổi."},{"wrong":"They have been wait outside for an hour.","right":"They have been waiting outside for an hour.","bad":"wait","fix":"waiting","why":"Sau “have been” luôn là V-ing. Tiếng Việt không chia dạng động từ nên người học hay để nguyên mẫu."},{"wrong":"I have been knowing him since childhood.","right":"I have known him since childhood.","bad":"been knowing","fix":"known","why":"“Know” là động từ trạng thái, không chia tiếp diễn. Người Việt hay thêm “been” vì nghĩ “đã biết suốt”."},{"wrong":"She has been waiting since two hours.","right":"She has been waiting for two hours.","bad":"since","fix":"for","why":"“Since” + mốc (since two o'clock), “for” + khoảng thời gian (for two hours). Tiếng Việt đều nói “từ/được”, nên dễ nhầm."},{"wrong":"He has been playing football for 2018.","right":"He has been playing football since 2018.","bad":"for","fix":"since","why":"“2018” là một mốc thời gian nên đi với “since”. “For” chỉ đi với khoảng thời gian như “six years”."},{"wrong":"I have been reading three books this month.","right":"I have read three books this month.","bad":"been","fix":"read","why":"Có số lượng (“three books”) là nói kết quả, nên dùng hoàn thành đơn. Cần đổi cả “been reading” thành “read”."},{"wrong":"She have been working all day.","right":"She has been working all day.","bad":"have","fix":"has","why":"Chủ ngữ ngôi thứ ba số ít (she/he/it) đi với has been. Chỉ I/you/we/they mới đi với have been."},{"wrong":"My feet hurt because I have standing all day.","right":"My feet hurt because I have been standing all day.","bad":"","fix":"been","why":"Thiếu “been”: cấu trúc đầy đủ là have been + V-ing. Hay quên vì tiếng Việt không có từ tương ứng."}],"contrast":{"title":"Hiện tại hoàn thành tiếp diễn hay hiện tại hoàn thành đơn?","a":"have/has been + V-ing","b":"have/has + V3","rows":[["Trọng tâm","Quá trình, hoạt động kéo dài: I've been reading.","Kết quả, việc đã xong: I've read it."],["Số lượng","Không đếm được số lần/lượng: I've been writing.","Đếm được kết quả: I've written three emails."],["Động từ trạng thái","Không dùng với know, like, want: ✗ have been knowing.","Dùng được: I've known her for years."],["Hỏi và trả lời","How long…? nhấn thời gian: How long have you been waiting?","How many…? nhấn lượng: How many pages have you read?"]],"ex":[["I've been painting the kitchen all day.","I've painted the kitchen. It looks great."],["She's been writing emails since nine.","She's written twelve emails today."]],"tip":"Nhấn quá trình hoặc thời gian thì dùng been + V-ing; nhấn kết quả hoặc số lượng thì dùng V3; động từ trạng thái luôn dùng V3.","quiz":[{"t":"c","q":"I ___ three chapters so far, and I'm still going.","opts":["have read","have been reading","read","am reading"],"a":0,"why":"Có số lượng “three chapters” và “so far”, nên chọn hoàn thành đơn have read.","wrong":{"have been reading":"Có số lượng “three chapters” nên nói về kết quả, dùng hoàn thành đơn.","read":"Quá khứ đơn không đi với “so far”; “so far” cần thì hoàn thành.","am reading":"Hiện tại tiếp diễn không diễn tả số chương đã đọc tính đến hiện tại."}},{"t":"c","q":"I ___ this old song since I was a child.","opts":["have been liking","have liked","like","am liking"],"a":1,"why":"“Like” là động từ trạng thái, “since I was a child” cần hoàn thành, nên chọn have liked.","wrong":{"have been liking":"“Like” là động từ trạng thái, không dùng dạng tiếp diễn dù có “since”.","like":"Hiện tại đơn không đi với “since I was a child” để chỉ việc kéo dài từ quá khứ.","am liking":"Động từ “like” chỉ cảm xúc ổn định nên không chia hiện tại tiếp diễn."}},{"t":"c","q":"She ___ her homework already, so she's free to play.","opts":["has been finishing","finishes","has finished","is finishing"],"a":2,"why":"“Already” cùng kết quả “free to play” cho thấy việc đã hoàn tất, nên dùng has finished.","wrong":{"has been finishing":"“Already” và việc được rảnh cho thấy đã xong, nên không dùng dạng tiếp diễn.","finishes":"Hiện tại đơn nói thói quen, không diễn tả việc đã xong rồi trước hiện tại.","is finishing":"Hiện tại tiếp diễn nói việc đang làm, trong khi cô ấy đã làm xong và rảnh."}},{"t":"c","q":"I ___ this novel for a month and I still haven't finished it.","opts":["have read","read","am reading","have been reading"],"a":3,"why":"Việc đọc vẫn chưa xong và kéo dài một tháng, nên cần have been reading nhấn mạnh quá trình.","wrong":{"have read":"Hoàn thành đơn ngụ ý đã đọc xong, mâu thuẫn với “still haven't finished”.","read":"Quá khứ đơn nói việc đã chấm dứt, trái với việc đọc vẫn chưa xong.","am reading":"Hiện tại tiếp diễn không đi với “for a month” để nối quá khứ với hiện tại."}},{"t":"c","q":"He ___ been feeling ill since Monday.","opts":["has","have","is","had"],"a":0,"why":"“He” là ngôi thứ ba số ít, nên dùng has been feeling; “since Monday” báo hiệu thì hoàn thành tiếp diễn.","wrong":{"have":"Chủ ngữ “he” số ít nên dùng has, không dùng have.","is":"“Is been” không tồn tại; trợ động từ đứng trước “been” là have/has.","had":"“Had been feeling since Monday” là quá khứ hoàn thành, không nối đến hiện tại như ngữ cảnh."}},{"t":"c","q":"We've been learning Japanese ___ three months.","opts":["since","for","ago","from"],"a":1,"why":"“Three months” là khoảng thời gian nên đi với “for”.","wrong":{"since":"“Since” đi với mốc thời gian, không đi với khoảng “three months”.","ago":"“Ago” không đứng sau động từ theo cách này; cần “for” cho khoảng thời gian.","from":"“From three months” không đúng để chỉ quãng thời gian kéo dài đến nay."}},{"t":"c","q":"I ___ sleeping well lately.","opts":["don't been","haven't","haven't been","am not been"],"a":2,"why":"“Lately” báo hiệu hoàn thành tiếp diễn, phủ định là haven't been + V-ing.","wrong":{"don't been":"“Don't” không đi với “been”; phủ định đúng là haven't been.","haven't":"Thiếu “been” trước sleeping nên cấu trúc không hoàn chỉnh.","am not been":"“Am not been” không tồn tại; sau “been” cần trợ động từ have."}},{"t":"c","q":"Why is Mai so tired? What ___ all night?","opts":["is she doing","she has been doing","has been she doing","has she been doing"],"a":3,"why":"Hỏi về hoạt động kéo dài gây mệt, dùng What + has she been doing, trợ động từ đảo trước chủ ngữ.","wrong":{"is she doing":"Hiện tại tiếp diễn không nối “all night” với trạng thái mệt hiện tại.","she has been doing":"Trong câu hỏi, trợ động từ has phải đứng trước chủ ngữ “she”.","has been she doing":"“She” phải đứng sau “has”, không chen giữa “been” và “doing”."}}]}},"pronouns":{"mistakes":[{"wrong":"Me and my sister live in Hanoi.","right":"My sister and I live in Hanoi.","bad":"Me","fix":"I","why":"Làm chủ ngữ thì dùng “I”, không dùng “me”. Mẹo: bỏ “my sister” đi, bạn sẽ nói “I live”, không nói “Me live”."},{"wrong":"The doctor gave the medicine to I.","right":"The doctor gave the medicine to me.","bad":"I","fix":"me","why":"Sau giới từ “to” phải dùng đại từ tân ngữ “me”. Người Việt chỉ có “tôi” nên dễ chọn nhầm “I”."},{"wrong":"My mother she is a nurse.","right":"My mother is a nurse.","bad":"she","fix":"(bỏ)","why":"Danh từ “My mother” đã là chủ ngữ, không nhắc lại bằng “she”. Tiếng Việt ít khi lặp kiểu này nhưng người học hay thêm vào."},{"wrong":"I like they very much.","right":"I like them very much.","bad":"they","fix":"them","why":"Sau động từ “like” là vị trí tân ngữ nên dùng “them”, không dùng chủ ngữ “they”."},{"wrong":"Look at he. He is laughing.","right":"Look at him. He is laughing.","bad":"he","fix":"him","why":"Sau giới từ “at” dùng tân ngữ “him”. Đại từ chủ ngữ “he” chỉ đứng trước động từ."},{"wrong":"I have a new phone. He is very fast.","right":"I have a new phone. It is very fast.","bad":"He","fix":"It","why":"Vật dùng “it”, không dùng “he” hay “she”. Tiếng Việt có “nó” cho cả vật lẫn người nên dễ nhầm giới tính."},{"wrong":"Is very hot today.","right":"It is very hot today.","bad":"","fix":"It","why":"Tiếng Anh luôn cần chủ ngữ. Nói về thời tiết thì dùng “It” làm chủ ngữ giả."},{"wrong":"Please call we after class.","right":"Please call us after class.","bad":"we","fix":"us","why":"Sau động từ “call” cần tân ngữ “us”. “We” chỉ dùng làm chủ ngữ trước động từ."}],"contrast":{"title":"I hay me? (chủ ngữ hay tân ngữ)","a":"Đại từ chủ ngữ (I, he, we...)","b":"Đại từ tân ngữ (me, him, us...)","rows":[["Vị trí","Trước động từ: “She likes tea.”","Sau động từ hoặc giới từ: “I like her.”"],["Vai trò","Người làm hành động","Người nhận hành động hoặc đi sau giới từ"],["Dạng thay đổi","I, he, she, we, they","me, him, her, us, them (you và it giữ nguyên)"],["Trả lời ngắn","Khi có động từ: “I am.”","Khi không có động từ: “Me too.”, “It's me.”"]],"ex":[["I help him every day.","He helps me every day."],["We love our teacher, and she loves us.","They know her, and she knows them."]],"tip":"Đứng trước động từ thì dùng I, he, we; đứng sau động từ hoặc giới từ thì dùng me, him, us.","quiz":[{"q":"My brother is shy, so I often help ___.","opts":["him","he","his","himself"],"a":0,"why":"“My brother” (nam) là tân ngữ của “help”, nên dùng “him”.","wrong":{"he":"Sau động từ “help” cần tân ngữ; “he” là chủ ngữ.","his":"“His” là sở hữu, cần một danh từ phía sau.","himself":"“Himself” chỉ dùng khi chủ ngữ và tân ngữ là cùng một người; ở đây chủ ngữ là “I”."}},{"q":"Hoa and Lan are in my class. ___ are very friendly.","opts":["Them","They","Their","She"],"a":1,"why":"Chủ ngữ của “are” là hai người, nên dùng “They”.","wrong":{"Them":"“Them” là tân ngữ, không dùng làm chủ ngữ trước “are”.","Their":"“Their” là sở hữu, đi kèm danh từ.","She":"“She” chỉ một người, trong khi có hai bạn."}},{"q":"Look! Someone is waving at ___.","opts":["we","our","us","ours"],"a":2,"why":"Sau giới từ “at” dùng tân ngữ “us”.","wrong":{"we":"Sau giới từ “at” dùng tân ngữ, không dùng chủ ngữ “we”.","our":"“Our” là sở hữu, cần danh từ theo sau.","ours":"“Ours” nghĩa là “của chúng ta”, không thay cho người được vẫy tay chào."}},{"q":"The tickets are on the table. Please take ___ with you.","opts":["them","they","their","it"],"a":0,"why":"“The tickets” là số nhiều và làm tân ngữ của “take”, nên dùng “them”.","wrong":{"they":"Sau động từ “take” cần tân ngữ; “they” là chủ ngữ.","their":"“Their” là sở hữu, cần danh từ đi sau.","it":"“Tickets” là số nhiều nên không dùng “it” số ít."}},{"q":"Mia is in my class. I teach ___ maths.","opts":["she","hers","them","her"],"a":3,"why":"“Mia” là một bé gái, làm tân ngữ của “teach”, nên dùng “her”.","wrong":{"she":"“She” là chủ ngữ; sau “teach” cần tân ngữ.","hers":"“Hers” nghĩa là “của cô ấy”, không chỉ người.","them":"“Mia” chỉ một người nên không dùng số nhiều “them”."}},{"q":"Anna and ___ are going to the market.","opts":["I","me","my","mine"],"a":0,"why":"“Anna and I” là chủ ngữ của “are going”; bỏ “Anna” thì còn “I”.","wrong":{"me":"“Anna and me” làm chủ ngữ thì sai; bỏ “Anna” sẽ thấy “me are going”.","my":"“My” là sở hữu, cần danh từ phía sau.","mine":"“Mine” nghĩa là “của tôi”, không làm chủ ngữ."}},{"q":"Please sit between Tom and ___.","opts":["I","me","my","mine"],"a":1,"why":"Sau “between” là tân ngữ, nên “Tom and me” là dạng đúng.","wrong":{"I":"Sau giới từ “between” cần tân ngữ “me”.","my":"“My” là sở hữu và cần danh từ.","mine":"“Mine” nghĩa là “của tôi”, không chỉ người."}},{"q":"Don't touch the oven. ___ is very hot.","opts":["Them","He","It","Its"],"a":2,"why":"“The oven” là một vật số ít làm chủ ngữ của “is”, nên dùng “It”.","wrong":{"Them":"“Them” là tân ngữ số nhiều, không làm chủ ngữ.","He":"“He” chỉ dùng cho người nam; “the oven” là vật.","Its":"“Its” là sở hữu, cần danh từ phía sau, ví dụ “its door”."}}]}},"quantifiers-2":{"mistakes":[{"wrong":"Every students must wear a uniform.","right":"Every student must wear a uniform.","bad":"students","fix":"student","why":"Sau every dùng danh từ số ít dù ý nghĩa là cả nhóm. Tiếng Việt “mọi học sinh” dễ khiến ta thêm -s."},{"wrong":"Both of my parent work in a bank.","right":"Both of my parents work in a bank.","bad":"parent","fix":"parents","why":"Both of + danh từ phải ở dạng số nhiều vì nói về hai người: “my parents”."},{"wrong":"I didn't see neither of them.","right":"I didn't see either of them.","bad":"neither","fix":"either","why":"Neither đã mang nghĩa phủ định, nên khi câu có “didn't” phải dùng “either”. Tránh phủ định kép."},{"wrong":"Every of my friends has a phone.","right":"Each of my friends has a phone.","bad":"Every","fix":"Each","why":"Every không đi trực tiếp với “of”. Khi có “of” thì dùng each of hoặc every one of."},{"wrong":"Each of the nurses have a locker.","right":"Each of the nurses has a locker.","bad":"have","fix":"has","why":"Each (of) luôn đi với động từ số ít, dù sau “of” là danh từ số nhiều."},{"wrong":"All of students passed the exam.","right":"All of the students passed the exam.","bad":"","fix":"the","why":"Sau “all of” cần có “the/my/these”: all of the students. Nếu bỏ “of” có thể nói “all students”."},{"wrong":"Neither student didn't come to class.","right":"Neither student came to class.","bad":"didn't","fix":"came","why":"“Neither” đã mang nghĩa phủ định nên động từ ở dạng khẳng định. Tiếng Việt nói “không ... không” nên dễ lặp phủ định."},{"wrong":"All my friends is coming to the party.","right":"All my friends are coming to the party.","bad":"is","fix":"are","why":"All + danh từ số nhiều đi với động từ số nhiều. Đừng nhầm với everybody (số ít) vì cùng nghĩa “mọi người”."}],"contrast":{"title":"every hay all?","a":"every","b":"all","rows":[["Danh từ theo sau","every + danh từ số ít: every student","all + danh từ số nhiều hoặc không đếm được: all students, all water"],["Động từ","Số ít: Every room has a window.","Số nhiều: All the rooms have a window."],["Với thời gian","every day = ngày nào cũng làm (thói quen)","all day = suốt cả ngày (một khoảng thời gian liên tục)"],["Đại từ liên quan","everybody, everyone, everything + động từ số ít","all of us / all of them + động từ số nhiều"]],"ex":[["She walks to work every day.","She stayed in bed all day."],["Every room has a window.","All the rooms have a window."]],"tip":"Every thì số ít và lặp lại (every day); all thì số nhiều hoặc cả một khoảng liền mạch (all day).","quiz":[{"q":"I was at the clinic ___ day yesterday.","opts":["every","all","each","both"],"a":1,"why":"Ở phòng khám suốt cả ngày hôm qua nên dùng all day.","wrong":{"every":"“Every day yesterday” vô lý vì yesterday chỉ một ngày cụ thể.","each":"“Each day” nói về từng ngày riêng lẻ, không hợp với hôm qua.","both":"“Both day” sai vì both cần danh từ số nhiều."}},{"q":"I brush my teeth ___ morning.","opts":["all","every","both","either"],"a":1,"why":"Thói quen hằng ngày dùng every + danh từ số ít: every morning.","wrong":{"all":"“All morning” nghĩa là suốt buổi sáng, không phải thói quen lặp lại.","both":"“Both morning” sai vì both cần danh từ số nhiều và chỉ hai đối tượng.","either":"“Either morning” nghĩa là buổi sáng nào trong hai buổi, không phải thói quen."}},{"q":"___ the teachers in this school are friendly.","opts":["Every","Each","All","Neither"],"a":2,"why":"Danh từ số nhiều có “the” và động từ “are” nên dùng all the teachers.","wrong":{"Every":"“Every” cần danh từ số ít và không đứng trước “the teachers”.","Each":"“Each” không đứng trước “the teachers” nếu thiếu “of”.","Neither":"“Neither” dùng cho hai đối tượng và mang nghĩa phủ định, trong khi câu nói tích cực về cả nhóm."}},{"q":"There are fifty teachers here, and ___ teacher is friendly.","opts":["every","all","both","either"],"a":0,"why":"“Teacher is” là số ít nên dùng every + danh từ số ít. “Fifty” cho thấy nhóm lớn hơn hai.","wrong":{"all":"“All teacher” sai vì all cần danh từ số nhiều.","both":"“Both” chỉ dùng cho hai người, mà ở đây có năm mươi giáo viên.","either":"“Either” chỉ dùng cho hai đối tượng, không hợp với năm mươi giáo viên."}},{"q":"The teacher gave a certificate to ___ of the thirty students.","opts":["both","either","neither","each"],"a":3,"why":"Có ba mươi học sinh, nhóm hơn hai người, nên chỉ each (từng em một) hợp lý; both, either, neither chỉ dùng cho hai.","wrong":{"both":"“Both” chỉ dùng cho đúng hai người, mà ở đây có ba mươi học sinh.","either":"“Either” nghĩa là một trong hai, không hợp với nhóm ba mươi người.","neither":"“Neither” là không ai trong hai người, và không hợp với nhóm ba mươi người nhận chứng chỉ."}},{"q":"You can sit on the sofa or the chair. ___ is fine with me.","opts":["Both","Either","Neither","Every"],"a":1,"why":"Hai lựa chọn, cái nào cũng ổn: dùng either với động từ số ít “is”.","wrong":{"Both":"“Both is” sai vì both cần động từ số nhiều, và nghĩa cũng không hợp.","Neither":"“Neither is fine” nghĩa là không cái nào ổn, trái với ý được chọn tuỳ ý.","Every":"“Every” cần danh từ đi sau và không dùng cho hai đối tượng."}},{"q":"Neither sister ___ married.","opts":["is","are","be","have"],"a":0,"why":"Neither + danh từ số ít đi với động từ số ít: neither sister is.","wrong":{"are":"“Neither sister” là số ít nên động từ phải là “is”.","be":"“Be” không chia thì nên không dùng làm động từ chính.","have":"“Have married” sai vì thiếu trợ động từ và không khớp số ít."}},{"q":"She speaks ___ English and German.","opts":["either","neither","every","both"],"a":3,"why":"Cặp both … and … nối hai thứ cùng đúng; ở đây cô ấy nói cả hai thứ tiếng.","wrong":{"either":"“Either” đi với “or”, không đi với “and”.","neither":"“Neither” đi với “nor”, không đi với “and”.","every":"“Every” cần danh từ số ít, không nối hai ngôn ngữ bằng “and”."}}]}},"relative-nondefining":{"mistakes":[{"wrong":"My mother, that is a teacher, loves books.","right":"My mother, who is a teacher, loves books.","bad":"that","fix":"who","why":"Sau dấu phẩy không dùng “that”. Với người, chọn “who”."},{"wrong":"Hanoi, where is the capital, is busy.","right":"Hanoi, which is the capital, is busy.","bad":"where","fix":"which","why":"“Where” cần một mệnh đề đầy đủ phía sau. Ở đây “is” thiếu chủ ngữ nên dùng “which”."},{"wrong":"He didn't call, what annoyed me.","right":"He didn't call, which annoyed me.","bad":"what","fix":"which","why":"Để nói về cả sự việc ở mệnh đề trước, dùng “which”. “What” không nối được hai mệnh đề."},{"wrong":"Dr Lee, whose her clinic is near, is kind.","right":"Dr Lee, whose clinic is near, is kind.","bad":"whose her","fix":"whose","why":"“Whose” đã chỉ sở hữu rồi, không thêm “her”. Lỗi này hay gặp vì tiếng Việt lặp “của cô ấy”."},{"wrong":"My uncle, whom I stayed with him, is a vet.","right":"My uncle, whom I stayed with, is a vet.","bad":"with him","fix":"with","why":"Đại từ quan hệ đã thay cho “him”, nên không lặp lại. Giữ giới từ “with” và bỏ “him”."},{"wrong":"She lives in Hue, which I was born.","right":"She lives in Hue, where I was born.","bad":"which","fix":"where","why":"Hue là nơi chốn và mệnh đề sau đủ chủ ngữ, nên dùng “where”, không dùng “which”."},{"wrong":"My cousin, who's car is red, is a pilot.","right":"My cousin, whose car is red, is a pilot.","bad":"who's","fix":"whose","why":"“Who's” là “who is”. Muốn chỉ sở hữu phải dùng “whose”."},{"wrong":"My phone, which I bought it last week, is broken.","right":"My phone, which I bought last week, is broken.","bad":"bought it","fix":"bought","why":"“Which” đã thay cho “it”, nên không lặp tân ngữ. Tiếng Việt cho phép lặp nên dễ sai."}],"contrast":{"title":"Có dấu phẩy hay không?","a":"Mệnh đề xác định (không dấu phẩy)","b":"Mệnh đề không xác định (có dấu phẩy)","rows":[["Chức năng","Giúp nhận ra người/vật nào: “the girl who sits there”.","Thêm thông tin phụ: “Anna, who sits there, …”."],["Dấu phẩy","Không có dấu phẩy.","Có hai dấu phẩy, hoặc một dấu cuối câu."],["Dùng “that”","Được dùng “that” thay who/which.","Không dùng “that”."],["Bỏ mệnh đề","Bỏ đi thì mất nghĩa của câu.","Bỏ đi, câu chính vẫn đủ nghĩa."]],"ex":[["The doctor who treated me is very kind.","Dr Hall, who treated me, is very kind."],["Books that are old are cheap here.","This book, which is old, is cheap."]],"tip":"Chỉ bổ sung: dùng dấu phẩy, không dùng that. Cần nhận dạng: không dấu phẩy.","quiz":[{"q":"Bạn chỉ có MỘT người chú. Câu nào đúng?","opts":["My uncle who works at a bank speaks German.","My uncle, who works at a bank, speaks German.","My uncle, that works at a bank, speaks German.","My uncle, which works at a bank, speaks German."],"a":1,"why":"Chỉ có một người chú nên thông tin về ngân hàng chỉ là phụ, cần hai dấu phẩy và “who”.","wrong":{"My uncle who works at a bank speaks German.":"Không có dấu phẩy ngụ ý bạn có nhiều chú và đang chọn ra một người, trái với ý chỉ có một.","My uncle, that works at a bank, speaks German.":"Không dùng “that” trong mệnh đề nằm giữa hai dấu phẩy.","My uncle, which works at a bank, speaks German.":"“Which” chỉ vật, còn uncle là người."}},{"q":"Bạn có nhiều đồng nghiệp và cần chỉ rõ người nào. Câu nào đúng?","opts":["The colleague who sits next to me is a nurse.","The colleague, who sits next to me, is a nurse.","The colleague, that sits next to me, is a nurse.","The colleague, which sits next to me, is a nurse."],"a":0,"why":"Cần nhận dạng người nào nên dùng mệnh đề xác định, không dấu phẩy.","wrong":{"The colleague, who sits next to me, is a nurse.":"Có dấu phẩy nghĩa là người nghe đã biết colleague nào, nên không giúp nhận ra.","The colleague, that sits next to me, is a nurse.":"Không dùng “that” sau dấu phẩy.","The colleague, which sits next to me, is a nurse.":"“Which” chỉ vật, còn colleague là người."}},{"q":"Her house, ___ is near the station, is for sale.","opts":["that","what","which","who"],"a":2,"why":"Có dấu phẩy nên dùng which cho vật, không dùng that.","wrong":{"that":"“That” không dùng trong mệnh đề có dấu phẩy.","what":"“What” không làm đại từ quan hệ.","who":"“Who” chỉ người, còn house là vật."}},{"q":"Students ___ miss more than three lessons will be removed from the course.","opts":[", who",", which",", whom","who"],"a":3,"why":"Câu chỉ nhóm học sinh nhất định, cần mệnh đề xác định không có dấu phẩy.","wrong":{", who":"Dấu phẩy sẽ khiến câu nói về tất cả học sinh, trái với ý chỉ nhóm nhất định.",", which":"“Which” chỉ vật, và có dấu phẩy không hợp nghĩa.",", whom":"“Whom” là tân ngữ, mà ở đây từ cần thay là chủ ngữ."}},{"q":"She is late again, ___ is typical.","opts":["which","what","that","who"],"a":0,"why":"“Which” thay cho cả mệnh đề “she is late again”.","wrong":{"what":"“What” không làm đại từ quan hệ nối hai mệnh đề.","that":"Sau dấu phẩy không dùng “that”.","who":"“Who” chỉ người, còn đây là cả sự việc."}},{"q":"Dr Kim, ___ I work, is very kind.","opts":["with who","who with","whom with","with whom"],"a":3,"why":"Giới từ đứng trước whom: “with whom I work” là cách viết trang trọng.","wrong":{"with who":"Sau giới từ with phải dùng whom, không dùng who.","who with":"“Who with” là thứ tự sai; giới từ phải đứng trước whom.","whom with":"Giới từ with phải đứng trước whom, không phải sau."}},{"q":"The town, ___ I grew up, has a new hospital.","opts":["when","where","whose","who"],"a":1,"why":"“Where” thay cho “in the town”; town là nơi chốn.","wrong":{"when":"“When” chỉ thời gian, còn town là nơi chốn.","whose":"“Whose” cần danh từ ngay sau.","who":"“Who” chỉ người, mà town là nơi chốn."}},{"q":"Ms Dang, ___ children are all doctors, is very proud.","opts":["who","which","whose","whom"],"a":2,"why":"“Whose + danh từ” chỉ sở hữu; “whose children” nghĩa là con của cô Dang.","wrong":{"who":"“Who” không đứng ngay trước danh từ children.","which":"“Which” chỉ vật, không chỉ sở hữu của người.","whom":"“Whom” không đứng trước danh từ children."}}]}},"some-any":{"mistakes":[{"wrong":"I can't see some students in the room.","right":"I can't see any students in the room.","bad":"some","fix":"any","why":"Câu phủ định dùng “any”. Tiếng Việt chỉ nói “không thấy”, nên dễ chọn nhầm “some”."},{"wrong":"She doesn't know nothing about it.","right":"She doesn't know anything about it.","bad":"nothing","fix":"anything","why":"Tiếng Anh không dùng hai từ phủ định. Sau “doesn't” dùng “anything”, khác với tiếng Việt “không biết gì”."},{"wrong":"Nobody don't like waiting.","right":"Nobody likes waiting.","bad":"don't","fix":"likes","why":"“Nobody” đã mang nghĩa phủ định và là số ít, nên động từ ở dạng khẳng định số ít."},{"wrong":"Have you got some brothers or sisters?","right":"Have you got any brothers or sisters?","bad":"some","fix":"any","why":"Câu hỏi thông tin thông thường dùng “any”. Chỉ dùng “some” khi mời hoặc nhờ."},{"wrong":"Could I have any water, please?","right":"Could I have some water, please?","bad":"any","fix":"some","why":"Lời nhờ vả dùng “some”, vì người nói mong nhận được. Đừng dùng “any” như trong câu hỏi thông tin."},{"wrong":"There aren't no seats left.","right":"There aren't any seats left.","bad":"no","fix":"any","why":"Sau “aren't” dùng “any”, không dùng “no”: đã có “not” thì không thêm từ phủ định nữa."},{"wrong":"I want to buy anything for my mother.","right":"I want to buy something for my mother.","bad":"anything","fix":"something","why":"Câu khẳng định dùng “something”, không dùng “anything”. Tiếng Việt “cái gì đó” và “bất cứ cái gì” khác nhau nhưng dễ bị gộp thành một."},{"wrong":"I need to buy something new shoes.","right":"I need to buy some new shoes.","bad":"something","fix":"some","why":"“Something” là đại từ, không đứng trước danh từ. Trước danh từ số nhiều dùng “some”."}],"contrast":{"title":"some hay any?","a":"some","b":"any","rows":[["Câu khẳng định","Dùng some: “I have some questions.”","Thường không dùng; chỉ có nghĩa “bất kỳ”: “Ask any teacher.”"],["Câu phủ định","Không dùng some sau “not”.","Dùng any sau not/never: “I don't have any time.”"],["Câu hỏi","Dùng khi mời hoặc nhờ: “Would you like some tea?”","Dùng cho câu hỏi thông tin: “Is there any tea?”"],["Từ ghép","somebody, something, somewhere","anybody, anything, anywhere"]],"ex":[["I'd like some water, please.","Do you have any water?"],["She has some friends in London.","She doesn't have any friends in London."]],"tip":"Câu khẳng định, lời mời, lời nhờ thì some; câu phủ định và câu hỏi thông tin thì any.","quiz":[{"t":"c","q":"We haven't got ___ eggs for the cake.","opts":["some","no","any","something"],"a":2,"why":"Câu phủ định “haven't got” cần any.","wrong":{"some":"“Some” không dùng trong phủ định thông thường như vậy.","no":"“No” cộng với “haven't” là hai phủ định.","something":"“Something” là đại từ, không đứng trước danh từ “eggs”."}},{"t":"c","q":"Would you like ___ coffee before the meeting?","opts":["some","no","anything","every"],"a":0,"why":"Lời mời “Would you like ...?” dùng some trước danh từ không đếm được.","wrong":{"no":"“No coffee” không hợp trong lời mời.","anything":"“Anything” là đại từ, không đứng trước danh từ “coffee”.","every":"“Every” đi với danh từ đếm được số ít, không đi với danh từ không đếm được “coffee”."}},{"t":"c","q":"Is there ___ parking near the hospital?","opts":["some","any","nothing","every"],"a":1,"why":"Câu hỏi thông tin chưa biết có hay không dùng any.","wrong":{"some":"“Some” hợp với lời mời hoặc nhờ, không phải câu hỏi thông tin này.","nothing":"“Nothing” là đại từ, không đứng trước danh từ “parking”.","every":"“Every parking” sai vì “parking” không đếm được; cần từ trung tính như any."}},{"t":"c","q":"Can I have ___ help with these forms, please?","opts":["any","anything","nothing","some"],"a":3,"why":"Lời nhờ “Can I have ... please?” dùng some để mong nhận được sự giúp đỡ.","wrong":{"any":"“Any” không phù hợp khi nhờ cụ thể; some tự nhiên hơn.","anything":"“Anything” là đại từ, không đứng trước danh từ “help”.","nothing":"“Nothing” có nghĩa phủ định, mâu thuẫn với lời nhờ."}},{"t":"c","q":"I'm hungry, but there's ___ in the cupboard.","opts":["anything","something","nothing","some"],"a":2,"why":"“But” báo hiệu đối lập: đói nhưng không có gì trong tủ, nên dùng nothing.","wrong":{"anything":"“Anything” cần câu phủ định, còn “there's” là khẳng định.","something":"“Something” nghĩa là có đồ ăn, không đối lập với “hungry”.","some":"“Some” cần danh từ đi sau, ở đây không có."}},{"t":"c","q":"She didn't tell ___ about the surprise party.","opts":["any","somebody","nobody","anybody"],"a":3,"why":"Câu phủ định “didn't tell” đi với anybody, nghĩa là không nói với ai.","wrong":{"somebody":"“Somebody” không dùng sau “didn't” trong nghĩa này.","nobody":"“Nobody” cộng với “didn't” là hai phủ định.","any":"“Any” cần danh từ đi sau (any people); ở đây không có danh từ nên không đúng."}},{"t":"c","q":"___ has called me since this morning, so I'm worried.","opts":["Nobody","Anybody","Somebody","Everybody"],"a":0,"why":"Từ “so I'm worried” cho thấy không ai gọi, nên dùng nobody làm chủ ngữ.","wrong":{"Somebody":"“Somebody has called” nghĩa là có người gọi, không gây lo lắng.","Anybody":"“Anybody” không dùng làm chủ ngữ để diễn đạt không ai.","Everybody":"“Everybody has called” nghĩa là ai cũng gọi, không khớp với lo lắng."}},{"t":"c","q":"We looked for the cat, but it was ___ to be found.","opts":["somewhere","nowhere","anywhere","everywhere"],"a":1,"why":"Cấu trúc “was nowhere to be found” là cụm cố định, nghĩa là không thấy đâu cả.","wrong":{"somewhere":"“Somewhere to be found” không đúng cụm cố định.","anywhere":"“Anywhere” cần câu phủ định, ở đây là “was ... to be found”.","everywhere":"“Everywhere to be found” nghĩa ngược lại, tìm thấy ở khắp nơi."}}]}},"subjunctive-formal":{"mistakes":[{"wrong":"The manager insisted that he comes early.","right":"The manager insisted that he come early.","bad":"comes","fix":"come","why":"Sau insist that trang trọng dùng nguyên mẫu, không chia -s. Hãy bỏ -s dù chủ ngữ là “he”."},{"wrong":"It's time we go to bed.","right":"It's time we went to bed.","bad":"go","fix":"went","why":"Sau “It's time + S” dùng quá khứ đơn dù nghĩa là bây giờ. Đây là lỗi vì tiếng Việt không đổi thì."},{"wrong":"I'd rather not to go to the party.","right":"I'd rather not go to the party.","bad":"not to go","fix":"not go","why":"Phủ định của would rather là “would rather not + nguyên mẫu”, không có “to”. Đừng nhầm với “decide not to go”."},{"wrong":"You had better to see a dentist.","right":"You had better see a dentist.","bad":"to see","fix":"see","why":"Sau “had better” cũng là nguyên mẫu không “to”, giống các động từ khuyết thiếu."},{"wrong":"I'd rather you don't tell anyone.","right":"I'd rather you didn't tell anyone.","bad":"don't","fix":"didn't","why":"Would rather + chủ ngữ mới dùng quá khứ đơn, dù nói hiện tại hoặc tương lai: “didn't tell”."},{"wrong":"The rules demand that every student is on time.","right":"The rules demand that every student be on time.","bad":"is","fix":"be","why":"Sau demand that dùng “be” nguyên mẫu, không dùng is/are. Hãy nhớ “be” cho mọi ngôi."},{"wrong":"She suggested me to leave early.","right":"She suggested that I leave early.","bad":"me to leave","fix":"that I leave","why":"Suggest không đi với “someone to V”. Dùng “suggest that + S + V” hoặc “suggest leaving”."},{"wrong":"I would rather have tea than to drink coffee.","right":"I would rather have tea than drink coffee.","bad":"to drink","fix":"drink","why":"Sau “would rather … than” cả hai vế đều nguyên mẫu không “to”, giữ song song."}],"contrast":{"title":"would rather + V hay would rather + S + V2?","a":"would rather + V","b":"would rather + S + V2","rows":[["Chủ ngữ","Cùng chủ ngữ: “I'd rather stay.”","Chủ ngữ khác: “I'd rather you stayed.”"],["Dạng động từ","Nguyên mẫu không “to”: “rather go”.","Quá khứ đơn: “rather you went”."],["Ý nghĩa","Sở thích của bản thân.","Điều mình muốn người khác làm hoặc không làm."],["Phủ định","“I'd rather not go.”","“I'd rather you didn't go.”"]],"ex":[["I'd rather walk to work.","I'd rather you walked to work."],["She'd rather not wait.","She'd rather he didn't wait."]],"tip":"Một người làm: rather + nguyên mẫu. Hai người: rather + chủ ngữ mới + quá khứ đơn.","quiz":[{"q":"I'm tired. I'd rather ___ a taxi than walk home.","opts":["took","take","to take","taking"],"a":1,"why":"Cùng chủ ngữ “I” nên chỉ cần would rather + nguyên mẫu; không có chủ ngữ mới nên không dùng quá khứ.","wrong":{"took":"Quá khứ chỉ dùng khi sau rather có chủ ngữ mới; ở đây cùng chủ ngữ “I”.","to take":"Sau would rather không dùng “to”.","taking":"V-ing không đi sau would rather; cần nguyên mẫu."}},{"q":"I'd rather you ___ here; it's a hospital zone.","opts":["didn't park","don't park","not to park","won't park"],"a":0,"why":"Chủ ngữ mới “you” + would rather nên dùng didn't park để nói điều mình không muốn.","wrong":{"don't park":"Có chủ ngữ mới “you” nên cần quá khứ đơn, không dùng hiện tại.","not to park":"“not to park” sai dạng khi sau rather có chủ ngữ mới.","won't park":"Tương lai không dùng sau would rather + chủ ngữ mới."}},{"q":"My brother would rather ___ his own business than work for a company.","opts":["starts","started","start","to start"],"a":2,"why":"Cùng chủ ngữ nên dùng nguyên mẫu; vế “than work” cũng là nguyên mẫu để song song.","wrong":{"starts":"Sau would rather chỉ dùng nguyên mẫu, không chia -s.","started":"Cùng chủ ngữ “My brother” nên không dùng quá khứ.","to start":"Sau would rather không có “to”."}},{"q":"She'd rather her husband ___ so late every night.","opts":["didn't work","doesn't work","not working","not work"],"a":0,"why":"Chủ ngữ mới “her husband” đòi hỏi quá khứ đơn phủ định: didn't work.","wrong":{"doesn't work":"Chủ ngữ mới “her husband” nên dùng quá khứ đơn, không dùng hiện tại.","not working":"V-ing không dùng sau chủ ngữ mới của would rather.","not work":"Thiếu trợ động từ “didn't”; “not work” không tạo thành quá khứ đơn phủ định."}},{"q":"The company insisted that all staff ___ the new rules.","opts":["follows","followed","following","follow"],"a":3,"why":"Insist that + S + V nguyên mẫu; “all staff follow” chứ không chia -s.","wrong":{"follows":"Sau insist that giả định, nên giữ nguyên mẫu.","followed":"Quá khứ không dùng trong mệnh đề giả định sau insist.","following":"V-ing không làm động từ chính của mệnh đề that."}},{"q":"'The deadline is tomorrow.' 'It's time we ___ working on the report.'","opts":["start","started","starting","will start"],"a":1,"why":"“The deadline is tomorrow” cho thấy việc cần làm ngay; It's time + S + V2 tức là “we started”.","wrong":{"start":"Sau “It's time we” dùng quá khứ đơn.","starting":"V-ing không đi với “It's time we”; cần quá khứ đơn.","will start":"Tương lai không dùng sau “It's time + S”."}},{"q":"You ___ see a doctor if the pain gets worse.","opts":["better to","'d to","'d better","'d better to"],"a":2,"why":"Had better + V nguyên mẫu; cách viết tắt đúng là “'d better see”.","wrong":{"better to":"Thiếu “had”; và sau had better không có “to”.","'d to":"“'d to” không phải cấu trúc đúng; cần had better.","'d better to":"Có “to” thừa sau had better."}},{"q":"The doctor recommended that she ___ any heavy bags.","opts":["doesn't carry","didn't carry","not to carry","not carry"],"a":3,"why":"Phủ định giả định: that + S + not + V nguyên mẫu, nên “she not carry”.","wrong":{"doesn't carry":"Phủ định giả định dùng not + nguyên mẫu, không dùng trợ động từ chia ngôi.","didn't carry":"Quá khứ phủ định không dùng trong mệnh đề giả định sau recommend that.","not to carry":"Sau chủ ngữ “she” không dùng “not to”; cần not + nguyên mẫu."}}]}},"time-clauses":{"mistakes":[{"wrong":"When I will finish work, I will go to the gym.","right":"When I finish work, I will go to the gym.","bad":"will finish","fix":"finish","why":"Sau when nói về tương lai dùng hiện tại đơn, không dùng will. Người Việt hay thêm will vì thấy “sẽ” ở cả hai vế."},{"wrong":"He called me during I was in the shower.","right":"He called me while I was in the shower.","bad":"during","fix":"while","why":"During đi với danh từ như “the lesson”. Trước một mệnh đề có chủ ngữ và động từ phải dùng while."},{"wrong":"I'll finish the report until Friday.","right":"I'll finish the report by Friday.","bad":"until","fix":"by","why":"By nghĩa là chậm nhất vào lúc đó; until nghĩa là kéo dài liên tục đến lúc đó. Việc hoàn thành một lần dùng by."},{"wrong":"By the time you will arrive, I will have left.","right":"By the time you arrive, I will have left.","bad":"will arrive","fix":"arrive","why":"By the time là liên từ thời gian nên mệnh đề đi sau dùng hiện tại đơn khi nói về tương lai."},{"wrong":"I was walking home when it was starting to rain.","right":"I was walking home when it started to rain.","bad":"was starting","fix":"started","why":"Hành động ngắn cắt ngang dùng quá khứ đơn; chỉ việc đang diễn ra mới dùng quá khứ tiếp diễn."},{"wrong":"As soon I get home, I'll call you.","right":"As soon as I get home, I'll call you.","bad":"","fix":"as","why":"Cụm cố định là “as soon as”, cần hai chữ “as”. Người học hay bỏ “as” thứ hai."},{"wrong":"I stayed in the waiting room until the doctor didn't come.","right":"I stayed in the waiting room until the doctor came.","bad":"didn't come","fix":"came","why":"Until đã mang nghĩa “cho đến khi”, nên không cần phủ định. Tiếng Việt hay nói “đến khi bác sĩ chưa đến”."},{"wrong":"Before to leave home, I turn off the lights.","right":"Before leaving home, I turn off the lights.","bad":"to leave","fix":"leaving","why":"Sau before dùng V-ing hoặc một mệnh đề, không dùng to + động từ."}],"contrast":{"title":"when hay while?","a":"when","b":"while","rows":[["Ý nghĩa","Vào lúc, khi: một thời điểm hoặc việc ngắn. “When she called, I was out.”","Trong lúc: một khoảng thời gian, việc kéo dài. “While I was out, she called.”"],["Thì thường gặp","Thường đi với quá khứ đơn cho việc ngắn: “when the phone rang”.","Thường đi với tiếp diễn cho việc đang diễn ra: “while I was cooking”."],["Hai việc song song","Ít dùng cho hai việc dài cùng lúc.","Rất hợp: “She read while he cooked.”"],["Tương lai","Cả hai đều dùng hiện tại đơn: “when I arrive”.","“While I'm away, ...” cũng dùng hiện tại, không dùng will."]],"ex":[["I was cooking when the phone rang.","I was cooking while he was washing up."],["When I get home, I'll call you.","While I'm at home, I'll finish the report."]],"tip":"When: mốc thời điểm, việc ngắn. While: khoảng kéo dài, việc đang diễn ra. Hai việc dài song song thì nghĩ ngay đến while.","quiz":[{"t":"c","q":"I'll call you ___ I get home.","opts":["while","when","during","until"],"a":1,"why":"Sau chỗ trống là mệnh đề chỉ một thời điểm trong tương lai, nên dùng when.","wrong":{"while":"While chỉ khoảng thời gian dài đang diễn ra, không hợp với một thời điểm về đến nhà.","during":"During cần danh từ phía sau, không đi với mệnh đề.","until":"Until nghĩa là cho đến khi, ý câu không phải là gọi liên tục đến lúc về nhà."}},{"t":"c","q":"Please don't talk ___ the film.","opts":["while","when","during","until"],"a":2,"why":"Sau chỗ trống là danh từ “the film”, nên dùng giới từ during.","wrong":{"while":"While cần một mệnh đề đủ chủ ngữ và động từ.","when":"When cũng cần mệnh đề, không đứng trước danh từ.","until":"Until nghĩa là cho đến khi, không hợp nghĩa."}},{"t":"c","q":"I was cleaning the kitchen ___ my brother was doing his homework.","opts":["while","during","until","by"],"a":0,"why":"Hai việc đang diễn ra cùng lúc, mỗi vế có chủ ngữ và động từ, nên dùng while.","wrong":{"during":"During đi với danh từ, không đi với mệnh đề.","until":"Until nghĩa là cho đến khi, không diễn tả việc đồng thời.","by":"By là giới từ, không nối hai mệnh đề."}},{"t":"c","q":"I was sleeping ___ the alarm rang.","opts":["during","after","by","when"],"a":3,"why":"Việc ngắn (chuông reo) cắt ngang việc đang diễn ra, nên dùng when.","wrong":{"during":"During cần danh từ, không đi với mệnh đề “the alarm rang”.","after":"After nghĩa là sau khi chuông reo, nên trật tự hai việc bị đảo và câu không hợp lý.","by":"By là giới từ, không nối mệnh đề."}},{"t":"c","q":"Stay in bed ___ the fever goes down.","opts":["while","by","during","until"],"a":3,"why":"Nghỉ ngơi liên tục cho đến một mốc, nên dùng until; sau until dùng hiện tại đơn.","wrong":{"while":"While nghe như hai việc xảy ra cùng lúc, không chỉ mốc kết thúc.","by":"By chỉ hạn chót, không hợp với việc kéo dài liên tục.","during":"During đi với danh từ, không với mệnh đề."}},{"t":"c","q":"By the time the doctor arrived, the patient ___.","opts":["already leaves","had already left","has already left","will already leave"],"a":1,"why":"Mốc “arrived” ở quá khứ, việc rời đi xảy ra trước đó nên dùng quá khứ hoàn thành: had already left.","wrong":{"already leaves":"Hiện tại đơn không hợp với mốc “arrived” ở quá khứ.","has already left":"Hiện tại hoàn thành không đi với mốc trong quá khứ.","will already leave":"Will nói về tương lai, trong khi câu kể quá khứ."}},{"t":"c","q":"She'll ring us as soon as she ___ the hotel.","opts":["reaches","will reach","reached","would reach"],"a":0,"why":"Sau as soon as nói về tương lai dùng hiện tại đơn: reaches.","wrong":{"will reach":"Không dùng will sau as soon as khi nói tương lai.","reached":"Quá khứ đơn sai thì với “She'll ring”.","would reach":"Would reach không hợp trong mệnh đề thời gian ở tương lai."}},{"t":"c","q":"I'll have a coffee after I ___ these emails.","opts":["will send","am sending","have sent","sending"],"a":2,"why":"Việc gửi thư xong trước khi uống cà phê, dùng hiện tại hoàn thành sau after: have sent.","wrong":{"will send":"Không dùng will sau after khi nói về tương lai.","am sending":"Hiện tại tiếp diễn nghĩa là đang gửi, không nhấn mạnh việc đã xong.","sending":"Sending thiếu trợ động từ nên chưa thành mệnh đề đầy đủ."}}]}},"verb-object-infinitive":{"mistakes":[{"wrong":"He wants I to come early.","right":"He wants me to come early.","bad":"I","fix":"me","why":"Sau “want” cần tân ngữ, nên dùng “me”, không dùng “I”. Tiếng Việt chỉ có “tôi” nên hay nhầm."},{"wrong":"My boss made me to work late.","right":"My boss made me work late.","bad":"to work","fix":"work","why":"Sau “make + tân ngữ” bỏ “to”. Chỉ make và let có quy tắc này."},{"wrong":"The nurse told me don't eat before surgery.","right":"The nurse told me not to eat before surgery.","bad":"don't","fix":"not to","why":"Lời dặn gián tiếp dùng “not to V”. “Don't” chỉ dùng khi nói trực tiếp."},{"wrong":"The teacher let us to leave early.","right":"The teacher let us leave early.","bad":"to leave","fix":"leave","why":"“Let” giống “make”: sau tân ngữ dùng nguyên mẫu không “to”. Đừng thêm “to” theo thói quen."},{"wrong":"I advise you taking a break.","right":"I advise you to take a break.","bad":"taking","fix":"to take","why":"“Advise + tân ngữ” đi với to V, không dùng V-ing. Nhớ: người + to V."},{"wrong":"She asked me that I open the window.","right":"She asked me to open the window.","bad":"that I","fix":"to","why":"Không dùng “that + mệnh đề” để yêu cầu như tiếng Việt “nhờ tôi rằng”. Dùng “ask + O + to V”."},{"wrong":"My dad doesn't allow me going out alone.","right":"My dad doesn't allow me to go out alone.","bad":"going","fix":"to go","why":"“Allow + tân ngữ” cần to V. V-ing chỉ dùng khi không có tân ngữ: “allow going out”."},{"wrong":"The sign tells people no to enter.","right":"The sign tells people not to enter.","bad":"no","fix":"not","why":"Phủ định của to V là “not to V”. “No” dùng trước danh từ, không đứng trước “to”."}],"contrast":{"title":"to V hay V nguyên mẫu?","a":"want/ask/tell + O + to V","b":"make/let + O + V","rows":[["Có “to” không?","Có “to”: “told me to wait”, “asked us to come”.","Không “to”: “made me wait”, “let us come”."],["Nghĩa chính","Yêu cầu, khuyên, cho phép, mong đợi: “advise, allow, expect”.","“Make” là bắt buộc; “let” là cho phép."],["Các động từ","want, ask, tell, advise, allow, expect, would like.","Chỉ make và let; riêng “help” dùng được cả hai (help me carry / help me to carry)."],["Phủ định","“told us not to go”.","“didn't let us go”, “didn't make us go” (phủ định ở động từ chính)."]],"ex":[["She asked me to stay.","She made me stay."],["They allowed us to park here.","They let us park here."]],"tip":"Chỉ make và let “không to”; mọi động từ khác đi với người rồi to V.","quiz":[{"q":"Our teacher ___ us to bring dictionaries.","opts":["let","made","asked","can"],"a":2,"why":"Câu có “us to bring”, nên động từ phải là ask/tell kiểu cần to V, đáp án là “asked”.","wrong":{"let":"Sau “let + tân ngữ” không có “to”, nhưng câu này có “to bring”.","made":"“Made us to” sai vì sau make bỏ “to”.","can":"Động từ khiếm khuyết “can” không đi với tân ngữ rồi to V."}},{"q":"The film ___ me cry.","opts":["made","wanted","told","asked"],"a":0,"why":"Câu có “me cry” không có “to”, nên chỉ make hoặc let đi được; make hợp nghĩa gây ra cảm xúc.","wrong":{"wanted":"“Wanted me cry” thiếu to; nghĩa cũng không phù hợp.","told":"“Told me cry” thiếu to và sai nghĩa vì phim không ra lệnh.","asked":"“Asked me cry” thiếu to; sau ask phải có to V."}},{"q":"Her mother ___ her go to the party, so she was very happy.","opts":["told","let","advised","asked"],"a":1,"why":"Không có “to” sau “her”, nên chọn let (cho phép), hợp với cô ấy vui.","wrong":{"told":"“Told her go” thiếu “to” và nghĩa trái với “happy”.","advised":"“Advised her go” thiếu to; cũng không nói là được phép.","asked":"“Asked her go” thiếu to."}},{"q":"What do you want me ___?","opts":["do","doing","done","to do"],"a":3,"why":"“Want + O + to V” cho câu hỏi “What do you want me to do?”.","wrong":{"do":"“Want me” cần to V, không dùng nguyên mẫu trần.","doing":"V-ing không dùng sau “want + tân ngữ”.","done":"Dạng V3 sẽ đổi nghĩa thành bị động; ở đây cần to do."}},{"q":"Could you ask the receptionist ___ the doctor?","opts":["call","to call","calling","that call"],"a":1,"why":"“Ask + O + to V”: “ask the receptionist to call” là yêu cầu nhờ vả.","wrong":{"call":"“Ask + O” cần to V.","calling":"V-ing không đi sau “ask the receptionist”.","that call":"“That call” thiếu chủ ngữ cho mệnh đề."}},{"q":"The teacher told us ___ late.","opts":["not to be","don't be","no to be","not be"],"a":0,"why":"Phủ định của to V là “not to V”, nên “told us not to be late”.","wrong":{"don't be":"“Don't be” chỉ dùng khi trích dẫn trực tiếp.","no to be":"“No to be” không phải dạng phủ định đúng.","not be":"Thiếu “to”; sau “told us” cần not to be."}},{"q":"The security guard didn't let anyone ___ the building.","opts":["to enter","entering","enter","entered"],"a":2,"why":"Sau “let + O” dùng nguyên mẫu trần, nên chọn “enter”.","wrong":{"to enter":"“Let” không đi với “to” sau tân ngữ anyone.","entering":"V-ing không đúng sau let + O.","entered":"Không chia quá khứ lần nữa sau tân ngữ."}},{"q":"I'd like ___ the results as soon as possible.","opts":["that you send","you send","you sending","you to send"],"a":3,"why":"“Would like + O + to V” nên chọn “you to send”.","wrong":{"that you send":"“Would like” + that-clause không tự nhiên trong tiếng Anh thông thường.","you send":"Thiếu “to”: “would like you” cần to V.","you sending":"V-ing không đúng cấu trúc này."}}]}}};
  const ORDER = [["be","pronouns","demonstratives","have-got","plurals","articles","possessives","imperatives","present-simple","frequency-adverbs","questions","can-ability","there-is","prepositions","present-continuous"],["past-simple","past-continuous","used-to","some-any","quantifiers","quantifiers-2","adjectives-adverbs","comparatives","as-as","future","modals","present-perfect","first-conditional","zero-conditional"],["pp-vs-past","present-perfect-continuous","past-perfect","time-clauses","gerund-infinitive","verb-object-infinitive","modals-deduction","passive","relative","in-case-unless","reported","second-conditional","question-tags","sva","dependent-prepositions","phrasal-verbs","word-forms","too-enough"],["third-conditional","modals-past","relative-nondefining","passive-reporting","linking","indirect-questions","causative","future-perfect","subjunctive-formal"],["mixed-conditionals","inversion","participle-clauses","cleft-sentences"]];
  NEW.forEach(g => GRAMMAR.push(g));
  Object.assign(GRAMMAR_BANK, BANK); Object.assign(GRAMMAR_THEORY, THEORY); Object.assign(GRAMMAR_GX, GX_ADD);
  const rank = Object.fromEntries(ORDER.flatMap(l => l.map((id, i) => [id, i])));
  const lv = { A1: 1, A2: 2, B1: 3, B2: 4, C1: 5 };
  GRAMMAR.sort((a, b) => (lv[a.lvl] - lv[b.lvl]) || ((rank[a.id] ?? 99) - (rank[b.id] ?? 99)));
})();
